const COMMANDS = new Set([
  'daemon',
  'status',
  'resources',
  'preflight',
  'prepare-stage-a',
  'run-stage-a',
  'run-library-page',
  'library-task',
  'prepare-bricks-handoff',
  'run-bricks-handoff',
  'repair-bricks-handoff',
  'prepare-stage-b',
  'run-stage-b',
  'repair-stage-b',
  'quick-text-edit',
  'import-stage-b',
  'insert-stage-b',
  'import-artifact',
  'stage-a-status',
  'pair-url',
  'help',
]);

async function main() {
  const parsed = parseArgs(process.argv.slice(2));
  const command = parsed.command || 'help';

  if (!COMMANDS.has(command)) {
    printError(`Unknown command "${command}".`);
    printHelp();
    process.exitCode = 2;
    return;
  }

  if (command === 'help' || parsed.flags.help) {
    printHelp();
    return;
  }

  if (command === 'daemon') {
    await runBridgeDaemonCommand(parsed.positional.slice(1), parsed.flags);
    return;
  }

  if (command === 'pair-url') {
    const result = await pairBridgeFromProtocolUrl(parsed.positional.slice(1), parsed.flags);
    outputResult(result, parsed.flags, renderBridgeProtocolPairSummary);
    return;
  }

  if (command === 'prepare-stage-a') {
    const result = await prepareStageAWorkspace(parsed.flags);
    outputResult(result, parsed.flags, renderPrepareStageASummary);
    return;
  }

  if (command === 'run-stage-a') {
    const result = await runStageAWorkspace(parsed.flags);
    outputResult(result, parsed.flags, renderRunStageASummary);
    return;
  }

  if (command === 'run-library-page') {
    const result = await runLibraryPageWorkspace(parsed.flags);
    outputResult(result, parsed.flags, renderRunStageASummary);
    return;
  }

  if (command === 'prepare-stage-b' || command === 'prepare-bricks-handoff') {
    const result = await prepareStageBWorkspace(parsed.flags);
    outputResult(result, parsed.flags, renderPrepareStageBSummary);
    return;
  }

  if (command === 'run-stage-b' || command === 'run-bricks-handoff') {
    const result = await runStageBWorkspace(parsed.flags);
    outputResult(result, parsed.flags, renderRunStageBSummary);
    return;
  }

  if (command === 'repair-stage-b' || command === 'repair-bricks-handoff') {
    const result = await repairStageBWorkspace(parsed.flags);
    outputResult(result, parsed.flags, renderRunStageBSummary);
    return;
  }

  if (command === 'quick-text-edit') {
    const result = await runQuickTextEditWorkspace(parsed.flags);
    outputResult(result, parsed.flags, renderQuickTextEditSummary);
    return;
  }

  const config = await loadConfig(parsed.flags);
  const client = createPixflowClient(config);

  if (command === 'status') {
    const result = await client.post('/cli-bridge/status', {});
    outputResult(result, parsed.flags, renderStatusSummary);
    return;
  }

  if (command === 'resources') {
    const stage = config.stage || DEFAULT_STAGE;
    const result = await client.post('/cli-bridge/resources/status', { stage });
    outputResult(result, parsed.flags, renderResourcesSummary);
    return;
  }

  if (command === 'preflight') {
    const stage = config.stage || DEFAULT_STAGE;
    const [status, resources] = await Promise.all([
      client.post('/cli-bridge/status', {}),
      client.post('/cli-bridge/resources/status', { stage }),
    ]);
    const result = { status, resources };
    outputResult(result, parsed.flags, renderPreflightSummary);
    return;
  }

  if (command === 'import-artifact') {
    const payload = await buildImportArtifactPayload(parsed.flags);
    const result = await client.post('/cli-bridge/stage-a/import-artifact', payload);
    outputResult(result, parsed.flags, renderImportSummary);
    return;
  }

  if (command === 'import-stage-b') {
    const payload = await buildStageBImportPayload(parsed.flags);
    const result = await client.post('/cli-bridge/stage-b/import-result', payload);
    outputResult(result, parsed.flags, renderStageBImportSummary);
    return;
  }

  if (command === 'insert-stage-b') {
    const payload = await buildStageBInsertPayload(parsed.flags);
    const result = await client.post('/pixflow-mcp/conversion/initial-html-insert', buildStageBWpInitialInsertPayload(payload));
    outputResult(result, parsed.flags, renderStageBInsertSummary);
    return;
  }

  if (command === 'stage-a-status') {
    const runId = firstString(parsed.flags.runId, parsed.flags.run, parsed.flags.run_id);
    if (!runId) {
      throw new CliError('Missing required --runId for stage-a-status.');
    }
    const result = await client.post('/cli-bridge/stage-a/status', { runId });
    outputResult(result, parsed.flags, renderStageAStatusSummary);
    return;
  }

  if (command === 'library-task') {
    const result = await runLibraryTask(parsed.flags);
    outputResult(result, parsed.flags, renderLibraryTaskSummary);
  }
}

function parseArgs(args) {
  const flags = {};
  const positional = [];

  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];

    if (!arg.startsWith('--')) {
      positional.push(arg);
      continue;
    }

    const eqIndex = arg.indexOf('=');
    if (eqIndex !== -1) {
      flags[arg.slice(2, eqIndex)] = arg.slice(eqIndex + 1);
      continue;
    }

    const key = arg.slice(2);
    const next = args[index + 1];
    if (next && !next.startsWith('--')) {
      flags[key] = next;
      index += 1;
    } else {
      flags[key] = true;
    }
  }

  return {
    command: positional[0] || '',
    positional,
    flags: normalizeFlags(flags),
  };
}

export async function buildPixflowStageBHtmlBaseline({ htmlFile, plan, iconSystem, fontSystem }) {
  const html = await readTextFile(htmlFile, 'Stage A artifact for Stage B baseline');
  const resolvedIconSystem = Object.keys(objectValue(iconSystem)).length > 0
    ? objectValue(iconSystem)
    : await buildStageBIconSystem(
      path.dirname(htmlFile),
      htmlFile,
      firstString(plan?.title, plan?.metadata?.title, 'Pixflow HTML import'),
      objectValue(plan?.metadata),
    );
  const resolvedFontSystem = Object.keys(objectValue(fontSystem)).length > 0
    ? objectValue(fontSystem)
    : await buildStageBFontSystem(
      path.dirname(htmlFile),
      htmlFile,
      firstString(plan?.title, plan?.metadata?.title, 'Pixflow HTML import'),
      objectValue(plan?.metadata),
      { conversionPolicy: objectValue(plan?.conversionPolicy) },
    );
  const bricksCompatibility = objectValue(plan?.bricksCompatibility);
  const compatibilityContext = bricksCompatibility.schema
    ? bricksCompatibility
    : resolvePixflowBricksCompatibilityContext({
      bricksVersion: plan?.bricksVersion,
      breakpoints: plan?.bricksBreakpoints || plan?.breakpoints || [],
      breakpointMode: plan?.bricksBreakpointMode,
    });
  const cssText = extractStageBStyleText(html);
  // Responsive media rules are projected into Bricks breakpoint controls or
  // scoped class CSS below. Container queries have no native Bricks control,
  // so keep their source rules out of the unconditional cascade and preserve
  // them as scoped custom CSS instead of accidentally applying them at every
  // viewport.
  const baseCssText = stripPixflowStageBAtRuleBlocks(
    stripPixflowStageBAtRuleBlocks(cssText, 'media'),
    'container',
  );
  const rules = extractStageBCssRuleSummaries(baseCssText);
  const classInfo = buildPixflowStageBHtmlClassInfo(html, cssText, rules, {
    breakpoints: plan?.bricksBreakpoints || plan?.breakpoints || [],
    existingGlobalClasses: plan?.existingGlobalClasses || plan?.bricksGlobalClasses || [],
    allowedUtilityClasses: plan?.routeContract?.variableAuthority?.allowedUtilityClasses
      || plan?.routeContextReport?.allowlists?.utilityClasses
      || [],
    sourceId: plan?.sourceId || plan?.metadata?.sourceId || plan?.source?.id,
    title: plan?.title || plan?.metadata?.title || plan?.source?.title,
    fontSystem: resolvedFontSystem,
    compatibilityContext,
  });
  const documentRoot = parsePixflowStageBHtmlDocument(html);
  const body = findFirstPixflowHtmlElement(documentRoot, (node) => node.tag === 'body') || documentRoot;
  assignPixflowStageBInternalSourceIds(body);
  const roots = getPixflowStageBBodyRootNodes(body);
  const pageStructureRoots = arrayValue(body?.children)
    .filter((node) => node?.type !== 'text' || normalizeWhitespace(node?.text));
  const runtimeEvidenceBySourceId = objectValue(
    objectValue(objectValue(plan?.sourceEvidence).renderedSnapshot).nodesBySourceId,
  );
  const headerNodes = selectPixflowStageBHeaderNodes(documentRoot, plan);
  const footerNodes = selectPixflowStageBFooterNodes(documentRoot, plan);
  // An uploaded HTML document is a full-page clone contract. Header/footer
  // landmark detection is useful for optional template extraction, but a
  // user who has not opted into a sitewide template must not lose a hero or
  // page header from the page canvas. Keep detected landmarks in page content
  // for uploaded HTML; template-oriented conversion profiles retain the
  // explicit include/omit behaviour.
  const uploadedHtmlClone = isPixflowStageBSourceFidelityClonePlan(plan);
  const pageSkipNodes = new Set([
    ...(uploadedHtmlClone || plan?.headerPlan?.includeHeader !== true ? [] : headerNodes.pageSkipNodes),
    ...(uploadedHtmlClone || plan?.footerPlan?.includeFooter !== true ? [] : footerNodes.pageSkipNodes),
  ]);
  // Bricks element ids occupy one payload-wide namespace even when Pixflow
  // compiles page, header, and footer trees independently. Share one registry
  // so the short deterministic hash can be resolved before an element is
  // recorded, referenced, or validated.
  const usedElementIds = new Set();

  const pageContext = createPixflowStageBHtmlCompilerContext({
    scope: 'page',
    plan,
    classInfo,
    iconSystem: resolvedIconSystem,
    sourceRoots: pageStructureRoots,
    runtimeEvidenceBySourceId,
    compatibilityContext,
    usedElementIds,
  });
  if (!uploadedHtmlClone && plan?.headerPlan?.includeHeader === true) {
    for (const node of headerNodes.pageSkipNodes) {
      pageContext.structureRecorder.recordSubtreeDisposition(
        node,
        'normalized_into_header_template',
        'source_landmark_extracted_into_header_template',
        '',
        true,
      );
    }
  }
  if (!uploadedHtmlClone && plan?.footerPlan?.includeFooter === true) {
    for (const node of footerNodes.pageSkipNodes) {
      pageContext.structureRecorder.recordSubtreeDisposition(
        node,
        'normalized_into_footer_template',
        'source_landmark_extracted_into_footer_template',
        '',
        true,
      );
    }
  }
  const pageWrapper = pageStructureRoots.find((node) => node?.type === 'element' && isPixflowStageBPageWrapper(node));
  if (pageWrapper) {
    pageContext.structureRecorder.recordDisposition(
      pageWrapper,
      'normalized_into_children',
      'source_page_wrapper_flattened_without_losing_children',
    );
  }
  let bodyRootTextSectionId = '';
  for (const node of roots) {
    if (node?.type === 'text' && normalizeWhitespace(node?.text)) {
      if (!bodyRootTextSectionId) {
        const sectionClassId = classInfo.syntheticClassIdByKey?.get('tag:section');
        bodyRootTextSectionId = addPixflowStageBHtmlElement(
          pageContext,
          `page:body-root-text-section:${node.sourceIndex}`,
          'section',
          sectionClassId ? { _cssGlobalClasses: [sectionClassId] } : {},
          '',
          { syntheticReason: 'body_root_text_section_contract' },
        );
      }
      compilePixflowStageBHtmlNode(node, bodyRootTextSectionId, pageContext, { pageSkipNodes });
      continue;
    }
    bodyRootTextSectionId = '';
    compilePixflowStageBHtmlNode(node, '', pageContext, { pageSkipNodes });
  }

  const headerContext = createPixflowStageBHtmlCompilerContext({
    scope: 'header',
    plan,
    classInfo,
    iconSystem: resolvedIconSystem,
    sourceRoots: plan?.headerPlan?.includeHeader ? headerNodes.templateNodes : [],
    runtimeEvidenceBySourceId,
    compatibilityContext,
    usedElementIds,
  });
  if (plan?.headerPlan?.includeHeader) {
    for (const node of headerNodes.templateNodes) {
      compilePixflowStageBHtmlNode(node, '', headerContext, { templatePart: 'header' });
    }
  }

  const footerContext = createPixflowStageBHtmlCompilerContext({
    scope: 'footer',
    plan,
    classInfo,
    iconSystem: resolvedIconSystem,
    sourceRoots: plan?.footerPlan?.includeFooter ? footerNodes.templateNodes : [],
    runtimeEvidenceBySourceId,
    compatibilityContext,
    usedElementIds,
  });
  if (plan?.footerPlan?.includeFooter) {
    for (const node of footerNodes.templateNodes) {
      compilePixflowStageBHtmlNode(node, '', footerContext, { templatePart: 'footer' });
    }
  }

  const scriptCode = buildStageBJavaScriptCode(plan?.scripts || extractStageBScripts(html));
  const themeStylePayload = buildPixflowStageBThemeStylePayload({
    sourceId: firstString(plan?.sourceId, plan?.metadata?.sourceId),
    title: firstString(plan?.title, plan?.metadata?.title, 'Pixflow Handoff'),
    cssText,
    rules,
    classInfo,
    fontSystem: resolvedFontSystem,
    plan,
    compatibilityContext,
  });
  const pageSettings = buildPixflowStageBPageSettings(scriptCode, plan);
  applyPixflowStageBPageBaseCss(
    pageSettings,
    rules,
    classInfo.cssVariables,
    buildPixflowStageBFontMappingOptions(resolvedFontSystem),
    cssText,
    {
      sourceFidelityClone: isPixflowStageBSourceFidelityClonePlan(plan),
      themeStylePayload,
    },
  );
  applyPixflowStageBMeasuredDocumentCss(pageSettings, plan, resolvedFontSystem, themeStylePayload);
  ensurePixflowStageBFlexContainerDisplay(classInfo.globalClasses);

  const content = pageContext.content;
  const headerContent = headerContext.content;
  const footerContent = footerContext.content;
  const flattenedPageBoundaryProjection = applyPixflowStageBFlattenedPageBoundaryCss(
    pageSettings,
    documentRoot,
    plan,
    resolvedFontSystem,
  );
  // Flattened body/main classes must be attached before relationship-derived
  // defaults inspect the live Bricks parent. Otherwise a row-flex main looks
  // unstyled here and its intrinsic-width children inherit Bricks' stretch.
  preservePixflowStageBFlattenedMainAnchor(content, documentRoot, classInfo, {
    boundaryProjected: flattenedPageBoundaryProjection.applied,
  });
  const intrinsicFlexItemDefaults = applyPixflowStageBIntrinsicFlexItemDefaults(
    [content, headerContent, footerContent],
    classInfo.globalClasses,
    { sourceFidelityClone: isPixflowStageBSourceFidelityClonePlan(plan) },
  );
  applyPixflowStageBSourceFidelityClonePageSettings(pageSettings, plan, headerContent, footerContent);
  applyPixflowStageBHeaderBaselineContract(headerContent, plan?.headerPlan, classInfo, {
    preserveSourceHierarchy: isPixflowStageBSourceFidelityClonePlan(plan),
    structureRecorder: headerContext.structureRecorder,
  });
  // Pixflow-owned: inline rich-text marks keep their class attribute inside
  // Bricks text/heading HTML, so their selector CSS must live at page scope.
  applyPixflowStageBInlineMarkupPageCss(pageSettings, [content, headerContent, footerContent], classInfo);
  const tokensUsed = extractPixflowStageBTokenReferences(`${html}\n${cssText}`);
  const themeStyleDefaultPruning = {
    skipped: true,
    reason: 'pre_stage_b_class_owned_styling',
    prunedPropertyCount: 0,
    entries: [],
  };
  const emptyClassPruning = removePixflowStageBEmptyGlobalClasses(classInfo, [content, headerContent, footerContent]);
  const classLifecycleReport = reconcilePixflowHtmlClassLifecycle({
    globalClasses: classInfo.globalClasses,
    elementBuckets: [content, headerContent, footerContent],
    classPlan: classInfo.classOwnershipPlan,
    pageSettings,
    classIdBySourceName: classInfo.classIdByName,
  });
  const preliminaryStyleOwnershipReport = buildPixflowStyleOwnershipReport({
    cssText,
    sourceHtml: html,
    globalClasses: classInfo.globalClasses,
    sourceClassIdByName: classInfo.classIdByName,
    usageByClass: classInfo.usageByClass,
    cascadeDecisions: classInfo.cascadeDecisions,
    pageSettings,
    compatibilityContext,
    themeStylePayload,
  });
  appendPixflowStyleOwnershipPageFallbacks(pageSettings, preliminaryStyleOwnershipReport, {
    representedSelectors: flattenedPageBoundaryProjection.representedSelectors,
  });
  const tokenGraphReport = reconcilePixflowHtmlTokenGraph({
    cssText,
    globalClasses: classInfo.globalClasses,
    pageSettings,
    sourceClassIdByName: classInfo.classIdByName,
    runtimeVariables: collectPixflowStageBRuntimeVariables(plan),
    routeContract: plan?.routeContract || plan?.stage_b_route_contract || {},
    existingGlobalData: plan?.existingGlobalData || plan?.bricksGlobalData || {},
    colorSystem: plan?.colorSystem || {},
    additionalSettings: [themeStylePayload.settings],
  });
  const stageBColorSystem = structuredClone(objectValue(
    plan?.colorSystem
      || plan?.stage_b_color_system
      || plan?.stageBColorSystem,
  ));
  if (!firstString(stageBColorSystem.type)) stageBColorSystem.type = 'pixflow_stage_b_color_system';
  if (!Number.isFinite(Number(stageBColorSystem.version))) stageBColorSystem.version = 2;
  if (!firstString(stageBColorSystem.source)) stageBColorSystem.source = 'pixflow_html_token_graph';
  mergePixflowStageBTokenGraphResources(stageBColorSystem, tokenGraphReport);
  refreshPixflowStageBThemeStyleDependencies(themeStylePayload, tokenGraphReport);
  reconcilePixflowHtmlClassRenameDependencies({
    globalClasses: classInfo.globalClasses,
    elementBuckets: [content, headerContent, footerContent],
    pageSettings,
    themeStylePayload,
    lifecycleReport: classLifecycleReport,
  });
  const styleOwnershipReport = buildPixflowStyleOwnershipReport({
    cssText,
    sourceHtml: html,
    globalClasses: classInfo.globalClasses,
    sourceClassIdByName: classInfo.classIdByName,
    usageByClass: classInfo.usageByClass,
    cascadeDecisions: classInfo.cascadeDecisions,
    pageSettings,
    compatibilityContext,
    themeStylePayload,
    resolvedUndefinedVariableNames: [
      ...arrayValue(tokenGraphReport.resolvedUndefinedVariableNames),
      ...arrayValue(tokenGraphReport.outputDefinedVariables),
    ],
  });
  applyPixflowStageBSvgIconClassControls(
    classInfo.globalClasses,
    [content, headerContent, footerContent],
    pageSettings,
  );

  const baseline = {
    mode: 'pixflow_html_baseline',
    content,
    headerContent,
    footerContent,
    globalClasses: classInfo.globalClasses,
    classPlan: classInfo.classOwnershipPlan,
    pageSettings,
    themeStylePayload,
    themeStyleDefaultPruning,
    emptyClassPruning,
    classLifecycleReport,
    tokenGraphReport,
    stage_b_color_system: stageBColorSystem,
    stage_b_font_system: resolvedFontSystem,
    stage_b_icon_system: resolvedIconSystem,
    tokensUsed,
    rawColorFallbacks: extractPixflowStageBRawColorFallbacks(cssText),
    styleOwnershipReport,
    summary: {
      parser: 'pixflow_clean_room_html_to_bricks_baseline',
      conversionProfile: firstString(
        plan?.conversionPolicy?.conversionProfile,
        plan?.source?.conversionProfile,
        plan?.conversionProfile,
      ),
      sourceFidelityClone: uploadedHtmlClone,
      sourceHtmlLength: html.length,
      cssRuleCount: rules.length,
      classCount: classInfo.globalClasses.length,
      classPlanDecisionCount: classInfo.classOwnershipPlan?.decisions?.length || 0,
      pageElementCount: content.length,
      headerElementCount: headerContent.length,
      footerElementCount: footerContent.length,
      pageSettingsScriptCount: pageSettings.customScriptsBodyFooter ? 1 : 0,
      themeStylePayloadIncluded: Object.keys(objectValue(themeStylePayload.settings)).length > 0,
      themeStyleDefaultPruning,
      flattenedPageBoundaryProjection,
      intrinsicFlexItemDefaults,
      emptyClassPruning,
      classLifecycle: {
        ok: classLifecycleReport.ok,
        retainedClassCount: classLifecycleReport.retainedClassCount,
        prunedClassCount: classLifecycleReport.prunedClassCount,
        directlyReferencedClassCount: classLifecycleReport.directlyReferencedClassCount,
        dependencyOnlyClassCount: classLifecycleReport.dependencyOnlyClassCount,
        customOnlyClassCount: classLifecycleReport.customOnlyClassCount,
        duplicateSignatureSurplusCount: classLifecycleReport.duplicateSignatureSurplusCount,
        orphanReferenceCount: classLifecycleReport.orphanReferenceCount,
        unexplainedUnusedClassCount: classLifecycleReport.unexplainedUnusedClassCount,
      },
      tokenGraph: {
        ok: tokenGraphReport.ok,
        tokenCount: tokenGraphReport.tokenCount,
        resolvedTokenCount: tokenGraphReport.resolvedTokenCount,
        unresolvedTokenCount: tokenGraphReport.unresolvedTokenCount,
        cycleCount: tokenGraphReport.cycleCount,
        undefinedOutputReferenceCount: tokenGraphReport.undefinedOutputReferenceCount,
        repeatedValueCandidateCount: arrayValue(tokenGraphReport.repeatedValueCandidates).length,
        exactFrameworkReuseCount: Number(tokenGraphReport.framework?.exactReuseCount || 0),
        paletteColorCount: arrayValue(tokenGraphReport.mutationIntent?.palette?.colors).length,
      },
      compatibilityProfile: {
        profileId: compatibilityContext.profileId,
        profileVersion: compatibilityContext.profileVersion,
        status: compatibilityContext.status,
        bricksVersion: compatibilityContext.bricksVersion,
        fallbackUsed: compatibilityContext.fallbackUsed,
      },
      styleOwnership: {
        ok: styleOwnershipReport.ok,
        declarationCount: styleOwnershipReport.declarationCount,
        nativeControlDeclarationCount: styleOwnershipReport.nativeControlDeclarationCount,
        fallbackDeclarationCount: styleOwnershipReport.fallbackDeclarationCount,
        scopedCustomCssBytes: styleOwnershipReport.scopedCustomCssBytes,
        pageCssBytes: styleOwnershipReport.pageCssBytes,
        unresolvedDeclarationCount: styleOwnershipReport.unresolvedDeclarationCount,
        silentLossCount: styleOwnershipReport.silentLossCount,
      },
      skippedHeaderNodes: headerNodes.pageSkipNodes.length,
      skippedFooterNodes: footerNodes.pageSkipNodes.length,
    },
  };
  normalizeStageBFlexDirectionControlKeys(baseline);
  const compatibilityValidation = validatePixflowBricksPayload({
    content: [...baseline.content, ...baseline.headerContent, ...baseline.footerContent],
    globalClasses: baseline.globalClasses,
  }, compatibilityContext);
  baseline.bricksCompatibility = compatibilityContext;
  baseline.compatibilityValidation = compatibilityValidation;
  baseline.summary.compatibilityValidation = {
    ok: compatibilityValidation.ok,
    errorCount: compatibilityValidation.errors.length,
    warningCount: compatibilityValidation.warnings.length,
  };
  if (!compatibilityValidation.ok) {
    const firstError = compatibilityValidation.errors[0];
    throw new Error(`Pixflow Bricks compatibility validation failed: ${firstString(firstError?.message, firstError?.code, 'unknown compatibility error')}`);
  }
  // A Build in Bricks prompt can ask for a capability in ordinary language
  // while Stage A quite reasonably renders a visual placeholder (for
  // example, three static blog cards). Apply only the typed, structurally
  // verifiable requirements here so the fast converter never leaves a
  // requested query listing as static HTML. This is deliberately idempotent;
  // a later Stage B/model repair can refine the same native payload.
  baseline.generationRequirementRepair = applyStageBGeneratedCapabilityRequirements(
    baseline,
    plan?.conversionPolicy || {},
  );
  for (const recorder of [
    pageContext.structureRecorder,
    headerContext.structureRecorder,
    footerContext.structureRecorder,
  ]) {
    recorder.reconcileRemovedElements({
      elementIds: baseline.generationRequirementRepair.removedElementIds,
      ownerElementId: baseline.generationRequirementRepair.loopElementId,
      reason: 'typed_generation_requirement_normalized_into_native_query_template',
    });
  }
  baseline.summary.pageElementCount = baseline.content.length;
  baseline.summary.generationRequirementRepair = baseline.generationRequirementRepair;
  const structureProjection = finalizePixflowHtmlStructureProjection({
    recorders: [
      pageContext.structureRecorder,
      headerContext.structureRecorder,
      footerContext.structureRecorder,
    ],
    elements: [...baseline.content, ...baseline.headerContent, ...baseline.footerContent],
    compatibilityContext,
  });
  baseline.structureIr = structureProjection.ir;
  baseline.structureReport = structureProjection.report;
  baseline.summary.structure = {
    ok: structureProjection.report.ok,
    sourceNodeCount: structureProjection.report.sourceNodeCount,
    sourceCoverageRatio: structureProjection.report.sourceCoverageRatio,
    sourceProjectedElementCount: structureProjection.report.sourceProjectedElementCount,
    syntheticElementCount: structureProjection.report.syntheticElementCount,
    nativeEditableElementCount: structureProjection.report.nativeEditableElementCount,
    exactFallbackElementCount: structureProjection.report.exactFallbackElementCount,
    errorCount: structureProjection.report.errorCount,
    warningCount: structureProjection.report.warningCount,
  };
  if (!structureProjection.report.ok) {
    const firstError = structureProjection.report.errors[0];
    throw new Error(`Pixflow structure validation failed: ${firstString(firstError?.message, firstError?.code, 'unknown structure error')}`);
  }
  const sourceClassPreservation = preserveScopedPrototypeBricksSourceClasses();
  baseline.summary.sourceClassPreservation = sourceClassPreservation;
  // Compatibility alias for existing reports; no BEM normalization occurs.
  baseline.summary.scopedBemNormalization = sourceClassPreservation;
  return baseline;
}

function collectPixflowStageBRuntimeVariables(plan) {
  const viewports = arrayValue(objectValue(objectValue(plan?.sourceEvidence).renderedSnapshot).viewports);
  const preferred = viewports.find((viewport) => /desktop|base/i.test(firstString(viewport?.id))) || viewports[0];
  const result = {};
  for (const viewport of [preferred, ...viewports].filter(Boolean)) {
    for (const [name, value] of Object.entries(objectValue(viewport?.variables))) {
      if (/^--[A-Za-z0-9_-]+$/.test(name) && firstString(value) && !firstString(result[name])) {
        result[name] = firstString(value);
      }
    }
  }
  return result;
}

function mergePixflowStageBTokenGraphResources(colorSystem, tokenGraphReport) {
  const target = objectValue(colorSystem);
  const additions = objectValue(objectValue(tokenGraphReport).mutationIntent?.resourceAdditions);
  const variables = arrayValue(additions.variables);
  const colors = arrayValue(additions.paletteColors);
  if (Object.keys(objectValue(additions.variableCategory)).length > 0) {
    target.variableCategory = {
      ...objectValue(additions.variableCategory),
      ...objectValue(target.variableCategory),
    };
  }
  if (Object.keys(objectValue(additions.palette)).length > 0) {
    target.palette = {
      ...objectValue(additions.palette),
      ...objectValue(target.palette),
    };
  }
  if (variables.length > 0) {
    const existing = arrayValue(target.variables);
    const names = new Set(existing.map((item) => firstString(item?.name)).filter(Boolean));
    target.variables = [
      ...existing,
      ...variables.filter((item) => firstString(item?.name) && !names.has(firstString(item.name))),
    ];
  }
  if (colors.length > 0) {
    target.palette = objectValue(target.palette);
    const existing = arrayValue(target.palette.colors);
    const ids = new Set(existing.map((item) => firstString(item?.id)).filter(Boolean));
    target.palette.colors = [
      ...existing,
      ...colors.filter((item) => firstString(item?.id) && !ids.has(firstString(item.id))),
    ];
  }
}

function appendPixflowStyleOwnershipPageFallbacks(pageSettings, ownershipReport, options = {}) {
  const representedSelectors = new Set(arrayValue(options.representedSelectors)
    .map((selector) => firstString(selector).trim())
    .filter(Boolean));
  const missing = arrayValue(objectValue(ownershipReport).declarations)
    .filter((item) => (
      item?.emitted !== true
      && firstString(item?.destination) !== 'variable_token_candidate'
      && !representedSelectors.has(firstString(item?.selector).trim())
    ));
  if (missing.length === 0) return;
  const grouped = new Map();
  for (const item of missing) {
    const selector = firstString(item?.selector);
    const property = firstString(item?.property).toLowerCase();
    const value = firstString(item?.value);
    if (!selector || !property || !value || property === '@keyframes') continue;
    const media = firstString(item?.media);
    const key = `${media}\u0000${selector}`;
    const group = grouped.get(key) || { media, selector, declarations: [] };
    group.declarations.push(`${property}: ${value}${item?.important ? ' !important' : ''};`);
    grouped.set(key, group);
  }
  const blocks = [];
  for (const group of grouped.values()) {
    const scopedSelector = splitPixflowCssSelectorList(group.selector)
      .map((selector) => scopePixflowStyleOwnershipSelector(selector))
      .filter(Boolean)
      .join(', ');
    if (!scopedSelector || group.declarations.length === 0) continue;
    const rule = `${scopedSelector} { ${group.declarations.join(' ')} }`;
    blocks.push(group.media ? `@media ${group.media} { ${rule} }` : rule);
  }
  if (blocks.length === 0) return;
  const settings = objectValue(pageSettings);
  const existing = firstString(settings.customCss);
  settings.customCss = [existing, ...blocks].filter(Boolean).join('\n');
}

function scopePixflowStyleOwnershipSelector(selector) {
  const value = firstString(selector);
  if (!value) return '';
  if (/^#brx-content(?:\b|\s|[.#:[>+~])/i.test(value)) return value;
  if (/^(?::root|html|body)$/i.test(value)) return '#brx-content';
  if (/^(?:html|body)\b/i.test(value)) return value.replace(/^(?:html|body)\b/i, '#brx-content');
  if (/^(?:\*|::?before|::?after)$/i.test(value)) return `:where(#brx-content) ${value}`;
  return `#brx-content ${value}`;
}

export function applyStageBGeneratedCapabilityRequirements(baseline, conversionPolicy = {}) {
  const requirements = Array.isArray(conversionPolicy?.generationRequirements)
    ? conversionPolicy.generationRequirements
    : [];
  const kinds = new Set(requirements.map((item) => firstString(item?.kind).toLowerCase()).filter(Boolean));
  if (!kinds.has('query_loop') && !kinds.has('dynamic_data')) {
    return { applied: false, reason: 'no_generated_query_or_dynamic_data_requirement', loopElementId: '', removedElementIds: [], dynamicBindings: [] };
  }

  const content = arrayValue(baseline?.content);
  const byId = new Map(content.map((element) => [firstString(element?.id), element]).filter(([id]) => id));
  const childrenByParent = new Map();
  for (const element of content) {
    const parentId = firstString(element?.parent);
    if (!parentId) continue;
    const siblings = childrenByParent.get(parentId) || [];
    siblings.push(firstString(element.id));
    childrenByParent.set(parentId, siblings);
  }
  for (const element of content) {
    const parentId = firstString(element?.id);
    if (!parentId) continue;
    const explicitChildren = arrayValue(element?.children).map(firstString).filter((id) => byId.has(id));
    const derivedChildren = childrenByParent.get(parentId) || [];
    const children = uniqueStrings(explicitChildren.length > 0 ? explicitChildren : derivedChildren);
    if (children.length > 0) element.children = children;
  }

  const signature = (elementId, depth = 0, seen = new Set()) => {
    if (!elementId || depth > 8 || seen.has(elementId)) return '';
    const element = byId.get(elementId);
    if (!element) return '';
    const nextSeen = new Set(seen);
    nextSeen.add(elementId);
    const settings = objectValue(element.settings);
    const classes = arrayValue(settings._cssGlobalClasses).map(firstString).filter(Boolean).sort().join(',');
    const tag = firstString(settings.tag).toLowerCase();
    const childSignatures = arrayValue(element.children)
      .map((childId) => signature(firstString(childId), depth + 1, nextSeen))
      .filter(Boolean)
      .sort();
    return `${firstString(element.name).toLowerCase()}|${tag}|${classes}|${childSignatures.join(';')}`;
  };
  const descendantIds = (rootId) => {
    const result = [];
    const queue = [rootId];
    const seen = new Set();
    while (queue.length > 0) {
      const id = queue.shift();
      if (!id || seen.has(id) || !byId.has(id)) continue;
      seen.add(id);
      result.push(id);
      queue.push(...arrayValue(byId.get(id)?.children).map(firstString).filter(Boolean));
    }
    return result;
  };
  const descendantElements = (rootId) => descendantIds(rootId).map((id) => byId.get(id)).filter(Boolean);
  const hasContentSignals = (rootId) => descendantElements(rootId).some((element) => {
    const settings = objectValue(element?.settings);
    const tag = firstString(settings.tag).toLowerCase();
    return firstString(element?.name).toLowerCase() === 'heading'
      || /^h[1-6]$/.test(tag)
      || firstString(element?.name).toLowerCase() === 'image'
      || firstString(settings.text).trim() !== '';
  });

  const candidateGroups = [];
  for (const [parentId, childIds] of childrenByParent.entries()) {
    const groups = new Map();
    for (const childId of childIds) {
      const child = byId.get(childId);
      if (!child || !hasContentSignals(childId)) continue;
      const key = signature(childId);
      if (!key) continue;
      const group = groups.get(key) || [];
      group.push(childId);
      groups.set(key, group);
    }
    for (const ids of groups.values()) {
      if (ids.length < 2) continue;
      const first = byId.get(ids[0]);
      const settings = objectValue(first?.settings);
      const classText = arrayValue(settings._cssGlobalClasses).map(firstString).join(' ').toLowerCase();
      const tag = firstString(settings.tag).toLowerCase();
      const score = ids.length * 20
        + (tag === 'article' ? 80 : 0)
        + (/\b(?:card|post|blog|article|entry|item)\b/.test(classText) ? 45 : 0)
        + Math.min(20, descendantIds(ids[0]).length);
      candidateGroups.push({ parentId, ids, score });
    }
  }
  candidateGroups.sort((left, right) => right.score - left.score);

  let templateId = candidateGroups[0]?.ids?.[0] || '';
  if (!templateId) {
    const fallback = content
      .filter((element) => {
        const settings = objectValue(element?.settings);
        const tag = firstString(settings.tag).toLowerCase();
        const name = firstString(element?.name).toLowerCase();
        const classText = arrayValue(settings._cssGlobalClasses).map(firstString).join(' ').toLowerCase();
        return hasContentSignals(firstString(element?.id))
          && (tag === 'article' || /\b(?:card|post|blog|article|entry|item)\b/.test(classText) || name === 'block');
      })
      .sort((left, right) => descendantIds(firstString(right.id)).length - descendantIds(firstString(left.id)).length)[0];
    templateId = firstString(fallback?.id);
  }
  if (!templateId || !byId.has(templateId)) {
    return { applied: false, reason: 'no_repeated_content_template_found', loopElementId: '', removedElementIds: [], dynamicBindings: [] };
  }

  const template = byId.get(templateId);
  const templateSettings = objectValue(template.settings);
  const queryRequirement = requirements.find((item) => firstString(item?.kind).toLowerCase() === 'query_loop') || {};
  const countWords = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
  const countToken = firstString(queryRequirement?.postsPerPage, queryRequirement?.posts_per_page)
    || '';
  const requestedCount = Number(countToken) || countWords[String(countToken).toLowerCase()] || 3;
  if (kinds.has('query_loop')) {
    templateSettings.hasLoop = true;
    templateSettings.query = {
      objectType: 'post',
      post_type: ['post'],
      posts_per_page: Number.isFinite(requestedCount) ? Math.max(1, Math.min(100, requestedCount)) : 3,
      orderby: 'date',
      order: 'DESC',
    };
    const attributes = arrayValue(templateSettings._attributes).filter((attribute) => firstString(attribute?.name).toLowerCase() !== 'data-query-loop-item');
    attributes.push({
      id: deterministicBricksId(`stage-b-generated-query-loop-attribute:${templateId}`),
      name: 'data-query-loop-item',
    });
    templateSettings._attributes = attributes;
  }
  template.settings = templateSettings;

  const dynamicBindings = [];
  const removedElementIds = [];
  if (kinds.has('dynamic_data')) {
    for (const element of descendantElements(templateId)) {
      const settings = objectValue(element.settings);
      const tag = firstString(settings.tag).toLowerCase();
      const name = firstString(element.name).toLowerCase();
      const text = firstString(settings.text);
      if (name === 'heading' || /^h[1-6]$/.test(tag)) {
        if (text !== '{post_title}') {
          settings.text = '{post_title}';
          dynamicBindings.push({ elementId: firstString(element.id), field: 'text', tag: '{post_title}' });
        }
      } else if (name === 'text-basic' && (/^\s*(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)\b/i.test(text) || /\b(?:20\d{2}|published|date)\b/i.test(text))) {
        settings.text = '{post_date}';
        dynamicBindings.push({ elementId: firstString(element.id), field: 'text', tag: '{post_date}' });
      } else if (name === 'text-basic' && (tag === 'p' || text.length >= 40)) {
        settings.text = '{post_excerpt}';
        dynamicBindings.push({ elementId: firstString(element.id), field: 'text', tag: '{post_excerpt}' });
      }
      if (settings.link && typeof settings.link === 'object' && !Array.isArray(settings.link)) {
        const link = objectValue(settings.link);
        settings.link = { ...link, type: 'meta', useDynamicData: '{post_url}' };
        dynamicBindings.push({ elementId: firstString(element.id), field: 'link', tag: '{post_url}' });
      }
      if (name === 'image') {
        const image = objectValue(settings.image);
        settings.image = { ...image, useDynamicData: '{featured_image}' };
        dynamicBindings.push({ elementId: firstString(element.id), field: 'image', tag: '{featured_image}' });
      }
      element.settings = settings;
    }

    // Stage A often represents artwork with a role="img" wrapper rather than
    // an <img>. Reuse that wrapper as a native Bricks image so a requested
    // featured image is actually renderable instead of leaving static artwork
    // or a text placeholder in the loop card.
    const mediaWrapper = descendantElements(templateId).find((element) => {
      const attrs = arrayValue(objectValue(element.settings)._attributes);
      return attrs.some((attribute) => firstString(attribute?.name).toLowerCase() === 'role' && firstString(attribute?.value).toLowerCase() === 'img');
    });
    if (mediaWrapper && firstString(mediaWrapper.name).toLowerCase() !== 'image') {
      const mediaSettings = objectValue(mediaWrapper.settings);
      mediaWrapper.name = 'image';
      mediaWrapper.settings = {
        ...mediaSettings,
        image: { useDynamicData: '{featured_image}' },
        alt: firstString(mediaSettings.alt, 'Featured image'),
      };
      const removedChildren = arrayValue(mediaWrapper.children).map(firstString).filter(Boolean);
      mediaWrapper.children = [];
      dynamicBindings.push({ elementId: firstString(mediaWrapper.id), field: 'image', tag: '{featured_image}' });
      for (const removedId of removedChildren) {
        const removed = descendantIds(removedId);
        for (const id of removed) {
          byId.delete(id);
          removedElementIds.push(id);
        }
      }
    }
  }

  const duplicateGroup = candidateGroups.find((group) => group.ids.includes(templateId));
  if (kinds.has('query_loop') && duplicateGroup) {
    for (const duplicateId of duplicateGroup.ids.slice(1)) {
      const parent = byId.get(firstString(duplicateGroup.parentId));
      if (parent) parent.children = arrayValue(parent.children).map(firstString).filter((id) => id && id !== duplicateId);
      for (const id of descendantIds(duplicateId)) {
        byId.delete(id);
        removedElementIds.push(id);
      }
    }
  }
  baseline.content = content.filter((element) => byId.has(firstString(element?.id)));
  return {
    applied: true,
    reason: 'native_generated_capability_contract',
    loopElementId: kinds.has('query_loop') ? templateId : '',
    removedElementIds,
    dynamicBindings,
    postsPerPage: kinds.has('query_loop') ? templateSettings.query.posts_per_page : null,
  };
}

function preserveScopedPrototypeBricksSourceClasses() {
  // The HTML source is authoritative. The Web Prototype preset intentionally
  // uses reusable classes such as `container`, `stack`, and `grid-3`; renaming
  // those to manufacture a BEM block breaks the copied layout CSS and can make
  // the Bricks canvas diverge from Stage A.
  return { applied: false, reason: 'source_class_names_preserved', renamed: 0 };
}

function applyPixflowStageBIntrinsicFlexItemDefaults(elementGroups, globalClasses, options = {}) {
  const elements = arrayValue(elementGroups).flatMap((group) => arrayValue(group));
  const elementById = new Map(elements.map((element) => [firstString(element?.id), element]).filter(([id]) => id));
  const classById = new Map(arrayValue(globalClasses)
    .map((classItem) => [firstString(classItem?.id), classItem])
    .filter(([id]) => id));
  const effectiveSetting = (element, key) => {
    const direct = objectValue(element?.settings);
    if (direct[key] !== undefined && direct[key] !== '') return direct[key];
    let value;
    for (const classId of arrayValue(direct._cssGlobalClasses)) {
      const settings = objectValue(classById.get(firstString(classId))?.settings);
      if (settings[key] !== undefined && settings[key] !== '') value = settings[key];
    }
    return value;
  };
  const updated = [];
  for (const element of elements) {
    const parent = elementById.get(firstString(element?.parent));
    if (!parent) continue;
    const parentDisplay = firstString(effectiveSetting(parent, '_display')).toLowerCase();
    const parentDirection = firstString(effectiveSetting(parent, '_direction'), 'row').toLowerCase();
    if (!['flex', 'inline-flex'].includes(parentDisplay) || !['row', 'row-reverse'].includes(parentDirection)) continue;
    const settings = objectValue(element.settings);
    const effectiveWidth = effectiveSetting(element, '_width');
    const effectiveMaxWidth = effectiveSetting(element, '_widthMax');
    const converterOwnedContainerWidth = (
      options.sourceFidelityClone === true
      && firstString(effectiveWidth) === '100%'
      && firstString(settings._width) === '100%'
      && firstString(settings._widthMax) === '100%'
    );
    if (effectiveWidth !== undefined && !converterOwnedContainerWidth) continue;
    // A max-width-only source block fills the available line and stops at its
    // cap. Bricks' row-flex block can instead shrink to converted min-content,
    // so make that browser `width:auto` behavior explicit as a fluid 100% cap.
    settings._width = effectiveMaxWidth !== undefined ? '100%' : 'auto';
    if (converterOwnedContainerWidth) delete settings._widthMax;
    element.settings = settings;
    updated.push(firstString(element.id));
  }
  return {
    applied: updated.length > 0,
    count: updated.length,
    elementIds: updated,
    reason: 'preserve_source_intrinsic_width_for_row_flex_children',
  };
}

function applyPixflowStageBFlattenedPageBoundaryCss(pageSettings, documentRoot, plan = {}, fontSystem = {}) {
  const target = '#brx-content';
  const main = findFirstPixflowHtmlElement(documentRoot, (node) => isPixflowStageBFlattenedMainBoundary(node));
  if (!main || !isPixflowStageBSourceFidelityClonePlan(plan)) {
    return {
      applied: false,
      reason: main ? 'source_fidelity_clone_not_active' : 'flattened_main_not_found',
      sourceNodeId: '',
      target,
      declarationCount: 0,
      responsiveOverrideCount: 0,
      representedSelectors: [],
    };
  }

  const sourceNodeId = firstString(pixflowStageBAttr(main, 'data-pf-source-id'));
  const snapshot = objectValue(objectValue(plan?.sourceEvidence).renderedSnapshot || plan?.renderedSnapshot);
  const evidence = arrayValue(objectValue(snapshot.nodesBySourceId)[sourceNodeId]);
  if (!sourceNodeId || evidence.length === 0) {
    return {
      applied: false,
      reason: sourceNodeId ? 'flattened_main_runtime_evidence_missing' : 'flattened_main_source_id_missing',
      sourceNodeId,
      target,
      declarationCount: 0,
      responsiveOverrideCount: 0,
      representedSelectors: [],
    };
  }

  const snapshotViewports = arrayValue(snapshot.viewports);
  const definedVariables = new Set(snapshotViewports
    .flatMap((viewport) => Object.keys(objectValue(viewport?.variables)))
    .filter((name) => /^--[A-Za-z0-9_-]+$/.test(firstString(name))));
  const variableValuesByName = new Map();
  for (const viewport of snapshotViewports) {
    for (const [name, value] of Object.entries(objectValue(viewport?.variables))) {
      const values = variableValuesByName.get(name) || new Set();
      values.add(normalizeStageBComparableCssValue(firstString(value)));
      variableValuesByName.set(name, values);
    }
  }
  const responsiveVariables = new Set([...variableValuesByName.entries()]
    .filter(([, values]) => values.size > 1)
    .map(([name]) => name));
  const computedValuesByAuthoredProperty = new Map();
  const viewportComputedCascadeProperties = new Set([
    'display',
    'position',
    'flex-direction',
    'flex-wrap',
    'align-items',
    'justify-content',
    'grid-template-columns',
    'grid-template-rows',
    'grid-column',
    'grid-column-start',
    'grid-column-end',
    'grid-row',
    'grid-row-start',
    'grid-row-end',
    'gap',
    'row-gap',
    'column-gap',
  ]);
  for (const entry of evidence) {
    for (const property of stringList(objectValue(entry).authoredProperties)) {
      const winner = objectValue(objectValue(objectValue(entry).winningDeclarations)[property]);
      const computedValue = firstString(winner.computedValue, objectValue(entry).styles?.[property]);
      if (!computedValue) continue;
      const values = computedValuesByAuthoredProperty.get(property) || new Set();
      values.add(normalizeStageBComparableCssValue(computedValue));
      computedValuesByAuthoredProperty.set(property, values);
    }
  }
  const viewportComputedProperties = new Set([...computedValuesByAuthoredProperty.entries()]
    .filter(([property, values]) => viewportComputedCascadeProperties.has(property) && values.size > 1)
    .map(([property]) => property));
  const safeDeclarations = (entryValue) => Object.fromEntries(Object.entries(stageBMeasuredDeclarations(
    objectValue(entryValue).styles,
    'section',
    entryValue,
    definedVariables,
    responsiveVariables,
    viewportComputedProperties,
  )).filter(([property, value]) => {
    const normalizedProperty = firstString(property).toLowerCase();
    const normalizedValue = firstString(value).trim();
    return /^(?:--[a-z0-9_-]+|-?[a-z][a-z0-9-]*)$/i.test(normalizedProperty)
      && normalizedValue.length > 0
      && normalizedValue.length <= 4096
      && !/[{}<>]/.test(normalizedValue)
      && !/(?:expression\s*\(|javascript\s*:|@import\b)/i.test(normalizedValue);
  }));
  const base = evidence.find((entry) => firstString(objectValue(entry).provenance?.viewport) === 'desktop')
    || evidence.find((entry) => firstString(objectValue(entry).provenance?.viewport) === 'bricks_base')
    || evidence[0];
  const baseDeclarations = safeDeclarations(base);
  const fontOptions = buildPixflowStageBFontMappingOptions(fontSystem);
  const baseCss = serializePixflowCssDeclarations(baseDeclarations, fontOptions);
  if (!baseCss) {
    return {
      applied: false,
      reason: 'flattened_main_has_no_authored_boundary_declarations',
      sourceNodeId,
      target,
      declarationCount: 0,
      responsiveOverrideCount: 0,
      representedSelectors: [],
    };
  }

  const blocks = [`${target} { ${baseCss} }`];
  let responsiveOverrideCount = 0;
  const mobilePortraitMaxWidth = Number(
    arrayValue(plan?.bricksBreakpoints)
      .find((breakpoint) => firstString(breakpoint?.key) === 'mobile_portrait')?.width
      || 478,
  );
  const bricksBase = evidence.find((entry) => firstString(objectValue(entry).provenance?.viewport) === 'bricks_base');
  const bricksBaseViewportWidth = Number(
    snapshotViewports.find((viewport) => firstString(viewport?.id) === 'bricks_base')?.width
    || 992,
  );
  const bricksBaseCss = serializePixflowCssDeclarations(safeDeclarations(bricksBase), fontOptions);
  if (
    bricksBaseCss
    && bricksBaseCss !== baseCss
    && bricksBaseViewportWidth > mobilePortraitMaxWidth
  ) {
    blocks.push(`@media (min-width: ${mobilePortraitMaxWidth + 1}px) and (max-width: ${bricksBaseViewportWidth}px) { ${target} { ${bricksBaseCss} } }`);
    responsiveOverrideCount += 1;
  }
  const mobile = evidence.find((entry) => firstString(objectValue(entry).provenance?.viewport) === 'mobile');
  const mobileCss = serializePixflowCssDeclarations(safeDeclarations(mobile), fontOptions);
  if (mobileCss && mobileCss !== baseCss) {
    blocks.push(`@media (max-width: ${mobilePortraitMaxWidth}px) { ${target} { ${mobileCss} } }`);
    responsiveOverrideCount += 1;
  }

  const existing = firstString(pageSettings.customCss);
  pageSettings.customCss = [existing, ...blocks].filter(Boolean).join('\n\n');
  const representedSelectors = uniqueStrings([
    'main',
    ...pixflowStageBHtmlClassList(main)
      .filter((className) => /^[A-Za-z_][A-Za-z0-9_-]*$/.test(className))
      .map((className) => `.${className}`),
  ]);
  return {
    applied: true,
    reason: 'flattened_main_authored_boundary_projected_to_bricks_page_root',
    sourceNodeId,
    target,
    declarationCount: Object.keys(baseDeclarations).length,
    responsiveOverrideCount,
    representedSelectors,
  };
}

function preservePixflowStageBFlattenedMainAnchor(content, documentRoot, classInfo = {}, options = {}) {
  const main = findFirstPixflowHtmlElement(documentRoot, (node) => isPixflowStageBFlattenedMainBoundary(node));
  if (!main) return;

  // Pixflow-owned: the clean-room compiler intentionally flattens the HTML
  // <main> wrapper because Bricks owns the page content landmark. Runtime-
  // proven wrapper declarations belong on #brx-content; attaching them to the
  // first section would only cover one sibling and can create false min-height
  // or overflow ownership. Keep the legacy class anchor only when evidence was
  // unavailable, while semantic attributes still move to the first page root.
  const firstRoot = arrayValue(content).find((element) => !firstString(element?.parent));
  if (!firstRoot) return;
  const settings = objectValue(firstRoot.settings);
  firstRoot.settings = settings;
  const mainClassIds = orderPixflowStageBClassNamesForCascade(
    pixflowStageBHtmlClassList(main),
    classInfo,
  ).map((className) => classInfo.classIdByName?.get?.(className)).filter(Boolean);
  if (options.boundaryProjected !== true && mainClassIds.length > 0) {
    settings._cssGlobalClasses = uniqueStrings([
      ...mainClassIds,
      ...arrayValue(settings._cssGlobalClasses),
    ]);
  }
  const attributes = arrayValue(settings._attributes);
  const existingAttributeNames = new Set(attributes
    .map((attribute) => firstString(attribute?.name).toLowerCase())
    .filter(Boolean));
  const carriedAttributes = buildPixflowStageBHtmlBricksAttributes(main, `flattened-main:${firstRoot.id}`)
    .filter((attribute) => {
      const name = firstString(attribute?.name).toLowerCase();
      // The HTML <main> is flattened because Bricks owns the page landmark.
      // Moving its id onto the first section makes fidelity matching compare
      // the full source page wrapper with one hero section and produces a
      // false geometry failure. Preserve accessible attributes, but not the
      // flattened landmark's structural id.
      return name !== 'class'
        && name !== 'id'
        // Internal runtime evidence identifies the flattened <main> itself.
        // Copying that id to a synthetic first root (for example a skip-link
        // wrapper) makes the measured pass apply the whole page boundary's
        // geometry to that one section as well as to #brx-content.
        && name !== 'data-pf-source-id'
        && !existingAttributeNames.has(name);
    });
  if (carriedAttributes.length > 0) {
    settings._attributes = [...attributes, ...carriedAttributes];
  }
}

function ensurePixflowStageBFlexContainerDisplay(globalClasses) {
  for (const classItem of arrayValue(globalClasses)) {
    const settings = objectValue(classItem?.settings);
    if (firstString(settings._display)) continue;
    const hasResponsiveFlexDisplay = Object.entries(settings).some(([key, value]) => (
      key.startsWith('_display:') && ['flex', 'inline-flex'].includes(firstString(value).toLowerCase())
    ));
    const ownsFlexContainerControls = [
      '_direction',
      '_flexWrap',
      '_alignItems',
      '_justifyContent',
      '_columnGap',
      '_rowGap',
    ].some((key) => firstString(settings[key]));
    if (hasResponsiveFlexDisplay && ownsFlexContainerControls) {
      // Pixflow-owned: responsive relationship/structural helper classes can
      // inherit desktop flex display from a companion source class. Bricks QA
      // correctly requires flex-container controls to be self-contained, so
      // materialize the same display on the helper without changing layout.
      settings._display = 'flex';
    }
  }
}

function buildPixflowStageBThemeStylePayload({
  sourceId,
  title,
  cssText,
  rules,
  classInfo,
  fontSystem,
  plan,
  compatibilityContext,
}) {
  const cssVariables = classInfo?.cssVariables instanceof Map ? classInfo.cssVariables : new Map();
  const fontOptions = buildPixflowStageBFontMappingOptions(fontSystem);
  const declarationsByClass = classInfo?.declarationsByClass instanceof Map ? classInfo.declarationsByClass : new Map();
  const bodyDeclarations = extractPixflowStageBPageRuleDeclarations(rules, 'body');
  const htmlDeclarations = extractPixflowStageBPageRuleDeclarations(rules, 'html');
  const rootDeclarations = extractPixflowStageBPageRuleDeclarations(rules, ':root');
  const sectionDeclarations = extractPixflowStageBPageRuleDeclarations(rules, 'section');
  const containerDeclarations = pickPixflowStageBRepeatedContainerDeclarations(classInfo, declarationsByClass);
  const buttonDeclarations = extractPixflowStageBPageRuleDeclarations(rules, 'button');
  const inputDeclarations = {
    ...extractPixflowStageBPageRuleDeclarations(rules, 'input'),
    ...extractPixflowStageBPageRuleDeclarations(rules, 'textarea'),
    ...extractPixflowStageBPageRuleDeclarations(rules, 'select'),
  };
  const linkDeclarations = extractPixflowStageBPageRuleDeclarations(rules, 'a');
  const focusDeclarations = extractPixflowStageBPageRuleDeclarations(rules, ':focus-visible', { includePseudoState: true });
  const browserDocumentDefaults = collectPixflowStageBFoundationBrowserDocumentDefaults(plan);
  const templateOwnership = {
    content: 'source_owned',
    header: plan?.headerPlan?.includeHeader === true ? 'source_owned' : 'destination_preserved',
    footer: plan?.footerPlan?.includeFooter === true ? 'source_owned' : 'destination_preserved',
  };
  const nativeGlobalScopeSafe = templateOwnership.header === 'source_owned'
    && templateOwnership.footer === 'source_owned';
  const semanticDefaults = {};
  const bodyTypography = mapPixflowCssDeclarationsToBricksSettings(pickPixflowStageBInheritedTextDeclarations({
    ...browserDocumentDefaults.body,
    ...bodyDeclarations,
  }), { cssVariables, ...fontOptions })._typography;
  if (bodyTypography) {
    semanticDefaults.bodyTypography = bodyTypography;
  }
  if (firstString(htmlDeclarations['font-size'], browserDocumentDefaults.html['font-size'])) {
    semanticDefaults.htmlFontSize = firstString(htmlDeclarations['font-size'], browserDocumentDefaults.html['font-size']);
  }
  const headings = {};
  for (const tag of ['h1', 'h2', 'h3', 'h4', 'h5', 'h6']) {
    const declarations = extractPixflowStageBPageRuleDeclarations(rules, tag);
    const heading = mapPixflowCssDeclarationsToBricksSettings(pickPixflowStageBInheritedTextDeclarations(declarations), { cssVariables, ...fontOptions })._typography;
    if (heading) {
      headings[tag] = heading;
    }
  }
  if (Object.keys(headings).length > 0) semanticDefaults.headings = headings;

  const section = pickPixflowStageBThemeStyleSection(sectionDeclarations);
  if (Object.keys(section).length > 0) semanticDefaults.section = section;
  const container = pickPixflowStageBThemeStyleContainer(containerDeclarations, sectionDeclarations);
  if (Object.keys(container).length > 0) semanticDefaults.container = container;
  const authoredSiteBackground = pickPixflowStageBThemeStyleBackground({ ...rootDeclarations, ...htmlDeclarations, ...bodyDeclarations });
  const siteBackground = Object.keys(authoredSiteBackground).length > 0
    ? authoredSiteBackground
    : pickPixflowStageBFoundationBrowserBackground(browserDocumentDefaults);
  if (Object.keys(siteBackground).length > 0) semanticDefaults.siteBackground = siteBackground;
  const link = pickPixflowStageBThemeStyleLink(linkDeclarations, cssVariables, fontOptions, templateOwnership);
  if (Object.keys(link).length > 0) semanticDefaults.link = link;
  const button = pickPixflowStageBThemeStyleButton(buttonDeclarations, cssVariables, fontOptions);
  if (Object.keys(button).length > 0) semanticDefaults.button = button;
  const form = pickPixflowStageBThemeStyleForm(inputDeclarations, cssVariables, fontOptions);
  if (Object.keys(form).length > 0) semanticDefaults.form = form;
  if (firstString(focusDeclarations.outline)) semanticDefaults.focusOutline = firstString(focusDeclarations.outline);

  const foundationDeclarations = buildPixflowStageBFoundationDeclarationOwnership({
    cssText,
    semanticDefaults,
    nativeGlobalScopeSafe,
  });
  foundationDeclarations.push(...buildPixflowStageBFoundationBrowserDeclarationOwnership({
    browserDocumentDefaults,
    semanticDefaults,
    existingDeclarations: foundationDeclarations,
    nativeGlobalScopeSafe,
  }));
  if (isPixflowStageBSourceFidelityClonePlan(plan)) {
    const sourceRootRemPx = inferStageBRootRemPxFromCss(cssText);
    for (let index = foundationDeclarations.length - 1; index >= 0; index -= 1) {
      const item = foundationDeclarations[index];
      if (firstString(item?.selector).toLowerCase() === 'html'
        && firstString(item?.property).toLowerCase() === 'font-size') {
        foundationDeclarations.splice(index, 1);
      }
    }
    foundationDeclarations.push({
      selector: 'html',
      property: 'font-size',
      value: `${sourceRootRemPx}px`,
      important: true,
      sourceOrder: -1,
      group: 'css',
      control: 'stylesheet',
      nativeSupported: false,
      provenance: 'source_root_rem_baseline',
    });
  }
  const mapped = buildPixflowBricksPageFoundationThemeStyle({
    id: deterministicBricksId(`html-page-foundation:${sourceId || title}`),
    label: `Pixflow HTML Foundation - ${firstString(title, sourceId, 'Generated Page')}`,
    conditions: {
      conditions: [{
        id: deterministicBricksId(`html-page-foundation-condition:${sourceId || title}`),
        main: 'ids',
        ids: ['__PIXFLOW_TARGET_PAGE_ID__'],
        idsIncludeChildren: false,
      }],
    },
    semanticDefaults: nativeGlobalScopeSafe ? semanticDefaults : {},
  }, compatibilityContext);
  const preliminarySettings = objectValue(mapped.value?.settings);
  for (const item of foundationDeclarations) {
    if (!item.nativeSupported) continue;
    item.nativeSupported = Object.prototype.hasOwnProperty.call(
      objectValue(preliminarySettings[firstString(item.group)]),
      firstString(item.control),
    );
  }
  const stylesheet = buildPixflowStageBFoundationStylesheet(foundationDeclarations, templateOwnership);
  preliminarySettings.css = { stylesheet };
  const settings = objectValue(mapped.value?.settings);
  const ownershipDeclarations = foundationDeclarations.map((item) => ({
    ...item,
    destination: nativeGlobalScopeSafe && mapped.ok && item.nativeSupported
      ? 'theme_style_native_control'
      : 'theme_style_stylesheet',
  }));
  const payload = {
    type: 'pixflow_stage_b_theme_style_payload',
    schema: 'pixflow.html_to_bricks.page_foundation.v1',
    version: 1,
    id: firstString(mapped.value?.id),
    label: firstString(mapped.value?.label),
    mode: 'page_foundation',
    owner: 'pixflow_html_to_bricks',
    scope: 'current_page',
    conditionTarget: 'target_post_id',
    applyStrategy: 'create_or_update_pixflow_owned_page_foundation_before_baseline_insert',
    nativeGlobalScopeSafe: nativeGlobalScopeSafe && mapped.ok,
    templateOwnership,
    compatibility: objectValue(mapped.value?.compatibility),
    compatibilityDiagnostics: arrayValue(mapped.diagnostics),
    settings,
    ownership: {
      declarations: ownershipDeclarations,
      nativeDeclarationCount: ownershipDeclarations.filter((item) => item.destination === 'theme_style_native_control').length,
      stylesheetDeclarationCount: ownershipDeclarations.filter((item) => item.destination === 'theme_style_stylesheet').length,
      syntheticCompatibilityRuleCount: 4,
      syntheticCompatibilityDeclarationCount: 5,
      stylesheetBytes: Buffer.byteLength(stylesheet, 'utf8'),
      nativeSettingGroups: Object.keys(settings).filter((group) => !['conditions', 'css'].includes(group)).sort(),
    },
    dependencies: {
      cssVariables: collectPixflowStageBThemeStyleVariableReferences(settings),
      paletteOrVariableResources: [],
    },
  };
  return payload;
}

function applyPixflowStageBSvgIconClassControls(globalClasses, elementBuckets, pageSettings = {}) {
  const classesById = new Map(arrayValue(globalClasses)
    .map((classItem) => [firstString(classItem?.id), classItem])
    .filter(([id]) => id));
  const pageFallbacks = new Map();
  for (const element of arrayValue(elementBuckets).flatMap((bucket) => arrayValue(bucket))) {
    if (firstString(element?.name).toLowerCase() !== 'icon') continue;
    for (const classId of arrayValue(objectValue(element?.settings)._cssGlobalClasses)) {
      const classItem = classesById.get(firstString(classId));
      if (!classItem) continue;
      const settings = objectValue(classItem.settings);
      const iconSettings = { ...objectValue(settings.icon) };
      const svgFallbackDeclarations = [];
      if (!firstString(iconSettings.width) && firstString(settings._width)) {
        iconSettings.width = settings._width;
      }
      if (firstString(settings._width)) {
        svgFallbackDeclarations.push(`width: ${settings._width}`);
      }
      if (!firstString(iconSettings.height) && firstString(settings._height)) {
        iconSettings.height = settings._height;
      }
      if (firstString(settings._height)) {
        svgFallbackDeclarations.push(`height: ${settings._height}`);
      }
      if (Object.keys(iconSettings).length > 0) settings.icon = iconSettings;
      if (svgFallbackDeclarations.length > 0) {
        const fallback = `%root% { ${svgFallbackDeclarations.join('; ')}; }`;
        if (!firstString(settings._cssCustom).includes(fallback)) {
          settings._cssCustom = [firstString(settings._cssCustom), fallback].filter(Boolean).join('\n');
        }
        const className = firstString(classItem.name);
        if (className) {
          pageFallbacks.set(
            className,
            `.${encodePixflowCssIdentifier(className)}.brxe-icon { ${svgFallbackDeclarations.join('; ')}; }`,
          );
        }
      }
      classItem.settings = settings;
    }
  }
  if (pageFallbacks.size > 0) {
    const existing = firstString(pageSettings.customCss);
    const blocks = [...pageFallbacks.values()].sort();
    pageSettings.customCss = [existing, ...blocks].filter(Boolean).join('\n');
  }
}

function extractPixflowStageBPageRuleDeclarations(rules, selectorName, options = {}) {
  const result = {};
  const wanted = firstString(selectorName).toLowerCase();
  for (const rule of arrayValue(rules)) {
    if (rule?.hasPseudoElement || (rule?.hasPseudoState && options.includePseudoState !== true)) {
      continue;
    }
    for (const selector of splitPixflowCssSelectorList(rule?.selector || '')) {
      if (firstString(selector).trim().toLowerCase() === wanted) {
        Object.assign(result, objectValue(rule.declarations));
      }
    }
  }
  return result;
}

function mergePixflowStageBHeadingDefaults(tagDeclarations, cssVariables, rules = []) {
  const result = {};
  for (const tag of ['h1', 'h2', 'h3', 'h4', 'h5', 'h6']) {
    const declarations = objectValue(tagDeclarations.get(tag));
    for (const [key, value] of Object.entries(pickPixflowStageBInheritedTextDeclarations(declarations))) {
      if (result[key] === undefined && value) {
        result[key] = value;
      }
    }
  }
  if (!result['font-family']) {
    const body = objectValue(tagDeclarations.get('body'));
    if (firstString(body['font-family'])) {
      result['font-family'] = body['font-family'];
    }
  }
  const aggregated = aggregatePixflowStageBHeadingRuleDefaults(rules);
  for (const [key, value] of Object.entries(aggregated)) {
    if (result[key] === undefined && value) {
      result[key] = value;
    }
  }
  return result;
}

function normalizePixflowStageBGenericHeadingThemeTypography(declarations, tagDeclarations) {
  const result = { ...objectValue(declarations) };
  if (!firstString(result['font-family'])) {
    return result;
  }
  const headingFamilies = [];
  for (const tag of ['h1', 'h2', 'h3', 'h4', 'h5', 'h6']) {
    const family = firstString(objectValue(tagDeclarations?.get?.(tag))['font-family']);
    if (family) {
      headingFamilies.push(family);
    }
  }
  // Pixflow-owned: Bricks `typographyHeadings` applies to every heading level.
  // Keep per-level heading families in H1-H6 theme options instead; otherwise a
  // source H1 font can incorrectly restyle component H3/H4 text that inherited
  // the body font in the original HTML.
  const uniqueFamilies = uniqueStrings(headingFamilies.map((family) => normalizeWhitespace(family).toLowerCase()));
  if (uniqueFamilies.length !== 1 || headingFamilies.length < 6) {
    delete result['font-family'];
  }
  return result;
}

function aggregatePixflowStageBHeadingRuleDefaults(rules) {
  const valuesByProperty = new Map();
  const allowed = new Set(['font-family', 'font-weight', 'line-height', 'letter-spacing', 'color']);
  for (const rule of arrayValue(rules)) {
    if (rule?.hasPseudoElement || rule?.hasPseudoState) {
      continue;
    }
    if (!/(?:^|[\s>])h[1-6]\b/i.test(firstString(rule.selector))) {
      continue;
    }
    for (const [key, value] of Object.entries(objectValue(rule.declarations))) {
      const property = String(key || '').toLowerCase();
      if (!allowed.has(property) || !value) {
        continue;
      }
      const bucket = valuesByProperty.get(property) || new Map();
      bucket.set(value, (bucket.get(value) || 0) + 1);
      valuesByProperty.set(property, bucket);
    }
  }
  const result = {};
  for (const [property, bucket] of valuesByProperty.entries()) {
    const sorted = [...bucket.entries()].sort((a, b) => b[1] - a[1]);
    if (sorted[0]) {
      result[property] = sorted[0][0];
    }
  }
  return result;
}

function pickPixflowStageBThemeStyleClassDeclarations(declarationsByClass, pattern) {
  const result = {};
  if (!(declarationsByClass instanceof Map)) {
    return result;
  }
  for (const [className, declarations] of declarationsByClass.entries()) {
    if (pattern.test(firstString(className))) {
      Object.assign(result, objectValue(declarations));
    }
  }
  return result;
}

function pickPixflowStageBThemeStyleButtonClassDeclarations(declarationsByClass) {
  const result = {};
  if (!(declarationsByClass instanceof Map)) {
    return result;
  }
  for (const [className, declarations] of declarationsByClass.entries()) {
    if (isPixflowStageBThemeStyleButtonClassName(className)) {
      Object.assign(result, objectValue(declarations));
    }
  }
  return result;
}

function isPixflowStageBThemeStyleButtonClassName(className) {
  // Pixflow-owned: Gemini and Codex frequently use ".cta" for entire CTA
  // sections. Only button-like CTA variants should seed Bricks Theme Style
  // button defaults; wrappers such as .cta and .cta-inner stay as classes.
  const name = firstString(className).toLowerCase();
  if (!name) {
    return false;
  }
  if (/^(?:cta|cta-inner|cta-section|cta-wrap|cta-wrapper|cta-content)$/.test(name)) {
    return false;
  }
  return /(?:^|[-_])(?:btn|button|ticket-link)(?:$|[-_])/i.test(name)
    || /(?:^|[-_])cta$/i.test(name)
    || /^(?:primary|secondary|tertiary|ghost|outline)[-_](?:btn|button|cta|link)$/i.test(name);
}

function pickPixflowStageBThemeStyleDescendantDeclarations(rules, tagPattern) {
  const result = {};
  for (const rule of arrayValue(rules)) {
    if (rule?.hasPseudoElement || rule?.hasPseudoState) {
      continue;
    }
    for (const selector of splitPixflowCssSelectorList(rule?.selector || '')) {
      const trimmed = firstString(selector).trim().toLowerCase();
      const lastToken = firstString(trimmed.split(/\s+|>\s*/).filter(Boolean).pop());
      if (tagPattern.test(lastToken)) {
        Object.assign(result, objectValue(rule.declarations));
      }
    }
  }
  return result;
}

function pickPixflowStageBThemeStyleSection(declarations) {
  if (Object.keys(objectValue(declarations)).length === 0) return {};
  const settings = mapPixflowCssDeclarationsToBricksSettings(pickPixflowStageBSectionShellDeclarations(declarations, {}));
  const result = { _display: 'block' };
  if (settings._padding) {
    result.padding = pickPixflowStageBVerticalPadding(settings._padding);
  }
  if (settings._background) {
    result.background = settings._background;
  }
  return result;
}

function pickPixflowStageBThemeStyleContainer(declarations, sectionDeclarations = {}) {
  const mapped = mapPixflowCssDeclarationsToBricksSettings(declarations);
  const result = {};
  if (mapped._width) result.width = mapped._width;
  if (mapped._widthMax) result.widthMax = mapped._widthMax;
  const sectionPadding = mapPixflowCssDeclarationsToBricksSettings(pickPixflowStageBSectionShellDeclarations(sectionDeclarations, {}))._padding;
  const inlinePadding = pickPixflowStageBHorizontalPadding(mapped._padding || sectionPadding);
  if (inlinePadding) result.padding = inlinePadding;
  if (mapped._rowGap) result._rowGap = mapped._rowGap;
  if (mapped._columnGap) result._columnGap = mapped._columnGap;
  return result;
}

function pickPixflowStageBVerticalPadding(padding) {
  const value = objectValue(padding);
  return {
    top: firstString(value.top, '0'),
    right: '0',
    bottom: firstString(value.bottom, value.top, '0'),
    left: '0',
  };
}

function pickPixflowStageBHorizontalPadding(padding) {
  const value = objectValue(padding);
  const left = firstString(value.left, value.right);
  const right = firstString(value.right, value.left);
  if (!left && !right) return null;
  return {
    top: '0',
    right: firstString(right, '0'),
    bottom: '0',
    left: firstString(left, '0'),
  };
}

function pickPixflowStageBThemeStyleBackground(declarations) {
  const background = firstString(declarations['background-color'], declarations.background);
  if (!background || !isPixflowCssColorValue(background)) {
    return {};
  }
  return {
    color: { raw: background },
  };
}

function pickPixflowStageBThemeStyleButton(declarations, cssVariables, fontOptions = {}) {
  const mapped = mapPixflowCssDeclarationsToBricksSettings(declarations, { cssVariables, ...fontOptions });
  if (Object.keys(mapped).length === 0) return {};
  const result = {};
  if (mapped._padding) result.sizeDefaultPadding = mapped._padding;
  const typography = removePixflowStageBInheritOnlyTypography(mapped._typography);
  if (typography) result.typography = typography;
  if (mapped._border) result.border = mapped._border;
  if (mapped._cssTransition) result.transition = mapped._cssTransition;
  if (mapped._background?.color) result.primaryBackground = mapped._background.color;
  if (typography?.color) result.primaryTypography = { color: typography.color };
  if (mapped._background?.color) result.darkBackground = mapped._background.color;
  if (typography?.color) result.darkTypography = { color: typography.color };
  if (mapped._border) result.darkBorder = mapped._border;
  result.darkOutlineBackground = { raw: 'transparent' };
  if (mapped._border) result.darkOutlineBorder = mapped._border;
  if (mapped._border?.color || typography?.color) {
    result.darkOutlineTypography = {
      color: objectValue(mapped._border?.color).raw ? mapped._border.color : typography.color,
    };
  }
  return result;
}

function removePixflowStageBInheritOnlyTypography(typography) {
  const result = { ...objectValue(typography) };
  if (String(firstString(objectValue(result.color).raw, result.color)).trim().toLowerCase() === 'inherit') {
    delete result.color;
  }
  return Object.keys(result).length > 0 ? result : null;
}

function pickPixflowStageBThemeStyleForm(declarations, cssVariables, fontOptions = {}) {
  const mapped = mapPixflowCssDeclarationsToBricksSettings(declarations, { cssVariables, ...fontOptions });
  const result = {};
  if (mapped._typography) result.fieldTypography = mapped._typography;
  if (mapped._background?.color) result.fieldBackgroundColor = mapped._background.color;
  if (mapped._border) result.fieldBorder = mapped._border;
  if (mapped._padding) result.fieldPadding = mapped._padding;
  if (mapped._margin) result.fieldMargin = mapped._margin;
  return result;
}

function prunePixflowStageBThemeStyleDefaultsFromClassInfo(classInfo, themeStylePayload) {
  const settings = objectValue(themeStylePayload?.settings);
  if (Object.keys(settings).length === 0 || !Array.isArray(classInfo?.globalClasses)) {
    return {
      prunedClassCount: 0,
      prunedPropertyCount: 0,
      entries: [],
    };
  }

  const defaults = buildPixflowStageBThemeStyleDefaultProfile(settings);
  const usageByClass = classInfo?.usageByClass instanceof Map ? classInfo.usageByClass : new Map();
  const sourceClassNameByClassId = classInfo?.sourceClassNameByClassId instanceof Map ? classInfo.sourceClassNameByClassId : new Map();
  const entries = [];
  let prunedPropertyCount = 0;

  for (const classItem of classInfo.globalClasses) {
    const classSettings = objectValue(classItem?.settings);
    if (Object.keys(classSettings).length === 0) {
      continue;
    }

    const sourceClassName = firstString(sourceClassNameByClassId.get(firstString(classItem?.id)));
    const className = firstString(sourceClassName, classItem?.name);
    if (className === 'section' || /\bsection\b/i.test(className)) {
      continue;
    }
    const usage = usageByClass.get(sourceClassName) || usageByClass.get(className) || {};
    const tags = arrayValue(usage?.tags).map((tag) => firstString(tag).toLowerCase()).filter(Boolean);
    const beforeHash = hashPixflowStageBClassSettings(classSettings);
    const pruned = [];

    if (classSettings._typography) {
      const profile = pickPixflowStageBTypographyDefaultForClass(className, tags, defaults);
      const removed = prunePixflowStageBMatchingObjectDefaults(classSettings._typography, profile);
      pruned.push(...removed.map((key) => `_typography.${key}`));
      if (Object.keys(objectValue(classSettings._typography)).length === 0) {
        delete classSettings._typography;
      }
    }

    if (isPixflowStageBButtonLikeClass(className, tags)) {
      pruned.push(...prunePixflowStageBMatchingSetting(classSettings, '_padding', defaults.button.sizeDefaultPadding, 'button.sizeDefaultPadding'));
      pruned.push(...prunePixflowStageBMatchingSetting(classSettings, '_border', defaults.button.border, 'button.border'));
      pruned.push(...prunePixflowStageBMatchingSetting(classSettings, '_background', defaults.button.background, 'button.primaryBackground'));
      if (classSettings._typography) {
        const removed = prunePixflowStageBMatchingObjectDefaults(classSettings._typography, defaults.button.typography);
        pruned.push(...removed.map((key) => `_typography.${key}`));
        if (Object.keys(objectValue(classSettings._typography)).length === 0) {
          delete classSettings._typography;
        }
      }
    }

    if (isPixflowStageBFormFieldLikeClass(className, tags)) {
      pruned.push(...prunePixflowStageBMatchingSetting(classSettings, '_padding', defaults.form.fieldPadding, 'form.fieldPadding'));
      pruned.push(...prunePixflowStageBMatchingSetting(classSettings, '_margin', defaults.form.fieldMargin, 'form.fieldMargin'));
      pruned.push(...prunePixflowStageBMatchingSetting(classSettings, '_border', defaults.form.fieldBorder, 'form.fieldBorder'));
      pruned.push(...prunePixflowStageBMatchingSetting(classSettings, '_background', defaults.form.fieldBackground, 'form.fieldBackgroundColor'));
      if (classSettings._typography) {
        const removed = prunePixflowStageBMatchingObjectDefaults(classSettings._typography, defaults.form.fieldTypography);
        pruned.push(...removed.map((key) => `_typography.${key}`));
        if (Object.keys(objectValue(classSettings._typography)).length === 0) {
          delete classSettings._typography;
        }
      }
    }

    if (classSettings._typography && classSettings._typography.fallback && !firstString(classSettings._typography['font-family'])) {
      delete classSettings._typography.fallback;
      pruned.push('_typography.fallback');
      if (Object.keys(objectValue(classSettings._typography)).length === 0) {
        delete classSettings._typography;
      }
    }

    classItem.settings = removeUndefinedObjectValues(classSettings);
    if (pruned.length > 0) {
      prunedPropertyCount += pruned.length;
      entries.push({
        classId: firstString(classItem.id),
        className: firstString(classItem.name),
        sourceClassName,
        removed: uniqueStrings(pruned),
        beforeHash,
        afterHash: hashPixflowStageBClassSettings(classItem.settings),
      });
    }
  }

  const summary = {
    prunedClassCount: entries.length,
    prunedPropertyCount,
    entries,
  };
  if (classInfo.classOwnershipPlan && typeof classInfo.classOwnershipPlan === 'object') {
    classInfo.classOwnershipPlan.themeStyleDefaultPruning = summary;
  }
  return summary;
}

function removePixflowStageBEmptyGlobalClasses(classInfo, elementBuckets = []) {
  if (!Array.isArray(classInfo?.globalClasses)) {
    return {
      removedClassCount: 0,
      removedReferenceCount: 0,
      removedClasses: [],
    };
  }
  const removable = classInfo.globalClasses.filter((classItem) => Object.keys(objectValue(classItem?.settings)).length === 0);
  if (removable.length === 0) {
    return {
      removedClassCount: 0,
      removedReferenceCount: 0,
      removedClasses: [],
    };
  }
  const removableIds = new Set(removable.map((classItem) => firstString(classItem?.id)).filter(Boolean));
  let removedReferenceCount = 0;
  for (const elements of arrayValue(elementBuckets)) {
    for (const element of arrayValue(elements)) {
      const settings = objectValue(element?.settings);
      if (!Array.isArray(settings._cssGlobalClasses)) {
        continue;
      }
      const before = settings._cssGlobalClasses.length;
      settings._cssGlobalClasses = settings._cssGlobalClasses
        .map(firstString)
        .filter((classId) => classId && !removableIds.has(classId));
      removedReferenceCount += before - settings._cssGlobalClasses.length;
      if (settings._cssGlobalClasses.length === 0) {
        delete settings._cssGlobalClasses;
      }
      element.settings = settings;
    }
  }
  classInfo.globalClasses = classInfo.globalClasses.filter((classItem) => !removableIds.has(firstString(classItem?.id)));
  const summary = {
    removedClassCount: removable.length,
    removedReferenceCount,
    removedClasses: removable.map((classItem) => ({
      id: firstString(classItem?.id),
      name: firstString(classItem?.name),
    })),
  };
  if (classInfo.classOwnershipPlan && typeof classInfo.classOwnershipPlan === 'object') {
    classInfo.classOwnershipPlan.emptyClassPruning = summary;
  }
  return summary;
}

function buildPixflowStageBThemeStyleDefaultProfile(settings) {
  const typography = objectValue(settings.typography);
  const button = objectValue(settings.button);
  const form = objectValue(settings.form);
  return {
    bodyTypography: objectValue(typography.typographyBody || typography.body),
    headingTypography: objectValue(typography.typographyHeadings || typography.heading),
    headingTypographyByTag: {
      h1: objectValue(typography.typographyHeadingH1),
      h2: objectValue(typography.typographyHeadingH2),
      h3: objectValue(typography.typographyHeadingH3),
      h4: objectValue(typography.typographyHeadingH4),
      h5: objectValue(typography.typographyHeadingH5),
      h6: objectValue(typography.typographyHeadingH6),
    },
    button: {
      sizeDefaultPadding: objectValue(button.sizeDefaultPadding),
      typography: objectValue(button.typography),
      border: objectValue(button.border),
      background: button.primaryBackground ? { color: button.primaryBackground } : {},
      textColor: objectValue(button.primaryTypography).color ? { color: objectValue(button.primaryTypography).color } : {},
    },
    form: {
      fieldTypography: objectValue(form.fieldTypography),
      fieldPadding: objectValue(form.fieldPadding),
      fieldMargin: objectValue(form.fieldMargin),
      fieldBorder: objectValue(form.fieldBorder),
      fieldBackground: form.fieldBackgroundColor ? { color: form.fieldBackgroundColor } : {},
    },
  };
}

function pickPixflowStageBTypographyDefaultForClass(className, tags, defaults) {
  const classText = firstString(className).toLowerCase();
  if (classText === 'stage-a-body-type') {
    return objectValue(defaults.bodyTypography);
  }
  const syntheticHeadingMatch = classText.match(/^stage-a-(h[1-6])-type$/);
  if (syntheticHeadingMatch) {
    const tag = syntheticHeadingMatch[1];
    return {
      ...objectValue(defaults.headingTypography),
      ...objectValue(defaults.headingTypographyByTag?.[tag]),
    };
  }
  const headingTag = tags.find((tag) => /^h[1-6]$/.test(tag));
  if (headingTag) {
    return {
      ...objectValue(defaults.headingTypography),
      ...objectValue(defaults.headingTypographyByTag?.[headingTag]),
    };
  }
  if (/\b(?:heading|title|headline|display|h[1-6])\b/.test(classText)) {
    return objectValue(defaults.headingTypography);
  }
  if (tags.some((tag) => ['p', 'span', 'small', 'strong', 'b', 'em', 'label', 'li', 'blockquote', 'text', 'text-basic'].includes(tag))) {
    return objectValue(defaults.bodyTypography);
  }
  if (/\b(?:text|copy|body|paragraph|rich|caption|eyebrow|label|meta)\b/.test(classText)) {
    return objectValue(defaults.bodyTypography);
  }
  return {};
}

function applyPixflowStageBInheritedHeadingTypography(settings, className, usage, context = {}) {
  const safeSettings = objectValue(settings);
  const tags = arrayValue(usage?.tags).map((tag) => firstString(tag).toLowerCase()).filter(Boolean);
  const classText = firstString(className).toLowerCase();
  const headingTag = tags.find((tag) => /^h[1-6]$/.test(tag));
  const isHeadingLike = Boolean(headingTag) || /\b(?:heading|title|headline|display|h[1-6])\b/.test(classText);
  if (!isHeadingLike) {
    return;
  }
  const tagDeclarationsByTag = context.tagDeclarationsByTag instanceof Map ? context.tagDeclarationsByTag : new Map();
  const cssVariables = context.cssVariables || new Map();
  const fontOptions = objectValue(context.fontOptions);
  const headingDeclarations = {
    ...mergePixflowStageBHeadingDefaults(tagDeclarationsByTag, cssVariables, context.rules),
    ...objectValue(headingTag ? tagDeclarationsByTag.get(headingTag) : {}),
  };
  // Browsers give semantic h1-h6 elements a bold UA default. Bricks Theme
  // Styles commonly replace that with a project heading weight (for example
  // 500), so an accepted source that intentionally leaves font-weight
  // implicit drifts after conversion unless the baseline makes the browser
  // default explicit.
  if (headingTag && !firstString(headingDeclarations['font-weight'])) {
    headingDeclarations['font-weight'] = '700';
  }
  const headingTypography = mapPixflowCssDeclarationsToBricksSettings(
    pickPixflowStageBInheritedTextDeclarations(headingDeclarations),
    { cssVariables, ...fontOptions },
  )._typography;
  if (!headingTypography || Object.keys(headingTypography).length === 0) {
    return;
  }
  safeSettings._typography = objectValue(safeSettings._typography);
  for (const [key, value] of Object.entries(headingTypography)) {
    if (safeSettings._typography[key] === undefined || safeSettings._typography[key] === '') {
      safeSettings._typography[key] = value;
    }
  }
  if (Object.keys(safeSettings._typography).length === 0) {
    delete safeSettings._typography;
  }
}

function isPixflowStageBButtonLikeClass(className, tags) {
  const classText = firstString(className).toLowerCase();
  return tags.includes('button') || tags.includes('a') || /\b(?:btn|button|cta|action|ticket-link)\b/.test(classText);
}

function isPixflowStageBFormFieldLikeClass(className, tags) {
  const classText = firstString(className).toLowerCase();
  return tags.some((tag) => ['input', 'textarea', 'select'].includes(tag))
    || /\b(?:input|field|textarea|select|form-field)\b/.test(classText);
}

function prunePixflowStageBMatchingSetting(settings, key, defaultValue, label) {
  if (!settings || !Object.prototype.hasOwnProperty.call(settings, key)) {
    return [];
  }
  if (Object.keys(objectValue(defaultValue)).length === 0) {
    return [];
  }
  if (!pixflowStageBValuesEqual(settings[key], defaultValue)) {
    return [];
  }
  delete settings[key];
  return [label];
}

function prunePixflowStageBMatchingObjectDefaults(target, defaults) {
  const safeTarget = objectValue(target);
  const safeDefaults = objectValue(defaults);
  const removed = [];
  for (const [key, value] of Object.entries(safeDefaults)) {
    if (!Object.prototype.hasOwnProperty.call(safeTarget, key)) {
      continue;
    }
    if (pixflowStageBValuesEqual(safeTarget[key], value)) {
      delete safeTarget[key];
      removed.push(key);
    }
  }
  return removed;
}

function pixflowStageBValuesEqual(a, b) {
  return stablePixflowStageBJsonStringify(normalizePixflowStageBComparableValue(a))
    === stablePixflowStageBJsonStringify(normalizePixflowStageBComparableValue(b));
}

function normalizePixflowStageBComparableValue(value) {
  if (Array.isArray(value)) {
    return value.map((item) => normalizePixflowStageBComparableValue(item));
  }
  if (value && typeof value === 'object') {
    const normalized = {};
    for (const [key, child] of Object.entries(value)) {
      if (child === undefined || child === null || child === '') {
        continue;
      }
      normalized[key] = normalizePixflowStageBComparableValue(child);
    }
    return normalized;
  }
  return typeof value === 'string' ? normalizeWhitespace(value) : value;
}

function buildPixflowStageBPageSettings(scriptCode, plan = {}) {
  const code = appendPixflowStageBRevealViewportReconciliation(firstString(scriptCode));
  const libraryIds = detectStageBScriptLibraryUsage(code);
  const librarySettings = Object.fromEntries(
    Object.entries(STAGE_B_SCRIPT_LIBRARY_SETTINGS)
      .filter(([, libraryId]) => libraryIds.includes(libraryId))
      .map(([settingKey]) => [settingKey, '1'])
  );
  if (!code) {
    return librarySettings;
  }
  const sourceContract = firstString(
    plan?.conversionPolicy?.sourceContract,
    plan?.source?.sourceContract,
    plan?.sourceContract,
  );
  const fragment = {
    id: sourceContract === 'build-in-bricks-html-first'
      ? 'build-in-bricks-source'
      : 'prototype-bricks-stage-b',
    placement: 'bodyFooter',
    dependencies: libraryIds,
    code,
    runPolicy: 'replace',
  };
  return {
    customScriptsBodyFooter: `<script data-pixflow-fragment="${fragment.id}">\n${code}\n</script>`,
    pixflowScriptFragments: [fragment],
    ...librarySettings,
  };
}

function isPixflowBuildInBricksHtmlFirstPlan(plan) {
  const sourceContract = firstString(
    plan?.conversionPolicy?.sourceContract,
    plan?.source?.sourceContract,
    plan?.sourceContract,
  );
  return sourceContract === 'build-in-bricks-html-first';
}

function isPixflowStageBSourceFidelityClonePlan(plan) {
  // Ordinary Build can still use the uploaded-HTML conversion profile at the
  // deterministic converter boundary. Its explicit HTML-first source contract
  // owns the destination-aware Build semantics and must never inherit the
  // clone-only document/body isolation behaviour merely because the converter
  // profile is shared.
  if (isPixflowBuildInBricksHtmlFirstPlan(plan)) {
    return false;
  }
  if (firstString(
    plan?.conversionPolicy?.conversionProfile,
    plan?.source?.conversionProfile,
    plan?.conversionProfile,
  ).toLowerCase() === 'uploaded_html') {
    return true;
  }
  const stageASource = objectValue(
    plan?.conversionPolicy?.stageASource
      || plan?.conversionPolicy?.stage_a_source
      || plan?.source?.stageASource
      || plan?.source?.stage_a_source
  );
  return stageASource.sourceFidelityClone === true || stageASource.source_fidelity_clone === true;
}

function resolveStageBMeasuredStyleOwnership(plan, snapshotValue) {
  const snapshot = objectValue(snapshotValue);
  if (isPixflowBuildInBricksHtmlFirstPlan(plan)) return 'authored_source';
  if (snapshot.available !== true) return 'fill_missing';
  if (
    isPixflowStageBSourceFidelityClonePlan(plan)
    || ['single_document', 'document_bundle', 'generated_document'].includes(firstString(snapshot.inputKind))
  ) return 'browser_fidelity';
  return 'fill_missing';
}

function applyPixflowStageBSourceFidelityClonePageSettings(pageSettings, plan, headerContent, footerContent) {
  if (!isPixflowStageBSourceFidelityClonePlan(plan)) return;
  // Uploaded HTML is a complete observable page, not content intended to
  // inherit unrelated destination templates. Disable active Bricks templates
  // only when the accepted source did not provide that landmark.
  if (arrayValue(headerContent).length === 0) pageSettings.headerDisabled = '1';
  if (arrayValue(footerContent).length === 0) pageSettings.footerDisabled = '1';
}

function appendPixflowStageBRevealViewportReconciliation(scriptCode) {
  const code = firstString(scriptCode);
  if (!/querySelectorAll\(\s*['"]\.reveal['"]\s*\)|\.reveal/i.test(code) || /pixflowStageBRevealViewportReconciliation/.test(code)) {
    return code;
  }
  const reconciliation = `
;setTimeout(function pixflowStageBRevealViewportReconciliation() {
  var els = document.querySelectorAll('.reveal:not(.is-visible)');
  els.forEach(function (el) {
    var rect = el.getBoundingClientRect();
    if (rect.bottom > 0 && rect.top < window.innerHeight) {
      el.classList.add('is-visible');
    }
  });
}, 160);`;
  return `${code}\n${reconciliation}`;
}

function applyPixflowStageBPageBaseCss(pageSettings, rules, cssVariables, fontOptions = {}, cssText = '', options = {}) {
  const css = buildPixflowStageBPageBaseCss(rules, cssVariables, fontOptions, cssText, options);
  if (!css) {
    return;
  }
  // Pixflow-owned: Stage A prototypes depend on root variables and body/page
  // backgrounds. Bricks sections are otherwise rendered against WP defaults.
  const existing = firstString(pageSettings.customCss);
  pageSettings.customCss = [css, existing].filter(Boolean).join('\n\n');
}

function applyPixflowStageBMeasuredDocumentCss(pageSettings, plan, fontSystem = {}, themeStylePayload = {}) {
  const snapshot = objectValue(objectValue(plan?.sourceEvidence).renderedSnapshot || plan?.renderedSnapshot);
  const viewports = arrayValue(snapshot.viewports);
  const base = viewports.find((viewport) => firstString(viewport?.id) === 'desktop')
    || viewports.find((viewport) => firstString(viewport?.id) === 'bricks_base')
    || viewports[0];
  if (!base) return;
  const variables = Object.fromEntries(
    Object.entries(objectValue(base.variables))
      .filter(([name, value]) => /^--[a-z0-9_-]+$/i.test(name) && firstString(value))
      .slice(0, 400)
  );
  const documentStyles = objectValue(base.documentStyles);
  const htmlStyles = objectValue(documentStyles.html);
  const bodyStyles = objectValue(documentStyles.body);
  const sourceFidelityClone = isPixflowStageBSourceFidelityClonePlan(plan);
  const pageStyles = {};
  if (sourceFidelityClone) {
    for (const property of [
      'font-family', 'font-size', 'font-weight', 'line-height', 'letter-spacing',
      'color', 'background-color', 'background-image', 'min-height',
    ]) {
      const value = firstString(bodyStyles[property], htmlStyles[property]);
      if (!value || value === 'normal' && !['line-height'].includes(property)) continue;
      if (property === 'background-color' && /^(?:transparent|rgba\(0,\s*0,\s*0,\s*0\))$/i.test(value)) continue;
      if (property === 'background-image' && value === 'none') continue;
      pageStyles[property] = value;
    }
  }
  const blocks = [];
  const sourceRootTheme = firstString(plan?.htmlStats?.htmlDataTheme).toLowerCase();
  const sourceColorScheme = firstString(plan?.htmlStats?.htmlColorScheme).toLowerCase();
  if (sourceRootTheme === 'dark' || sourceRootTheme === 'light') {
    const inactiveTheme = sourceRootTheme === 'dark' ? 'light' : 'dark';
    // WordPress cannot persist arbitrary attributes on the document root.
    // Reconcile the common source theme switch without adding runtime JS so
    // theme-gated media layers retain the state captured by source evidence.
    blocks.push(
      `html:not([data-theme]) .media-${sourceRootTheme} { display: block !important; }`,
      `html:not([data-theme]) .media-${inactiveTheme} { display: none !important; }`,
    );
  }
  if (sourceColorScheme === 'dark' || sourceColorScheme === 'light') {
    blocks.push(`html, body, #brx-content { color-scheme: ${sourceColorScheme}; }`);
  }
  const variableBody = serializePixflowCssDeclarations(variables);
  // Pixflow-owned: the HTML snapshot's active root variables must also win on
  // the Bricks content root. Bricks' generated page-variable block targets
  // `#brx-content`, so a later `:root` declaration alone loses on specificity
  // and can leave the canvas on an inactive light/dark theme branch.
  if (variableBody) blocks.push(`:root, #brx-content { ${variableBody} }`);
  const pageBody = serializePixflowCssDeclarations(
    omitPixflowStageBThemeStyleOwnedDeclarations(pageStyles, themeStylePayload, [':root', 'html', 'body']),
    buildPixflowStageBFontMappingOptions(fontSystem),
  );
  if (pageBody) blocks.push(`body, #brx-content { ${pageBody} }`);
  if (sourceFidelityClone) {
    const measuredBodyLayout = (viewport) => {
      const styles = objectValue(objectValue(viewport?.documentStyles).body);
      const declarations = {};
      for (const property of [
        'box-sizing',
        'margin-top', 'margin-right', 'margin-bottom', 'margin-left',
        'padding-top', 'padding-right', 'padding-bottom', 'padding-left',
      ]) {
        const value = firstString(styles[property]);
        if (value && !/[;{}]/.test(value)) declarations[property] = value;
      }
      return declarations;
    };
    const baseBodyLayout = measuredBodyLayout(base);
    const baseBodyLayoutCss = serializePixflowCssDeclarations(baseBodyLayout);
    if (baseBodyLayoutCss) blocks.push(`#brx-content { ${baseBodyLayoutCss} }`);
    const bricksBase = viewports.find((viewport) => firstString(viewport?.id) === 'bricks_base');
    const bricksBaseBodyLayoutCss = serializePixflowCssDeclarations(measuredBodyLayout(bricksBase));
    const mobile = viewports.find((viewport) => firstString(viewport?.id) === 'mobile');
    const mobileBodyLayoutCss = serializePixflowCssDeclarations(measuredBodyLayout(mobile));
    const mobilePortraitMaxWidth = Number(
      arrayValue(plan?.bricksBreakpoints)
        .find((breakpoint) => firstString(breakpoint?.key) === 'mobile_portrait')?.width
        || 478,
    );
    const bricksBaseViewportWidth = Number(bricksBase?.width || 992);
    if (
      bricksBaseBodyLayoutCss
      && bricksBaseBodyLayoutCss !== baseBodyLayoutCss
      && bricksBaseViewportWidth > mobilePortraitMaxWidth
    ) {
      blocks.push(
        `@media (min-width: ${mobilePortraitMaxWidth + 1}px) and (max-width: ${bricksBaseViewportWidth}px) { #brx-content { ${bricksBaseBodyLayoutCss} } }`,
      );
    }
    if (mobileBodyLayoutCss && mobileBodyLayoutCss !== baseBodyLayoutCss) {
      blocks.push(`@media (max-width: ${mobilePortraitMaxWidth}px) { #brx-content { ${mobileBodyLayoutCss} } }`);
    }
  }
  if (blocks.length === 0) return;
  const existing = firstString(pageSettings.customCss);
  pageSettings.customCss = [existing, ...blocks].filter(Boolean).join('\n\n');
}

export function applyPixflowStageBMeasuredDocumentCssForTest({ pageSettings = {}, plan = {}, fontSystem = {}, themeStylePayload = {} } = {}) {
  applyPixflowStageBMeasuredDocumentCss(pageSettings, plan, fontSystem, themeStylePayload);
  return pageSettings;
}

function buildPixflowStageBPageBaseCss(rules, cssVariables = new Map(), fontOptions = {}, cssText = '', options = {}) {
  const variableDeclarations = {};
  const pageDeclarations = {};
  const sourceBodyLayoutDeclarations = {};
  for (const rule of arrayValue(rules)) {
    const selector = firstString(rule?.selector);
    const declarations = objectValue(rule?.declarations);
    if (!selector || Object.keys(declarations).length === 0) {
      continue;
    }
    for (const selectorPart of splitPixflowCssSelectorList(selector)) {
      const normalized = selectorPart.trim().toLowerCase();
      if (normalized === ':root' || normalized === 'html' || normalized === 'body') {
        for (const [property, value] of Object.entries(declarations)) {
          const key = String(property || '').toLowerCase();
          if (key.startsWith('--')) {
            variableDeclarations[property] = value;
          }
        }
      }
      if (normalized === 'html' || normalized === 'body') {
        for (const [property, value] of Object.entries(declarations)) {
          const key = String(property || '').toLowerCase();
          if ([
            'background',
            'background-color',
            'background-image',
            'background-size',
            'background-position',
            'background-repeat',
            'color',
            'font-family',
            'font-size',
            'font-weight',
            'line-height',
            'letter-spacing',
            'min-height',
            'overflow-x',
            'scroll-behavior',
            'text-rendering',
            '-webkit-font-smoothing',
            '-webkit-text-size-adjust',
          ].includes(key)) {
            pageDeclarations[property] = value;
          }
        }
      }
      if (options.sourceFidelityClone === true && normalized === 'body') {
        Object.assign(
          sourceBodyLayoutDeclarations,
          pickPixflowStageBSourceBodyLayoutDeclarations(declarations),
        );
      }
    }
  }
  if (options.sourceFidelityClone === true) {
    // Standalone documents inherit the browser's 16px/normal body defaults;
    // Bricks themes commonly replace both. Website Clone must preserve the
    // observed source baseline instead of inheriting destination typography.
    if (!firstString(pageDeclarations['font-size'])) pageDeclarations['font-size'] = '16px';
    if (!firstString(pageDeclarations['line-height'])) pageDeclarations['line-height'] = 'normal';
    // `html, body { min-height: 100% }` fills the viewport in a standalone
    // document. Bricks inserts another wrapper, where 100% has no definite
    // containing height and can stop at the content. Materialize the same
    // observable geometry as 100vh on the page wrapper.
    if (/^100%$/i.test(firstString(pageDeclarations['min-height']))) {
      pageDeclarations['min-height'] = '100vh';
    }
    if (/^100%$/i.test(firstString(sourceBodyLayoutDeclarations['min-height']))) {
      sourceBodyLayoutDeclarations['min-height'] = '100vh';
    }
  }
  const blocks = [];
  const themeStylePayload = objectValue(options.themeStylePayload);
  const hasPageFoundation = firstString(themeStylePayload.mode) === 'page_foundation'
    && Boolean(firstString(objectValue(objectValue(themeStylePayload.settings).css).stylesheet));
  // The page foundation owns Bricks' wrapper inset when present. Keep this
  // fallback for older/non-foundation compiler consumers only.
  if (!hasPageFoundation) blocks.push('#brx-content { padding: 0; }');
  if (options.sourceFidelityClone === true) {
    // Bricks installations commonly set `html` to 62.5% so 1rem equals 10px.
    // Uploaded standalone HTML is rendered against the browser root (16px
    // unless its stylesheet says otherwise). Preserve that root explicitly;
    // otherwise every source rem value shrinks after an otherwise-correct
    // conversion (4.5rem becomes 45px instead of 72px).
    const sourceRootRemPx = inferStageBRootRemPxFromCss(cssText);
    blocks.push(`html { font-size: ${sourceRootRemPx}px; }`);
  }
  const variableBody = serializePixflowCssDeclarations(variableDeclarations, { cssVariables });
  if (variableBody) {
    blocks.push(`:root { ${variableBody} }`);
  }
  const pageBody = serializePixflowCssDeclarations(
    omitPixflowStageBThemeStyleOwnedDeclarations(
      pageDeclarations,
      themeStylePayload,
      [':root', 'html', 'body'],
    ),
    { cssVariables, ...fontOptions },
  );
  if (pageBody) {
    blocks.push(`body, #brx-content { ${pageBody} }`);
  }
  const sourceBodyLayout = serializePixflowCssDeclarations(
    omitPixflowStageBThemeStyleOwnedDeclarations(sourceBodyLayoutDeclarations, themeStylePayload, ['body']),
    { cssVariables },
  );
  if (sourceBodyLayout) {
    // Bricks owns the real document body. The editable equivalent of the
    // source body box is its page-content wrapper, so clone-only body geometry
    // belongs here instead of being silently dropped or duplicated on every
    // root section.
    blocks.push(`#brx-content { ${sourceBodyLayout} }`);
  }
  const responsiveSourceBodyLayout = options.sourceFidelityClone === true
    ? buildPixflowStageBResponsiveSourceBodyLayoutCss(cssText, cssVariables)
    : '';
  if (responsiveSourceBodyLayout) {
    blocks.push(responsiveSourceBodyLayout);
  }
  const tagDefaults = buildPixflowStageBPageTagDefaultsCss(rules, cssVariables, fontOptions, themeStylePayload);
  if (tagDefaults) {
    blocks.push(tagDefaults);
  }
  const keyframes = extractPixflowStageBKeyframeBlocks(cssText);
  if (keyframes) {
    blocks.push(keyframes);
  }
  return blocks.join('\n');
}

export function buildPixflowStageBPageBaseCssForTest({ cssText = '', conversionProfile = 'uploaded_html' } = {}) {
  const baseCssText = stripPixflowStageBAtRuleBlocks(
    stripPixflowStageBAtRuleBlocks(firstString(cssText), 'media'),
    'container',
  );
  const rules = extractStageBCssRuleSummaries(baseCssText);
  const cssVariables = extractPixflowStageBCssVariables(rules);
  return buildPixflowStageBPageBaseCss(rules, cssVariables, {}, firstString(cssText), {
    sourceFidelityClone: isPixflowStageBSourceFidelityClonePlan({ conversionPolicy: { conversionProfile } }),
  });
}

const PIXFLOW_STAGE_B_SOURCE_BODY_LAYOUT_PROPERTIES = new Set([
  'display',
  'position',
  'inset',
  'top',
  'right',
  'bottom',
  'left',
  'width',
  'min-width',
  'max-width',
  'height',
  'min-height',
  'max-height',
  'margin',
  'margin-block',
  'margin-inline',
  'margin-top',
  'margin-right',
  'margin-bottom',
  'margin-left',
  'padding',
  'padding-block',
  'padding-inline',
  'padding-top',
  'padding-right',
  'padding-bottom',
  'padding-left',
  'box-sizing',
  // The source body is flattened into Bricks' content root. Responsive body
  // typography therefore has no element/class owner and must travel with the
  // same page-scoped projection as responsive body geometry.
  'font-family',
  'font-size',
  'font-style',
  'font-weight',
  'font-variation-settings',
  'line-height',
  'letter-spacing',
  'text-align',
  'text-transform',
  'text-wrap',
  'white-space',
  'color',
]);

function pickPixflowStageBSourceBodyLayoutDeclarations(declarations) {
  return Object.fromEntries(Object.entries(objectValue(declarations))
    .filter(([property, value]) => (
      PIXFLOW_STAGE_B_SOURCE_BODY_LAYOUT_PROPERTIES.has(String(property || '').toLowerCase())
      && Boolean(firstString(value))
    )));
}

function buildPixflowStageBResponsiveSourceBodyLayoutCss(cssText, cssVariables = new Map()) {
  const source = stripStageBCssComments(cssText);
  const blocks = [];
  const pattern = /@media\s*([^{]+)\{/gi;
  let match;
  while ((match = pattern.exec(source)) !== null) {
    const condition = normalizeWhitespace(match[1] || '');
    const openIndex = source.lastIndexOf('{', pattern.lastIndex - 1);
    const closeIndex = openIndex >= 0 ? findPixflowCssBlockClose(source, openIndex) : -1;
    if (!condition || openIndex < 0 || closeIndex <= openIndex) continue;
    pattern.lastIndex = closeIndex + 1;
    const declarations = {};
    for (const rule of extractStageBCssRuleSummaries(source.slice(openIndex + 1, closeIndex))) {
      if (splitPixflowCssSelectorList(rule.selector || '')
        .some((selector) => selector.trim().toLowerCase() === 'body')) {
        Object.assign(declarations, pickPixflowStageBSourceBodyLayoutDeclarations(rule.declarations));
      }
    }
    const body = serializePixflowCssDeclarations(declarations, { cssVariables });
    if (body) blocks.push(`@media ${condition} { #brx-content { ${body} } }`);
  }
  return blocks.join('\n');
}

function pixflowStageBThemeStyleOwnsDeclaration(themeStylePayload, selector, property) {
  const wantedSelector = firstString(selector).trim().toLowerCase();
  const wantedProperty = firstString(property).trim().toLowerCase();
  if (!wantedSelector || !wantedProperty || firstString(themeStylePayload?.mode) !== 'page_foundation') {
    return false;
  }
  return arrayValue(themeStylePayload?.ownership?.declarations).some((item) => (
    firstString(item?.selector).trim().toLowerCase() === wantedSelector
    && firstString(item?.property).trim().toLowerCase() === wantedProperty
    && ['theme_style_native_control', 'theme_style_stylesheet'].includes(firstString(item?.destination))
  ));
}

function omitPixflowStageBThemeStyleOwnedDeclarations(declarations, themeStylePayload, selectors) {
  const selectorList = arrayValue(selectors).map((selector) => firstString(selector).trim().toLowerCase()).filter(Boolean);
  return Object.fromEntries(Object.entries(objectValue(declarations)).filter(([property]) => (
    !selectorList.some((selector) => pixflowStageBThemeStyleOwnsDeclaration(themeStylePayload, selector, property))
  )));
}

function buildPixflowStageBPageTagDefaultsCss(rules, cssVariables = new Map(), fontOptions = {}, themeStylePayload = {}) {
  const allowedTags = new Set([
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'a', 'ul', 'ol', 'menu',
    'blockquote', 'dd', 'dl', 'figure', 'hr', 'p', 'pre',
  ]);
  const allowedProperties = new Set([
    'font-family',
    'font-weight',
    'font-size',
    'line-height',
    'letter-spacing',
    'color',
    'text-decoration',
    'text-transform',
    'list-style',
    // Source resets (notably Tailwind preflight) neutralize browser default
    // margins on figure/blockquote/headings. Bricks does not reproduce those
    // resets automatically, so preserve them at the page-owned tag boundary.
    'margin',
    'padding',
  ]);
  const blocks = [];
  for (const rule of arrayValue(rules)) {
    const selectorParts = splitPixflowCssSelectorList(firstString(rule?.selector));
    if (selectorParts.length === 0) {
      continue;
    }
    const normalizedParts = selectorParts.map((part) => part.trim().toLowerCase());
    if (!normalizedParts.every((part) => allowedTags.has(part))) {
      continue;
    }
    const declarations = {};
    for (const [property, value] of Object.entries(objectValue(rule?.declarations))) {
      const key = String(property || '').toLowerCase();
      const ownedByFoundation = normalizedParts.every((selector) => (
        pixflowStageBThemeStyleOwnsDeclaration(themeStylePayload, selector, key)
      ));
      if (allowedProperties.has(key) && !ownedByFoundation) {
        declarations[property] = value;
      }
    }
    const body = serializePixflowCssDeclarations(declarations, { cssVariables, ...fontOptions });
    if (!body) {
      continue;
    }
    const scopedSelector = normalizedParts.map((tag) => `:where(#brx-content) :where(${tag})`).join(', ');
    blocks.push(`${scopedSelector} { ${body} }`);
  }
  return blocks.join('\n');
}

function applyPixflowStageBInlineMarkupPageCss(pageSettings, elementGroups, classInfo) {
  const inlineClassNames = collectStageBInlineMarkupClassNames(
    (Array.isArray(elementGroups) ? elementGroups : []).flatMap((group) => arrayValue(group))
  );
  if (inlineClassNames.length === 0) {
    return;
  }
  const css = buildPixflowStageBInlineMarkupPageCss(inlineClassNames, classInfo);
  if (!css) {
    return;
  }
  const existing = firstString(pageSettings.customCss);
  pageSettings.customCss = [css, existing].filter(Boolean).join('\n\n');
}

function buildPixflowStageBInlineMarkupPageCss(classNames, classInfo) {
  const rules = [];
  const declarationsByClass = classInfo?.declarationsByClass instanceof Map ? classInfo.declarationsByClass : new Map();
  const customRulesByClass = classInfo?.customRulesByClass instanceof Map ? classInfo.customRulesByClass : new Map();
  const cssVariables = classInfo?.cssVariables instanceof Map ? classInfo.cssVariables : new Map();
  for (const className of uniqueStrings(classNames)) {
    const declarations = objectValue(declarationsByClass.get(className));
    const body = serializePixflowCssDeclarations(declarations, { cssVariables });
    if (body) {
      rules.push(`${buildPixflowStageBCssClassSelector(className)} { ${body} }`);
    }
    for (const customRule of arrayValue(customRulesByClass.get(className))) {
      const unscoped = firstString(customRule).replace(/%root%/g, buildPixflowStageBCssClassSelector(className));
      if (unscoped) {
        rules.push(unscoped);
      }
    }
    for (const sourceRule of arrayValue(classInfo?.rules)) {
      if (!arrayValue(sourceRule?.classNames).includes(className)) continue;
      const selectorParts = splitPixflowCssSelectorList(firstString(sourceRule?.selector));
      const inlineSelector = buildPixflowStageBCssClassSelector(className);
      if (selectorParts.length === 0 || selectorParts.every((selector) => selector.trim() === inlineSelector)) continue;
      const sourceBody = serializePixflowCssDeclarations(sourceRule?.declarations, { cssVariables });
      if (!sourceBody) continue;
      const scopedSelectors = selectorParts.map((selector) => (
        /^#brx-content\b/i.test(selector.trim()) ? selector.trim() : `#brx-content ${selector.trim()}`
      ));
      // The inline mark remains inside one editable Bricks heading/text value;
      // it cannot receive the descendant source class as a separate Bricks
      // element. Preserve the authored relationship at page scope instead.
      rules.push(`${scopedSelectors.join(', ')} { ${sourceBody} }`);
    }
  }
  return uniqueStrings(rules).join('\n');
}

export function buildPixflowStageBInlineMarkupPageCssForTest({ html = '', cssText = '', classNames = [] } = {}) {
  const summaries = extractStageBCssRuleSummaries(
    stripPixflowStageBAtRuleBlocks(
      stripPixflowStageBAtRuleBlocks(cssText, 'media'),
      'container',
    ),
  );
  const classInfo = buildPixflowStageBHtmlClassInfo(html, cssText, summaries);
  return buildPixflowStageBInlineMarkupPageCss(classNames, classInfo);
}

function buildPixflowStageBHtmlClassInfo(html, cssText, rules, options = {}) {
  const usage = extractStageBClassUsage(html);
  const usageByClass = new Map(usage.map((item) => [item.name, item]));
  const allowedUtilityClassSet = new Set(stringArrayFromUnknown(options.allowedUtilityClasses));
  const utilityClassTargetByName = extractPixflowStageBUtilityClassTargets(html, {
    allowedUtilityClasses: allowedUtilityClassSet,
  });
  const idUsage = extractStageBIdUsage(html);
  const nestedInlineClassesByClass = extractPixflowStageBNestedInlineClassesByClass(html);
  const rawClassNames = uniqueStrings([
    ...usage.map((item) => item.name),
    ...rules.flatMap((rule) => rule.classNames || []),
  ]).filter((name) => !/^od-root$/i.test(name));
  // Every source class must be a first-class Bricks class. Previously the
  // converter collapsed utility-looking classes into a sibling source class
  // or carried allowlisted utilities through `_attributes[name="class"]`.
  // That rendered the class in HTML, but hid it in Bricks' class controls and
  // could merge unrelated declarations into classes such as `.container`.
  const classNames = rawClassNames;
  const preservedUtilityClasses = classNames.filter((className) => allowedUtilityClassSet.has(className));
  const idNames = uniqueStrings([
    ...idUsage.map((item) => item.name),
    ...rules.flatMap((rule) => rule.idNames || []),
  ]);
  const cssVariables = extractPixflowStageBCssVariables(rules);
  const compatibilityContext = objectValue(options.compatibilityContext).schema
    ? objectValue(options.compatibilityContext)
    : resolvePixflowBricksCompatibilityContext({ breakpoints: options.breakpoints });
  const compatibilityDiagnostics = [];
  const fontOptions = {
    ...buildPixflowStageBFontMappingOptions(options.fontSystem),
    compatibilityContext,
    compatibilityDiagnostics,
  };
  const bricksBreakpoints = normalizePixflowStageBBricksBreakpoints(options.breakpoints);
  const responsiveFallbackSuffix = pixflowStageBSmallestBreakpointSuffix(bricksBreakpoints);
  const responsiveRulesByClass = extractPixflowStageBResponsiveClassRules(cssText, classNames, cssVariables, {
    breakpoints: bricksBreakpoints,
  });
  const responsiveRulesByElement = extractPixflowStageBResponsiveElementRules(cssText, cssVariables, {
    breakpoints: bricksBreakpoints,
  });
  const tagDeclarationsByTag = extractPixflowStageBTagDeclarations(rules);
  const inheritedTextDeclarations = pickPixflowStageBInheritedTextDeclarations({
    ...objectValue(tagDeclarationsByTag.get('html')),
    ...objectValue(tagDeclarationsByTag.get('body')),
  });
  const hasSourceFormControls = /<(?:form|input|textarea|select)\b/i.test(String(html || ''));
  const syntheticClassIdByKey = new Map();
  const inlineStyleClassIdBySignature = new Map();
  const descendantElementClassIdByKey = new Map();
  const descendantElementClassRules = [];
  const descendantClassIdByKey = new Map();
  const structuralClassRules = [];
  const syntheticGlobalClasses = [];
  const lateSyntheticGlobalClasses = [];
  const usedPublicNames = new Set();
  const sourceClassNaming = buildStageBSourceClassNamePlan(classNames, {
    existingGlobalClasses: options.existingGlobalClasses,
    sourceId: options.sourceId,
    title: options.title,
  });
  const classPlanner = createPixflowStageBClassNamePlanner({
    existingGlobalClasses: options.existingGlobalClasses,
    sourceId: options.sourceId,
    title: options.title,
    sourcePrefix: sourceClassNaming.prefix,
    // Preserve every authored source name until the planner has both the
    // source settings and live Bricks class settings. It can then reuse an
    // empty/identical class or rename only the incompatible collision. The
    // older pre-plan prefixed a whole guessed BEM block before compatibility
    // was known and hid the actual collision reason from the report.
    sourceClassNamePlan: new Map(),
    preservedUtilityClasses,
  });
  const addSyntheticClass = (key, preferredName, settings) => {
    if (Object.keys(objectValue(settings)).length === 0) {
      return '';
    }
    const planned = classPlanner.claimPreferred(preferredName, {
      kind: 'synthetic',
      key,
      sourceName: preferredName,
      settings,
      idSeed: `stage-b-html-synthetic-class:${key}`,
    });
    const id = planned.id;
    syntheticClassIdByKey.set(key, id);
    syntheticGlobalClasses.push({ id, name: planned.name, settings });
    return id;
  };
  const addLateSyntheticClass = (key, preferredName, settings) => {
    if (Object.keys(objectValue(settings)).length === 0) {
      return '';
    }
    const planned = classPlanner.claimPreferred(preferredName, {
      kind: 'late-synthetic',
      key,
      sourceName: preferredName,
      settings,
      idSeed: `stage-b-html-synthetic-class:${key}`,
    });
    const id = planned.id;
    syntheticClassIdByKey.set(key, id);
    lateSyntheticGlobalClasses.push({ id, name: planned.name, settings });
    return id;
  };

  // Browser/semantic defaults are page-foundation concerns. They must not be
  // materialized as public global classes on every converted element: doing
  // so obscures source class ownership and can outrank later authored tag
  // rules. The scoped page-foundation stylesheet below neutralizes Bricks at
  // lower specificity, while source classes remain editable native controls.
  addSyntheticClass('template:header-root', 'pixflow-template-header-reset', {
    _padding: { top: '0', right: '0', bottom: '0', left: '0' },
  });
  addSyntheticClass('template:footer-root', 'pixflow-template-footer-reset', {
    _padding: { top: '0', right: '0', bottom: '0', left: '0' },
  });
  if (hasSourceFormControls) {
    addLateSyntheticClass('form:hidden-submit', 'pixflow-form-hidden-submit', {
      // Pixflow-owned: Bricks form elements always render a submit wrapper. This
      // class preserves source standalone input controls, such as search fields,
      // without introducing an extra visible button.
      _cssCustom: '%root% .submit-button-wrapper { display: none; }',
    });
    addLateSyntheticClass('form:hidden-labels', 'pixflow-form-hidden-labels', {
      // Pixflow-owned: Bricks generates field labels even for source controls
      // that were intentionally placeholder-only. Hide only the generated form
      // labels; source-authored labels remain separate editable text elements.
      _cssCustom: '%root% .form-group > label { display: none; }',
    });
  }

  const simpleClassCascade = resolvePixflowSimpleClassCascade({ rules, usageByClass });
  const declarationsByClass = simpleClassCascade.declarationsByClass;
  const plateDeclarations = declarationsByClass.get('plate');
  if (plateDeclarations) {
    delete plateDeclarations.border;
    delete plateDeclarations['border-color'];
    delete plateDeclarations['border-style'];
    delete plateDeclarations['border-width'];
  }
  const customRulesByClass = new Map();
  const stateSettingsByClass = new Map();
  const declarationsById = new Map();
  const customRulesById = new Map();

  for (const rule of rules) {
    const classNamesForRule = Array.isArray(rule.classNames) ? rule.classNames : [];
    for (const sourceClassName of classNamesForRule) {
      const className = sourceClassName;
      if (!classNames.includes(className)) continue;
      const stateSettings = buildPixflowStageBClassStateSettings(rule, sourceClassName, cssVariables);
      if (Object.keys(stateSettings).length > 0) {
        mergePixflowStageBSettings(
          stateSettingsByClass.get(className) || stateSettingsByClass.set(className, {}).get(className),
          stateSettings,
        );
      }
      const customRule = isPixflowStageBFullyMappableDescendantClassRule(rule, cssVariables)
        || isPixflowStageBFullyMappableDescendantElementRule(rule, cssVariables)
        || isPixflowStageBFullyMappableMixedSimpleDescendantElementRule(rule, cssVariables)
        || isPixflowStageBFullyMappableStructuralClassRule(rule, cssVariables)
        || isPixflowStageBFullyMappableMixedSimpleStructuralClassRule(rule, cssVariables)
        ? ''
        : convertPixflowStageBCssRuleToRoot(rule, sourceClassName, cssVariables);
      if (customRule) {
        const list = customRulesByClass.get(className) || [];
        list.push(customRule);
        customRulesByClass.set(className, list);
      }
    }
    for (const idName of Array.isArray(rule.idNames) ? rule.idNames : []) {
      if (!idNames.includes(idName)) continue;
      if (isPixflowStageBSimpleIdSelector(rule.selector, idName) && !declarationsById.has(idName)) {
        declarationsById.set(idName, { ...objectValue(rule.declarations) });
      }
      const customRule = convertPixflowStageBIdCssRuleToRoot(rule, idName, cssVariables);
      if (customRule) {
        const list = customRulesById.get(idName) || [];
        list.push(customRule);
        customRulesById.set(idName, list);
      }
    }
  }

  const responsiveFallbackRulesByClass = extractPixflowStageBResponsiveFallbackRulesByClass(
    cssText,
    classNames,
    cssVariables,
  );
  for (const [className, fallbackRules] of responsiveFallbackRulesByClass) {
    const list = customRulesByClass.get(className) || [];
    list.push(...fallbackRules);
    customRulesByClass.set(className, list);
  }

  const containerQueryFallbackRulesByClass = extractPixflowStageBContainerQueryFallbackRulesByClass(
    cssText,
    classNames,
    cssVariables,
  );
  for (const [className, fallbackRules] of containerQueryFallbackRulesByClass) {
    const list = customRulesByClass.get(className) || [];
    list.push(...fallbackRules);
    customRulesByClass.set(className, list);
  }

  // Pixflow-owned: simple source selectors such as `.hero h1` and
  // `.card img` are routine element styling, not decorative CSS. Attach a
  // deterministic helper class to the matching Bricks child element so Bricks
  // element defaults cannot override the source typography/media controls.
  const descendantElementStyles = buildPixflowStageBDescendantElementStyleMap(rules, cssVariables, {
    ...fontOptions,
    inheritedTextDeclarations,
    tagDeclarationsByTag,
  });
  for (const responsiveKey of responsiveRulesByElement.keys()) {
    if (!responsiveKey.startsWith('descendant:')) continue;
    const key = responsiveKey.slice('descendant:'.length);
    if (descendantElementStyles.has(key)) continue;
    const separator = key.lastIndexOf('|');
    if (separator <= 0) continue;
    const relationParts = key.slice(0, separator).split('>>');
    descendantElementStyles.set(key, {
      ancestorClass: relationParts.at(-1),
      requiredAncestorClass: relationParts.length > 1 ? relationParts[0] : '',
      tag: key.slice(separator + 1),
      settings: {},
    });
  }
  for (const [key, item] of descendantElementStyles.entries()) {
    const settings = objectValue(item.settings);
    applyPixflowStageBResponsiveSettings(settings, [`descendant:${key}`], {
      responsiveRulesByClass: responsiveRulesByElement,
    });
    if (Object.keys(settings).length === 0) {
      continue;
    }
    const preferredName = `pixflow-source-${item.requiredAncestorClass ? `${slugify(item.requiredAncestorClass)}-` : ''}${slugify(item.ancestorClass)}-${slugify(item.tag)}${item.structuralPseudo ? `-${slugify(item.structuralPseudo)}` : ''}${item.excludedClass ? `-except-${slugify(item.excludedClass)}` : ''}${item.state ? `-${slugify(item.state)}` : ''}-style`;
    const planned = classPlanner.claimPreferred(preferredName, {
      kind: 'descendant-style',
      key,
      sourceName: preferredName,
      settings,
      idSeed: `stage-b-html-descendant-element:${key}`,
    });
    const id = planned.id;
    descendantElementClassIdByKey.set(key, id);
    descendantElementClassRules.push({ ...item, id });
    lateSyntheticGlobalClasses.push({ id, name: planned.name, settings });
  }

  const structuralClassStyles = buildPixflowStageBStructuralClassStyleMap(rules, cssVariables);
  for (const responsiveKey of responsiveRulesByElement.keys()) {
    if (!responsiveKey.startsWith('structural:')) continue;
    const key = responsiveKey.slice('structural:'.length);
    if (structuralClassStyles.has(key)) continue;
    const separator = key.indexOf('|');
    if (separator <= 0 || separator >= key.length - 1) continue;
    structuralClassStyles.set(key, {
      sourceClass: key.slice(0, separator),
      structuralPseudo: key.slice(separator + 1),
      settings: {},
    });
  }
  for (const [key, item] of structuralClassStyles.entries()) {
    const settings = objectValue(item.settings);
    applyPixflowStageBResponsiveSettings(settings, [`structural:${key}`], {
      responsiveRulesByClass: responsiveRulesByElement,
    });
    if (Object.keys(settings).length === 0) continue;
    const preferredName = `pixflow-source-${slugify(item.sourceClass)}-${slugify(item.structuralPseudo)}-style`;
    const planned = classPlanner.claimPreferred(preferredName, {
      kind: 'structural-class-style',
      key,
      sourceName: preferredName,
      settings,
      idSeed: `stage-b-html-structural-class:${key}`,
    });
    structuralClassRules.push({ ...item, id: planned.id });
    lateSyntheticGlobalClasses.push({ id: planned.id, name: planned.name, settings });
  }

  // Pixflow-owned: descendant-class rules are scoped relationships, not
  // declarations on the shared descendant class. Lift both base and responsive
  // rules into one helper attached only when both sides of the relationship
  // match. This also avoids stale source selectors after Bricks class renaming.
  const descendantClassStyles = buildPixflowStageBDescendantClassStyleMap(rules, cssVariables, fontOptions);
  for (const responsiveKey of responsiveRulesByElement.keys()) {
    if (!responsiveKey.startsWith('descendant-class:')) continue;
    const key = responsiveKey.slice('descendant-class:'.length);
    if (descendantClassStyles.has(key)) continue;
    const separator = key.indexOf('|');
    if (separator <= 0 || separator >= key.length - 1) continue;
    descendantClassStyles.set(key, {
      ancestorClass: key.slice(0, separator),
      descendantClass: key.slice(separator + 1),
      settings: {},
    });
  }
  for (const [key, item] of descendantClassStyles.entries()) {
    const settings = objectValue(item.settings);
    applyPixflowStageBResponsiveSettings(settings, [`descendant-class:${key}`], {
      responsiveRulesByClass: responsiveRulesByElement,
    });
    if (Object.keys(settings).length === 0) continue;
    const preferredName = `pixflow-source-${slugify(item.ancestorClass)}-${slugify(item.descendantClass)}-style`;
    const planned = classPlanner.claimPreferred(preferredName, {
      kind: 'descendant-class-style',
      key,
      sourceName: preferredName,
      settings,
      idSeed: `stage-b-html-descendant-class:${key}`,
    });
    descendantClassIdByKey.set(key, planned.id);
    lateSyntheticGlobalClasses.push({ id: planned.id, name: planned.name, settings });
  }

  const workContainerShellSettings = buildPixflowStageBWorkContainerShellSettings(
    declarationsByClass.get('work'),
    declarationsByClass.get('section'),
    declarationsByClass.get('section-dark'),
    responsiveRulesByClass,
    cssVariables,
    fontOptions,
  );
  const shouldTransferWorkSectionShell = hasStageBTopBottomPadding(workContainerShellSettings);
  addLateSyntheticClass('work:container-shell', 'work-container-shell', workContainerShellSettings);

  const universalBorderStyle = firstString(...rules
    .filter((rule) => splitPixflowCssSelectorList(firstString(rule?.selector)).some((selector) => (
      /^(?:\*|::?before|::?after)$/i.test(selector.trim())
    )))
    .map((rule) => objectValue(rule?.declarations)['border-style']));

  const sourceGlobalClasses = classNames.map((className) => {
    const sourceDeclarations = declarationsByClass.get(className) || {};
    const declarations = firstString(sourceDeclarations['border-width'])
      && !firstString(sourceDeclarations['border-style'])
      && universalBorderStyle
      ? { ...sourceDeclarations, 'border-style': universalBorderStyle }
      : sourceDeclarations;
    const settings = mapPixflowCssDeclarationsToBricksSettings(declarations, {
      cssVariables,
      ...fontOptions,
      responsiveFallbackSuffix,
      preferFlexForGridCenter: shouldUsePixflowStageBFlexForInlineGridCenter(usageByClass.get(className), declarations),
    });
    mergePixflowStageBSettings(settings, stateSettingsByClass.get(className));
    applyPixflowStageBInheritedControlTypography(settings, className, usageByClass.get(className), {
      inheritedTextDeclarations,
      cssVariables,
      fontOptions,
    });
    // Heading tag typography belongs to the semantic heading owner above.
    // Copying those defaults into every source class used on a heading makes
    // class order destructive: a later `.font-bold` class carrying
    // `font-size: inherit`, for example, overrides an earlier authored
    // `.text-[2.75rem]` class. Source classes must own only declarations from
    // their own selectors so utility classes remain composable.
    applyPixflowStageBDefaultSourceDisplay(settings, className, declarations, usageByClass.get(className));
    applyPixflowStageBMaxWidthBlockFill(settings, declarations, usageByClass.get(className));
    applyPixflowStageBUtilityDisplayDefaults(settings);
    applyPixflowStageBResponsiveSettings(settings, [className], { responsiveRulesByClass });
    const singleAxisGapCompatibilityRules = applyPixflowStageBSingleAxisGapCompatibility(
      settings,
      declarations,
      responsiveRulesByClass.get(className),
      cssVariables,
    );
    if (className === 'work' && shouldTransferWorkSectionShell) {
      removePixflowStageBWorkSectionShellSettings(settings);
      applyPixflowStageBWorkSectionWrapperReset(settings);
    }
    applyPixflowStageBClassStyleHeuristics(settings, [className]);
    const customRules = [
      ...(customRulesByClass.get(className) || []),
      ...singleAxisGapCompatibilityRules,
    ];
    if (className === 'section') {
      const revealCss = buildPixflowStageBRevealCss(cssText);
      if (revealCss) customRules.push(revealCss);
    }
    if (className === 'marquee-track') {
      const keyframes = extractPixflowStageBKeyframes(cssText, 'marquee-x');
      if (keyframes) customRules.push(keyframes);
    }
    if (className === 'section-dark') {
      const themeVariableOverride = buildPixflowStageBDarkSectionThemeVariableOverride(declarations);
      if (themeVariableOverride) customRules.push(themeVariableOverride);
    }
    customRules.push(...buildPixflowStageBNestedInlineClassCustomRules(
      className,
      nestedInlineClassesByClass.get(className),
      declarationsByClass,
      cssVariables,
    ));
    const uniqueCustomRules = [...new Set(customRules.map((rule) => String(rule || '').trim()).filter(Boolean))];
    if (uniqueCustomRules.length > 0) {
      settings._cssCustom = uniqueCustomRules.join('\n');
    }
    applyPixflowStageBPolymorphicAlignmentFallback(settings);
    const planned = classPlanner.claimSourceClass(className, {
      settings,
      usage: usageByClass.get(className),
      idSeed: `stage-b-html-class:${className}`,
    });
    return {
      id: planned.id,
      name: planned.name,
      settings,
    };
  });
  const globalClasses = [...syntheticGlobalClasses, ...sourceGlobalClasses, ...lateSyntheticGlobalClasses];
  const sourceClassIdByName = new Map(classNames.map((className, index) => [className, sourceGlobalClasses[index].id]));
  const sourceClassNameByClassId = new Map(classNames.map((className, index) => [sourceGlobalClasses[index].id, className]));
  const sourceIdGlobalClasses = idNames.map((idName) => {
    const declarations = declarationsById.get(idName) || {};
    const settings = mapPixflowCssDeclarationsToBricksSettings(declarations, { cssVariables, ...fontOptions });
    const customRules = [...(customRulesById.get(idName) || [])];
    const uniqueCustomRules = [...new Set(customRules.map((rule) => String(rule || '').trim()).filter(Boolean))];
    if (uniqueCustomRules.length > 0) {
      settings._cssCustom = uniqueCustomRules.join('\n');
    }
    const preferredName = `pixflow-source-id-${slugify(idName)}`;
    const planned = classPlanner.claimPreferred(preferredName, {
      kind: 'id-selector',
      key: idName,
      sourceName: idName,
      settings,
      idSeed: `stage-b-html-id:${idName}`,
    });
    return {
      id: planned.id,
      name: planned.name,
      settings,
    };
  }).filter((classItem) => Object.keys(objectValue(classItem.settings)).length > 0);
  globalClasses.splice(syntheticGlobalClasses.length + sourceGlobalClasses.length, 0, ...sourceIdGlobalClasses);
  const sourceIdClassIdByName = new Map(sourceIdGlobalClasses.map((classItem) => [
    firstString(classItem.name).replace(/^(?:stage-a|pixflow-source)-id-/, ''),
    classItem.id,
  ]));
  for (const idName of idNames) {
    const id = deterministicBricksId(`stage-b-html-id:${idName}`);
    if (sourceIdGlobalClasses.some((classItem) => classItem.id === id)) {
      sourceIdClassIdByName.set(idName, id);
    }
  }

  return {
    usage,
    cssText,
    rules,
    classNames,
    rawClassNames,
    preservedUtilityClasses,
    allowedUtilityClasses: [...allowedUtilityClassSet],
    utilityClassTargetByName,
    usageByClass,
    globalClasses,
    declarationsByClass,
    declarationsById,
    responsiveRulesByClass,
    customRulesByClass,
    customRulesById,
    cssVariables,
    tagDeclarationsByTag,
    inheritedTextDeclarations,
    syntheticClassIdByKey,
    inlineStyleClassIdBySignature,
    descendantElementClassIdByKey,
    descendantElementClassRules,
    descendantClassIdByKey,
    structuralClassRules,
    classPlanner,
    classOwnershipPlan: classPlanner.toPlan(),
    sourceClassNameByClassId,
    classIdByName: sourceClassIdByName,
    idClassIdByName: sourceIdClassIdByName,
    compatibilityContext,
    compatibilityDiagnostics,
    cascadeDecisions: simpleClassCascade.decisions,
  };
}

function parsePixflowStageBHtmlDocument(html) {
  const source = String(html || '');
  const root = {
    type: 'root',
    tag: '#document',
    attrs: {},
    attrList: [],
    children: [],
    parent: null,
    sourceIndex: 0,
    contentStart: 0,
    contentEnd: source.length,
  };
  const stack = [root];
  const voidTags = new Set(['area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr']);
  let match;
  let lastIndex = 0;
  let searchIndex = 0;
  let sourceIndex = 1;

  while ((match = findNextPixflowStageBHtmlToken(source, searchIndex)) !== null) {
    const token = match.token;
    if (match.index > lastIndex) {
      appendPixflowStageBHtmlText(stack[stack.length - 1], source.slice(lastIndex, match.index), sourceIndex++);
    }
    lastIndex = match.end;
    searchIndex = match.end;
    if (/^<!--/.test(token) || /^<!doctype/i.test(token)) {
      continue;
    }
    if (/^<\s*\//.test(token)) {
      const closingTag = (token.match(/^<\s*\/\s*([a-zA-Z0-9:-]+)/) || [])[1]?.toLowerCase();
      if (closingTag) {
        for (let index = stack.length - 1; index > 0; index -= 1) {
          const node = stack[index];
          node.contentEnd = match.index;
          if (node.tag === closingTag) {
            stack.length = index;
            break;
          }
        }
      }
      continue;
    }

    const open = token.match(/^<\s*([a-zA-Z0-9:-]+)([\s\S]*?)(\/?)>$/);
    if (!open) {
      continue;
    }
    const tag = String(open[1] || '').toLowerCase();
    const attrText = open[2] || '';
    const attrList = parsePixflowStageBHtmlAttributes(attrText);
    const attrs = {};
    for (const attr of attrList) {
      attrs[attr.name.toLowerCase()] = attr.value;
    }
    const node = {
      type: 'element',
      tag,
      attrs,
      attrList,
      children: [],
      parent: stack[stack.length - 1],
      sourceIndex: sourceIndex++,
      openTag: token,
      contentStart: match.end,
      contentEnd: match.end,
    };
    stack[stack.length - 1].children.push(node);
    const selfClosing = Boolean(open[3]) || voidTags.has(tag);
    if (selfClosing) {
      continue;
    }

    stack.push(node);

    // HTML script/style/textarea contents are raw text. The lightweight
    // parser intentionally avoids a browser DOM dependency, so it must still
    // advance over those bodies as a unit; otherwise JSX, JSON, or JavaScript
    // strings containing markup can be mistaken for real descendants and
    // swallow the rest of the document (including the page's <main>).
    if (['script', 'style', 'textarea'].includes(tag)) {
      const closingPattern = new RegExp(`</\\s*${tag}\\s*>`, 'ig');
      closingPattern.lastIndex = match.end;
      const closingMatch = closingPattern.exec(source);
      const rawEnd = closingMatch ? closingMatch.index : source.length;
      if (rawEnd > match.end) {
        appendPixflowStageBHtmlText(node, source.slice(match.end, rawEnd), sourceIndex++);
      }
      node.contentEnd = rawEnd;
      if (closingMatch) {
        searchIndex = closingMatch.index + closingMatch[0].length;
        lastIndex = searchIndex;
      } else {
        searchIndex = source.length;
        lastIndex = searchIndex;
      }
      stack.pop();
    }
  }

  if (lastIndex < source.length) {
    appendPixflowStageBHtmlText(stack[stack.length - 1], source.slice(lastIndex), sourceIndex++);
  }
  while (stack.length > 1) {
    const node = stack.pop();
    node.contentEnd = source.length;
  }
  root.rawHtml = source;
  return root;
}

function findNextPixflowStageBHtmlToken(source, fromIndex = 0) {
  const opener = /<(?=!--|!doctype\b|\/?\s*[a-zA-Z][a-zA-Z0-9:-]*)/gi;
  opener.lastIndex = Math.max(0, Number(fromIndex) || 0);
  const openingMatch = opener.exec(String(source || ''));
  if (!openingMatch) return null;
  const index = openingMatch.index;
  if (source.startsWith('<!--', index)) {
    const commentEnd = source.indexOf('-->', index + 4);
    const end = commentEnd === -1 ? source.length : commentEnd + 3;
    return { token: source.slice(index, end), index, end };
  }

  let quote = '';
  for (let cursor = index + 1; cursor < source.length; cursor += 1) {
    const char = source[cursor];
    if (quote) {
      if (char === quote) quote = '';
      continue;
    }
    if (char === '"' || char === "'") {
      quote = char;
      continue;
    }
    if (char === '>') {
      const end = cursor + 1;
      return { token: source.slice(index, end), index, end };
    }
  }
  return null;
}

function appendPixflowStageBHtmlText(parent, text, sourceIndex) {
  if (!text) return;
  parent.children.push({
    type: 'text',
    text,
    children: [],
    parent,
    sourceIndex,
  });
}

function parsePixflowStageBHtmlAttributes(attrText) {
  const attrs = [];
  const pattern = /([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
  let match;
  while ((match = pattern.exec(String(attrText || ''))) !== null) {
    const name = String(match[1] || '').trim();
    if (!name || name === '/') continue;
    const value = match[2] !== undefined ? match[2] : (match[3] !== undefined ? match[3] : (match[4] !== undefined ? match[4] : ''));
    attrs.push({ name, value: decodeHtmlEntities(value) });
  }
  return attrs;
}

function createPixflowStageBHtmlCompilerContext({
  scope,
  plan,
  classInfo,
  iconSystem,
  sourceRoots = [],
  runtimeEvidenceBySourceId = {},
  compatibilityContext = {},
  usedElementIds = new Set(),
}) {
  const structureIr = buildPixflowHtmlStructureIr({
    scope,
    roots: sourceRoots,
    runtimeEvidenceBySourceId,
  });
  return {
    scope,
    plan,
    classInfo,
    iconSystem: iconSystem || {},
    conversionPolicy: summarizeStageBConversionPolicy(plan?.conversionPolicy || {}),
    content: [],
    elementsById: new Map(),
    usedElementIds,
    structureIr,
    structureRecorder: createPixflowStructureProjectionRecorder({
      ir: structureIr,
      compatibilityContext,
    }),
  };
}

function isPixflowStageBFlattenedMainBoundary(node) {
  if (firstString(node?.tag).toLowerCase() !== 'main') return false;
  const parentTag = firstString(node?.parent?.tag).toLowerCase();
  return ['html', 'body'].includes(parentTag) || isPixflowStageBPageWrapper(node?.parent);
}

function compilePixflowStageBHtmlNode(node, parentId, context, options = {}) {
  if (!node) return '';
  if (node.type === 'text') {
    const decodedText = decodeHtmlEntities(node.text);
    const normalizedText = normalizeWhitespace(decodedText);
    if (!normalizedText) return '';
    if (!parentId) {
      context.structureRecorder.recordDisposition(
        node,
        'omitted',
        'unparented_source_text_cannot_be_projected_without_a_structural_root',
      );
      return '';
    }
    const inlineTextParent = isPixflowStageBInlineTextParentNode(options.parentNode);
    const text = inlineTextParent
      // Bricks trims leading/trailing whitespace from individual text controls
      // during persistence. Keep authored inline word boundaries as numeric
      // space entities so the browser restores normal collapsible spaces after
      // the adjacent native button/link controls are rendered.
      ? `${/^\s/.test(decodedText) ? '&#32;' : ''}${normalizedText}${/\s$/.test(decodedText) ? '&#32;' : ''}`
      : normalizedText;
    // Bricks requires text to live in an editable element even when the
    // source authored a bare text node. Render that unavoidable projection as
    // a span: a default text-basic div adds block wrappers that did not exist
    // in the source DOM and can change flex/grid sizing and descendant CSS.
    const settings = { text, tag: 'span' };
    if (inlineTextParent) {
      settings._display = 'inline';
    }
    return addPixflowStageBHtmlElement(
      context,
      `text:${node.sourceIndex}`,
      'text-basic',
      settings,
      parentId,
      { node, reason: 'source_text_projection' },
    );
  }
  if (node.type !== 'element') return '';
  if (options.pageSkipNodes && options.pageSkipNodes.has(node)) {
    return '';
  }

  const tag = node.tag;
  if (isPixflowStageBIncidentalNonVisualNode(node)) {
    context.structureRecorder.recordSubtreeDisposition(
      node,
      'omitted_nonvisual_runtime_node',
      'runtime_evidence_identified_incidental_nonvisual_node',
      '',
      true,
    );
    return '';
  }
  if (
    ['html', 'body'].includes(tag)
    || (tag === 'main' && isPixflowStageBFlattenedMainBoundary(node))
    || (tag !== 'main' && isPixflowStageBPageWrapper(node))
  ) {
    context.structureRecorder.recordDisposition(
      node,
      'normalized_into_children',
      `source_${tag}_wrapper_flattened_without_losing_children`,
    );
    for (const child of node.children || []) {
      compilePixflowStageBHtmlNode(child, parentId, context, options);
    }
    return '';
  }
  if (isPixflowStageBPrototypeIncidentalWrapperNode(node, context)) {
    context.structureRecorder.recordDisposition(
      node,
      'normalized_into_children',
      'prototype_incidental_wrapper_flattened_without_losing_children',
    );
    for (const child of node.children || []) {
      compilePixflowStageBHtmlNode(child, parentId, context, { ...options, parentNode: node });
    }
    return '';
  }
  if (['head', 'style', 'script', 'meta', 'link', 'title', 'noscript', 'template'].includes(tag)) {
    context.structureRecorder.recordSubtreeDisposition(
      node,
      'omitted_nonvisual_source_node',
      `source_${tag}_is_not_visual_page_structure`,
      '',
      true,
    );
    return '';
  }
  if (tag === 'img' && isPixflowStageBEmptyRuntimeImageNode(node)) {
    context.structureRecorder.recordDisposition(
      node,
      'omitted_empty_runtime_media',
      'empty_runtime_image_has_no_persistable_media_reference',
    );
    return '';
  }
  if (tag === 'svg') {
    const svgParentId = parentId || addPixflowStageBRootLeafSection(context, node);
    if (isPixflowStageBArtworkSvgNode(node)) {
      return addPixflowStageBHtmlArtworkSvgElement(node, svgParentId, context, options);
    }
    return addPixflowStageBHtmlIconElement(node, svgParentId, context, options);
  }

  const classNames = pixflowStageBHtmlClassList(node);
  const settings = buildPixflowStageBElementBaseSettings(node, context, options, parentId);
  const resolved = resolvePixflowStageBBricksElement(node, settings, context);
  const structuralName = resolvePixflowStageBStructuralElementName(node, resolved.name, settings, context);
  const requiresRootLeafSection = resolved.wholeNode || firstString(settings.tag).toLowerCase() === 'button';
  const effectiveParentId = parentId || (requiresRootLeafSection ? addPixflowStageBRootLeafSection(context, node) : '');
  const name = shouldPromotePixflowStageBRootToSection(effectiveParentId, context, resolved, structuralName)
    ? 'section'
    : structuralName;
  const wholeNode = resolved.wholeNode;
  if (name === 'section') {
    const sectionResetClassId = context.classInfo.syntheticClassIdByKey?.get('tag:section');
    if (sectionResetClassId) {
      settings._cssGlobalClasses = uniqueStrings([
        sectionResetClassId,
        ...arrayValue(settings._cssGlobalClasses),
      ]);
    }
  }
  if (name === 'block') {
    applyPixflowStageBBlockElementWidthDefaults(node, settings, context);
  }
  if (name === 'container' && !hasPixflowStageBExplicitSourceWidth(node, context)) {
    // Pixflow-owned: a native Bricks container otherwise inherits the theme's
    // max width even when Stage A used it only as a flex/layout wrapper. Keep
    // source-auto sizing for direct flex-row children; forcing 100% there
    // changes an intrinsic flex item into a row-filling item.
    settings._width = firstString(
      settings._width,
      isPixflowStageBFlexRowChildNode(node, context) ? 'auto' : '100%',
    );
    settings._widthMax = firstString(settings._widthMax, '100%');
  }
  const gridItemProjection = applyPixflowBuildInBricksGridItemProjectionDefaults(
    node,
    name,
    settings,
    context,
  );
  const elementId = addPixflowStageBHtmlElement(
    context,
    `${context.scope}:${tag}:${node.sourceIndex}:${classNames.join('.')}`,
    name,
    settings,
    effectiveParentId,
    { node, reason: firstString(resolved.mappingReason, `source_${tag}_to_${name}`) },
  );
  if (resolved.diagnostic) {
    context.structureRecorder.addDiagnostic({
      ...resolved.diagnostic,
      sourceNodeId: pixflowStageBAttr(node, 'data-pf-source-id'),
      bricksElementId: elementId,
    });
  }
  if (gridItemProjection.applied) {
    context.structureRecorder.addDiagnostic({
      code: 'native_grid_item_auto_minimum_normalized',
      severity: 'info',
      message: 'Neutralized the converter-selected Bricks layout element automatic minimum so the authored CSS Grid controls track sizing.',
      sourceNodeId: pixflowStageBAttr(node, 'data-pf-source-id'),
      bricksElementId: elementId,
    });
  }

  if (!wholeNode) {
    // Projection is source-driven for every conversion profile. A profile-only
    // section > container insertion changes direct-child selectors, hierarchy,
    // and provenance for identical HTML, so retain the authored parent here.
    const childParentId = elementId;
    for (const child of node.children || []) {
      compilePixflowStageBHtmlNode(child, childParentId, context, { ...options, parentNode: node });
    }
  } else {
    context.structureRecorder.recordSubtreeDisposition(
      node,
      name === 'html'
        ? 'encapsulated_exact_fallback'
        : (name === 'form' ? 'projected_into_native_form' : 'folded_into_editable_leaf'),
      name === 'html'
        ? 'bounded_source_subtree_preserved_in_exact_html_fallback'
        : (name === 'form'
            ? 'source_form_descendants_projected_into_native_form_fields'
            : 'source_inline_descendants_preserved_in_editable_leaf_content'),
      elementId,
      false,
    );
  }
  return elementId;
}

function shouldPromotePixflowStageBRootToSection(parentId, context, resolved, name) {
  if (firstString(parentId) || resolved?.wholeNode === true || name === 'section') {
    return false;
  }
  // Pixflow-owned: Bricks' controlled-insert and template contracts require
  // structural top-level roots to be sections. Accepted HTML often wraps its
  // semantic page/header/footer landmarks in one styled div; extraction keeps
  // that wrapper to preserve page-level backgrounds and pseudo effects. Make
  // the wrapper natively insertable here instead of spending a model repair
  // pass changing only its Bricks element name later.
  return ['page', 'header', 'footer'].includes(firstString(context?.scope));
}

function isPixflowStageBPrototypeIncidentalWrapperNode(node, context = {}) {
  if (firstString(context?.conversionPolicy?.conversionProfile) !== 'prototype_bricks') {
    return false;
  }
  if (firstString(node?.tag).toLowerCase() !== 'div') {
    return false;
  }
  const attrs = objectValue(node?.attrs);
  const meaningfulAttrNames = Object.keys(attrs).filter((name) => {
    const normalized = String(name || '').toLowerCase();
    if (!normalized || normalized === 'class') return false;
    return true;
  });
  if (meaningfulAttrNames.length > 0 || pixflowStageBHtmlClassList(node).length > 0) {
    return false;
  }
  const children = arrayValue(node?.children);
  const elementChildren = children.filter((child) => child?.type === 'element');
  if (elementChildren.length !== 1) {
    return false;
  }
  const text = normalizeWhitespace(children
    .filter((child) => child?.type === 'text')
    .map((child) => child.text)
    .join(' '));
  if (text) {
    return false;
  }
  const childTag = firstString(elementChildren[0]?.tag).toLowerCase();
  // Preserve media/form runtime shells until Stage B has stronger native
  // mapping evidence. The prototype profile only flattens incidental layout
  // wrappers around structural/content children.
  return !['img', 'svg', 'video', 'canvas', 'iframe', 'form', 'input', 'textarea', 'select', 'button'].includes(childTag);
}

function resolvePixflowStageBStructuralElementName(node, name, settings, context = {}) {
  if (name !== 'div') {
    return name;
  }
  const tag = firstString(node?.tag).toLowerCase();
  if (!['div', 'nav', 'article', 'aside', 'a', 'span'].includes(tag)) {
    return name;
  }
  if (tag === 'span' && !hasPixflowStageBElementChildren(node)) {
    return name;
  }
  return shouldUsePixflowStageBBlockElement(node, settings, context) ? 'block' : name;
}

function shouldUsePixflowStageBBlockElement(node, settings, context = {}) {
  const source = objectValue(settings);
  const display = firstString(source._display).toLowerCase();
  // Pixflow-owned: Bricks divs are the right baseline for normal block-flow
  // wrappers. Use Bricks block whenever the source needs a non-block display,
  // because block exposes Bricks' editable layout display controls cleanly.
  if (display && display !== 'block') {
    return true;
  }
  if (firstString(source._direction, source._flexWrap, source._alignItems, source._justifyContent, source._columnGap, source._rowGap)) {
    return hasPixflowStageBElementChildren(node);
  }
  // Pixflow-owned: most baseline layout styles are represented by Bricks
  // global classes. If a source div carries a non-block display class, use a
  // Bricks block element so the editable display control owns that layout.
  for (const className of pixflowStageBHtmlClassList(node)) {
    const declarations = objectValue(context?.classInfo?.declarationsByClass?.get(className));
    if (Object.keys(declarations).length === 0) {
      continue;
    }
    const mapped = mapPixflowCssDeclarationsToBricksSettings(declarations, {
      cssVariables: context?.classInfo?.cssVariables,
    });
    const mappedDisplay = firstString(mapped._display).toLowerCase();
    if (mappedDisplay && mappedDisplay !== 'block') {
      return true;
    }
    if (firstString(mapped._direction, mapped._flexWrap, mapped._alignItems, mapped._justifyContent, mapped._columnGap, mapped._rowGap)) {
      return hasPixflowStageBElementChildren(node);
    }
  }
  return false;
}

function applyPixflowStageBBlockElementWidthDefaults(node, settings, context = {}) {
  if (
    !firstString(settings._width)
    && hasPixflowStageBExplicitSourceMaxWidth(node, context)
    && !['inline-flex', 'inline-grid', 'inline-block'].includes(
      firstString(resolvePixflowStageBNodeLayoutDeclaration(node, context).display).toLowerCase(),
    )
  ) {
    // Pixflow-owned: Bricks blocks inside flex rows otherwise shrink to their
    // converted child content. A source max-width is a cap, not an intrinsic
    // width request, so let the item consume available space up to that cap.
    settings._width = '100%';
  }
  if (firstString(settings._width, settings._widthMin, settings._widthMax)) {
    return settings;
  }
  if (!shouldUsePixflowStageBBlockAutoWidth(node, settings, context)) {
    return settings;
  }
  // Pixflow-owned: Bricks block elements render full-width by default. Source
  // inline-flex/inline-grid wrappers are intrinsic-width UI pieces, so keep
  // them as Bricks blocks for layout controls but restore width:auto.
  settings._width = 'auto';
  return settings;
}

function shouldUsePixflowStageBBlockAutoWidth(node, settings, context = {}) {
  const ownDisplay = firstString(settings?._display).toLowerCase();
  if (['inline-flex', 'inline-grid', 'inline-block'].includes(ownDisplay)) {
    return true;
  }
  for (const className of pixflowStageBHtmlClassList(node)) {
    const declarations = objectValue(context?.classInfo?.declarationsByClass?.get(className));
    const display = firstString(declarations.display).toLowerCase();
    if (['inline-flex', 'inline-grid', 'inline-block'].includes(display)) {
      return true;
    }
    const width = firstString(declarations.width).toLowerCase();
    if (['auto', 'fit-content', 'max-content', 'min-content'].includes(width)) {
      return true;
    }
  }
  if (isPixflowStageBFlexRowChildNode(node, context)) {
    return true;
  }
  return false;
}

function applyPixflowBuildInBricksGridItemProjectionDefaults(node, elementName, settings, context = {}) {
  if (!isPixflowBuildInBricksHtmlFirstPlan(context?.plan)) {
    return { applied: false, reason: 'canonical_build_not_active' };
  }
  if (!['section', 'container', 'block', 'div'].includes(firstString(elementName).toLowerCase())) {
    return { applied: false, reason: 'native_layout_element_not_selected' };
  }
  const parent = node?.parent;
  if (!parent || firstString(resolvePixflowStageBNodeLayoutDeclaration(parent, context).display) !== 'grid') {
    return { applied: false, reason: 'source_parent_is_not_grid' };
  }
  if (hasPixflowStageBExplicitSourceHorizontalSize(node, context)) {
    return { applied: false, reason: 'authored_horizontal_size_preserved' };
  }

  // Bricks layout primitives carry component-level full-width/flex defaults.
  // As direct CSS Grid items those defaults participate in the automatic
  // minimum contribution and can expand `fr` tracks beyond the authored grid.
  // This zero is converter-owned projection compensation, not measured source
  // styling: it only removes the intrinsic contribution introduced by the
  // selected native primitive and leaves real descendant overflow visible.
  settings._widthMin = '0';
  return { applied: true, reason: 'neutralize_bricks_grid_item_automatic_minimum' };
}

function isPixflowStageBFlexRowChildNode(node, context = {}) {
  const parent = node?.parent;
  if (!isPixflowStageBFlexRowLayoutParent(parent, context)) return false;
  // Pixflow-owned: Bricks block elements are full-width by default. When a
  // source node is a direct child of a flex-row wrapper, browser layout keeps
  // that child intrinsic-width unless the source declared otherwise. Preserve
  // that behavior so controls/action rows do not squeeze sibling headings.
  return !hasPixflowStageBExplicitSourceWidth(node, context);
}

function addPixflowStageBRootLeafSection(context, node) {
  const sectionClassId = context.classInfo.syntheticClassIdByKey?.get('tag:section');
  return addPixflowStageBHtmlElement(
    context,
    `${context.scope}:root-leaf-section:${node?.sourceIndex}`,
    'section',
    sectionClassId ? { _cssGlobalClasses: [sectionClassId] } : {},
    '',
    { syntheticReason: 'bricks_root_leaf_section_contract' },
  );
}

function isPixflowStageBFlexRowLayoutParent(parent, context = {}) {
  if (!parent || parent.type !== 'element') return false;
  const parentLayout = resolvePixflowStageBNodeLayoutDeclaration(parent, context);
  return ['flex', 'inline-flex'].includes(parentLayout.display)
    && !['column', 'column-reverse'].includes(parentLayout.direction);
}

function resolvePixflowStageBNodeLayoutDeclaration(node, context = {}) {
  const declarations = {};
  for (const className of pixflowStageBHtmlClassList(node)) {
    Object.assign(declarations, objectValue(context?.classInfo?.declarationsByClass?.get(className)));
  }
  const inlineStyle = firstString(pixflowStageBAttr(node, 'style'));
  if (inlineStyle) {
    Object.assign(declarations, parseStageBCssDeclarations(inlineStyle));
  }
  const mapped = mapPixflowCssDeclarationsToBricksSettings(declarations, {
    cssVariables: context?.classInfo?.cssVariables,
  });
  return {
    display: firstString(mapped._display, declarations.display).toLowerCase(),
    direction: firstString(mapped._direction, declarations['flex-direction']).toLowerCase(),
  };
}

function hasPixflowStageBExplicitSourceWidth(node, context = {}) {
  for (const className of pixflowStageBHtmlClassList(node)) {
    const declarations = objectValue(context?.classInfo?.declarationsByClass?.get(className));
    if (firstString(declarations.width)) {
      return true;
    }
  }
  const inlineDeclarations = parseStageBCssDeclarations(firstString(pixflowStageBAttr(node, 'style')));
  return Boolean(firstString(inlineDeclarations.width));
}

function hasPixflowStageBExplicitSourceHorizontalSize(node, context = {}) {
  const ownsHorizontalSize = (declarationsValue) => {
    const declarations = objectValue(declarationsValue);
    return [
      'width',
      'min-width',
      'max-width',
      'inline-size',
      'min-inline-size',
      'max-inline-size',
    ].some((property) => firstString(declarations[property]));
  };
  for (const className of pixflowStageBHtmlClassList(node)) {
    if (ownsHorizontalSize(context?.classInfo?.declarationsByClass?.get(className))) {
      return true;
    }
  }
  return ownsHorizontalSize(parseStageBCssDeclarations(firstString(pixflowStageBAttr(node, 'style'))));
}

function hasPixflowStageBExplicitSourceMaxWidth(node, context = {}) {
  for (const className of pixflowStageBHtmlClassList(node)) {
    const declarations = objectValue(context?.classInfo?.declarationsByClass?.get(className));
    if (firstString(declarations['max-width'])) return true;
  }
  const inlineDeclarations = parseStageBCssDeclarations(firstString(pixflowStageBAttr(node, 'style')));
  return Boolean(firstString(inlineDeclarations['max-width']));
}

function resolvePixflowStageBBricksElement(node, settings, context = {}) {
  const tag = node.tag;
  if (isPixflowStageBInlineProseChildNode(node)) {
    settings._display = firstString(settings._display, tag === 'button' ? 'inline-flex' : 'inline');
    if (['a', 'button'].includes(tag)) {
      settings._width = firstString(settings._width, 'auto');
    }
  }
  if (
    shouldPixflowStageBUseExactHtmlFallback(node)
    || isPixflowStageBCssStateControlIsland(node, context)
  ) {
    // Responsive picture source selection, embedded documents, canvas
    // fallback content, and custom-element subtrees cannot be reconstructed
    // faithfully from one native Bricks control. Keep the bounded authored
    // subtree instead of flattening its observable content model.
    applyPixflowStageBExactHtmlFallbackSettings(settings, node);
    return { name: 'html', wholeNode: true };
  }
  if (tag === 'hr' || isPixflowStageBDividerLikeNode(node)) {
    return { name: 'divider', wholeNode: true };
  }
  if (tag === 'div' && isPixflowStageBStructuralContainerNode(node)) {
    return { name: 'container', wholeNode: false };
  }
  if (/^h[1-6]$/.test(tag)) {
    if (pixflowStageBNodeHasDescendantInteractiveContent(node)) {
      // Heading text controls are leaf values in Bricks. Flattening an
      // authored FAQ trigger into that value persists raw <button> HTML,
      // loses the editable control subtree, and is rejected by handoff QA.
      // Keep the semantic heading as a structural Bricks element so its
      // interactive descendants are projected through their native mappings.
      settings.tag = tag;
      delete settings.text;
      return { name: 'div', wholeNode: false, mappingReason: 'semantic_heading_control_container' };
    }
    settings.tag = tag;
    settings.text = sanitizePixflowStageBInlineHtml(pixflowStageBNodeInnerHtml(node));
    return { name: 'heading', wholeNode: true };
  }
  if (tag === 'img') {
    // Runtime data-image slots are authored media references even when their
    // concrete data URI is held in a script map. Carry the key through the
    // structure gate so the workspace materialiser can resolve it. An image
    // with no source/data reference remains empty and still fails validation.
    const src = firstString(
      pixflowStageBAttr(node, 'src'),
      pixflowStageBAttr(node, 'data-src'),
      pixflowStageBAttr(node, 'srcset'),
      pixflowStageBAttr(node, 'data-img'),
    );
    settings.image = { url: src };
    if (/^https?:\/\//i.test(src)) {
      // Bricks' image control stores URL-mode images with the URL in both
      // `url` (rendering) and the string-valued `external` field (builder
      // control mode/value). Keep `sourceUrl` as Pixflow provenance.
      settings.image.full = src;
      settings.image.sourceUrl = src;
      settings.image.external = src;
      settings.image.size = 'full';
    }
    settings.altText = pixflowStageBAttr(node, 'alt');
    return { name: 'image', wholeNode: true };
  }
  if (tag === 'video') {
    // Pixflow-owned: preserve accepted Stage A video media as native Bricks
    // video elements so hero/background motion is not lost during handoff.
    const src = firstString(
      pixflowStageBAttr(node, 'src'),
      ...arrayValue(node.children)
        .filter((child) => firstString(child?.tag).toLowerCase() === 'source')
        .map((child) => pixflowStageBAttr(child, 'src'))
    );
    settings.videoType = 'file';
    if (src) settings.fileUrl = src;
    if (hasPixflowStageBAttr(node, 'autoplay')) settings.fileAutoplay = true;
    if (hasPixflowStageBAttr(node, 'loop')) settings.fileLoop = true;
    if (hasPixflowStageBAttr(node, 'muted')) settings.fileMuted = true;
    if (hasPixflowStageBAttr(node, 'playsinline')) settings.fileInline = true;
    const poster = pixflowStageBAttr(node, 'poster');
    if (poster) settings.videoPoster = { url: poster };
    return { name: 'video', wholeNode: true };
  }
  if (tag === 'audio') {
    if (!canPixflowStageBUseNativeAudio(node)) {
      settings.tag = 'custom';
      settings.customTag = 'audio';
      return { name: 'block', wholeNode: false };
    }
    const src = firstString(
      pixflowStageBAttr(node, 'src'),
      ...arrayValue(node.children)
        .filter((child) => firstString(child?.tag).toLowerCase() === 'source')
        .map((child) => pixflowStageBAttr(child, 'src'))
    );
    settings.source = 'external';
    settings.external = src;
    if (hasPixflowStageBAttr(node, 'autoplay')) settings.autoplay = true;
    if (hasPixflowStageBAttr(node, 'loop')) settings.loop = true;
    const preload = firstString(pixflowStageBAttr(node, 'preload')).toLowerCase();
    if (['auto', 'metadata'].includes(preload)) settings.preload = preload;
    return { name: 'audio', wholeNode: true };
  }
  if (tag === 'a') {
    const href = pixflowStageBAttr(node, 'href');
    if (isPixflowStageBCtaNode(node)) {
      settings.text = normalizeWhitespace(pixflowStageBNodeVisibleText(node));
      if (href) {
        applyPixflowStageBExternalLinkSettings(settings, node, href);
      }
      applyPixflowStageBNativeButtonSettings(settings, node, { context });
      if (shouldPixflowStageBButtonUseActionIcon(node)) {
        settings.icon = buildPixflowStageBActionIconSetting(node);
      }
      return { name: 'button', wholeNode: true };
    }
    if (isPixflowStageBInlineTextOnlyAnchorNode(node)) {
      // Pixflow-owned: source brand/nav anchors often use `<br>` or simple
      // inline emphasis for visual rhythm. Keep those as one editable text link
      // so line breaks survive instead of becoming separate flex/grid children.
      settings.text = sanitizePixflowStageBInlineHtml(pixflowStageBNodeInnerHtml(node));
      if (href) {
        applyPixflowStageBExternalLinkSettings(settings, node, href);
      }
      return { name: 'text-link', wholeNode: true };
    }
    if (hasPixflowStageBElementChildren(node)) {
      if (pixflowStageBNodeHasDescendantInteractiveContent(node)) {
        // A linked Bricks container renders its descendants inside an anchor.
        // Suppress that outer link when the authored subtree already contains
        // an interactive descendant; otherwise Bricks would persist invalid
        // nested anchors/controls. The inner controls remain editable and the
        // structure report makes the suppressed outer affordance explicit.
        return {
          name: 'div',
          wholeNode: false,
          mappingReason: 'linked_container_with_interactive_descendant',
          diagnostic: {
            code: 'nested_interactive_link_suppressed',
            severity: 'warning',
            message: `Outer link ${href || '(empty href)'} was not applied because its editable subtree contains another interactive control.`,
          },
        };
      }
      applyPixflowStageBStructuralAnchorSettings(settings, node, href);
      return { name: 'div', wholeNode: false, mappingReason: 'editable_linked_container' };
    }
    settings.text = sanitizePixflowStageBInlineHtml(pixflowStageBNodeInnerHtml(node));
    if (href) {
      applyPixflowStageBExternalLinkSettings(settings, node, href);
    }
    return { name: 'text-link', wholeNode: true };
  }
  if (tag === 'button') {
    if (hasPixflowStageBElementChildren(node)) {
      // Native Bricks button elements are leaf controls. Converting an
      // authored button with image/icon/span children to that leaf silently
      // drops its visual affordance (including hamburger lines and image-only
      // CTAs). A Bricks block with a semantic button tag keeps the full subtree
      // editable and preserves the source attributes/interactions.
      settings.tag = 'button';
      delete settings.text;
      return { name: 'block', wholeNode: false };
    }
    settings.text = normalizeWhitespace(pixflowStageBNodeVisibleText(node));
    // Preserve authored interaction controls as real buttons. Without the
    // explicit native tag, Bricks can render a link-shaped CTA; without the
    // source type, a focus chip inside a form can become an implicit submit.
    settings.tag = 'button';
    applyPixflowStageBNativeButtonSettings(settings, node, { context });
    if (shouldPixflowStageBButtonUseActionIcon(node)) {
      settings.icon = buildPixflowStageBActionIconSetting(node);
    }
    return { name: 'button', wholeNode: true };
  }
  if (tag === 'form') {
    // Pixflow-owned: Bricks has no standalone input element. Preserve source
    // forms as native Bricks form elements instead of flattening fields to divs.
    if (canPixflowStageBUseNativeForm(node)) {
      applyPixflowStageBFormSettings(settings, node, { hideSubmitWhenMissing: false, context });
      return { name: 'form', wholeNode: true };
    }
    // A mixed form cannot be represented by one Bricks form control without
    // changing its fields, selected options, auxiliary controls, or layout.
    // Preserve the bounded authored form as the fidelity fallback.
    applyPixflowStageBExactHtmlFallbackSettings(settings, node);
    return { name: 'html', wholeNode: true };
  }
  if (['input', 'textarea', 'select'].includes(tag)) {
    // Pixflow-owned: standalone source controls, such as search inputs, need a
    // real frontend field. Wrap them in a one-field Bricks form and hide the
    // submit wrapper when the source did not include a submit action.
    applyPixflowStageBFormSettings(settings, node, { hideSubmitWhenMissing: true, context });
    return { name: 'form', wholeNode: true };
  }
  if (['p', 'figcaption', 'address'].includes(tag)) {
    if (
      (tag === 'p' && pixflowStageBNodeHasDescendantInteractiveContent(node))
      || (tag !== 'p' && pixflowStageBNodeHasDescendantAnchor(node))
    ) {
      // Pixflow-owned: Bricks text-basic content does not expose nested source
      // controls as editable Bricks controls. Keep the semantic wrapper and
      // project mixed paragraph text as inline spans alongside native inline
      // buttons/links. This preserves one flowing sentence without placing raw
      // form controls in a Bricks text setting or generating invalid block
      // descendants that the browser reparses outside the paragraph.
      settings.tag = tag;
      delete settings.text;
      return { name: 'div', wholeNode: false, mappingReason: 'semantic_inline_control_container' };
    }
    settings.tag = tag;
    settings.text = sanitizePixflowStageBInlineHtml(pixflowStageBNodeInnerHtml(node));
    return { name: 'text-basic', wholeNode: true };
  }
  if ([
    'blockquote',
    'label',
    'summary',
    'time',
    'cite',
    'mark',
    'abbr',
    'kbd',
    'samp',
    'var',
    'q',
    'del',
    'ins',
    'sub',
    'sup',
  ].includes(tag) && !hasPixflowStageBElementChildren(node)) {
    settings.tag = 'custom';
    settings.customTag = tag;
    settings.text = sanitizePixflowStageBInlineHtml(pixflowStageBNodeInnerHtml(node));
    return { name: 'text-basic', wholeNode: true };
  }
  if (tag === 'i' && !hasPixflowStageBElementChildren(node)) {
    // Pixflow-owned: Stage A commonly uses empty <i> nodes as decorative data
    // bars and ticks with selectors such as `.dash-bars i`. Preserve the tag
    // instead of converting to a plain div so descendant CSS remains valid.
    settings.tag = 'custom';
    settings.customTag = 'i';
    return { name: 'div', wholeNode: true };
  }
  if (tag === 'span' && isPixflowStageBEmptyDecorativeInlineNode(node)) {
    settings.tag = 'span';
    return { name: 'div', wholeNode: false };
  }
  if (isPixflowStageBCollapsibleInlineTextNode(node)) {
    // Pixflow-owned: the live Bricks text-basic schema accepts the native
    // inline `span` tag but does not expose `customTag`. Preserve emphasis
    // through the source global class instead of handing Stage B a known
    // schema violation to repair.
    settings.tag = 'span';
    delete settings.customTag;
    settings.text = sanitizePixflowStageBInlineHtml(pixflowStageBNodeInnerHtml(node));
    return { name: 'text-basic', wholeNode: true };
  }
  if (tag === 'span' && hasPixflowStageBElementChildren(node)) {
    settings.tag = 'custom';
    settings.customTag = 'span';
    return { name: 'div', wholeNode: false };
  }
  if (tag === 'span' && !hasPixflowStageBElementChildren(node)) {
    settings.tag = 'span';
    delete settings.customTag;
    settings.text = sanitizePixflowStageBInlineHtml(pixflowStageBNodeInnerHtml(node));
    return { name: 'text-basic', wholeNode: true };
  }
  if (tag === 'code' && firstString(node?.parent?.tag).toLowerCase() === 'pre' && !hasPixflowStageBElementChildren(node)) {
    // Pixflow-owned: whitespace is content inside pre/code. The general inline
    // sanitizer deliberately collapses it, which turns readable commands and
    // configuration into one long line on the Bricks canvas.
    settings.tag = 'span';
    delete settings.customTag;
    settings.text = sanitizePixflowStageBPreformattedInlineHtml(pixflowStageBNodeInnerHtml(node));
    return { name: 'text-basic', wholeNode: true };
  }
  if (['small', 'strong', 'b', 'em', 'code'].includes(tag) && !hasPixflowStageBElementChildren(node)) {
    settings.tag = 'span';
    delete settings.customTag;
    settings.text = sanitizePixflowStageBInlineHtml(pixflowStageBNodeInnerHtml(node));
    return { name: 'text-basic', wholeNode: true };
  }
  if (['section', 'header', 'footer'].includes(tag)) {
    const parentTag = firstString(node?.parent?.tag).toLowerCase();
    if (['header', 'footer'].includes(tag) && !['body', 'main'].includes(parentTag)) {
      settings.tag = tag;
      return { name: 'div', wholeNode: false };
    }
    if (tag !== 'section') {
      settings.tag = tag;
    }
    return { name: 'section', wholeNode: false };
  }
  if (['nav', 'article', 'aside', 'ol', 'ul', 'li', 'address', 'figure'].includes(tag)) {
    settings.tag = tag;
    return { name: 'div', wholeNode: false };
  }
  if (['details', 'dialog', 'fieldset', 'legend'].includes(tag)) {
    settings.tag = 'custom';
    settings.customTag = tag;
    return { name: 'div', wholeNode: false };
  }
  if (['blockquote', 'dl', 'dt', 'dd', 'pre', 'table', 'caption', 'colgroup', 'thead', 'tbody', 'tfoot', 'tr', 'th', 'td', 'progress', 'meter', 'output'].includes(tag)) {
    settings.tag = 'custom';
    settings.customTag = tag;
    return { name: 'div', wholeNode: false };
  }
  if (tag === 'br') {
    settings.text = '';
    return { name: 'text-basic', wholeNode: true };
  }
  if (tag.includes('-')) {
    // Preserve custom semantic/runtime elements as their authored tag while
    // compiling descendants to editable Bricks children. The saved frontend
    // still exposes the same custom-element name to any retained bounded JS;
    // a raw HTML fallback is unnecessary merely because the tag has a dash.
    settings.tag = 'custom';
    settings.customTag = tag;
    return { name: 'div', wholeNode: false, mappingReason: 'editable_custom_element_tag' };
  }
  return { name: 'div', wholeNode: false };
}

function isPixflowStageBStandaloneStateControl(node) {
  if (firstString(node?.tag).toLowerCase() !== 'input') return false;
  const type = firstString(pixflowStageBAttr(node, 'type')).toLowerCase();
  if (!['radio', 'checkbox'].includes(type)) return false;
  for (let parent = node?.parent; parent; parent = parent.parent) {
    if (firstString(parent?.tag).toLowerCase() === 'form') return false;
  }
  return true;
}

function pixflowStageBStateControlGroupKey(node) {
  const type = firstString(pixflowStageBAttr(node, 'type')).toLowerCase();
  return `${type}:${firstString(pixflowStageBAttr(node, 'name'), pixflowStageBAttr(node, 'id'), `source-${node?.sourceIndex}`)}`;
}

function lowestPixflowStageBCommonAncestor(nodes) {
  const candidates = arrayValue(nodes).filter(Boolean);
  if (candidates.length === 0) return null;
  const firstAncestors = [];
  for (let current = candidates[0]; current; current = current.parent) {
    firstAncestors.push(current);
  }
  return firstAncestors.find((candidate) => candidates.every((node) => {
    for (let current = node; current; current = current.parent) {
      if (current === candidate) return true;
    }
    return false;
  })) || null;
}

function isPixflowStageBCssStateControlIsland(node, context = {}) {
  if (!node || node.type !== 'element') return false;
  const documentRoot = (() => {
    let current = node;
    while (current?.parent) current = current.parent;
    return current;
  })();
  const allElements = flattenPixflowHtmlElements(documentRoot);
  const allControls = allElements.filter(isPixflowStageBStandaloneStateControl);
  const descendantControls = flattenPixflowHtmlElements(node).filter(isPixflowStageBStandaloneStateControl);
  if (descendantControls.length === 0) return false;

  const matchingGroup = allControls.filter((control) => (
    pixflowStageBStateControlGroupKey(control) === pixflowStageBStateControlGroupKey(descendantControls[0])
  ));
  if (matchingGroup.length === 0 || lowestPixflowStageBCommonAncestor(matchingGroup) !== node) return false;

  const controlIds = new Set(matchingGroup.map((control) => firstString(pixflowStageBAttr(control, 'id'))).filter(Boolean));
  const hasAssociatedLabel = flattenPixflowHtmlElements(node).some((item) => (
    firstString(item?.tag).toLowerCase() === 'label'
    && controlIds.has(firstString(pixflowStageBAttr(item, 'for')))
  ));
  if (!hasAssociatedLabel) return false;

  const controlTokens = uniqueStrings(matchingGroup.flatMap((control) => [
    ...pixflowStageBHtmlClassList(control).map((className) => `.${className}`),
    firstString(pixflowStageBAttr(control, 'id')) ? `#${firstString(pixflowStageBAttr(control, 'id'))}` : '',
  ]));
  return arrayValue(context?.classInfo?.rules).some((rule) => {
    const selector = firstString(rule?.selector);
    return selector.includes(':checked') && controlTokens.some((token) => selector.includes(token));
  });
}

function pixflowStageBNodeHasDescendantAnchor(node) {
  return flattenPixflowHtmlElements(node)
    .some((item) => item !== node && firstString(item?.tag).toLowerCase() === 'a');
}

function shouldPixflowStageBUseExactHtmlFallback(node) {
  const tag = firstString(node?.tag).toLowerCase();
  return [
    'picture',
    'iframe',
    'canvas',
    'template',
    'noscript',
    'object',
    'embed',
    'map',
  ].includes(tag);
}

function pixflowStageBNodeHasDescendantInteractiveContent(node) {
  return flattenPixflowHtmlElements(node).some((item) => (
    item !== node
    && ['a', 'button', 'input', 'select', 'textarea'].includes(firstString(item?.tag).toLowerCase())
  ));
}

function applyPixflowStageBExactHtmlFallbackSettings(settings, node) {
  for (const key of Object.keys(objectValue(settings))) {
    delete settings[key];
  }
  // Pixflow-owned: the HTML element is the final fallback, used only when a
  // native Bricks control or a semantic custom tag cannot preserve the source
  // content model. Keep the complete authored subtree rather than silently
  // flattening sources, embeds, canvas fallback text, or custom elements.
  settings.html = pixflowStageBNodeOuterHtml(node).replace(/\sdata-pf-source-id=(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, '');
}

function canPixflowStageBUseNativeAudio(node) {
  const sources = arrayValue(node?.children).filter((child) => firstString(child?.tag).toLowerCase() === 'source');
  if (!firstString(pixflowStageBAttr(node, 'src')) && sources.length !== 1) return false;
  if (sources.length > 1) return false;
  return !['muted', 'crossorigin', 'controlslist', 'disableremoteplayback'].some((name) => hasPixflowStageBAttr(node, name));
}

function canPixflowStageBUseNativeForm(node) {
  const formMethod = firstString(pixflowStageBAttr(node, 'method')).toLowerCase();
  const formAction = firstString(pixflowStageBAttr(node, 'action')).trim();
  // `action="#"` is a common design-source placeholder, not a portable
  // submission destination. Treat it like an omitted action so ordinary Build
  // can project the authored controls to an editable native Bricks form. Real
  // relative/absolute destinations still use the exact-fidelity fallback.
  const hasAuthoredDestination = Boolean(formAction && formAction !== '#');
  const unsupportedMethod = formMethod && !['get', 'post'].includes(formMethod);
  if (
    hasAuthoredDestination
    || unsupportedMethod
    || ['enctype', 'target', 'novalidate', 'accept-charset', 'rel'].some((name) => hasPixflowStageBAttr(node, name))
  ) {
    // The current native Bricks form projection owns editable fields and
    // presentation, not arbitrary authored submission/navigation behaviour.
    // Preserve destination-bearing or unsupported bounded forms exactly.
    // A GET/POST method without an action has no portable source endpoint once
    // inserted on a different WordPress page, so it must not pre-empt native
    // compatibility analysis for a visual/composer form.
    return false;
  }
  const elements = flattenPixflowHtmlElements(node);
  const controls = elements.filter((item) => ['input', 'textarea', 'select', 'button'].includes(firstString(item?.tag).toLowerCase()));
  const submitControls = controls.filter((control) => {
    const tag = firstString(control?.tag).toLowerCase();
    const type = firstString(pixflowStageBAttr(control, 'type'), tag === 'button' ? 'submit' : 'text').toLowerCase();
    return (tag === 'button' && type === 'submit') || (tag === 'input' && ['submit', 'image'].includes(type));
  });
  if (submitControls.length > 1) return false;
  if (controls.some((control) => {
    const tag = firstString(control?.tag).toLowerCase();
    const type = firstString(pixflowStageBAttr(control, 'type'), tag === 'button' ? 'submit' : 'text').toLowerCase();
    // Mode/model/attachment chips inside modern composer forms are auxiliary
    // `type="button"` controls, not submitted fields. They cannot be expressed
    // inside Bricks' native form control, but they also must not force the
    // entire form into raw HTML (which is non-editable and rejected at insert).
    // Omit those presentation-only chips while preserving the actual fields
    // and submit action natively. Reset and implicit non-submit semantics stay
    // on the exact-fallback path until Bricks can model them safely.
    if (tag === 'button' && type === 'button') return false;
    if (tag === 'button' && type !== 'submit') return true;
    if (tag === 'input' && ['date', 'datetime-local', 'month', 'week', 'time', 'range', 'color', 'image'].includes(type)) return true;
    if (tag === 'select' && (hasPixflowStageBAttr(control, 'multiple') || hasPixflowStageBAttr(control, 'size'))) return true;
    if (tag === 'textarea' && hasPixflowStageBAttr(control, 'wrap')) return true;
    return ['list', 'formaction', 'formenctype', 'formmethod', 'formnovalidate', 'formtarget'].some((name) => hasPixflowStageBAttr(control, name));
  })) return false;
  if (elements.some((item) => ['fieldset', 'legend', 'datalist', 'optgroup', 'output'].includes(firstString(item?.tag).toLowerCase()))) return false;
  return true;
}

function isPixflowStageBDividerLikeNode(node) {
  const tag = firstString(node?.tag).toLowerCase();
  if (tag !== 'div' && tag !== 'span') {
    return false;
  }
  const children = arrayValue(node?.children).filter((child) => child?.type === 'element' || normalizeWhitespace(child?.text));
  if (children.length > 0) {
    return false;
  }
  const marker = [
    ...pixflowStageBHtmlClassList(node),
    firstString(pixflowStageBAttr(node, 'id')),
    firstString(pixflowStageBAttr(node, 'role')),
    firstString(pixflowStageBAttr(node, 'aria-label')),
  ].join(' ').toLowerCase();
  return /\b(?:divider|separator|rule|hairline|split-line|line-break)\b/.test(marker);
}

function applyPixflowStageBFormSettings(settings, node, options = {}) {
  applyPixflowStageBFormRootLayoutSettings(settings, node, options.context);
  const controls = collectPixflowStageBFormControls(node);
  const decorativeFieldLabel = controls
    .map((control) => findPixflowStageBDecorativeWrappingFormLabel(control, node))
    .find(Boolean);
  const decorativeFieldSourceId = firstString(pixflowStageBAttr(decorativeFieldLabel, 'data-pf-source-id'));
  if (decorativeFieldSourceId) {
    settings._attributes = [
      ...arrayValue(settings._attributes),
      {
        id: deterministicBricksId(`stage-b-form-decorative-field-source:${decorativeFieldSourceId}`),
        name: 'data-pf-decorative-field-source-id',
        value: decorativeFieldSourceId,
      },
    ];
  }
  const fields = buildPixflowStageBFormFields(controls, node, { context: options.context });

  if (fields.length === 0) {
    fields.push({
      id: deterministicBricksId(`stage-b-form-field:fallback:${node?.sourceIndex || 0}`),
      type: 'text',
      label: firstString(pixflowStageBAttr(node, 'aria-label'), 'Field'),
      name: 'field',
    });
  }

  const submit = controls.find((control) => {
    const tag = firstString(control?.tag).toLowerCase();
    const type = firstString(pixflowStageBAttr(control, 'type'), tag === 'button' ? 'submit' : 'text').toLowerCase();
    return (tag === 'button' && type === 'submit') || (tag === 'input' && type === 'submit');
  });
  settings.fields = fields;
  settings.actions = [];
  settings.showLabels = hasPixflowStageBVisibleFormLabels(node);
  settings.requiredAsterisk = true;
  applyPixflowStageBFormNativeVisualSettings(settings, controls, node, submit, options.context);
  const internalLayoutCss = buildPixflowStageBFormInternalLayoutCss(controls, node, options.context, settings);
  if (internalLayoutCss) {
    settings._cssCustom = [firstString(settings._cssCustom), internalLayoutCss].filter(Boolean).join('\n');
  }
  if (!settings.showLabels) {
    const hiddenLabelsClassId = options.context?.classInfo?.syntheticClassIdByKey?.get('form:hidden-labels');
    if (hiddenLabelsClassId) {
      settings._cssGlobalClasses = uniqueStrings([
        ...arrayValue(settings._cssGlobalClasses),
        hiddenLabelsClassId,
      ]);
    }
  }

  if (submit) {
    const submitText = normalizeWhitespace(
      pixflowStageBNodeText(submit)
      || pixflowStageBAttr(submit, 'value')
      || pixflowStageBAttr(submit, 'aria-label')
    );
    if (submitText) {
      settings.submitButtonText = submitText;
    }
    applyPixflowStageBNativeButtonSettings(settings, submit, {
      styleKey: 'submitButtonStyle',
      sizeKey: 'submitButtonSize',
      context: options.context,
    });
    const submitName = firstString(pixflowStageBAttr(submit, 'name'));
    if (submitName) {
      // Bricks does not expose name/value controls on its generated submit
      // button. A single-submit form can preserve the exact submitted payload
      // with a native hidden field while keeping the form editable.
      fields.push({
        id: deterministicBricksId(`stage-b-form-submit-value:${submit?.sourceIndex || 0}:${submitName}`),
        type: 'hidden',
        label: submitName,
        name: submitName,
        value: firstString(pixflowStageBAttr(submit, 'value')),
      });
    }
  } else {
    settings.submitButtonText = '';
    if (options.hideSubmitWhenMissing) {
      const hiddenSubmitClassId = options.context?.classInfo?.syntheticClassIdByKey?.get('form:hidden-submit');
      if (hiddenSubmitClassId) {
        settings._cssGlobalClasses = uniqueStrings([
          ...arrayValue(settings._cssGlobalClasses),
          hiddenSubmitClassId,
        ]);
      }
    }
  }
}

function applyPixflowStageBFormRootLayoutSettings(settings, node, context = {}) {
  if (!node || firstString(node.tag).toLowerCase() !== 'form') {
    return;
  }
  const layoutKeys = [
    '_display',
    '_direction',
    '_flexWrap',
    '_flexGrow',
    '_flexShrink',
    '_flexBasis',
    '_alignSelf',
    '_order',
    '_gridItemJustifySelf',
    '_alignItems',
    '_justifyContent',
    '_justifyItemsGrid',
    '_alignContentGrid',
    '_justifyContentGrid',
    '_alignItemsGrid',
    '_gridTemplateColumns',
    '_gridTemplateRows',
    '_columnGap',
    '_rowGap',
  ];
  for (const className of pixflowStageBHtmlClassList(node)) {
    const declarations = objectValue(context?.classInfo?.declarationsByClass?.get(className));
    if (Object.keys(declarations).length === 0) {
      continue;
    }
    const mapped = mapPixflowCssDeclarationsToBricksSettings(declarations, {
      cssVariables: context?.classInfo?.cssVariables,
    });
    const display = firstString(mapped._display).toLowerCase();
    if (!['grid', 'inline-grid', 'flex', 'inline-flex'].includes(display)) {
      continue;
    }
    // Pixflow-owned: Bricks native forms may not apply layout controls from
    // global classes early enough for their internal field wrappers. Copy only
    // root layout controls to the form element itself so source form rows keep
    // their baseline geometry without moving visual styling out of classes.
    for (const [key, value] of Object.entries(mapped)) {
      const baseKey = String(key || '').split(':')[0];
      if (layoutKeys.includes(baseKey) && value !== undefined && settings[key] === undefined) {
        settings[key] = value;
      }
    }
  }
}

function collectPixflowStageBFormControls(node) {
  const controls = [];
  const visit = (item) => {
    if (!item || item.type !== 'element') return;
    const tag = firstString(item.tag).toLowerCase();
    if (['input', 'textarea', 'select', 'button'].includes(tag)) {
      controls.push(item);
    }
    if (tag === 'form' || !['input', 'textarea', 'select'].includes(tag)) {
      for (const child of item.children || []) visit(child);
    }
  };
  visit(node);
  return controls;
}

function buildPixflowStageBFormFields(controls, formNode, options = {}) {
  const source = arrayValue(controls)
    .filter((control) => ['input', 'textarea', 'select'].includes(firstString(control?.tag).toLowerCase()));
  const fields = [];
  const consumed = new Set();
  for (let index = 0; index < source.length; index += 1) {
    const control = source[index];
    if (consumed.has(control)) continue;
    const rawType = firstString(pixflowStageBAttr(control, 'type'), 'text').toLowerCase();
    let group = [control];
    if (['checkbox', 'radio'].includes(rawType)) {
      const name = firstString(pixflowStageBAttr(control, 'name'));
      if (name) {
        group = source.filter((candidate) => (
          firstString(candidate?.tag).toLowerCase() === 'input'
          && firstString(pixflowStageBAttr(candidate, 'type'), 'text').toLowerCase() === rawType
          && firstString(pixflowStageBAttr(candidate, 'name')) === name
        ));
      }
      group.forEach((item) => consumed.add(item));
    }
    const field = buildPixflowStageBFormField(control, index, { formNode, group, context: options.context });
    if (field) fields.push(field);
  }
  return fields;
}

function buildPixflowStageBFormField(control, index, options = {}) {
  const tag = firstString(control?.tag).toLowerCase();
  const rawType = tag === 'textarea'
    ? 'textarea'
    : (tag === 'select' ? 'select' : firstString(pixflowStageBAttr(control, 'type'), 'text').toLowerCase());
  if (['submit', 'button', 'reset', 'image'].includes(rawType)) {
    return null;
  }
  const supportedType = rawType === 'search' ? 'text' : rawType;
  const type = ['email', 'number', 'text', 'tel', 'url', 'datepicker', 'password', 'file', 'hidden', 'textarea', 'select', 'checkbox', 'radio'].includes(supportedType)
    ? supportedType
    : 'text';
  const sourceId = firstString(pixflowStageBAttr(control, 'id'));
  const sourceName = firstString(pixflowStageBAttr(control, 'name'), sourceId, `field-${index + 1}`);
  const ariaLabel = firstString(pixflowStageBAttr(control, 'aria-label'));
  const placeholder = firstString(pixflowStageBAttr(control, 'placeholder'));
  const associatedLabel = findPixflowStageBFormControlLabel(control, options.formNode);
  const decorativeWrappingLabel = findPixflowStageBDecorativeWrappingFormLabel(control, options.formNode);
  const field = {
    id: deterministicBricksId(`stage-b-form-field:${control?.sourceIndex || index}:${sourceName}:${type}`),
    type,
    label: firstString(ariaLabel, associatedLabel, placeholder, sourceName),
    name: sourceName,
  };
  if (placeholder || (decorativeWrappingLabel && associatedLabel)) {
    field.placeholder = firstString(placeholder, associatedLabel);
  }
  const value = firstString(pixflowStageBAttr(control, 'value'));
  if (value && type !== 'file') field.value = value;
  if (hasPixflowStageBAttr(control, 'required')) field.required = true;
  const autocomplete = firstString(pixflowStageBAttr(control, 'autocomplete'));
  if (autocomplete) field.autocomplete = autocomplete;
  const pattern = firstString(pixflowStageBAttr(control, 'pattern'));
  if (pattern) field.pattern = pattern;
  const title = firstString(pixflowStageBAttr(control, 'title'));
  if (title) field.title = title;
  const minLength = parsePixflowStageBPositiveIntegerAttribute(control, 'minlength');
  const maxLength = parsePixflowStageBPositiveIntegerAttribute(control, 'maxlength');
  if (minLength !== null) field.minLength = minLength;
  if (maxLength !== null) field.maxLength = maxLength;
  if (type === 'number') {
    for (const key of ['min', 'max', 'step']) {
      const numeric = firstString(pixflowStageBAttr(control, key));
      if (numeric && Number.isFinite(Number(numeric))) field[key] = Number(numeric);
    }
  }
  if (type === 'select') {
    applyPixflowStageBSelectFieldOptions(field, control);
  }
  if (['checkbox', 'radio'].includes(type)) {
    applyPixflowStageBChoiceFieldOptions(field, arrayValue(options.group).length > 0 ? options.group : [control], options.formNode);
  }
  applyPixflowStageBFormFieldWidth(field, control, options.formNode, options.context);
  // Pixflow-owned: preserve source ids for downstream script rewriting and
  // handoff QA, even though Bricks generates frontend input ids at render time.
  if (sourceId) field.sourceId = sourceId;
  if (rawType === 'search') field.sourceType = 'search';
  return field;
}

function applyPixflowStageBFormFieldWidth(field, control, formNode, context = {}) {
  const { declarations, foundWrapper } = collectPixflowStageBFormControlWrapperDeclarations(control, formNode, context);
  const flex = parsePixflowStageBFlexShorthand(firstString(declarations.flex));
  const width = firstString(declarations.width, declarations['flex-basis'], flex?.basis);
  const percentage = width.match(/^(?:calc\(\s*)?(\d+(?:\.\d+)?)%/i)?.[1];
  if (percentage) {
    field.width = Number(percentage);
  } else if (foundWrapper && ['flex', 'inline-flex'].includes(firstString(
    resolvePixflowStageBNodeLayoutDeclaration(formNode, context).display,
  ).toLowerCase())) {
    field.width = 'auto';
  }
}

function applyPixflowStageBFormNativeVisualSettings(settings, controls, formNode, submit, context = {}) {
  const classInfo = objectValue(context?.classInfo);
  const descendantStyles = buildPixflowStageBDescendantElementStyleMap(
    classInfo.rules,
    classInfo.cssVariables,
  );
  const visualFieldControls = arrayValue(controls).filter((control) => {
    if (control === submit) return false;
    const tag = firstString(control?.tag).toLowerCase();
    const type = firstString(pixflowStageBAttr(control, 'type'), 'text').toLowerCase();
    return ['input', 'select', 'textarea'].includes(tag)
      && !['hidden', 'checkbox', 'radio', 'file'].includes(type);
  });
  const commonFieldStyle = commonPixflowStageBFormDescendantStyle(visualFieldControls, descendantStyles);
  if (commonFieldStyle._padding) settings.fieldPadding = commonFieldStyle._padding;
  if (objectValue(commonFieldStyle._background).color) settings.fieldBackgroundColor = commonFieldStyle._background.color;
  if (commonFieldStyle._border) settings.fieldBorder = commonFieldStyle._border;
  if (commonFieldStyle._typography) settings.fieldTypography = commonFieldStyle._typography;

  const labels = flattenPixflowHtmlElements(formNode)
    .filter((item) => firstString(item?.tag).toLowerCase() === 'label');
  const commonLabelStyle = commonPixflowStageBFormLabelStyle(labels, descendantStyles, classInfo);
  if (commonLabelStyle._typography) settings.labelTypography = commonLabelStyle._typography;
  const decorativeLabels = labels.filter((label) => isPixflowStageBDecorativeFormControlLabel(label));
  const decorativeFieldStyle = pixflowStageBDecorativeFormFieldStyle(
    formNode,
    context,
    descendantStyles,
  );
  if (decorativeFieldStyle._padding) settings.fieldPadding = decorativeFieldStyle._padding;
  if (objectValue(decorativeFieldStyle._background).color) {
    settings.fieldBackgroundColor = decorativeFieldStyle._background.color;
  }
  if (decorativeFieldStyle._border) settings.fieldBorder = decorativeFieldStyle._border;
  const decorativeLabelClassNames = new Set(decorativeLabels.flatMap((label) => pixflowStageBHtmlClassList(label)));
  const decorativeFieldShadow = arrayValue(classInfo.globalClasses)
    .find((item) => decorativeLabelClassNames.has(firstString(item?.name)))?.settings?._boxShadow;
  if (decorativeFieldShadow) {
    // The source composer chrome wraps the field and its internal actions.
    // Bricks has no field-shadow control, so put the native shadow on the form
    // root while field padding/background/radius remain editable field controls.
    settings._boxShadow = decorativeFieldShadow;
  }

  const submitStyle = {};
  for (const className of pixflowStageBHtmlClassList(submit)) {
    mergePixflowStageBSettings(submitStyle, mapPixflowCssDeclarationsToBricksSettings(
      objectValue(classInfo.declarationsByClass?.get?.(className)),
      { cssVariables: classInfo.cssVariables },
    ));
  }
  mergePixflowStageBSettings(submitStyle, mapPixflowCssDeclarationsToBricksSettings(
    parseStageBCssDeclarations(firstString(pixflowStageBAttr(submit, 'style'))),
    { cssVariables: classInfo.cssVariables },
  ));
  if (submitStyle._margin) settings.submitButtonMargin = submitStyle._margin;
  if (submitStyle._typography) settings.submitButtonTypography = submitStyle._typography;
  if (objectValue(submitStyle._background).color) settings.submitButtonBackgroundColor = submitStyle._background.color;
  if (submitStyle._border) settings.submitButtonBorder = submitStyle._border;
  const width = firstString(submitStyle._width);
  const percentage = width.match(/^(-?(?:\d+\.?\d*|\.\d+))%$/);
  if (percentage) {
    settings.submitButtonWidth = Number(percentage[1]);
  }
}

function commonPixflowStageBFormDescendantStyle(nodes, descendantStyles) {
  const styles = arrayValue(nodes).map((node) => {
    const merged = {};
    const tag = firstString(node?.tag).toLowerCase();
    for (const ancestorClass of getPixflowStageBAncestorClassNames(node)) {
      const item = descendantStyles.get(buildPixflowStageBDescendantElementStyleKey(ancestorClass, tag));
      if (item?.settings) mergePixflowStageBSettings(merged, item.settings);
    }
    return merged;
  }).filter((style) => Object.keys(style).length > 0);
  if (styles.length === 0) return {};
  const result = {};
  for (const key of ['_padding', '_background', '_border', '_typography']) {
    const first = styles[0][key];
    if (first !== undefined && styles.every((style) => JSON.stringify(style[key]) === JSON.stringify(first))) {
      result[key] = first;
    }
  }
  return result;
}

function commonPixflowStageBFormLabelStyle(labels, descendantStyles, classInfo = {}) {
  const styles = arrayValue(labels).map((label) => {
    const merged = {};
    for (const className of pixflowStageBHtmlClassList(label)) {
      mergePixflowStageBSettings(merged, mapPixflowCssDeclarationsToBricksSettings(
        objectValue(classInfo.declarationsByClass?.get?.(className)),
        { cssVariables: classInfo.cssVariables },
      ));
    }
    mergePixflowStageBSettings(merged, mapPixflowCssDeclarationsToBricksSettings(
      parseStageBCssDeclarations(firstString(pixflowStageBAttr(label, 'style'))),
      { cssVariables: classInfo.cssVariables },
    ));
    const descendant = commonPixflowStageBFormDescendantStyle([label], descendantStyles);
    mergePixflowStageBSettings(merged, descendant);
    const contentNodes = arrayValue(label?.children).filter((child) => {
      if (child?.type !== 'element' || !normalizeWhitespace(pixflowStageBNodeText(child))) return false;
      return !['input', 'select', 'textarea', 'button'].includes(firstString(child?.tag).toLowerCase());
    });
    for (const contentNode of contentNodes) {
      for (const className of pixflowStageBHtmlClassList(contentNode)) {
        mergePixflowStageBSettings(merged, mapPixflowCssDeclarationsToBricksSettings(
          objectValue(classInfo.declarationsByClass?.get?.(className)),
          { cssVariables: classInfo.cssVariables },
        ));
      }
      mergePixflowStageBSettings(
        merged,
        commonPixflowStageBFormDescendantStyle([contentNode], descendantStyles),
      );
    }
    return merged;
  }).filter((style) => Object.keys(style).length > 0);
  if (styles.length === 0) return {};
  const result = {};
  for (const key of ['_padding', '_background', '_border', '_boxShadow', '_typography']) {
    const first = styles[0][key];
    if (first !== undefined && styles.every((style) => JSON.stringify(style[key]) === JSON.stringify(first))) {
      result[key] = first;
    }
  }
  return result;
}

function pickPixflowStageBRepeatedContainerDeclarations(classInfo, declarationsByClass) {
  const usageByClass = classInfo?.usageByClass instanceof Map ? classInfo.usageByClass : new Map();
  const result = {};
  for (const className of ['container', 'wrap']) {
    const usage = objectValue(usageByClass.get(className));
    if (Number(usage.count || 0) < 2) continue;
    Object.assign(result, objectValue(declarationsByClass.get(className)));
  }
  return result;
}

function pickPixflowStageBThemeStyleLink(declarations, cssVariables, fontOptions, templateOwnership) {
  const mapped = mapPixflowCssDeclarationsToBricksSettings(declarations, { cssVariables, ...fontOptions });
  const result = {};
  const typography = removePixflowStageBInheritOnlyTypography(mapped._typography);
  if (typography) result.typography = typography;
  if (mapped._background) result.background = mapped._background;
  if (mapped._border) result.border = mapped._border;
  if (mapped._padding) result.padding = mapped._padding;
  if (mapped._cssTransition) result.transition = mapped._cssTransition;
  const roots = ['#brx-content'];
  if (templateOwnership?.header === 'source_owned') roots.push('#brx-header');
  if (templateOwnership?.footer === 'source_owned') roots.push('#brx-footer');
  result.cssSelectors = roots.map((root) => `${root} a`).join(', ');
  return Object.keys(result).length === 1 ? {} : result;
}

function collectPixflowStageBFoundationBrowserDocumentDefaults(plan) {
  const snapshot = objectValue(objectValue(plan?.sourceEvidence).renderedSnapshot || plan?.renderedSnapshot);
  const viewports = arrayValue(snapshot.viewports);
  const base = viewports.find((viewport) => firstString(viewport?.id) === 'desktop')
    || viewports.find((viewport) => firstString(viewport?.id) === 'bricks_base')
    || viewports[0];
  const documentStyles = objectValue(base?.documentStyles);
  return {
    viewportId: firstString(base?.id),
    html: objectValue(documentStyles.html),
    body: objectValue(documentStyles.body),
  };
}

function isPixflowStageBTransparentBackground(value) {
  return /^(?:transparent|rgba\(\s*0\s*,\s*0\s*,\s*0\s*,\s*0(?:\.0+)?\s*\))$/i.test(firstString(value));
}

function pickPixflowStageBFoundationBrowserBackground(browserDocumentDefaults) {
  const body = objectValue(browserDocumentDefaults?.body);
  const html = objectValue(browserDocumentDefaults?.html);
  const bodyBackground = firstString(body['background-color'], body.background);
  if (bodyBackground && !isPixflowStageBTransparentBackground(bodyBackground)) {
    return pickPixflowStageBThemeStyleBackground({ 'background-color': bodyBackground });
  }
  const htmlBackground = firstString(html['background-color'], html.background);
  if (htmlBackground && !isPixflowStageBTransparentBackground(htmlBackground)) {
    return pickPixflowStageBThemeStyleBackground({ 'background-color': htmlBackground });
  }
  return {};
}

function buildPixflowStageBFoundationBrowserDeclarationOwnership({
  browserDocumentDefaults,
  semanticDefaults,
  existingDeclarations,
  nativeGlobalScopeSafe,
}) {
  const existing = new Set(arrayValue(existingDeclarations).map((item) => (
    `${firstString(item?.selector).toLowerCase()}\u0000${firstString(item?.property).toLowerCase()}`
  )));
  const candidates = [];
  const body = objectValue(browserDocumentDefaults?.body);
  for (const [property, value] of Object.entries(pickPixflowStageBInheritedTextDeclarations(body))) {
    candidates.push({ selector: 'body', property, value });
  }
  const bodyBackground = firstString(body['background-color'], body.background);
  if (bodyBackground && !isPixflowStageBTransparentBackground(bodyBackground)) {
    candidates.push({ selector: 'body', property: 'background-color', value: bodyBackground });
  } else {
    const html = objectValue(browserDocumentDefaults?.html);
    const htmlBackground = firstString(html['background-color'], html.background);
    if (htmlBackground && !isPixflowStageBTransparentBackground(htmlBackground)) {
      candidates.push({ selector: 'html', property: 'background-color', value: htmlBackground });
    }
  }
  const htmlFontSize = firstString(objectValue(browserDocumentDefaults?.html)['font-size']);
  if (htmlFontSize) candidates.push({ selector: 'html', property: 'font-size', value: htmlFontSize });

  const result = [];
  for (const candidate of candidates) {
    const property = firstString(candidate.property).toLowerCase();
    const selector = firstString(candidate.selector).toLowerCase();
    const key = `${selector}\u0000${property}`;
    if (!property || !selector || !firstString(candidate.value) || existing.has(key)) continue;
    const native = pixflowStageBFoundationNativeControl(selector, property, semanticDefaults);
    result.push({
      selector,
      property,
      value: firstString(candidate.value),
      important: false,
      sourceOrder: -1,
      group: native.group,
      control: native.control,
      nativeSupported: nativeGlobalScopeSafe && native.supported,
      provenance: 'browser_computed_page_wide_evidence',
      evidenceViewport: firstString(browserDocumentDefaults?.viewportId),
    });
  }
  return result;
}

function buildPixflowStageBFoundationDeclarationOwnership({ cssText, semanticDefaults, nativeGlobalScopeSafe }) {
  const result = [];
  for (const declaration of parsePixflowStylesheetDeclarations(cssText)) {
    const property = firstString(declaration?.property).toLowerCase();
    if (declaration?.kind !== 'declaration'
      || declaration?.media) {
      continue;
    }
    for (const selectorValue of splitPixflowCssSelectorList(firstString(declaration?.selector))) {
      const selector = firstString(selectorValue).trim().toLowerCase();
      if (!isPixflowStageBDirectFoundationSelector(selector)) continue;
      if (property.startsWith('--')) {
        if (![':root', 'html', 'body'].includes(selector)) continue;
        result.push({
          selector,
          property,
          value: firstString(declaration.value),
          important: declaration.important === true,
          sourceOrder: Number(declaration.sourceOrder || 0),
          group: 'css',
          control: 'stylesheet',
          nativeSupported: false,
          provenance: 'authored_page_wide_source_variable',
        });
        continue;
      }
      const native = pixflowStageBFoundationNativeControl(selector, property, semanticDefaults);
      result.push({
        selector,
        property,
        value: firstString(declaration.value),
        important: declaration.important === true,
        sourceOrder: Number(declaration.sourceOrder || 0),
        group: native.group,
        control: native.control,
        nativeSupported: nativeGlobalScopeSafe && native.supported && declaration.important !== true,
        provenance: 'authored_page_wide_source_rule',
      });
    }
  }
  return result;
}

function isPixflowStageBDirectFoundationSelector(selector) {
  return /^(?::root|html|body|a|h[1-6]|section|button|input|textarea|select|:focus-visible)$/.test(firstString(selector));
}

function pixflowStageBFoundationNativeControl(selector, property, semanticDefaults) {
  const typographyProperties = new Set([
    'color', 'font', 'font-family', 'font-size', 'font-style', 'font-weight',
    'letter-spacing', 'line-height', 'text-align', 'text-decoration', 'text-transform',
  ]);
  if (selector === 'body' && typographyProperties.has(property) && semanticDefaults.bodyTypography) {
    return { supported: true, group: 'typography', control: 'typographyBody' };
  }
  if (selector === 'html' && property === 'font-size' && semanticDefaults.htmlFontSize) {
    return { supported: true, group: 'typography', control: 'typographyHtml' };
  }
  if ([':root', 'html', 'body'].includes(selector)
    && ['background', 'background-color'].includes(property)
    && semanticDefaults.siteBackground) {
    return { supported: true, group: 'general', control: 'siteBackground' };
  }
  if (/^h[1-6]$/.test(selector) && typographyProperties.has(property) && objectValue(semanticDefaults.headings)[selector]) {
    return { supported: true, group: 'typography', control: `typographyHeading${selector.toUpperCase()}` };
  }
  if (selector === 'a' && semanticDefaults.link) {
    if (typographyProperties.has(property)) return { supported: true, group: 'links', control: 'typography' };
    if (property.startsWith('background')) return { supported: true, group: 'links', control: 'background' };
    if (property.startsWith('border')) return { supported: true, group: 'links', control: 'border' };
    if (property.startsWith('padding')) return { supported: true, group: 'links', control: 'padding' };
    if (property === 'transition') return { supported: true, group: 'links', control: 'transition' };
  }
  if (selector === 'section' && semanticDefaults.section) {
    if (property === 'display') return { supported: true, group: 'section', control: '_display' };
    if (property.startsWith('padding')) return { supported: true, group: 'section', control: 'padding' };
    if (property.startsWith('background')) return { supported: true, group: 'section', control: 'background' };
  }
  if (selector === 'button' && semanticDefaults.button) {
    if (typographyProperties.has(property)) return { supported: true, group: 'button', control: 'typography' };
    if (property.startsWith('background')) return { supported: true, group: 'button', control: 'primaryBackground' };
    if (property.startsWith('border')) return { supported: true, group: 'button', control: 'border' };
    if (property.startsWith('padding')) return { supported: true, group: 'button', control: 'sizeDefaultPadding' };
    if (property === 'transition') return { supported: true, group: 'button', control: 'transition' };
  }
  if (['input', 'textarea', 'select'].includes(selector) && semanticDefaults.form) {
    if (typographyProperties.has(property)) return { supported: true, group: 'form', control: 'fieldTypography' };
    if (property === 'background-color') return { supported: true, group: 'form', control: 'fieldBackgroundColor' };
    if (property.startsWith('border')) return { supported: true, group: 'form', control: 'fieldBorder' };
    if (property.startsWith('padding')) return { supported: true, group: 'form', control: 'fieldPadding' };
  }
  if (selector === ':focus-visible' && property === 'outline' && semanticDefaults.focusOutline) {
    return { supported: true, group: 'typography', control: 'focusOutline' };
  }
  return { supported: false, group: 'css', control: 'stylesheet' };
}

function buildPixflowStageBFoundationStylesheet(declarations, templateOwnership) {
  const reset = `/* Pixflow page-foundation compatibility reset: only neutralises Bricks defaults inside the converted content root. */
#brx-content.pixflow-generated-page { min-width: 0; padding: 0; font-size: 16px; line-height: normal; }
:where(#brx-content.pixflow-generated-page) :is(.brxe-section, .brxe-container, .brxe-block, .brxe-div) { display: block; min-width: 0; }
:where(#brx-content.pixflow-generated-page) .brxe-section { padding: 0; }
:where(#brx-content.pixflow-generated-page) :is(.brxe-heading, .brxe-text, .brxe-text-basic, .brxe-text-link, .brxe-button) { color: inherit; font-family: inherit; }
:where(#brx-content.pixflow-generated-page) h1.brxe-heading { margin: .67em 0; font-size: 2em; font-weight: 700; line-height: normal; }
:where(#brx-content.pixflow-generated-page) h2.brxe-heading { margin: .83em 0; font-size: 1.5em; font-weight: 700; line-height: normal; }
:where(#brx-content.pixflow-generated-page) h3.brxe-heading { margin: 1em 0; font-size: 1.17em; font-weight: 700; line-height: normal; }
:where(#brx-content.pixflow-generated-page) h4.brxe-heading { margin: 1.33em 0; font-size: 1em; font-weight: 700; line-height: normal; }
:where(#brx-content.pixflow-generated-page) h5.brxe-heading { margin: 1.67em 0; font-size: .83em; font-weight: 700; line-height: normal; }
:where(#brx-content.pixflow-generated-page) h6.brxe-heading { margin: 2.33em 0; font-size: .67em; font-weight: 700; line-height: normal; }
:where(#brx-content.pixflow-generated-page) p:is(.brxe-text, .brxe-text-basic) { margin: 1em 0; }
:where(#brx-content.pixflow-generated-page) blockquote:is(.brxe-block, .brxe-div, .brxe-text, .brxe-text-basic) { position: static; margin: 1em 40px; padding: 0; border: 0; font-weight: inherit; }
:where(#brx-content.pixflow-generated-page) blockquote { position: static; margin: 1em 40px; padding: 0; border: 0; font-weight: inherit; }
:where(#brx-content.pixflow-generated-page) a:is(.brxe-text-link, .brxe-button, .brxe-block, .brxe-div, .brxe-text-basic) { display: inline; color: #0000ee; text-decoration: underline; }
:where(#brx-content.pixflow-generated-page) :is(button, input, textarea, select) { font: inherit; }`;
  const blocks = [];
  for (const item of arrayValue(declarations)) {
    if (item.nativeSupported) continue;
    const selector = scopePixflowStageBFoundationSelector(
      firstString(item.provenance) === 'source_root_rem_baseline' ? 'html' : item.selector,
      templateOwnership,
    );
    if (!selector || !firstString(item.property) || !firstString(item.value)) continue;
    blocks.push(`${selector} { ${item.property}: ${item.value}${item.important ? ' !important' : ''}; }`);
  }
  return uniqueStrings([reset, ...blocks]).join('\n');
}

function scopePixflowStageBFoundationSelector(selectorValue, templateOwnership) {
  const selector = firstString(selectorValue).toLowerCase();
  const roots = ['#brx-content.pixflow-generated-page'];
  if (templateOwnership?.header === 'source_owned') roots.push('#brx-header');
  if (templateOwnership?.footer === 'source_owned') roots.push('#brx-footer');
  if ([':root', 'html', 'body'].includes(selector)) return roots.join(', ');
  const specificityNeutralRoot = `:where(${roots.join(', ')})`;
  if (selector === ':focus-visible') return `${specificityNeutralRoot} :focus-visible`;
  if (!isPixflowStageBDirectFoundationSelector(selector)) return '';
  const bricksElementSelector = {
    h1: 'h1.brxe-heading',
    h2: 'h2.brxe-heading',
    h3: 'h3.brxe-heading',
    h4: 'h4.brxe-heading',
    h5: 'h5.brxe-heading',
    h6: 'h6.brxe-heading',
    p: 'p:is(.brxe-text, .brxe-text-basic)',
    // Exact HTML interaction islands render their semantic descendants
    // without a Bricks wrapper class. Scope authored blockquote defaults to
    // the semantic tag so native projections and exact islands share the
    // same source reset while class-owned component styles still win.
    blockquote: 'blockquote',
    figcaption: 'figcaption:is(.brxe-text, .brxe-text-basic)',
    a: 'a:is(.brxe-text-link, .brxe-button, .brxe-block, .brxe-div, .brxe-text-basic)',
  }[selector] || selector;
  // Adding an ID-bearing Bricks root directly would make a source `h2` reset
  // outrank class-owned component typography. :where() constrains the rule to
  // the owned roots without changing the source selector's specificity.
  return `${specificityNeutralRoot} ${bricksElementSelector}`;
}

function collectPixflowStageBThemeStyleVariableReferences(value) {
  const json = JSON.stringify(value || {});
  return uniqueStrings([...json.matchAll(/var\((--[A-Za-z0-9_-]+)/g)].map((match) => match[1])).sort();
}

function refreshPixflowStageBThemeStyleDependencies(themeStylePayload, tokenGraphReport) {
  const settings = objectValue(themeStylePayload?.settings);
  const cssVariables = collectPixflowStageBThemeStyleVariableReferences(settings);
  const resources = arrayValue(tokenGraphReport?.mutationIntent?.resourceAdditions?.variables)
    .filter((item) => cssVariables.includes(firstString(item?.cssVariable)))
    .map((item) => firstString(item?.id))
    .filter(Boolean);
  themeStylePayload.dependencies = {
    cssVariables,
    paletteOrVariableResources: uniqueStrings(resources).sort(),
  };
}

function pixflowStageBDecorativeFormFieldStyle(formNode, context = {}, descendantStyles) {
  const classInfo = objectValue(context?.classInfo);
  const labels = flattenPixflowHtmlElements(formNode).filter((item) => (
    firstString(item?.tag).toLowerCase() === 'label'
    && isPixflowStageBDecorativeFormControlLabel(item)
  ));
  const resolvedDescendantStyles = descendantStyles || buildPixflowStageBDescendantElementStyleMap(
    classInfo.rules,
    classInfo.cssVariables,
  );
  return commonPixflowStageBFormLabelStyle(labels, resolvedDescendantStyles, classInfo);
}

function collectPixflowStageBFormControlWrapperDeclarations(control, formNode, context = {}) {
  let wrapper = control?.parent;
  const declarations = {};
  let foundWrapper = false;
  while (wrapper && wrapper !== formNode) {
    foundWrapper = true;
    for (const className of pixflowStageBHtmlClassList(wrapper)) {
      Object.assign(declarations, objectValue(context?.classInfo?.declarationsByClass?.get(className)));
    }
    wrapper = wrapper.parent;
  }
  return { declarations, foundWrapper };
}

function buildPixflowStageBFormInternalLayoutCss(controls, formNode, context = {}, nativeSettings = {}) {
  const chunks = [];
  const emittedChunks = new Set();
  const pushChunk = (chunk) => {
    const value = firstString(chunk);
    if (!value || emittedChunks.has(value)) return;
    emittedChunks.add(value);
    chunks.push(value);
  };
  const consumedChoiceNames = new Set();
  let visibleFieldIndex = 0;
  for (const control of arrayValue(controls)) {
    const tag = firstString(control?.tag).toLowerCase();
    if (!['input', 'textarea', 'select'].includes(tag)) continue;
    const type = tag === 'input' ? firstString(pixflowStageBAttr(control, 'type'), 'text').toLowerCase() : tag;
    if (['submit', 'button', 'reset', 'image', 'hidden'].includes(type)) continue;
    if (['checkbox', 'radio'].includes(type)) {
      const choiceName = firstString(pixflowStageBAttr(control, 'name'));
      const choiceKey = `${type}:${choiceName}`;
      if (choiceName && consumedChoiceNames.has(choiceKey)) continue;
      if (choiceName) consumedChoiceNames.add(choiceKey);
    }
    visibleFieldIndex += 1;
    const { declarations } = collectPixflowStageBFormControlWrapperDeclarations(control, formNode, context);
    const layout = {};
    for (const key of [
      'display',
      'flex',
      'flex-direction',
      'flex-wrap',
      'flex-grow',
      'flex-shrink',
      'flex-basis',
      'gap',
      'row-gap',
      'column-gap',
      'align-items',
      'align-self',
      'justify-content',
      'order',
      'width',
      'min-width',
      'max-width',
      'height',
      'min-height',
      'max-height',
    ]) {
      if (firstString(declarations[key])) layout[key] = declarations[key];
    }
    const css = serializePixflowCssDeclarations(layout, { cssVariables: context?.classInfo?.cssVariables });
    if (css) pushChunk(`%root% .form-group:nth-child(${visibleFieldIndex}) { ${css} }`);

    const controlDeclarations = collectPixflowStageBNativeFormControlDeclarations(control, context);
    const controlLayout = {};
    const nativeFieldPaddingAvailable = Object.keys(objectValue(nativeSettings.fieldPadding)).length > 0;
    for (const key of [
      'height',
      'min-height',
      'max-height',
      ...(!nativeFieldPaddingAvailable ? [
        'padding',
        'padding-block',
        'padding-inline',
        'padding-top',
        'padding-right',
        'padding-bottom',
        'padding-left',
      ] : []),
      'resize',
    ]) {
      if (firstString(controlDeclarations[key])) controlLayout[key] = controlDeclarations[key];
    }
    const controlCss = serializePixflowCssDeclarations(controlLayout, { cssVariables: context?.classInfo?.cssVariables });
    if (controlCss) pushChunk(`%root% ${tag} { ${controlCss} }`);
    for (const stateCss of buildPixflowStageBFormControlStateCss(control, context)) {
      pushChunk(stateCss);
    }
  }

  const submit = arrayValue(controls).find((control) => {
    const tag = firstString(control?.tag).toLowerCase();
    const type = firstString(pixflowStageBAttr(control, 'type'), tag === 'button' ? 'submit' : 'text').toLowerCase();
    return (tag === 'button' && type === 'submit') || (tag === 'input' && type === 'submit');
  });
  if (submit) {
    const wrapperDeclarations = collectPixflowStageBFormControlWrapperDeclarations(
      submit,
      formNode,
      context,
    ).declarations;
    const controlDeclarations = collectPixflowStageBNativeFormControlDeclarations(submit, context);
    const declarations = {
      // The native Bricks wrapper replaces the source wrapper but contains the
      // source button. Use the button as a dimensional fallback, while keeping
      // wrapper-owned position/insets/layout authoritative when both declare
      // the same property (for example absolute wrapper + relative button).
      ...controlDeclarations,
      ...wrapperDeclarations,
    };
    const submitWrapperLayout = {};
    for (const key of [
      'position',
      'top',
      'right',
      'bottom',
      'left',
      'inset-inline-start',
      'inset-inline-end',
      'z-index',
      'display',
      'justify-content',
      'align-items',
      'width',
      'min-width',
      'max-width',
      'height',
      'min-height',
      'max-height',
      'margin-top',
      'margin-right',
      'margin-bottom',
      'margin-left',
      'align-self',
      'order',
    ]) {
      const value = firstString(declarations[key]);
      if (!value) continue;
      // Percentage width is represented by Bricks' native numeric
      // submitButtonWidth control. Auto is already the Bricks frontend
      // default; emitting the string "auto" into a number control is invalid.
      if (key === 'width' && (/^-?(?:\d+\.?\d*|\.\d+)%$/.test(value) || value === 'auto')) continue;
      submitWrapperLayout[key] = value;
    }
    const submitWrapperCss = serializePixflowCssDeclarations(submitWrapperLayout, {
      cssVariables: context?.classInfo?.cssVariables,
    }).replace(/\b(width|height):\s*([^;]+);/g, '$1: $2 !important;');
    if (submitWrapperCss) pushChunk(`%root% .submit-button-wrapper { ${submitWrapperCss} }`);
    if (firstString(submitWrapperLayout.width) && firstString(submitWrapperLayout.height)) {
      pushChunk('%root% .submit-button-wrapper .bricks-button { width: 100% !important; height: 100% !important; min-height: 0 !important; padding: 0 !important; overflow: hidden; }');
    }
    const visibleSubmitText = normalizeWhitespace(
      pixflowStageBNodeText(submit) || pixflowStageBAttr(submit, 'value'),
    );
    const accessibleSubmitText = normalizeWhitespace(pixflowStageBAttr(submit, 'aria-label'));
    const submitSvg = flattenPixflowHtmlElements(submit)
      .find((node) => firstString(node?.tag).toLowerCase() === 'svg');
    if (
      !visibleSubmitText
      && submitSvg
      && /\b(?:send|submit|prompt)\b/i.test(accessibleSubmitText)
    ) {
      // Bricks' custom-CSS compiler rejects data-URI SVG masks and can drop
      // the page stylesheet. Preserve common icon-only send controls with a
      // compiler-safe arrow while retaining the real accessible label.
      pushChunk('%root% .submit-button-wrapper .bricks-button .text { display: block; width: 16px; height: 16px; font-size: 0; line-height: 1; color: inherit; overflow: hidden; }');
      pushChunk('%root% .submit-button-wrapper .bricks-button .text::after { content: "↑"; display: block; width: 100%; height: 100%; font-size: 16px; line-height: 1; }');
    }
    if (firstString(submitWrapperLayout.position).toLowerCase() === 'absolute') {
      // Bricks adds a 20px bottom gap to every non-final form group. An
      // absolutely positioned source submit is removed from document flow, so
      // that gap incorrectly increases the native form/composer height.
      pushChunk('%root% .form-group:not(.submit-button-wrapper) { padding-bottom: 0; }');
    }
  }
  return chunks.join('\n');
}

function buildPixflowStageBFormControlStateCss(control, context = {}) {
  const classInfo = objectValue(context?.classInfo);
  const ancestorClasses = new Set(getPixflowStageBAncestorClassNames(control));
  const ownClasses = new Set(pixflowStageBHtmlClassList(control));
  const tag = firstString(control?.tag).toLowerCase();
  const result = [];
  for (const rule of arrayValue(classInfo.rules)) {
    for (const selector of splitPixflowCssSelectorList(rule?.selector || '')) {
      const match = matchPixflowStageBSimpleDescendantElementSelector(selector);
      if (
        !match
        || match.tag !== tag
        || !firstString(match.state)
        || match.structuralPseudo
        || (match.excludedClass && ownClasses.has(match.excludedClass))
        || !ancestorClasses.has(match.ancestorClass)
        || (match.requiredAncestorClass && !ancestorClasses.has(match.requiredAncestorClass))
      ) {
        continue;
      }
      const css = serializePixflowCssDeclarations(objectValue(rule.declarations), {
        cssVariables: classInfo.cssVariables,
      });
      if (css) result.push(`%root% ${tag}:${match.state} { ${css} }`);
    }
  }
  return uniqueStrings(result);
}

function collectPixflowStageBNativeFormControlDeclarations(control, context = {}) {
  const declarations = {};
  const classInfo = objectValue(context?.classInfo);
  for (const className of pixflowStageBHtmlClassList(control)) {
    Object.assign(declarations, objectValue(classInfo.declarationsByClass?.get?.(className)));
  }
  const ancestorClasses = new Set(getPixflowStageBAncestorClassNames(control));
  const tag = firstString(control?.tag).toLowerCase();
  for (const rule of arrayValue(classInfo.rules)) {
    for (const selector of splitPixflowCssSelectorList(rule?.selector || '')) {
      const match = matchPixflowStageBSimpleDescendantElementSelector(selector);
      if (
        !match
        || match.tag !== tag
        || match.state
        || match.structuralPseudo
        || match.excludedClass
        || match.interactionAncestorClass
        || !ancestorClasses.has(match.ancestorClass)
        || (match.requiredAncestorClass && !ancestorClasses.has(match.requiredAncestorClass))
      ) {
        continue;
      }
      Object.assign(declarations, objectValue(rule.declarations));
    }
  }
  Object.assign(declarations, parseStageBCssDeclarations(firstString(pixflowStageBAttr(control, 'style'))));
  return declarations;
}

function findPixflowStageBFormControlLabel(control, formNode) {
  const sourceId = firstString(pixflowStageBAttr(control, 'id'));
  if (sourceId && formNode) {
    const explicit = flattenPixflowHtmlElements(formNode).find((item) => (
      firstString(item?.tag).toLowerCase() === 'label'
      && firstString(pixflowStageBAttr(item, 'for')) === sourceId
    ));
    const explicitText = pixflowStageBFormLabelText(explicit);
    if (explicitText) return explicitText;
  }
  let parent = control?.parent;
  while (parent && parent !== formNode) {
    if (firstString(parent.tag).toLowerCase() === 'label') {
      const text = pixflowStageBDecorativeFormLabelAccessibleText(parent)
        || pixflowStageBFormLabelText(parent);
      if (text) return text;
    }
    parent = parent.parent;
  }
  return '';
}

function pixflowStageBFormLabelText(label) {
  const chunks = [];
  const visit = (node) => {
    if (!node) return;
    if (node.type === 'text') {
      const text = normalizeWhitespace(node.text);
      if (text) chunks.push(text);
      return;
    }
    if (node.type !== 'element') return;
    if (['input', 'select', 'textarea', 'button'].includes(firstString(node.tag).toLowerCase())) {
      return;
    }
    for (const child of arrayValue(node.children)) visit(child);
  };
  for (const child of arrayValue(label?.children)) visit(child);
  return normalizeWhitespace(chunks.join(' '));
}

function parsePixflowStageBPositiveIntegerAttribute(node, name) {
  const value = firstString(pixflowStageBAttr(node, name));
  if (!/^\d+$/.test(value)) return null;
  return Number.parseInt(value, 10);
}

function applyPixflowStageBSelectFieldOptions(field, control) {
  const options = arrayValue(control?.children)
    .filter((child) => firstString(child?.tag).toLowerCase() === 'option')
    .map((option) => {
      const label = normalizeWhitespace(pixflowStageBNodeText(option));
      const value = firstString(pixflowStageBAttr(option, 'value'), label);
      return { label, value, selected: hasPixflowStageBAttr(option, 'selected') };
    })
    .filter((option) => option.label || option.value);
  if (options.length === 0) return;
  field.options = options.map((option) => `${option.value}:${option.label}`).join('\n');
  field.valueLabelOptions = true;
  const selected = options.find((option) => option.selected);
  if (selected) field.value = selected.value;
}

function applyPixflowStageBChoiceFieldOptions(field, controls, formNode) {
  const options = arrayValue(controls).map((control) => {
    const label = firstString(
      findPixflowStageBFormControlLabel(control, formNode),
      pixflowStageBAttr(control, 'aria-label'),
      pixflowStageBAttr(control, 'value'),
      field.name,
    );
    const value = firstString(pixflowStageBAttr(control, 'value'), 'on');
    return { label, value, checked: hasPixflowStageBAttr(control, 'checked') };
  });
  field.options = options.map((option) => `${option.value}:${option.label}`).join('\n');
  field.valueLabelOptions = true;
  const checked = options.filter((option) => option.checked).map((option) => option.value);
  if (checked.length > 0) field.value = checked.join(',');
  // Checkbox/radio option labels already carry the visible source label. Avoid
  // rendering the same wrapping-label copy twice as a separate group heading.
  if (!firstString(pixflowStageBAttr(controls[0], 'aria-label'))) field.label = '';
}

function hasPixflowStageBVisibleFormLabels(node) {
  if (!node || node.type !== 'element') return false;
  if (firstString(node.tag).toLowerCase() === 'label') {
    if (isPixflowStageBDecorativeFormControlLabel(node)) return false;
    const hidden = pixflowStageBHtmlClassList(node).some((className) => (
      /^(?:sr-only|screen-reader-text|visually-hidden)$/i.test(className)
    ));
    return !hidden && Boolean(normalizeWhitespace(pixflowStageBNodeText(node)));
  }
  return (node.children || []).some((child) => hasPixflowStageBVisibleFormLabels(child));
}

function addPixflowStageBHtmlIconElement(node, parentId, context, options = {}) {
  if (!parentId) return '';
  const iconId = inferPixflowStageBIconId(node);
  const setId = firstString(context.iconSystem?.defaultSetId, 'tabler-outline');
  ensurePixflowStageBIconSystemIcon(context.iconSystem, {
    id: iconId,
    setId,
    roles: ['source_inline_icon'],
    reason: 'Mapped from a compact source inline SVG during deterministic Bricks conversion.',
  });
  const settings = buildPixflowStageBElementBaseSettings(node, context, options, parentId);
  if (Array.isArray(settings._attributes)) {
    // Bricks inlines custom SVG files and merges root attributes by substring.
    // Re-emitting source width/height here can therefore append `width` to the
    // SVG's existing `stroke-width` and produce invalid values such as
    // `stroke-width="24 2"`. Dimensions already belong to the native icon
    // control and source classes, so keep semantic attributes but remove the
    // duplicate presentation attributes from the rendered SVG root.
    settings._attributes = settings._attributes.filter((attribute) => ![
      'width',
      'height',
    ].includes(firstString(attribute?.name).toLowerCase()));
    if (settings._attributes.length === 0) delete settings._attributes;
  }
  settings.icon = buildPixflowStageBIconControlSetting({
    iconId,
    setId,
    node,
    context,
  });
  const elementId = addPixflowStageBHtmlElement(
    context,
    `${context.scope}:icon:${node.sourceIndex}:${iconId}`,
    'icon',
    settings,
    parentId,
    { node, reason: 'compact_svg_to_native_icon' },
  );
  context.structureRecorder.recordSubtreeDisposition(
    node,
    'encapsulated_native_icon',
    'source_svg_descendants_projected_into_native_icon_control',
    elementId,
    false,
  );
  return elementId;
}

function addPixflowStageBHtmlArtworkSvgElement(node, parentId, context, options = {}) {
  if (!parentId) return '';
  const settings = buildPixflowStageBElementBaseSettings(node, context, options, parentId);
  const attributes = (Array.isArray(settings._attributes) ? settings._attributes : [])
    // Bricks injects element `_attributes` onto the root SVG returned by the
    // signed code. Repeating source-owned root attributes (height, width,
    // viewBox, aria-*) concatenates their values and can invalidate SVG sizing
    // such as `height="22.26 22.26"`. Keep only the internal evidence trace;
    // the complete sanitized source SVG already owns every authored attribute.
    .filter((attribute) => firstString(attribute?.name).toLowerCase() === 'data-pf-source-id');
  attributes.push(buildPixflowStageBManualAttribute(`svg-artwork:${node.sourceIndex}`, 'data-pixflow-svg-role', 'artwork'));
  settings._attributes = attributes;
  settings.source = 'code';
  settings.code = sanitizePixflowStageBInlineSvgMarkup(pixflowStageBNodeOuterHtml(node))
    // The trusted role marker is supplied once through `_attributes` so the
    // WordPress signing boundary can identify Pixflow artwork without Bricks
    // concatenating a duplicate value already present in source markup.
    .replace(/\sdata-pixflow-svg-role\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, '');
  // Pixflow-owned: source charts and decorative visualizations are not icons.
  // Preserve them as Bricks SVG code so the baseline remains visually close,
  // while icon-like SVGs still flow through the Pixflow icon-set path.
  const elementId = addPixflowStageBHtmlElement(
    context,
    `${context.scope}:svg-artwork:${node.sourceIndex}`,
    'svg',
    settings,
    parentId,
    { node, reason: 'source_svg_artwork_projection' },
  );
  context.structureRecorder.recordSubtreeDisposition(
    node,
    'encapsulated_svg_artwork',
    'source_svg_descendants_preserved_in_native_svg_code',
    elementId,
    false,
  );
  return elementId;
}

function addPixflowStageBHtmlElement(context, seed, name, settings = {}, parent = '', provenance = {}) {
  const idSeed = `stage-b-html-element:${seed}`;
  const usedElementIds = context.usedElementIds instanceof Set
    ? context.usedElementIds
    : new Set(context.elementsById?.keys?.() || []);
  context.usedElementIds = usedElementIds;
  const preferredId = deterministicBricksId(idSeed);
  let id = preferredId;
  let collisionIndex = 0;
  while (usedElementIds.has(id)) {
    collisionIndex += 1;
    id = deterministicBricksId(`${idSeed}:collision:${collisionIndex}`);
  }
  usedElementIds.add(id);
  const element = {
    id,
    name,
    settings: removeUndefinedObjectValues(settings),
    children: [],
  };
  if (parent) {
    element.parent = parent;
  }
  context.content.push(element);
  context.elementsById.set(id, element);
  if (parent) {
    const parentElement = context.elementsById.get(parent);
    if (parentElement && !parentElement.children.includes(id)) {
      parentElement.children.push(id);
    }
  }
  if (provenance?.node) {
    context.structureRecorder.recordSourceElement({
      elementId: id,
      elementName: name,
      node: provenance.node,
      reason: provenance.reason,
    });
  } else if (provenance?.syntheticReason) {
    context.structureRecorder.recordSyntheticElement({
      elementId: id,
      elementName: name,
      reason: provenance.syntheticReason,
      parentElementId: firstString(provenance.parentElementId, parent),
    });
  }
  if (collisionIndex > 0) {
    context.structureRecorder.addDiagnostic({
      code: 'deterministic_element_id_collision_resolved',
      severity: 'info',
      message: `Resolved deterministic Bricks element id collision ${preferredId} as ${id}.`,
      sourceNodeId: provenance?.node ? pixflowStageBAttr(provenance.node, 'data-pf-source-id') : '',
      bricksElementId: id,
      preferredBricksElementId: preferredId,
      collisionIndex,
    });
  }
  return id;
}

export function applyPixflowStageBHeaderBaselineContract(headerContent, headerPlan, classInfo = {}, options = {}) {
  if (!Array.isArray(headerContent) || headerContent.length === 0) {
    return;
  }
  const rootSections = headerContent.filter((element) => (
    (
      firstString(element?.name) === 'section'
      || ['header', 'nav'].includes(firstString(element?.settings?.tag).toLowerCase())
    )
    && !firstString(element?.parent)
  ));
  const selectedSectionOdId = firstString(headerPlan?.selectedSectionOdId);
  for (const root of rootSections) {
    const settings = objectValue(root.settings);
    if (selectedSectionOdId) {
      const attributes = Array.isArray(settings._attributes) ? settings._attributes : [];
      const hasTrace = attributes.some((attribute) => (
        ['data-od-id', 'id'].includes(firstString(attribute?.name))
        && firstString(attribute?.value) === selectedSectionOdId
      ));
      if (!hasTrace) {
        attributes.push(buildPixflowStageBManualAttribute(`header-selected:${root.id}`, 'data-od-id', selectedSectionOdId));
        settings._attributes = attributes;
      }
    }
    root.settings = settings;
    // Complete uploaded pages already carry the source header hierarchy and
    // measured layout. The generic template wrapper is useful for authored
    // Bricks headers, but inserting it into a source-fidelity conversion moves
    // nav and hero siblings into a new flex row and destroys the captured page.
    normalizePixflowStageBHeaderRootWrapper(headerContent, root, classInfo, options);
  }
}

function normalizePixflowStageBHeaderRootWrapper(headerContent, root, classInfo = {}, options = {}) {
  const childIds = Array.isArray(root.children) ? [...root.children] : [];
  if (childIds.length === 0) {
    return;
  }
  const byId = new Map(headerContent.map((element) => [firstString(element?.id), element]).filter(([id]) => id));
  let wrapper = childIds.length === 1 ? byId.get(firstString(childIds[0])) : null;
  if (
    options.preserveSourceHierarchy === true
    && (!wrapper || !['container', 'block', 'div'].includes(firstString(wrapper.name)))
  ) {
    return;
  }
  if (!wrapper || !['container', 'block', 'div'].includes(firstString(wrapper.name))) {
    const wrapperId = deterministicBricksId(`stage-b-html-header-wrapper:${root.id}`);
    wrapper = {
      id: wrapperId,
      name: 'container',
      parent: root.id,
      children: childIds,
      settings: {},
    };
    for (const childId of childIds) {
      const child = byId.get(firstString(childId));
      if (child) child.parent = wrapperId;
    }
    root.children = [wrapperId];
    const rootIndex = headerContent.findIndex((element) => firstString(element?.id) === firstString(root.id));
    headerContent.splice(rootIndex + 1, 0, wrapper);
    options.structureRecorder?.recordSyntheticElement({
      elementId: wrapperId,
      elementName: 'container',
      reason: 'bricks_header_container_contract',
      parentElementId: root.id,
    });
  }
  if (!hasPixflowStageBElementClassLayoutSettings(wrapper, classInfo)) {
    applyPixflowStageBHeaderLayoutSettings(wrapper.settings || (wrapper.settings = {}), {
      justifyContent: 'space-between',
    });
  }
  ensurePixflowStageBHeaderNarrowLayoutContract(wrapper, classInfo);
  const wrapperChildren = (Array.isArray(wrapper.children) ? wrapper.children : [])
    .map((id) => byId.get(firstString(id)) || headerContent.find((element) => firstString(element?.id) === firstString(id)))
    .filter(Boolean);
  for (const child of wrapperChildren) {
    const classText = resolvePixflowStageBElementClassText(child, classInfo);
    const directChildren = (Array.isArray(child?.children) ? child.children : [])
      .map((id) => byId.get(firstString(id)) || headerContent.find((element) => firstString(element?.id) === firstString(id)))
      .filter(Boolean);
    const hasDirectActionButton = directChildren.some((element) => firstString(element?.name) === 'button');
    if (
      firstString(child?.name) === 'div'
      && (
        /\b(?:nav|nav-links|menu|actions?)\b/i.test(classText)
        // Some saved pages use generated utility classes and expose no
        // semantic nav/action token at all. A wrapper with direct CTA/menu
        // buttons is still the header action block and must receive the same
        // explicit Bricks flex contract before Stage B QA.
        || hasDirectActionButton
      )
      && !hasPixflowStageBElementClassLayoutSettings(child, classInfo)
    ) {
      applyPixflowStageBHeaderLayoutSettings(child.settings || (child.settings = {}), {
        justifyContent: /\b(?:actions?)\b/i.test(classText) ? 'flex-end' : 'center',
      });
    }
  }
}

function applyPixflowStageBHeaderLayoutSettings(settings, options = {}) {
  settings._display = firstString(settings._display, 'flex');
  settings._direction = firstString(settings._direction, 'row');
  settings._flexWrap = firstString(settings._flexWrap, 'wrap');
  settings._alignItems = firstString(settings._alignItems, 'center');
  settings._justifyContent = firstString(settings._justifyContent, options.justifyContent, 'space-between');
  settings._columnGap = firstString(settings._columnGap, 'clamp(16px, 3vw, 32px)');
  settings._rowGap = firstString(settings._rowGap, '12px');
  settings['_direction:mobile_portrait'] = firstString(settings['_direction:mobile_portrait'], 'column');
}

function hasPixflowStageBElementClassLayoutSettings(element, classInfo = {}) {
  const classIds = arrayValue(objectValue(element?.settings)._cssGlobalClasses).map((id) => firstString(id)).filter(Boolean);
  if (classIds.length === 0) {
    return false;
  }
  const classes = arrayValue(classInfo?.globalClasses);
  const layoutKeys = [
    '_display',
    '_direction',
    '_gridTemplateColumns',
    '_gridTemplateRows',
    '_alignItems',
    '_justifyContent',
    '_alignItemsGrid',
    '_justifyItemsGrid',
  ];
  return classes.some((item) => {
    if (!classIds.includes(firstString(item?.id))) {
      return false;
    }
    const settings = objectValue(item?.settings);
    return layoutKeys.some((key) => firstString(settings[key]));
  });
}

function resolvePixflowStageBElementClassText(element, classInfo = {}) {
  const classIds = arrayValue(objectValue(element?.settings)._cssGlobalClasses);
  const idToClassName = new Map();
  for (const item of arrayValue(classInfo?.globalClasses)) {
    idToClassName.set(firstString(item?.id), firstString(item?.name));
  }
  return [
    firstString(element?.name),
    ...classIds.map((id) => firstString(idToClassName.get(id))),
    JSON.stringify(objectValue(element?.settings)._attributes || []),
  ].join(' ');
}

function buildPixflowStageBElementBaseSettings(node, context, options = {}, parentId = '') {
  const settings = {};
  const classNames = pixflowStageBHtmlClassList(node);
  const classIds = [];
  const tag = firstString(node?.tag).toLowerCase();
  const bodyClassId = context.classInfo.syntheticClassIdByKey?.get('body');
  const tagClassId = context.classInfo.syntheticClassIdByKey?.get(`tag:${tag}`);
  const attachesBodyType = bodyClassId && shouldAttachPixflowStageBBodyTypeClass(node, parentId, context.classInfo);
  if (attachesBodyType) {
    classIds.push(bodyClassId);
  }
  if (!attachesBodyType && parentId && /^(?:span|strong|b|em|small|code)$/.test(tag)) {
    const inheritClassId = context.classInfo.syntheticClassIdByKey?.get('inline:inherit');
    if (inheritClassId) classIds.push(inheritClassId);
  }
  if (tagClassId) {
    classIds.push(tagClassId);
  }
  if (!parentId && options.templatePart === 'header') {
    const resetClassId = context.classInfo.syntheticClassIdByKey?.get('template:header-root');
    if (resetClassId) classIds.push(resetClassId);
  }
  if (!parentId && options.templatePart === 'footer') {
    const resetClassId = context.classInfo.syntheticClassIdByKey?.get('template:footer-root');
    if (resetClassId) classIds.push(resetClassId);
  }
  classIds.push(...orderPixflowStageBClassNamesForCascade(classNames, context.classInfo)
    .map((className) => context.classInfo.classIdByName.get(className))
    .filter(Boolean));
  const htmlId = firstString(pixflowStageBAttr(node, 'id'));
  const idClassId = htmlId ? context.classInfo.idClassIdByName?.get(htmlId) : '';
  if (idClassId) {
    classIds.push(idClassId);
  }
  const descendantClassIds = resolvePixflowStageBDescendantElementClassIds(node, context.classInfo);
  if (descendantClassIds.length > 0) {
    classIds.push(...descendantClassIds);
  }
  const responsiveDescendantClassIds = resolvePixflowStageBDescendantClassIds(node, context.classInfo);
  if (responsiveDescendantClassIds.length > 0) {
    classIds.push(...responsiveDescendantClassIds);
  }
  classIds.push(...resolvePixflowStageBStructuralClassIds(node, context.classInfo));
  if (isPixflowStageBWorkInnerContainerNode(node)) {
    const workShellClassId = context.classInfo.syntheticClassIdByKey?.get('work:container-shell');
    if (workShellClassId) classIds.push(workShellClassId);
  }
  if (classIds.length > 0) {
    settings._cssGlobalClasses = uniqueStrings(classIds);
  }
  const attributes = buildPixflowStageBHtmlBricksAttributes(node, `${context.scope}:${node.tag}:${node.sourceIndex}`);
  if (attributes.length > 0) {
    settings._attributes = attributes;
  }
  const entranceInteraction = buildPixflowStageBEntranceInteraction(node, context);
  if (entranceInteraction) {
    settings._interactions = [entranceInteraction];
  }
  const inlineStyle = firstString(pixflowStageBAttr(node, 'style'));
  if (inlineStyle) {
    // Pixflow-owned: generated Stage A artifacts sometimes carry critical
    // layout as inline style. Preserve it via deterministic global classes so
    // baseline visual parity starts close without writing Bricks ID styles.
    const inlineStyleClassId = ensurePixflowStageBInlineStyleGlobalClass(context.classInfo, inlineStyle);
    if (inlineStyleClassId) {
      settings._cssGlobalClasses = uniqueStrings([
        ...arrayValue(settings._cssGlobalClasses),
        inlineStyleClassId,
      ]);
    }
  }
  applyPixflowStageBSemanticElementDefaults(settings, tag, context.classInfo);
  return settings;
}

const PIXFLOW_STAGE_B_NATIVE_ENTRANCE_ANIMATIONS = new Set([
  'fadeIn',
  'fadeInDown',
  'fadeInLeft',
  'fadeInRight',
  'fadeInUp',
  'zoomIn',
  'zoomInDown',
  'zoomInLeft',
  'zoomInRight',
  'zoomInUp',
  'slideInDown',
  'slideInLeft',
  'slideInRight',
  'slideInUp',
]);

function buildPixflowStageBEntranceInteraction(node, context) {
  if (firstString(pixflowStageBAttr(node, 'data-pixflow-motion'))) {
    return null;
  }
  const animationType = normalizePixflowStageBEntranceAnimationType(
    pixflowStageBAttr(node, 'data-pixflow-animation')
  );
  if (!PIXFLOW_STAGE_B_NATIVE_ENTRANCE_ANIMATIONS.has(animationType)) {
    return null;
  }
  const seed = `${context.scope}:${node.tag}:${node.sourceIndex}:${animationType}`;
  const interaction = {
    id: deterministicBricksId(`stage-b-native-entrance:${seed}`),
    trigger: 'enterView',
    action: 'startAnimation',
    animationType,
    titleEditable: 'Pixflow entrance animation',
  };
  const duration = normalizePixflowStageBAnimationTime(firstString(
    pixflowStageBAttr(node, 'data-pixflow-animation-duration'),
    pixflowStageBAttr(node, 'data-pixflow-duration')
  ));
  const delay = normalizePixflowStageBAnimationTime(firstString(
    pixflowStageBAttr(node, 'data-pixflow-animation-delay'),
    pixflowStageBAttr(node, 'data-pixflow-delay')
  ));
  if (duration) interaction.animationDuration = duration;
  if (delay) interaction.animationDelay = delay;
  if (isTruthySettingValue(firstString(
    pixflowStageBAttr(node, 'data-pixflow-animation-once'),
    pixflowStageBAttr(node, 'data-pixflow-once'),
    pixflowStageBAttr(node, 'data-pixflow-run-once')
  ))) {
    interaction.runOnce = true;
  }
  return interaction;
}

function normalizePixflowStageBEntranceAnimationType(value) {
  const normalized = firstString(value).replace(/[^a-z0-9]/gi, '').toLowerCase();
  if (!normalized) return '';
  const aliases = {
    enterview: 'fadeInUp',
    enterviewfade: 'fadeIn',
    enterviewfadedown: 'fadeInDown',
    enterviewfadeleft: 'fadeInLeft',
    enterviewfaderight: 'fadeInRight',
    enterviewfadeup: 'fadeInUp',
    enterviewzoom: 'zoomIn',
    enterviewzoomdown: 'zoomInDown',
    enterviewzoomleft: 'zoomInLeft',
    enterviewzoomright: 'zoomInRight',
    enterviewzoomup: 'zoomInUp',
    enterviewslidedown: 'slideInDown',
    enterviewslideleft: 'slideInLeft',
    enterviewslideright: 'slideInRight',
    enterviewslideup: 'slideInUp',
    fadein: 'fadeIn',
    enterfade: 'fadeIn',
    fadeindown: 'fadeInDown',
    enterfadedown: 'fadeInDown',
    fadeinleft: 'fadeInLeft',
    enterfadeleft: 'fadeInLeft',
    fadeinright: 'fadeInRight',
    enterfaderight: 'fadeInRight',
    fadeinup: 'fadeInUp',
    enterfadeup: 'fadeInUp',
    zoomin: 'zoomIn',
    enterzoom: 'zoomIn',
    zoomindown: 'zoomInDown',
    enterzoomdown: 'zoomInDown',
    zoominleft: 'zoomInLeft',
    enterzoomleft: 'zoomInLeft',
    zoominright: 'zoomInRight',
    enterzoomright: 'zoomInRight',
    zoominup: 'zoomInUp',
    enterzoomup: 'zoomInUp',
    slideindown: 'slideInDown',
    enterslidedown: 'slideInDown',
    slideinleft: 'slideInLeft',
    enterslideleft: 'slideInLeft',
    slideinright: 'slideInRight',
    enterslideright: 'slideInRight',
    slideinup: 'slideInUp',
    enterslideup: 'slideInUp',
  };
  return aliases[normalized] || '';
}

function normalizePixflowStageBAnimationTime(value) {
  const normalized = firstString(value);
  if (!normalized) return '';
  if (/^\d*\.?\d+(?:ms|s)$/i.test(normalized)) return normalized.toLowerCase();
  if (/^\d*\.?\d+$/.test(normalized)) {
    return Number(normalized) > 10 ? `${normalized}ms` : `${normalized}s`;
  }
  return '';
}

function ensurePixflowStageBHeaderNarrowLayoutContract(wrapper, classInfo = {}) {
  const settings = objectValue(wrapper?.settings);
  wrapper.settings = settings;
  const classIds = arrayValue(settings._cssGlobalClasses).map((id) => firstString(id)).filter(Boolean);
  const classSettings = arrayValue(classInfo?.globalClasses)
    .filter((classItem) => classIds.includes(firstString(classItem?.id)))
    .map((classItem) => objectValue(classItem?.settings));
  const hasResponsiveLayout = [settings, ...classSettings].some((source) => (
    Object.keys(source).some((key) => /^_(?:direction|flexWrap|gridTemplateColumns):/.test(key))
  ));
  if (hasResponsiveLayout) return;

  // Pixflow-owned: a source header may intentionally remain a row at mobile
  // while hiding navigation/actions. Record that responsive decision on the
  // live wrapper so Stage B can prove it considered the narrow layout without
  // forcing a less-faithful column transformation.
  settings['_direction:mobile_portrait'] = firstString(
    settings._direction,
    ...classSettings.map((source) => source._direction),
    'row'
  );
  settings['_flexWrap:mobile_portrait'] = firstString(
    settings._flexWrap,
    ...classSettings.map((source) => source._flexWrap),
    'nowrap'
  );
}

function applyPixflowStageBSemanticElementDefaults(settings, tag, classInfo = {}) {
  const normalizedTag = firstString(tag).toLowerCase();
  if (!/^(?:section|header|footer|nav|main|article|aside|figure)$/.test(normalizedTag)) {
    return;
  }

  // Bricks gives section/block primitives flex-oriented browser styles and
  // gives sections a project-level vertical gutter. Standalone semantic HTML
  // starts as block flow with zero padding. Global classes alone can lose to
  // Bricks' built-in selector order, so mirror the final native class values
  // onto the element controls that own these collision-prone defaults.
  const classesById = new Map(arrayValue(classInfo?.globalClasses)
    .map((item) => [firstString(item?.id), objectValue(item?.settings)]));
  const classSettings = arrayValue(objectValue(settings)._cssGlobalClasses)
    .map((id) => classesById.get(firstString(id)))
    .filter(Boolean);

  let display = 'block';
  for (const current of classSettings) {
    display = firstString(current?._display, display);
    for (const [key, value] of Object.entries(objectValue(current))) {
      if (key.startsWith('_display:') && firstString(value)) {
        settings[key] = value;
      }
    }
  }
  settings._display = display;

  if (!/^(?:section|header|footer)$/.test(normalizedTag)) {
    return;
  }
  const padding = { top: '0', right: '0', bottom: '0', left: '0' };
  for (const current of classSettings) {
    Object.assign(padding, objectValue(current?._padding));
    for (const [key, value] of Object.entries(objectValue(current))) {
      if (key.startsWith('_padding:') && Object.keys(objectValue(value)).length > 0) {
        settings[key] = { ...objectValue(value) };
      }
    }
  }
  settings._padding = padding;
}

function orderPixflowStageBClassNamesForCascade(classNames, classInfo = {}) {
  return arrayValue(classNames)
    .map((className, index) => ({ className: firstString(className), index }))
    .filter((item) => item.className)
    .sort((a, b) => {
      const aScore = scorePixflowStageBClassCascadePriority(a.className, classInfo);
      const bScore = scorePixflowStageBClassCascadePriority(b.className, classInfo);
      return aScore === bScore ? a.index - b.index : aScore - bScore;
    })
    .map((item) => item.className);
}

function scorePixflowStageBClassCascadePriority(className, classInfo = {}) {
  const declarations = objectValue(classInfo?.declarationsByClass?.get?.(className));
  const normalized = firstString(className).toLowerCase();
  let score = 0;
  if (/\b(?:container|wrap|wrapper|inner|content|shell)\b/.test(normalized)) {
    score -= 10;
  }
  // Pixflow-owned: generic wrapper defaults such as `_display:block` must not
  // override real source layout classes in multi-class nodes like `nav wrap`.
  // Attach explicit layout classes later in the Bricks class list so grid/flex
  // source rules remain authoritative.
  if (firstString(declarations.display, declarations['grid-template-columns'], declarations['flex-direction'], declarations['justify-content'], declarations['align-items'])) {
    score += 10;
  }
  // Source modifiers must remain later than their base component class. Bricks
  // resolves attached global-class settings in list order, so moving a layout-
  // owning `.button` after `.button--primary` makes the base text colour win
  // even though ordinary CSS would let the later modifier rule win.
  if (/--[a-z0-9_-]+$/i.test(normalized) || /^(?:is|has)-[a-z0-9_-]+$/i.test(normalized)) {
    score += 20;
  }
  return score;
}

function ensurePixflowStageBInlineStyleGlobalClass(classInfo, inlineStyle) {
  const declarations = parseStageBCssDeclarations(inlineStyle);
  const settings = mapPixflowCssDeclarationsToBricksSettings(declarations, {
    cssVariables: classInfo?.cssVariables,
  });
  // Pixflow-owned: Stage A often uses per-node CSS custom properties for
  // repeated decorative data bars, for example style="--h: 62%". These are
  // not global design tokens, but they are critical visual state and must stay
  // scoped to the converted Bricks element.
  const inlineCustomProperties = Object.fromEntries(Object.entries(declarations)
    .filter(([property, value]) => /^--[A-Za-z][A-Za-z0-9_-]*$/.test(property) && firstString(value) !== ''));
  if (Object.keys(inlineCustomProperties).length > 0) {
    settings._cssCustom = [
      firstString(settings._cssCustom),
      `%root% { ${serializePixflowCssDeclarations(inlineCustomProperties, { cssVariables: classInfo?.cssVariables })} }`,
    ].filter(Boolean).join('\n');
  }
  const cleanSettings = removeUndefinedObjectValues(settings);
  if (Object.keys(cleanSettings).length === 0) {
    return '';
  }
  const signature = JSON.stringify(cleanSettings);
  if (classInfo?.inlineStyleClassIdBySignature?.has(signature)) {
    return classInfo.inlineStyleClassIdBySignature.get(signature);
  }
  const hash = createHash('sha256').update(signature).digest('hex').slice(0, 8);
  const planned = classInfo?.classPlanner?.claimPreferred
    ? classInfo.classPlanner.claimPreferred(`pixflow-inline-${hash}`, {
      kind: 'inline-style',
      key: hash,
      sourceName: `inline-${hash}`,
      settings: cleanSettings,
      idSeed: `stage-b-html-inline-style-class:${signature}`,
    })
    : {
      id: deterministicBricksId(`stage-b-html-inline-style-class:${signature}`),
      name: normalizePixflowStageBHtmlGlobalClassName(
        `pixflow-inline-${hash}`,
        new Set(arrayValue(classInfo?.globalClasses).map((item) => firstString(item?.name)).filter(Boolean)),
      ),
    };
  const id = planned.id;
  classInfo.inlineStyleClassIdBySignature?.set(signature, id);
  arrayValue(classInfo?.globalClasses).push({
    id,
    name: planned.name,
    settings: cleanSettings,
  });
  if (classInfo?.classPlanner?.toPlan) {
    classInfo.classOwnershipPlan = classInfo.classPlanner.toPlan();
  }
  return id;
}

function mergePixflowStageBSettings(target, source) {
  const result = objectValue(source);
  for (const [key, value] of Object.entries(result)) {
    if (value === undefined || value === null || value === '') {
      continue;
    }
    if (key === '_typography') {
      target._typography = { ...objectValue(target._typography), ...objectValue(value) };
      continue;
    }
    if (key === '_padding' || key === '_margin') {
      target[key] = { ...objectValue(target[key]), ...objectValue(value) };
      continue;
    }
    if (key === '_border') {
      target._border = { ...objectValue(target._border), ...objectValue(value) };
      continue;
    }
    if (key === '_background') {
      target._background = { ...objectValue(target._background), ...objectValue(value) };
      continue;
    }
    if (key === '_cssGlobalClasses') {
      target._cssGlobalClasses = uniqueStrings([
        ...arrayValue(target._cssGlobalClasses),
        ...arrayValue(value),
      ]);
      continue;
    }
    target[key] = value;
  }
  return target;
}

function applyPixflowStageBClassStyleHeuristics(settings, classNames) {
  // Source fidelity is the invariant here. Class-name guesses previously
  // changed navigation wrapping/alignment and invented a mobile column layout
  // that was absent from Stage A. Exact browser defaults are materialized by
  // the declaration mapper; responsive changes come only from source CSS.
  void classNames;
  return settings;
}

function shouldAttachPixflowStageBBodyTypeClass(node, parentId, classInfo = {}) {
  // Pixflow-owned: the deterministic Prototype Bricks baseline disables its
  // page-scoped Theme Style, so native Bricks text defaults would otherwise
  // replace the accepted Stage A body typography. Attach the scoped body type
  // class only to semantic text nodes, before their more specific source
  // classes; never turn structural wrappers into typography buckets.
  void parentId;
  if (!/^(?:h[1-6]|p|a|span|strong|b|em|small|label|li|dt|dd|blockquote|figcaption|caption|th|td|pre|code)$/.test(
    firstString(node?.tag).toLowerCase(),
  )) {
    return false;
  }
  // Preserve CSS inheritance from contextual wrappers. Applying the body
  // class to every descendant otherwise forces 16px/ink onto nav links and
  // dark-section list items even when Stage A intentionally inherits a
  // smaller size or inverse colour from an ancestor component.
  for (let ancestor = node?.parent; ancestor && ancestor.type === 'element'; ancestor = ancestor.parent) {
    for (const className of pixflowStageBHtmlClassList(ancestor)) {
      const declarations = objectValue(classInfo?.declarationsByClass?.get?.(className));
      if (Object.keys(pickPixflowStageBInheritedTextDeclarations(declarations)).length > 0) {
        return false;
      }
    }
  }
  return true;
}

function isPixflowStageBStructuralContainerNode(node) {
  const classes = pixflowStageBHtmlClassList(node);
  return node?.tag === 'div'
    // Pixflow-owned: Stage A commonly emits `.wrap` or `.site-shell` as the
    // page-width owner. Treat it as the Bricks container so the converter does
    // not create a `section > container > .site-shell` double wrapper that
    // adds Bricks' default container gutter to the source shell padding.
    && classes.some((className) => (
      className === 'container'
      || className === 'wrap'
      || /(?:^|[-_])container$/i.test(className)
      || /__container(?:--[A-Za-z0-9_-]+)?$/i.test(className)
      || /__inner(?:--[A-Za-z0-9_-]+)?$/i.test(className)
      || /^(?:site|page|content|layout)[-_]shell$/i.test(className)
    ))
    && /^(?:section|header|footer)$/.test(firstString(node?.parent?.tag).toLowerCase());
}

function isPixflowStageBWorkInnerContainerNode(node) {
  return isPixflowStageBStructuralContainerNode(node)
    && pixflowStageBHtmlClassList(node?.parent).includes('work');
}

function buildPixflowStageBWorkContainerShellSettings(workDeclarations, sectionDeclarations, sectionDarkDeclarations, responsiveRulesByClass, cssVariables, fontOptions = {}) {
  const declarations = {
    ...pickPixflowStageBSectionShellDeclarations(sectionDeclarations, sectionDarkDeclarations),
    ...pickPixflowStageBWorkShellDeclarations(workDeclarations),
  };
  const settings = mapPixflowCssDeclarationsToBricksSettings(declarations, { cssVariables, ...fontOptions });
  applyPixflowStageBResponsiveSettings(settings, ['section', 'work'], { responsiveRulesByClass });
  removePixflowStageBNonShellResponsiveSettings(settings);
  return settings;
}

function buildPixflowStageBDarkSectionThemeVariableOverride(declarations) {
  const textColor = firstString(objectValue(declarations).color, 'var(--inverse)');
  return [
    `%root% { --heading: ${textColor}; --text: ${textColor}; }`,
    `%root% .stat-label b, %root% .stat-label strong { color: ${textColor}; }`,
  ].join('\n');
}

function pickPixflowStageBSectionShellDeclarations(sectionDeclarations, sectionDarkDeclarations) {
  const picked = {};
  const section = objectValue(sectionDeclarations);
  const dark = objectValue(sectionDarkDeclarations);
  if (firstString(section['padding-block'])) {
    picked['padding-block'] = section['padding-block'];
  } else if (firstString(section.padding)) {
    picked.padding = section.padding;
  }
  const sectionBg = firstString(dark['--section-bg'], dark['background'], dark['background-color']);
  if (sectionBg) {
    picked.background = sectionBg;
  }
  return picked;
}

function pickPixflowStageBWorkShellDeclarations(declarations) {
  const allowed = new Set([
    'margin',
    'margin-inline',
    'margin-left',
    'margin-right',
    'border-radius',
    'overflow',
  ]);
  const picked = {};
  for (const [property, value] of Object.entries(objectValue(declarations))) {
    if (allowed.has(String(property || '').toLowerCase()) && value) {
      picked[property] = value;
    }
  }
  return picked;
}

function removePixflowStageBWorkSectionShellSettings(settings) {
  removePixflowStageBSettingsByBaseKey(settings, new Set([
    '_margin',
    '_border',
    '_overflow',
  ]));
}

function applyPixflowStageBWorkSectionWrapperReset(settings) {
  settings._padding = {
    ...objectValue(settings._padding),
    top: '0',
    bottom: '0',
  };
  for (const suffix of ['tablet_portrait', 'mobile_landscape', 'mobile_portrait']) {
    const key = `_padding:${suffix}`;
    settings[key] = {
      ...objectValue(settings[key]),
      top: '0',
      bottom: '0',
    };
  }
  settings._background = { color: { raw: 'var(--paper)' } };
}

function removePixflowStageBNonShellResponsiveSettings(settings) {
  const allowedBaseKeys = new Set(['_padding', '_background', '_margin', '_border', '_overflow']);
  for (const key of Object.keys(settings)) {
    const baseKey = key.split(':')[0];
    if (key.includes(':') && !allowedBaseKeys.has(baseKey)) {
      delete settings[key];
    }
  }
}

function removePixflowStageBSettingsByBaseKey(settings, baseKeys) {
  for (const key of Object.keys(objectValue(settings))) {
    if (baseKeys.has(key.split(':')[0])) {
      delete settings[key];
    }
  }
}

function shouldUsePixflowStageBFlexForInlineGridCenter(usageItem, declarations) {
  const source = objectValue(declarations);
  if (!/^grid$/i.test(firstString(source.display)) || !firstString(source['place-items'])) {
    return false;
  }
  const tags = Array.isArray(usageItem?.tags) ? usageItem.tags.map((tag) => firstString(tag).toLowerCase()).filter(Boolean) : [];
  if (tags.length === 0) {
    return false;
  }
  return tags.every((tag) => /^(?:span|small|strong|b|em|code)$/.test(tag));
}

function extractPixflowStageBResponsiveClassRules(cssText, classNames, cssVariables = new Map(), options = {}) {
  const rulesByClass = new Map();
  const classSet = new Set(Array.isArray(classNames) ? classNames : []);
  const breakpointConfig = normalizePixflowStageBBricksBreakpoints(options.breakpoints);
  const source = stripStageBCssComments(cssText);
  const rootRemPx = Number.isFinite(Number(options.rootRemPx))
    ? Number(options.rootRemPx)
    : inferStageBRootRemPxFromCss(source);
  const pattern = /@media\s*([^{]+)\{/gi;
  let match;
  let order = 0;

  while ((match = pattern.exec(source)) !== null) {
    const condition = normalizeWhitespace(match[1] || '');
    const suffixes = pixflowStageBResponsiveSuffixesForMediaCondition(condition, breakpointConfig);
    const openIndex = source.lastIndexOf('{', pattern.lastIndex - 1);
    const closeIndex = openIndex >= 0 ? findPixflowCssBlockClose(source, openIndex) : -1;
    if (openIndex < 0 || closeIndex <= openIndex) {
      continue;
    }
    pattern.lastIndex = closeIndex + 1;
    if (suffixes.length === 0) {
      continue;
    }

    const mediaRules = extractStageBCssRuleSummaries(source.slice(openIndex + 1, closeIndex), { rootRemPx });
    for (const rule of mediaRules) {
      for (const className of rule.classNames || []) {
        if (!classSet.has(className) || !isPixflowStageBSimpleClassSelector(rule.selector, className)) {
          continue;
        }
        const mapped = mapPixflowCssDeclarationsToBricksSettings(rule.declarations, { deriveResponsive: false, cssVariables });
        const declarations = pickPixflowStageBResponsiveDeclarations(mapped);
        if (Object.keys(declarations).length === 0) {
          continue;
        }
        const list = rulesByClass.get(className) || [];
        list.push({
          condition,
          suffixes,
          selector: rule.selector,
          order: order += 1,
          declarations: { ...objectValue(rule.declarations) },
          settings: declarations,
        });
        rulesByClass.set(className, list);
      }
    }
  }

  return rulesByClass;
}

function extractPixflowStageBResponsiveElementRules(cssText, cssVariables = new Map(), options = {}) {
  const rulesByElement = new Map();
  const breakpointConfig = normalizePixflowStageBBricksBreakpoints(options.breakpoints);
  const source = stripStageBCssComments(cssText);
  const rootRemPx = Number.isFinite(Number(options.rootRemPx))
    ? Number(options.rootRemPx)
    : inferStageBRootRemPxFromCss(source);
  const pattern = /@media\s*([^{]+)\{/gi;
  let match;
  let order = 0;

  while ((match = pattern.exec(source)) !== null) {
    const condition = normalizeWhitespace(match[1] || '');
    const suffixes = pixflowStageBResponsiveSuffixesForMediaCondition(condition, breakpointConfig);
    const openIndex = source.lastIndexOf('{', pattern.lastIndex - 1);
    const closeIndex = openIndex >= 0 ? findPixflowCssBlockClose(source, openIndex) : -1;
    if (openIndex < 0 || closeIndex <= openIndex) continue;
    pattern.lastIndex = closeIndex + 1;
    if (suffixes.length === 0) continue;

    const mediaRules = extractStageBCssRuleSummaries(source.slice(openIndex + 1, closeIndex), { rootRemPx });
    for (const rule of mediaRules) {
      for (const selector of splitPixflowCssSelectorList(rule.selector || '')) {
        const tag = normalizePixflowStageBTagSelector(selector);
        const descendant = matchPixflowStageBSimpleDescendantElementSelector(selector);
        const descendantClass = matchPixflowStageBSimpleDescendantClassSelector(selector);
        const structural = matchPixflowStageBSimpleStructuralClassSelector(selector);
        const key = tag
          ? `tag:${tag}`
          : descendant
            ? `descendant:${buildPixflowStageBDescendantElementStyleKey(descendant.ancestorClass, descendant.tag, descendant.structuralPseudo, descendant.excludedClass, descendant.state, descendant.requiredAncestorClass)}`
            : descendantClass
              ? `descendant-class:${buildPixflowStageBDescendantClassStyleKey(descendantClass.ancestorClass, descendantClass.descendantClass)}`
              : structural
                ? `structural:${structural.sourceClass}|${structural.structuralPseudo}`
                : '';
        if (!key) continue;
        const declarations = descendantClass || structural
          ? objectValue(rule.declarations)
          : filterPixflowStageBDescendantElementDeclarations(tag || descendant.tag, rule.declarations);
        const mapped = mapPixflowCssDeclarationsToBricksSettings(declarations, {
          deriveResponsive: false,
          cssVariables,
        });
        const settings = pickPixflowStageBResponsiveDeclarations(mapped);
        if (Object.keys(settings).length === 0) continue;
        const list = rulesByElement.get(key) || [];
        list.push({
          condition,
          suffixes,
          selector: rule.selector,
          order: order += 1,
          settings,
        });
        rulesByElement.set(key, list);
      }
    }
  }

  return rulesByElement;
}

function extractPixflowStageBResponsiveFallbackRulesByClass(cssText, classNames, cssVariables = new Map()) {
  const rulesByClass = new Map();
  const classSet = new Set(arrayValue(classNames).map(firstString).filter(Boolean));
  const source = stripStageBCssComments(cssText);
  const rootRemPx = inferStageBRootRemPxFromCss(source);
  const pattern = /@media\s*([^{]+)\{/gi;
  let match;
  while ((match = pattern.exec(source)) !== null) {
    const condition = normalizeWhitespace(match[1] || '');
    const openIndex = source.lastIndexOf('{', pattern.lastIndex - 1);
    const closeIndex = openIndex >= 0 ? findPixflowCssBlockClose(source, openIndex) : -1;
    if (!condition || openIndex < 0 || closeIndex <= openIndex) continue;
    pattern.lastIndex = closeIndex + 1;
    const mediaRules = extractStageBCssRuleSummaries(source.slice(openIndex + 1, closeIndex), { rootRemPx });
    for (const rule of mediaRules) {
      for (const className of arrayValue(rule?.classNames)) {
        if (!classSet.has(className)) continue;
        const preserveNativeDeclarations = /min-width\s*:/i.test(condition)
          && !/max-width\s*:/i.test(condition);
        const fallback = convertPixflowStageBCssRuleToRoot(rule, className, cssVariables, {
          preserveNativeDeclarations,
        });
        if (!fallback) continue;
        // Bricks emits each global class in its own stylesheet and does not
        // preserve the source stylesheet's cross-class order. Overlapping
        // mobile-first utilities (sm:, md:, lg:) can therefore resolve in the
        // wrong direction even though both retain !important. Encode the
        // min-width tier as repeated root-class specificity so the larger
        // active breakpoint always wins, independent of Class Manager order.
        const minWidthMatch = condition.match(/min-width\s*:\s*(\d+(?:\.\d+)?)\s*(px|rem|em)?/i);
        const minWidthPx = minWidthMatch
          ? Number(minWidthMatch[1]) * (/^(?:rem|em)$/i.test(firstString(minWidthMatch[2])) ? rootRemPx : 1)
          : 0;
        const specificityRank = preserveNativeDeclarations && Number.isFinite(minWidthPx) && minWidthPx > 0
          ? Math.max(1, Math.min(8, Math.round(minWidthPx / 256)))
          : 1;
        const rankedFallback = specificityRank > 1
          ? fallback.replace('%root%', '%root%'.repeat(specificityRank))
          : fallback;
        const list = rulesByClass.get(className) || [];
        list.push(`@media ${condition} { ${rankedFallback} }`);
        rulesByClass.set(className, list);
      }
    }
  }
  return rulesByClass;
}

/**
 * Preserve supported container-query rules as scoped custom CSS. Bricks does
 * not expose a native container-query control, and treating the declarations
 * as ordinary class settings would apply them unconditionally. The source
 * class remains the owner; only the conditional wrapper is retained here.
 */
function extractPixflowStageBContainerQueryFallbackRulesByClass(cssText, classNames, cssVariables = new Map()) {
  const rulesByClass = new Map();
  const classSet = new Set(arrayValue(classNames).map(firstString).filter(Boolean));
  if (classSet.size === 0) return rulesByClass;
  const source = stripStageBCssComments(cssText);
  const pattern = /@container\s*([^\{]+)\{/gi;
  let match;
  while ((match = pattern.exec(source)) !== null) {
    const condition = normalizeWhitespace(match[1] || '');
    const openIndex = source.lastIndexOf('{', pattern.lastIndex - 1);
    const closeIndex = openIndex >= 0 ? findPixflowCssBlockClose(source, openIndex) : -1;
    if (!condition || openIndex < 0 || closeIndex <= openIndex) continue;
    pattern.lastIndex = closeIndex + 1;
    const nestedRules = extractStageBCssRuleSummaries(source.slice(openIndex + 1, closeIndex));
    for (const rule of nestedRules) {
      for (const className of arrayValue(rule?.classNames)) {
        if (!classSet.has(className)) continue;
        const scopedRule = convertPixflowStageBCssRuleToRoot(rule, className, cssVariables, {
          preserveNativeDeclarations: true,
        });
        if (!scopedRule) continue;
        const list = rulesByClass.get(className) || [];
        list.push(`@container ${condition} { ${scopedRule} }`);
        rulesByClass.set(className, list);
      }
    }
  }
  return rulesByClass;
}

function normalizePixflowStageBBricksBreakpoints(breakpoints) {
  const source = resolvePixflowBricksCompatibilityContext({ breakpoints }).breakpoints;
  const normalized = [];
  for (const breakpoint of source) {
    const item = objectValue(breakpoint);
    const key = firstString(item.key, item.name, item.id);
    const width = Number(item.width ?? item.value ?? item.maxWidth ?? item.max_width);
    const isBase = Boolean(item.base) || /^(?:desktop|base)$/i.test(key);
    if (!key || isBase || !Number.isFinite(width) || width <= 0) {
      continue;
    }
    normalized.push({
      key,
      label: firstString(item.label, key),
      width,
    });
  }
  return normalized
    .sort((a, b) => b.width - a.width)
    .filter((item, index, all) => all.findIndex((candidate) => candidate.key === item.key) === index);
}

function buildPixflowStageBBricksBreakpointMode(mode, breakpoints) {
  const data = objectValue(mode);
  const compatibility = resolvePixflowBricksCompatibilityContext({
    breakpoints,
    breakpointMode: data,
  });
  const normalized = normalizePixflowStageBBricksBreakpoints(breakpoints);
  const baseKey = firstString(data.baseKey, compatibility.breakpointMode.baseKey);
  const baseItem = normalized.find((breakpoint) => breakpoint.key === baseKey);
  const baseWidth = Number(data.baseWidth ?? baseItem?.width ?? compatibility.breakpointMode.baseWidth);
  const mobileFirst = data.mobileFirst === undefined
    ? compatibility.breakpointMode.mobileFirst
    : Boolean(data.mobileFirst);
  return {
    baseKey,
    baseWidth: Number.isFinite(baseWidth) && baseWidth > 0
      ? baseWidth
      : compatibility.breakpointMode.baseWidth,
    mobileFirst,
    narrowerRule: firstString(data.narrowerRule, compatibility.breakpointMode.narrowerRule),
    widerRule: firstString(data.widerRule, compatibility.breakpointMode.widerRule),
  };
}

function pixflowStageBSmallestBreakpointSuffix(breakpoints) {
  const normalized = normalizePixflowStageBBricksBreakpoints(breakpoints);
  return firstString(normalized[normalized.length - 1]?.key, 'mobile_portrait');
}

function pixflowStageBResponsiveSuffixesForMediaCondition(condition, breakpointConfig = null) {
  const maxWidths = [...String(condition || '').matchAll(/max-width\s*:\s*([0-9.]+)px/gi)]
    .map((match) => Number(match[1]))
    .filter((value) => Number.isFinite(value));
  const minWidths = [...String(condition || '').matchAll(/min-width\s*:\s*([0-9.]+)px/gi)]
    .map((match) => Number(match[1]))
    .filter((value) => Number.isFinite(value));
  const breakpoints = Array.isArray(breakpointConfig) && breakpointConfig.length > 0
    ? breakpointConfig
    : normalizePixflowStageBBricksBreakpoints([]);
  if (maxWidths.length === 0 && minWidths.length === 0) {
    return [];
  }
  if (maxWidths.length > 0) {
    const maxWidth = Math.min(...maxWidths);
    return pixflowStageBNearestBreakpointCascade(breakpoints, maxWidth, 'down');
  }
  // Bricks' default breakpoint model is desktop-first (`max-width`). A
  // source `min-width` rule cannot be represented by assigning it to a
  // narrower Bricks control: doing so reverses the rule and, for example,
  // turns Tailwind's `lg:` desktop typography into tablet typography. Keep
  // min-width rules in the class-scoped CSS fallback with their exact media
  // condition instead.
  return [];
}

function pixflowStageBNearestBreakpointCascade(breakpoints, width, direction) {
  let closestIndex = -1;
  let closestDistance = Number.POSITIVE_INFINITY;
  for (let index = 0; index < breakpoints.length; index += 1) {
    const distance = Math.abs(Number(breakpoints[index].width) - width);
    if (distance < closestDistance) {
      closestDistance = distance;
      closestIndex = index;
    }
  }
  if (closestIndex < 0) {
    return [];
  }
  if (direction === 'up') {
    return breakpoints.slice(0, closestIndex + 1).map((breakpoint) => breakpoint.key);
  }
  return breakpoints.slice(closestIndex).map((breakpoint) => breakpoint.key);
}

function pickPixflowStageBResponsiveDeclarations(settings) {
  const allowed = new Set([
    '_display',
    '_direction',
    '_flexWrap',
    '_flexGrow',
    '_flexShrink',
    '_flexBasis',
    '_alignSelf',
    '_order',
    '_gridItemJustifySelf',
    '_alignItems',
    '_alignItemsGrid',
    '_justifyContent',
    '_justifyContentGrid',
    '_justifyItemsGrid',
    '_alignContentGrid',
    '_columnGap',
    '_rowGap',
    '_gridTemplateColumns',
    '_gridTemplateRows',
    '_width',
    '_height',
    '_widthMin',
    '_widthMax',
    '_heightMin',
    '_heightMax',
    '_aspectRatio',
    '_objectFit',
    '_objectPosition',
    '_overflow',
    '_visibility',
    '_opacity',
    '_cursor',
    '_isolation',
    '_mixBlendMode',
    '_pointerEvents',
    '_perspective',
    '_perspectiveOrigin',
    '_scrollSnapType',
    '_scrollSnapAlign',
    '_scrollSnapStop',
    '_scrollMargin',
    '_cssFilters',
    '_position',
    '_top',
    '_right',
    '_bottom',
    '_left',
    '_zIndex',
    '_transform',
    '_transformOrigin',
    '_cssTransition',
    '_padding',
    '_margin',
    '_typography',
    '_background',
    '_gradient',
    '_border',
    '_boxShadow',
  ]);
  const picked = {};
  for (const [key, value] of Object.entries(objectValue(settings))) {
    if (allowed.has(key) && value !== undefined && value !== null && value !== '') {
      picked[key] = value;
    }
  }
  return picked;
}

function applyPixflowStageBResponsiveSettings(settings, classNames, classInfo) {
  const responsiveRulesByClass = classInfo?.responsiveRulesByClass;
  if (!responsiveRulesByClass || typeof responsiveRulesByClass.get !== 'function') {
    return settings;
  }
  const responsiveRules = [];
  for (const className of Array.isArray(classNames) ? classNames : []) {
    responsiveRules.push(...(responsiveRulesByClass.get(className) || []));
  }
  responsiveRules.sort((a, b) => (a.order || 0) - (b.order || 0));
  for (const rule of responsiveRules) {
    for (const suffix of rule.suffixes || []) {
      for (const [key, value] of Object.entries(objectValue(rule.settings))) {
        if (key.includes(':')) {
          continue;
        }
        applyPixflowStageBResponsiveBaseDefault(settings, key);
        settings[`${key}:${suffix}`] = value;
      }
    }
  }
  return settings;
}

function buildPixflowStageBHtmlBricksAttributes(node, seed) {
  return (Array.isArray(node?.attrList) ? node.attrList : [])
    .filter((attribute) => isPixflowStageBAllowedHtmlAttributeName(attribute.name))
    .map((attribute) => {
      const value = firstString(attribute.value);
      const result = {
        id: deterministicBricksId(`stage-b-html-attribute:${seed}:${attribute.name}:${value}`),
        name: attribute.name,
      };
      if (value) {
        result.value = value;
      }
      return result;
    });
}

function buildPixflowStageBManualAttribute(seed, name, value = '') {
  const result = {
    id: deterministicBricksId(`stage-b-html-attribute:manual:${seed}:${name}:${value}`),
    name,
  };
  if (firstString(value)) {
    result.value = firstString(value);
  }
  return result;
}

function applyPixflowStageBStructuralAnchorSettings(settings, node, href) {
  settings.tag = 'a';
  delete settings.customTag;

  const ariaLabel = pixflowStageBAttr(node, 'aria-label');
  if (Array.isArray(settings._attributes)) {
    settings._attributes = settings._attributes.filter((attribute) => {
      const name = firstString(attribute?.name).toLowerCase();
      return name !== 'aria-label' && name !== 'href';
    });
    if (settings._attributes.length === 0) {
      delete settings._attributes;
    }
  }

  if (href || ariaLabel) {
    settings.link = {
      type: 'meta',
    };
    if (href) {
      settings.link.useDynamicData = href;
    }
    if (ariaLabel) {
      settings.link.ariaLabel = ariaLabel;
    }
    applyPixflowStageBLinkMetadata(settings.link, node);
  }
}

function buildPixflowStageBExternalLinkSetting(node, href) {
  const link = { type: 'external', url: href };
  applyPixflowStageBLinkMetadata(link, node);
  return link;
}

function applyPixflowStageBExternalLinkSettings(settings, node, href) {
  // Bricks renders `settings.link` itself. Keeping the source `href` (or the
  // same accessible label) in `_attributes` makes Bricks concatenate the two
  // href values on the frontend, e.g. `#contact #contact`.
  if (Array.isArray(settings._attributes)) {
    settings._attributes = settings._attributes.filter((attribute) => {
      const name = firstString(attribute?.name).toLowerCase();
      return name !== 'href' && name !== 'aria-label';
    });
    if (settings._attributes.length === 0) delete settings._attributes;
  }
  settings.link = buildPixflowStageBExternalLinkSetting(node, href);
}

function applyPixflowStageBLinkMetadata(link, node) {
  const target = firstString(pixflowStageBAttr(node, 'target')).toLowerCase();
  const rel = firstString(pixflowStageBAttr(node, 'rel'));
  const title = firstString(pixflowStageBAttr(node, 'title'));
  const ariaLabel = firstString(pixflowStageBAttr(node, 'aria-label'));
  if (target === '_blank') link.newTab = true;
  if (rel) link.rel = rel;
  if (title) link.title = title;
  if (ariaLabel) link.ariaLabel = ariaLabel;
  return link;
}

function extractPixflowStageBCssVariables(rules) {
  const variables = new Map();
  for (const rule of Array.isArray(rules) ? rules : []) {
    const selectors = splitPixflowCssSelectorList(rule?.selector || '');
    if (!selectors.some((selector) => selector.trim() === ':root')) {
      continue;
    }
    for (const [key, value] of Object.entries(objectValue(rule.declarations))) {
      const name = normalizePixflowStageBCssVariableName(key);
      if (name && firstString(value)) {
        variables.set(name, firstString(value));
      }
    }
  }
  return variables;
}

function normalizePixflowStageBCssVariableName(name) {
  const value = firstString(name).trim();
  if (!value) return '';
  const normalized = value.startsWith('--') ? value : `--${value}`;
  return /^--[A-Za-z0-9_-]+$/.test(normalized) ? normalized : '';
}

function lookupPixflowStageBCssVariable(name, cssVariables) {
  const normalized = normalizePixflowStageBCssVariableName(name);
  if (!normalized) return '';
  if (cssVariables instanceof Map) {
    return firstString(cssVariables.get(normalized), cssVariables.get(normalized.toLowerCase()));
  }
  const source = objectValue(cssVariables);
  return firstString(source[normalized], source[normalized.toLowerCase()]);
}

function resolvePixflowStageBCssVariableExpression(value, cssVariables, seen = new Set()) {
  const source = firstString(value);
  const match = source.match(/^var\(\s*(--[A-Za-z0-9_-]+)\s*(?:,\s*([\s\S]+))?\)$/i);
  if (!match) {
    return source;
  }
  const name = normalizePixflowStageBCssVariableName(match[1]);
  if (!name || seen.has(name)) {
    return firstString(match[2], source);
  }
  seen.add(name);
  const resolved = lookupPixflowStageBCssVariable(name, cssVariables);
  if (resolved) {
    return resolvePixflowStageBCssVariableExpression(resolved, cssVariables, seen);
  }
  return firstString(match[2], source);
}

function resolvePixflowStageBFontFamilyValue(value, cssVariables = new Map()) {
  return resolvePixflowStageBFontFamilyTypography(value, { cssVariables })['font-family'] || '';
}

function resolvePixflowStageBFontFamilyTypography(value, options = {}) {
  const cssVariables = options.cssVariables || new Map();
  const availableFontFamilies = options.availableFontFamilies instanceof Set
    ? options.availableFontFamilies
    : new Set();
  const resolved = resolvePixflowStageBCssVariableExpression(value, cssVariables);
  const sourceFamilies = splitPixflowCssCommaList(resolved);
  const firstFamily = sourceFamilies[0] || resolved;
  const family = firstFamily
    .replace(/^["']|["']$/g, '')
    .trim();
  const fallback = buildPixflowStageBBricksFontFallbackValue(sourceFamilies.slice(1));
  if (sourceFamilies.length > 1 && isStageBSystemFontAliasFamily(family)) {
    const preferredSystemFamily = pickStageBPreferredSystemFontFallback(sourceFamilies);
    if (preferredSystemFamily) {
      return { 'font-family': preferredSystemFamily };
    }
  }
  if (!family || /^var\(/i.test(family) || /^(?:serif|sans-serif|monospace|cursive|fantasy|system-ui|ui-serif|ui-sans-serif|ui-monospace)$/i.test(family)) {
    return {};
  }
  const normalizedFamily = normalizeStageBFontFamilyId(family);
  const canUsePrimary = isStageBSystemFontFamily(family)
    || availableFontFamilies.has(normalizedFamily)
    || availableFontFamilies.has(family.toLowerCase());
  if (sourceFamilies.length > 1 && !canUsePrimary) {
    const fallbackFamilies = sourceFamilies
      .slice(1)
      .map((candidate) => candidate.replace(/^["']|["']$/g, '').trim())
      .filter(Boolean);
    const systemFallback = pickStageBPreferredSystemFontFallback(fallbackFamilies);
    if (systemFallback) {
      // Pixflow-owned: when Stage A names an unimported web-font first and
      // browsers fall back to the rest of the stack, keep Bricks on that same
      // fallback path. Otherwise the local builder may auto-resolve the first
      // family and shift line breaks before the model repair pass starts.
      const genericFallback = sourceFamilies
        .map((candidate) => candidate.replace(/^["']|["']$/g, '').trim())
        .findLast((candidate) => isStageBSystemFontAliasFamily(candidate));
      return {
        'font-family': systemFallback,
        ...(genericFallback ? { fallback: genericFallback } : {}),
      };
    }
  }
  return {
    'font-family': family,
    ...(fallback ? { fallback } : {}),
  };
}

function buildPixflowStageBFontMappingOptions(fontSystem) {
  const availableFontFamilies = new Set();
  for (const font of arrayValue(objectValue(fontSystem).fonts)) {
    const family = firstString(font?.family);
    const familyId = firstString(font?.familyId, font?.family_id);
    if (family) {
      availableFontFamilies.add(family.toLowerCase());
      availableFontFamilies.add(normalizeStageBFontFamilyId(family));
    }
    if (familyId) {
      availableFontFamilies.add(familyId.toLowerCase());
    }
  }
  for (const token of arrayValue(objectValue(fontSystem).roleTokens)) {
    const primaryFamily = firstString(token?.primaryFamily);
    if (primaryFamily) {
      availableFontFamilies.add(primaryFamily.toLowerCase());
      availableFontFamilies.add(normalizeStageBFontFamilyId(primaryFamily));
    }
  }
  return availableFontFamilies.size > 0 ? { availableFontFamilies } : {};
}

function buildPixflowStageBBricksFontFallbackValue(families) {
  const cleaned = arrayValue(families)
    .map((family) => String(family || '').trim().replace(/^["']|["']$/g, ''))
    .filter(Boolean)
    .filter((family) => !/^var\(/i.test(family));
  if (cleaned.length === 0) {
    return '';
  }
  return uniqueStrings(cleaned)
    .map((family) => /[\s,]/.test(family) && !isStageBSystemFontFamily(family) ? `"${family.replace(/"/g, '\\"')}"` : family)
    .join(', ');
}

function extractPixflowStageBTagDeclarations(rules) {
  const declarationsByTag = new Map();
  for (const rule of Array.isArray(rules) ? rules : []) {
    if (rule?.hasPseudoElement || rule?.hasPseudoState) {
      continue;
    }
    const declarations = objectValue(rule?.declarations);
    if (Object.keys(declarations).length === 0) {
      continue;
    }
    for (const selector of splitPixflowCssSelectorList(rule.selector || '')) {
      const tag = normalizePixflowStageBTagSelector(selector);
      if (!tag) {
        continue;
      }
      declarationsByTag.set(tag, {
        ...objectValue(declarationsByTag.get(tag)),
        ...declarations,
      });
    }
  }
  return declarationsByTag;
}

function normalizePixflowStageBTagSelector(selector) {
  const tag = firstString(selector).toLowerCase();
  if (!tag || tag === ':root') {
    return '';
  }
  if (!/^[a-z][a-z0-9-]*$/.test(tag)) {
    return '';
  }
  const allowed = new Set([
    'html',
    'body',
    'h1',
    'h2',
    'h3',
    'h4',
    'h5',
    'h6',
    'p',
    'blockquote',
    'label',
    'span',
    'small',
    'strong',
    'b',
    'em',
    'code',
    'a',
    'button',
    'figcaption',
    'li',
  ]);
  return allowed.has(tag) ? tag : '';
}

function pickPixflowStageBInheritedTextDeclarations(declarations) {
  const allowed = new Set([
    'color',
    'font-family',
    'font-size',
    'font-weight',
    'font-style',
    'font-variation-settings',
    'line-height',
    'letter-spacing',
    'white-space',
    'text-wrap',
    'text-align',
    'text-transform',
  ]);
  const result = {};
  for (const [key, value] of Object.entries(objectValue(declarations))) {
    if (allowed.has(String(key || '').toLowerCase()) && value) {
      result[key] = value;
    }
  }
  return result;
}

function isPixflowStageBInheritedTextTag(tag) {
  return /^(?:section|header|footer|nav|div|article|aside|h[1-6]|p|blockquote|label|span|small|strong|b|em|code|a|button|figcaption|li)$/.test(firstString(tag).toLowerCase());
}

function splitPixflowCssCommaList(value) {
  const result = [];
  let current = '';
  let depth = 0;
  let quote = '';
  for (const char of String(value || '')) {
    if (quote) {
      current += char;
      if (char === quote) {
        quote = '';
      }
      continue;
    }
    if (char === '"' || char === "'") {
      quote = char;
      current += char;
      continue;
    }
    if (char === '(') depth += 1;
    if (char === ')') depth = Math.max(0, depth - 1);
    if (char === ',' && depth === 0) {
      if (current.trim()) result.push(current.trim());
      current = '';
      continue;
    }
    current += char;
  }
  if (current.trim()) {
    result.push(current.trim());
  }
  return result;
}

function resolvePixflowStageBWidthConstraintCap(value, cssVariables, seen = new Set()) {
  const source = resolvePixflowStageBCssVariableExpression(value, cssVariables, new Set(seen)).trim();
  if (!source) return '';
  const match = source.match(/^min\(([\s\S]+)\)$/i);
  if (!match) {
    return normalizeStageBRemValue(source, 16);
  }
  for (const part of splitPixflowCssCommaList(match[1])) {
    const resolved = resolvePixflowStageBWidthConstraintCap(part, cssVariables, seen);
    if (resolved && !/^100%$/i.test(resolved)) {
      return resolved;
    }
  }
  return '';
}

function parsePixflowStageBMinWidthConstraint(value, cssVariables = new Map()) {
  const source = resolvePixflowStageBCssVariableExpression(value, cssVariables).trim();
  const match = source.match(/^min\(([\s\S]+)\)$/i);
  if (!match) return null;
  const parts = splitPixflowCssCommaList(match[1]);
  if (parts.length !== 2) {
    return null;
  }
  const fluidIndex = parts.findIndex((part) => (
    /^100%(?:\s|$|[-+*/])/.test(part.trim())
    || /^calc\(\s*100%(?:\s|[-+*/])/.test(part.trim())
  ));
  if (fluidIndex < 0) return null;
  const fluidWidth = parts[fluidIndex].trim();
  const maxWidth = resolvePixflowStageBWidthConstraintCap(parts[fluidIndex === 0 ? 1 : 0], cssVariables);
  if (!fluidWidth || !maxWidth) return null;
  return {
    width: fluidWidth === '100%' || /^calc\(/i.test(fluidWidth)
      ? fluidWidth
      : `calc(${fluidWidth})`,
    maxWidth,
  };
}

function parsePixflowStageBFlexShorthand(value) {
  const source = normalizeWhitespace(firstString(value)).trim();
  if (!source) return null;
  if (source === 'none') return { grow: '0', shrink: '0', basis: 'auto' };
  if (source === 'auto') return { grow: '1', shrink: '1', basis: 'auto' };
  if (source === 'initial') return { grow: '0', shrink: '1', basis: 'auto' };
  if (/^(?:inherit|unset|revert|revert-layer|var\()/i.test(source)) return null;

  // Keep function-valued bases intact. A plain whitespace split turns
  // `calc(50% - .5rem)` into five tokens and silently drops the responsive
  // flex rule during the HTML-to-Bricks projection.
  const parts = splitPixflowCssValueList(source);
  const isNumber = (part) => /^(?:\d+(?:\.\d+)?|\.\d+)$/.test(part);
  if (parts.length === 1) {
    return isNumber(parts[0])
      ? { grow: parts[0], shrink: '1', basis: '0%' }
      : { grow: '1', shrink: '1', basis: parts[0] };
  }
  if (parts.length === 2 && isNumber(parts[0])) {
    return isNumber(parts[1])
      ? { grow: parts[0], shrink: parts[1], basis: '0%' }
      : { grow: parts[0], shrink: '1', basis: parts[1] };
  }
  if (parts.length === 3 && isNumber(parts[0]) && isNumber(parts[1])) {
    return { grow: parts[0], shrink: parts[1], basis: parts[2] };
  }
  return null;
}

function splitPixflowStageBFontSizeLineHeightToken(value) {
  const source = firstString(value).trim();
  let depth = 0;
  for (let index = 0; index < source.length; index += 1) {
    const char = source[index];
    if (char === '(') depth += 1;
    else if (char === ')') depth = Math.max(0, depth - 1);
    else if (char === '/' && depth === 0) {
      return {
        size: source.slice(0, index).trim(),
        lineHeight: source.slice(index + 1).trim(),
      };
    }
  }
  return { size: source, lineHeight: '' };
}

function isPixflowStageBFontSizeToken(value) {
  const source = firstString(value).trim();
  if (!source) return false;
  if (/^(?:xx-small|x-small|small|medium|large|x-large|xx-large|xxx-large|larger|smaller)$/i.test(source)) {
    return true;
  }
  if (/^(?:calc|min|max|clamp|var)\(/i.test(source)) {
    return true;
  }
  return /^-?(?:\d+|\d*\.\d+)(?:px|em|rem|%|vw|vh|vmin|vmax|ch|ex|cap|ic|lh|rlh)$/i.test(source);
}

function parsePixflowStageBFontShorthand(value, options = {}) {
  const tokens = splitPixflowCssValueList(firstString(value));
  if (tokens.length < 2) return {};

  let sizeIndex = -1;
  let fontSize = '';
  let lineHeight = '';
  for (let index = 0; index < tokens.length; index += 1) {
    const pair = splitPixflowStageBFontSizeLineHeightToken(tokens[index]);
    if (!isPixflowStageBFontSizeToken(pair.size)) continue;
    sizeIndex = index;
    fontSize = pair.size;
    lineHeight = pair.lineHeight;
    break;
  }
  if (sizeIndex < 0 || !fontSize) return {};

  let familyIndex = sizeIndex + 1;
  if (!lineHeight && tokens[familyIndex] === '/') {
    lineHeight = firstString(tokens[familyIndex + 1]);
    familyIndex += 2;
  } else if (!lineHeight && firstString(tokens[familyIndex]).startsWith('/')) {
    lineHeight = firstString(tokens[familyIndex]).slice(1).trim();
    familyIndex += 1;
  }

  const typography = { 'font-size': fontSize };
  for (const token of tokens.slice(0, sizeIndex)) {
    if (/^(?:[1-9]00|1000|bold|bolder|lighter)$/i.test(token)) {
      typography['font-weight'] = token;
    } else if (/^(?:italic|oblique)$/i.test(token)) {
      typography['font-style'] = token;
    }
  }
  if (lineHeight) {
    typography['line-height'] = lineHeight;
  }

  const familyValue = tokens.slice(familyIndex).join(' ').trim();
  if (familyValue) {
    Object.assign(typography, resolvePixflowStageBFontFamilyTypography(familyValue, {
      cssVariables: options.cssVariables,
      availableFontFamilies: options.availableFontFamilies,
    }));
  }
  return typography;
}

function parsePixflowStageBTransform(value) {
  const source = firstString(value).trim();
  if (!source || /^(?:none|inherit|initial|unset|revert|revert-layer)$/i.test(source)) return null;
  // Browser runtime evidence serializes a completed CSS animation as a
  // matrix. Preserve the identity matrix explicitly so this later measured
  // class resets an authored entrance scale/translation instead of allowing
  // the invisible start transform to remain authoritative in Bricks.
  const matrix = source.match(/^matrix\(\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*,\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*,\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*,\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*,\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*,\s*(-?(?:\d+(?:\.\d+)?|\.\d+))\s*\)$/i);
  if (matrix && matrix.slice(1).map(Number).every(Number.isFinite)) {
    const [, a, b, c, d, tx, ty] = matrix.map(Number);
    if (a === 1 && b === 0 && c === 0 && d === 1) {
      return { scaleX: '1', scaleY: '1', translateX: String(tx), translateY: String(ty) };
    }
  }
  const directNames = new Map([
    ['translatex', 'translateX'],
    ['translatey', 'translateY'],
    ['perspective', 'perspective'],
    ['rotatex', 'rotateX'],
    ['rotatey', 'rotateY'],
    ['rotatez', 'rotateZ'],
    ['skewx', 'skewX'],
    ['skewy', 'skewY'],
    ['scalex', 'scaleX'],
    ['scaley', 'scaleY'],
  ]);
  const result = {};
  const assign = (name, raw) => {
    if (!name || !raw || Object.prototype.hasOwnProperty.call(result, name)) return false;
    result[name] = /^(?:rotate[XYZ]|skew[XY])$/.test(name) ? raw.replace(/deg$/i, '') : raw;
    return true;
  };
  let cursor = 0;
  const pattern = /([A-Za-z][A-Za-z0-9]*)\(([^()]*)\)/g;
  let match;
  while ((match = pattern.exec(source)) !== null) {
    if (source.slice(cursor, match.index).trim()) return null;
    const sourceName = match[1].toLowerCase();
    const raw = firstString(match[2]).trim();
    if (!raw) return null;
    const directName = directNames.get(sourceName);
    if (directName) {
      if (splitPixflowCssCommaList(raw).length !== 1 || !assign(directName, raw)) return null;
    } else if (sourceName === 'translate' || sourceName === 'scale' || sourceName === 'skew') {
      const parts = splitPixflowCssCommaList(raw);
      if (parts.length < 1 || parts.length > 2) return null;
      const names = sourceName === 'translate'
        ? ['translateX', 'translateY']
        : sourceName === 'scale'
          ? ['scaleX', 'scaleY']
          : ['skewX', 'skewY'];
      const second = parts[1] || (sourceName === 'scale' ? parts[0] : '0');
      if (!assign(names[0], parts[0]) || !assign(names[1], second)) return null;
    } else if (sourceName === 'rotate') {
      if (splitPixflowCssCommaList(raw).length !== 1 || !assign('rotateZ', raw)) return null;
    } else if (sourceName === 'scale3d') {
      const parts = splitPixflowCssCommaList(raw);
      if (parts.length !== 3 || Number(parts[2]) !== 1) return null;
      if (!assign('scale3dX', parts[0]) || !assign('scale3dY', parts[1])) return null;
    } else {
      return null;
    }
    cursor = pattern.lastIndex;
  }
  if (source.slice(cursor).trim() || Object.keys(result).length === 0) return null;
  return result;
}

function parsePixflowStageBIndividualTranslate(value) {
  const source = firstString(value).trim();
  if (!source || /^(?:none|inherit|initial|unset|revert|revert-layer)$/i.test(source)) return null;
  const parts = splitPixflowCssValueList(source);
  if (parts.length < 1 || parts.length > 3) return null;
  if (parts.length === 3 && !/^0(?:[a-z%]+)?$/i.test(parts[2])) return null;
  return {
    translateX: parts[0],
    translateY: parts[1] || '0',
  };
}

function parsePixflowStageBCssFilters(value) {
  const result = {};
  const parts = splitPixflowCssValueList(value);
  if (parts.length === 0) return null;
  const percentageFilters = new Set(['brightness', 'contrast', 'invert', 'opacity', 'saturate', 'sepia']);
  for (const part of parts) {
    const match = firstString(part).match(/^([a-z-]+)\(\s*([^()]*)\s*\)$/i);
    if (!match) return null;
    const type = match[1].toLowerCase();
    const raw = firstString(match[2]);
    if (!raw || Object.prototype.hasOwnProperty.call(result, type)) return null;
    if (type === 'blur') {
      const blur = raw.match(/^(-?(?:\d+(?:\.\d+)?|\.\d+))(px)?$/i);
      if (!blur || (!blur[2] && Number(blur[1]) !== 0)) return null;
      result[type] = String(Number(blur[1]));
      continue;
    }
    if (percentageFilters.has(type)) {
      const percentage = raw.match(/^(-?(?:\d+(?:\.\d+)?|\.\d+))(%)?$/);
      if (!percentage) return null;
      const numeric = Number(percentage[1]);
      result[type] = String(percentage[2] ? numeric : numeric * 100);
      continue;
    }
    if (type === 'hue-rotate') {
      const angle = raw.match(/^(-?(?:\d+(?:\.\d+)?|\.\d+))(deg)?$/i);
      if (!angle || (!angle[2] && Number(angle[1]) !== 0)) return null;
      result[type] = String(Number(angle[1]));
      continue;
    }
    return null;
  }
  return Object.keys(result).length > 0 ? result : null;
}

function parsePixflowStageBShadow(value, options = {}) {
  if (splitPixflowCssCommaList(value).length !== 1) return null;
  const tokens = splitPixflowCssValueList(value);
  const insetIndex = tokens.findIndex((token) => /^inset$/i.test(token));
  if (insetIndex >= 0 && !options.allowInset) return null;
  if (insetIndex >= 0) tokens.splice(insetIndex, 1);
  const colorIndex = tokens.findIndex((token) => isPixflowCssColorValue(token));
  if (colorIndex < 0) return null;
  const color = tokens.splice(colorIndex, 1)[0];
  const maxLengths = options.allowSpread ? 4 : 3;
  if (tokens.length < 2 || tokens.length > maxLengths) return null;
  if (tokens.some((token) => !/^(?:-?(?:\d+(?:\.\d+)?|\.\d+)(?:[a-z%]+)?|(?:var|calc|min|max|clamp)\([^()]+\))$/i.test(token))) {
    return null;
  }
  const values = {
    offsetX: tokens[0],
    offsetY: tokens[1],
    blur: tokens[2] || '0',
    // Bricks reads this string when rendering the shadow tuple, while the
    // sibling color object keeps the color picker editable.
    color,
  };
  if (options.allowSpread) values.spread = tokens[3] || '0';
  return {
    ...(insetIndex >= 0 ? { inset: true } : {}),
    values,
    color: { raw: color },
  };
}

function parsePixflowStageBBackgroundPosition(value) {
  if (splitPixflowCssCommaList(value).length !== 1) return null;
  const parts = splitPixflowCssValueList(value);
  if (parts.length !== 2 || parts.some((part) => /^(?:var|calc|min|max|clamp)\(/i.test(part))) {
    return { position: value };
  }
  const hasCustomCoordinate = parts.some((part) => /^-?(?:\d|\.)/.test(part) || /^var\(/i.test(part));
  return hasCustomCoordinate
    ? { position: 'custom', positionX: parts[0], positionY: parts[1] }
    : { position: value };
}

function parsePixflowStageBBackgroundSize(value) {
  if (splitPixflowCssCommaList(value).length !== 1) return null;
  const normalized = firstString(value).toLowerCase();
  if (['auto', 'cover', 'contain'].includes(normalized)) return { size: normalized };
  return value ? { size: 'custom', custom: value } : null;
}

function parsePixflowStageBBackgroundImage(value) {
  const gradient = parsePixflowStageBNativeGradientBackground(value);
  if (gradient) return gradient;
  const match = firstString(value).match(/^url\(\s*(['"]?)(.*?)\1\s*\)$/i);
  if (!match || !firstString(match[2])) return null;
  return { _background: { image: { url: match[2] } } };
}

function isPixflowStageBSingleBackgroundLayerValue(value) {
  return firstString(value) !== '' && splitPixflowCssCommaList(value).length === 1;
}

function parsePixflowStageBGradientColorStop(value) {
  const source = firstString(value).trim();
  if (!source) return null;
  const match = source.match(/^([\s\S]*?)(?:\s+(-?(?:\d+|\d*\.\d+)%))?$/);
  if (!match) return null;
  const color = firstString(match[1]).trim();
  if (!isPixflowCssColorValue(color)) return null;
  const result = { color: { raw: color } };
  const stop = firstString(match[2]).replace(/%$/, '');
  if (stop) result.stop = stop;
  return result;
}

function parsePixflowStageBNativeGradientBackground(value) {
  const layers = splitPixflowCssCommaList(firstString(value));
  if (layers.length < 1 || layers.length > 2) return null;
  const match = layers[0].match(/^(repeating-)?(linear|radial|conic)-gradient\(([\s\S]*)\)$/i);
  if (!match) return null;
  const gradientType = match[2].toLowerCase();
  const parts = splitPixflowCssCommaList(match[3]);
  if (parts.length < 2) return null;

  const gradient = { gradientType };
  if (match[1]) gradient.repeat = true;
  let colorStart = 0;
  if (!parsePixflowStageBGradientColorStop(parts[0])) {
    const prelude = firstString(parts[0]).trim();
    colorStart = 1;
    if (gradientType === 'radial') {
      const radial = prelude.match(/^(?:(circle|ellipse)\b)?\s*(?:(closest-side|closest-corner|farthest-side|farthest-corner)\b)?\s*(?:at\s+([\s\S]+))?$/i);
      if (!radial) return null;
      if (radial[1]) gradient.radialShape = radial[1].toLowerCase();
      if (radial[2]) gradient.radialSize = radial[2].toLowerCase();
      if (radial[3]) {
        gradient.radialPosition = 'custom';
        gradient.radialCustomPosition = radial[3].trim();
      }
    } else if (gradientType === 'linear') {
      const angle = prelude.match(/^(-?(?:\d+|\d*\.\d+))deg$/i);
      if (!angle) return null;
      gradient.angle = angle[1];
    } else {
      const conic = prelude.match(/^(?:from\s+(-?(?:\d+|\d*\.\d+))deg)?\s*(?:at\s+([\s\S]+))?$/i);
      if (!conic || (!conic[1] && !conic[2])) return null;
      if (conic[1]) gradient.conicAngle = conic[1];
      if (conic[2]) {
        gradient.conicPosition = 'custom';
        gradient.conicCustomPosition = conic[2].trim();
      }
    }
  }

  const colors = parts.slice(colorStart).map(parsePixflowStageBGradientColorStop);
  if (colors.length < 2 || colors.some((item) => !item)) return null;
  gradient.colors = colors;

  const settings = { _gradient: gradient };
  if (layers.length === 2) {
    const fallback = firstString(layers[1]).trim();
    if (!isPixflowCssColorValue(fallback)) return null;
    settings._background = { color: { raw: fallback } };
  }
  return settings;
}

function applyPixflowStageBResponsiveBaseDefault(settings, key) {
  if (Object.prototype.hasOwnProperty.call(settings, key)) {
    return settings;
  }
  // Bricks does not reliably emit a breakpoint-only control unless its base
  // counterpart exists. Materialize the CSS initial value for controls whose
  // defaults are unambiguous, so the responsive rule compiles without changing
  // the accepted desktop rendering.
  const defaults = {
    _width: 'auto',
    _height: 'auto',
    _direction: 'row',
    _flexWrap: 'nowrap',
    _justifyContent: 'flex-start',
    _alignItems: 'stretch',
    _flexGrow: '0',
    _flexShrink: '1',
    _flexBasis: 'auto',
    _alignSelf: 'auto',
    _order: '0',
  };
  if (Object.prototype.hasOwnProperty.call(defaults, key)) {
    settings[key] = defaults[key];
  }
  return settings;
}

function applyPixflowStageBTemplateRootDefaults(node, name, settings, parentId, context, options) {
  if (name !== 'section' || parentId) {
    return;
  }
  if (options.templatePart === 'header') {
    settings._padding = {
      top: firstString(settings._padding?.top, '0'),
      right: firstString(settings._padding?.right, '0'),
      bottom: firstString(settings._padding?.bottom, '0'),
      left: firstString(settings._padding?.left, '0'),
    };
  }
  if (options.templatePart === 'footer' && !hasStageBTopBottomPadding(settings)) {
    settings._padding = {
      top: firstString(settings._padding?.top, '0'),
      right: firstString(settings._padding?.right, '0'),
      bottom: firstString(settings._padding?.bottom, '0'),
      left: firstString(settings._padding?.left, '0'),
    };
  }
}

function mapPixflowCssDeclarationsToBricksSettings(declarations, options = {}) {
  const settings = {};
  const typography = {};
  const border = {};
  let gridColumnStart = '';
  let gridColumnEnd = '';
  let gridRowStart = '';
  let gridRowEnd = '';
  const source = objectValue(declarations);
  const cssVariables = options.cssVariables || new Map();

  for (const [property, value] of Object.entries(source)) {
    const key = property.toLowerCase();
    if (!value || key.startsWith('--')) continue;
    const compatibilityContext = objectValue(options.compatibilityContext).schema
      ? objectValue(options.compatibilityContext)
      : resolvePixflowBricksCompatibilityContext({});
    const compatibilityMapping = resolvePixflowBricksCssMapping(key, compatibilityContext);
    if (compatibilityMapping.ownership !== 'native_control') {
      if (Array.isArray(options.compatibilityDiagnostics) && compatibilityMapping.diagnostic) {
        const signature = `${compatibilityMapping.diagnostic.code}:${key}`;
        if (!options.compatibilityDiagnostics.some((item) => item.signature === signature)) {
          options.compatibilityDiagnostics.push({ ...compatibilityMapping.diagnostic, signature });
        }
      }
      continue;
    }
    if (key === 'display') settings._display = options.preferFlexForGridCenter && /^grid$/i.test(value) ? 'flex' : value;
    else if (key === 'flex-direction') settings._direction = value;
    else if (key === 'flex-wrap') settings._flexWrap = value;
    else if (key === 'flex') {
      const flex = parsePixflowStageBFlexShorthand(value);
      if (flex) {
        settings._flexGrow = flex.grow;
        settings._flexShrink = flex.shrink;
        settings._flexBasis = flex.basis;
      }
    }
    else if (key === 'flex-grow') settings._flexGrow = value;
    else if (key === 'flex-shrink') settings._flexShrink = value;
    else if (key === 'flex-basis') settings._flexBasis = value;
    else if (key === 'align-self') settings._alignSelf = value;
    else if (key === 'order') settings._order = value;
    else if (key === 'justify-self') settings._gridItemJustifySelf = value;
    else if (key === 'align-items') settings._alignItems = value;
    else if (key === 'justify-content') settings._justifyContent = value;
    else if (key === 'justify-items') settings._justifyItemsGrid = value;
    else if (key === 'align-content') settings._alignContentGrid = value;
    else if (key === 'place-items') {
      const pair = parsePixflowCssPlacePairValue(value);
      if (options.preferFlexForGridCenter) {
        settings._display = firstString(settings._display, 'flex');
        settings._alignItems = pair.align;
        settings._justifyContent = pair.justify;
      } else {
        settings._display = firstString(settings._display, 'grid');
        settings._alignItemsGrid = pair.align;
        settings._justifyItemsGrid = pair.justify;
      }
    }
    else if (key === 'place-content') {
      const pair = parsePixflowCssPlacePairValue(value);
      settings._display = firstString(settings._display, 'grid');
      settings._alignContentGrid = pair.align;
      settings._justifyContentGrid = pair.justify;
    }
    else if (key === 'gap') {
      const gapValues = splitPixflowCssValueList(value);
      settings._rowGap = gapValues[0] || value;
      settings._columnGap = gapValues[1] || gapValues[0] || value;
    } else if (key === 'column-gap') settings._columnGap = value;
    else if (key === 'row-gap') settings._rowGap = value;
    else if (key === 'grid-template-columns') settings._gridTemplateColumns = value;
    else if (key === 'grid-template-rows') settings._gridTemplateRows = value;
    else if (key === 'grid-column') settings._gridColumn = value;
    else if (key === 'grid-column-start') gridColumnStart = value;
    else if (key === 'grid-column-end') gridColumnEnd = value;
    else if (key === 'grid-row') settings._gridRow = value;
    else if (key === 'grid-row-start') gridRowStart = value;
    else if (key === 'grid-row-end') gridRowEnd = value;
    else if (key === 'width') {
      const constrainedWidth = parsePixflowStageBMinWidthConstraint(value, cssVariables);
      if (constrainedWidth) {
        settings._width = constrainedWidth.width;
        settings._widthMax = constrainedWidth.maxWidth;
      } else {
        settings._width = value;
      }
    }
    else if (key === 'height') settings._height = value;
    else if (key === 'min-width') settings._widthMin = value;
    else if (key === 'max-width') settings._widthMax = value;
    else if (key === 'min-height') settings._heightMin = value;
    else if (key === 'max-height') settings._heightMax = value;
    else if (key === 'aspect-ratio') settings._aspectRatio = value;
    else if (key === 'object-fit') settings._objectFit = value;
    else if (key === 'object-position') settings._objectPosition = value;
    else if (key === 'overflow') settings._overflow = value;
    else if (key === 'overflow-x' && !settings._overflow) settings._overflow = value;
    else if (key === 'overflow-y' && !settings._overflow) settings._overflow = value;
    else if (key === 'visibility') settings._visibility = value;
    else if (key === 'opacity') settings._opacity = value;
    else if (key === 'cursor') settings._cursor = value;
    else if (key === 'isolation') settings._isolation = value;
    else if (key === 'mix-blend-mode') settings._mixBlendMode = value;
    else if (key === 'pointer-events') settings._pointerEvents = value;
    else if (key === 'perspective') settings._perspective = value;
    else if (key === 'perspective-origin') settings._perspectiveOrigin = value;
    else if (key === 'scroll-snap-type') settings._scrollSnapType = value;
    else if (key === 'scroll-snap-align') settings._scrollSnapAlign = value;
    else if (key === 'scroll-snap-stop') settings._scrollSnapStop = value;
    else if (key === 'scroll-margin') settings._scrollMargin = parsePixflowCssBoxValue(value);
    else if (key === 'filter') {
      const filters = parsePixflowStageBCssFilters(value);
      if (filters) settings._cssFilters = filters;
    }
    else if (key === 'position') settings._position = value;
    else if (key === 'inset') Object.assign(settings, parsePixflowCssInsetValue(value));
    else if (['top', 'right', 'bottom', 'left'].includes(key)) settings[`_${key}`] = value;
    else if (key === 'z-index') settings._zIndex = value;
    else if (key === 'translate') {
      const translate = parsePixflowStageBIndividualTranslate(value);
      if (translate) settings._transform = { ...objectValue(settings._transform), ...translate };
    }
    else if (key === 'transform') {
      const transform = parsePixflowStageBTransform(value);
      if (transform) settings._transform = transform;
    }
    else if (key === 'transform-origin') settings._transformOrigin = value;
    else if (key === 'transition') settings._cssTransition = value;
    else if (key === 'padding') settings._padding = parsePixflowCssBoxValue(value);
    else if (key === 'padding-block') settings._padding = { ...objectValue(settings._padding), ...parsePixflowCssLogicalBlockValue(value) };
    else if (key === 'padding-inline') settings._padding = { ...objectValue(settings._padding), ...parsePixflowCssLogicalInlineValue(value) };
    else if (/^padding-(?:top|right|bottom|left)$/.test(key)) {
      settings._padding = { ...objectValue(settings._padding), [key.replace('padding-', '')]: value };
    }
    else if (key === 'margin') settings._margin = parsePixflowCssBoxValue(value);
    else if (key === 'margin-block') settings._margin = { ...objectValue(settings._margin), ...parsePixflowCssLogicalBlockValue(value) };
    else if (key === 'margin-inline') settings._margin = { ...objectValue(settings._margin), ...parsePixflowCssLogicalInlineValue(value) };
    else if (/^margin-(?:top|right|bottom|left)$/.test(key)) {
      settings._margin = { ...objectValue(settings._margin), [key.replace('margin-', '')]: value };
    }
    else if (key === 'color') typography.color = { raw: value };
    else if (key === 'font') {
      Object.assign(typography, parsePixflowStageBFontShorthand(value, {
        cssVariables,
        availableFontFamilies: options.availableFontFamilies,
      }));
    }
    else if (key === 'font-family') {
      const fontTypography = resolvePixflowStageBFontFamilyTypography(value, {
        cssVariables,
        availableFontFamilies: options.availableFontFamilies,
      });
      if (fontTypography['font-family']) {
        Object.assign(typography, fontTypography);
      }
    }
    else if (key === 'font-size') typography['font-size'] = value;
    else if (key === 'font-weight') typography['font-weight'] = value;
    else if (key === 'font-style') typography['font-style'] = value;
    else if (key === 'font-variation-settings') typography['font-variation-settings'] = value;
    else if (key === 'line-height') typography['line-height'] = value;
    else if (key === 'letter-spacing') typography['letter-spacing'] = value;
    else if (key === 'white-space') typography['white-space'] = value;
    else if (key === 'text-wrap') typography['text-wrap'] = value;
    else if (key === 'text-align') typography['text-align'] = value;
    else if (key === 'text-transform') typography['text-transform'] = value;
    else if (key === 'text-decoration') typography['text-decoration'] = value;
    else if (key === 'text-shadow') {
      const textShadow = parsePixflowStageBShadow(
        resolvePixflowStageBCssVariableExpression(value, cssVariables)
      );
      if (textShadow) typography['text-shadow'] = textShadow;
    }
    else if (key === 'background') {
      const resolvedValue = resolvePixflowStageBCssVariableExpression(value, cssVariables);
      const gradient = parsePixflowStageBNativeGradientBackground(resolvedValue);
      if (gradient) Object.assign(settings, gradient);
      else if (isPixflowCssColorValue(resolvedValue)) settings._background = { ...objectValue(settings._background), color: { raw: resolvedValue } };
      else {
        const backgroundImage = parsePixflowStageBBackgroundImage(resolvedValue);
        if (backgroundImage?._background) settings._background = { ...objectValue(settings._background), ...backgroundImage._background };
      }
    }
    else if (key === 'background-color' && isPixflowCssColorValue(value)) settings._background = { ...objectValue(settings._background), color: { raw: value } };
    else if (key === 'background-image') {
      const backgroundImage = parsePixflowStageBBackgroundImage(
        resolvePixflowStageBCssVariableExpression(value, cssVariables),
      );
      if (backgroundImage?._gradient) settings._gradient = backgroundImage._gradient;
      if (backgroundImage?._background) settings._background = { ...objectValue(settings._background), ...backgroundImage._background };
    }
    else if (key === 'background-repeat' && isPixflowStageBSingleBackgroundLayerValue(value)) settings._background = { ...objectValue(settings._background), repeat: value };
    else if (key === 'background-position') {
      const position = parsePixflowStageBBackgroundPosition(value);
      if (position) settings._background = { ...objectValue(settings._background), ...position };
    }
    else if (key === 'background-size') {
      const size = parsePixflowStageBBackgroundSize(value);
      if (size) settings._background = { ...objectValue(settings._background), ...size };
    }
    else if (key === 'background-attachment' && isPixflowStageBSingleBackgroundLayerValue(value)) settings._background = { ...objectValue(settings._background), attachment: value };
    else if (key === 'background-blend-mode' && isPixflowStageBSingleBackgroundLayerValue(value)) settings._background = { ...objectValue(settings._background), blendMode: value };
    else if (key === 'border-radius') border.radius = parsePixflowCssBorderRadiusValue(value);
    else if (/^border-(?:top-left|top-right|bottom-right|bottom-left)-radius$/.test(key)) {
      border.radius = {
        ...objectValue(border.radius),
        [pixflowCssBorderCornerToBricksRadiusSide(key)]: value,
      };
    }
    else if (key === 'border') Object.assign(border, parsePixflowCssBorderValue(value));
    else if (/^border-(?:top|right|bottom|left)$/.test(key)) {
      Object.assign(border, parsePixflowCssBorderSideValue(value, key.replace('border-', '')));
    }
    else if (key === 'border-width') border.width = buildPixflowCssBorderSideBox(value);
    else if (key === 'border-style') border.style = value;
    else if (key === 'border-color' && isPixflowCssColorValue(value)) border.color = { raw: value };
    else if (/^border-(?:top|right|bottom|left)-width$/.test(key)) {
      border.width = {
        ...objectValue(border.width),
        [key.replace(/^border-|-width$/g, '')]: normalizePixflowCssBorderWidthValue(value),
      };
    }
    else if (/^border-(?:top|right|bottom|left)-style$/.test(key)) border.style = value;
    else if (/^border-(?:top|right|bottom|left)-color$/.test(key) && isPixflowCssColorValue(value)) border.color = { raw: value };
    else if (key === 'box-shadow') {
      const boxShadow = parsePixflowStageBShadow(
        resolvePixflowStageBCssVariableExpression(value, cssVariables),
        { allowInset: true, allowSpread: true }
      );
      if (boxShadow) settings._boxShadow = boxShadow;
    }
  }

  if (Object.keys(typography).length > 0) {
    settings._typography = typography;
  }
  if (!settings._gridColumn && (gridColumnStart || gridColumnEnd)) {
    settings._gridColumn = `${gridColumnStart || 'auto'} / ${gridColumnEnd || 'auto'}`;
  }
  if (!settings._gridRow && (gridRowStart || gridRowEnd)) {
    settings._gridRow = `${gridRowStart || 'auto'} / ${gridRowEnd || 'auto'}`;
  }
  const flexFlow = splitPixflowCssValueList(firstString(source['flex-flow'])).map((part) => part.toLowerCase());
  if (flexFlow.length > 0) {
    const direction = flexFlow.find((part) => ['row', 'row-reverse', 'column', 'column-reverse'].includes(part));
    const wrap = flexFlow.find((part) => ['nowrap', 'wrap', 'wrap-reverse'].includes(part));
    if (direction) settings._direction = direction;
    if (wrap) settings._flexWrap = wrap;
  }
  if (Object.keys(border).length > 0) {
    settings._border = border;
  }
  if (['grid', 'inline-grid'].includes(firstString(settings._display).toLowerCase())) {
    if (settings._alignItems && !settings._alignItemsGrid) {
      settings._alignItemsGrid = settings._alignItems;
    }
    if (settings._justifyContent && !settings._justifyContentGrid) {
      settings._justifyContentGrid = settings._justifyContent;
    }
    delete settings._alignItems;
    delete settings._justifyContent;
  }
  if ((settings._direction || settings._flexDirection || settings._flexWrap) && !settings._display) {
    settings._display = 'flex';
  }
  if (['flex', 'inline-flex'].includes(firstString(settings._display).toLowerCase())) {
    // Bricks' editor defaults are not the browser's flex defaults in every
    // context. Preserve the Stage A computed baseline explicitly so a later
    // responsive value also has a dependable base control to inherit from.
    if (!settings._direction) settings._direction = 'row';
    if (!settings._flexWrap) settings._flexWrap = 'nowrap';
    if (!settings._justifyContent) settings._justifyContent = 'flex-start';
    if (!settings._alignItems) settings._alignItems = 'stretch';
  }
  if (settings._gridTemplateColumns && !settings._display) {
    settings._display = 'grid';
  }
  if (options.deriveResponsive !== false && settings._gridTemplateColumns && stageBGridColumnCountHint(settings._gridTemplateColumns) > 1) {
    const fallbackSuffix = firstString(options.responsiveFallbackSuffix, 'mobile_portrait');
    const fallbackKey = `_gridTemplateColumns:${fallbackSuffix}`;
    if (!settings[fallbackKey]) {
      settings[fallbackKey] = '1fr';
    }
  }
  return settings;
}

function getPixflowStageBBodyRootNodes(body) {
  const children = (body?.children || []).filter((node) => node.type !== 'text' || normalizeWhitespace(node.text));
  const pageWrapper = children.find((node) => node.type === 'element' && isPixflowStageBPageWrapper(node));
  if (pageWrapper) {
    return pageWrapper.children || [];
  }
  return children;
}

function normalizePixflowStageBHtmlGlobalClassName(className, usedNames) {
  const preferred = firstString(className);
  let name = preferred || 'pixflow-source-class';
  let suffix = 2;
  while (usedNames.has(name)) {
    name = `${preferred}-${suffix}`;
    suffix += 1;
  }
  usedNames.add(name);
  return name;
}

function createPixflowStageBClassNamePlanner(options = {}) {
  const existingGlobalClasses = normalizePixflowStageBExistingGlobalClasses(options.existingGlobalClasses);
  const existingByLowerName = new Map(existingGlobalClasses.map((item) => [item.name.toLowerCase(), item]));
  const usedLowerNames = new Set(existingGlobalClasses.map((item) => item.name.toLowerCase()));
  const emittedLowerNames = new Set();
  const decisions = [];
  const sourcePrefix = firstString(options.sourcePrefix, buildPixflowStageBBemBlockPrefix(options));
  const sourceClassNamePlan = options.sourceClassNamePlan instanceof Map ? options.sourceClassNamePlan : new Map();
  const preservedUtilityClasses = stringArrayFromUnknown(options.preservedUtilityClasses);

  const claim = (preferredName, details = {}) => {
    const settings = objectValue(details.settings);
    const requestedName = sanitizePixflowStageBClassPublicName(preferredName, 'pf-stage-b-class');
    let finalName = requestedName;
    let status = 'created';
    let reason = 'available';
    let existingClass = existingByLowerName.get(finalName.toLowerCase()) || null;

    if (existingClass) {
      // A site class can be empty and therefore compatible with multiple
      // source names after sanitisation (for example `-mt-0` and `mt-0`).
      // Reusing it a second time emits duplicate Class Manager entries with
      // the same id. Once a public name has been claimed in this handoff,
      // force the later source class through the normal conflict suffix.
      if (!emittedLowerNames.has(finalName.toLowerCase())
        && isPixflowStageBCompatibleExistingGlobalClass(existingClass, settings)) {
        status = 'reused-compatible';
        reason = existingClass.settingsEmpty ? 'existing-empty-class' : 'same-settings-hash';
        emittedLowerNames.add(finalName.toLowerCase());
        decisions.push(buildPixflowStageBClassDecision({
          ...details,
          requestedName,
          finalName,
          status,
          reason,
          id: existingClass.id,
          existingClass,
          settings,
        }));
        return { id: existingClass.id, name: existingClass.name, status, existingClass };
      }
      status = 'renamed-conflict';
      reason = 'existing-class-manager-name-has-different-settings';
      const conflictName = sanitizePixflowStageBClassPublicName(firstString(details.conflictName), '');
      if (conflictName && conflictName.toLowerCase() !== finalName.toLowerCase()) {
        finalName = conflictName;
      }
    }

    const suffixBaseName = finalName;
    let suffix = 2;
    while (usedLowerNames.has(finalName.toLowerCase()) || emittedLowerNames.has(finalName.toLowerCase())) {
      finalName = `${suffixBaseName}-${suffix}`;
      suffix += 1;
      status = status === 'created' ? 'renamed-local-duplicate' : status;
      reason = reason === 'available' ? 'duplicate-name' : reason;
    }

    emittedLowerNames.add(finalName.toLowerCase());
    const id = deterministicBricksId(`${firstString(details.idSeed, 'stage-b-class')}:${finalName}`);
    decisions.push(buildPixflowStageBClassDecision({
      ...details,
      requestedName,
      finalName,
      status,
      reason,
      id,
      existingClass,
      settings,
    }));
    return { id, name: finalName, status, existingClass };
  };

  return {
    sourcePrefix,
    claimPreferred(preferredName, details = {}) {
      return claim(preferredName, details);
    },
    claimSourceClass(sourceClassName, details = {}) {
      const source = firstString(sourceClassName);
      const preferredName = firstString(
        sourceClassNamePlan.get(source),
        buildPixflowStageBSafeSourceClassName(source, sourcePrefix)
      );
      const conflictName = buildPixflowStageBSourceBemClassName(sourceClassName, {
        sourcePrefix,
        usage: details.usage,
      });
      return claim(preferredName, {
        ...details,
        kind: 'source-class',
        key: firstString(sourceClassName),
        sourceName: firstString(sourceClassName),
        originalSourceClass: firstString(sourceClassName),
        conflictName,
      });
    },
    toPlan() {
      return {
        type: 'pixflow_stage_b_bem_class_ownership_plan',
        version: 1,
        naming: {
          prefix: sourcePrefix,
          sourceClassStrategy: 'preserve_source_class_names_prefix_only_on_existing_bricks_class_conflict',
          conflictPolicy: 'reuse-empty-or-identical-existing-class-else-rename',
        },
        existingClassCount: existingGlobalClasses.length,
        generatedClassCount: decisions.filter((item) => item.status !== 'reused-compatible').length,
        reusedClassCount: decisions.filter((item) => item.status === 'reused-compatible').length,
        conflictCount: decisions.filter((item) => item.status === 'renamed-conflict').length,
        preservedUtilityClassCount: preservedUtilityClasses.length,
        preservedUtilityClasses,
        decisions: decisions.map((item) => ({ ...item })),
      };
    },
  };
}

function normalizePixflowStageBExistingGlobalClasses(value) {
  return arrayValue(value).map((item) => {
    const object = objectValue(item);
    const id = firstString(object.id);
    const name = sanitizePixflowStageBClassPublicName(firstString(object.name), '');
    if (!id || !name) {
      return null;
    }
    const settings = objectValue(object.settings);
    const hasSettings = Object.keys(settings).length > 0;
    return {
      id,
      name,
      settings,
      // A compact WordPress compatibility index intentionally omits settings
      // bodies. Honour its explicit non-empty bit instead of interpreting an
      // absent body as an empty class and reusing an incompatible Class
      // Manager record.
      settingsEmpty: object.settingsEmpty === true || (object.settingsEmpty !== false && !hasSettings),
      settingsHash: firstString(
        object.settingsHash,
        hasSettings ? hashPixflowStageBClassSettings(settings) : '',
      ),
    };
  }).filter(Boolean);
}

function buildPixflowStageBBemBlockPrefix(options = {}) {
  const source = firstString(options.sourceId, options.title, 'handoff');
  const slug = slugify(source).replace(/^stage-a-/, '');
  const letters = (slug.match(/[a-z0-9]/g) || []).join('');
  const prefix = (letters || 'pfx').slice(0, 3).padEnd(3, 'x');
  return sanitizePixflowStageBClassPublicName(prefix, 'pfx');
}

function buildPixflowStageBSourceClassName(sourceClassName) {
  return sanitizePixflowStageBClassPublicName(firstString(sourceClassName, 'element'), 'element');
}

function buildPixflowStageBSafeSourceClassName(sourceClassName, sourcePrefix) {
  const raw = firstString(sourceClassName);
  // CSS utility variants may legitimately start with `-` or `@` (Tailwind's
  // negative and container variants). The public Bricks class name sanitizer
  // removes those sigils, which collapses distinct source classes into one
  // name. Give them stable, editable prefixes before sanitisation instead.
  const prefixedRaw = raw.startsWith('@')
    ? `at-${raw.slice(1)}`
    : raw.startsWith('-')
      ? `negative-${raw.slice(1)}`
      : raw;
  const sanitized = buildPixflowStageBSourceClassName(prefixedRaw);
  if (!sanitized) {
    return '';
  }
  if (/^[a-z_]/i.test(sanitized)) {
    return sanitized;
  }
  const prefix = sanitizePixflowStageBClassPublicName(sourcePrefix, 'pfx');
  return `${prefix}-${sanitized}`;
}

function parsePixflowStageBSourceBemClassName(sourceClassName, knownClassNames = null) {
  const sanitized = buildPixflowStageBSourceClassName(sourceClassName);
  const elementIndex = sanitized.indexOf('__');
  if (elementIndex > 0) {
    const block = sanitized.slice(0, elementIndex);
    const elementAndModifier = sanitized.slice(elementIndex + 2);
    const modifierIndex = elementAndModifier.indexOf('--');
    return {
      block,
      elementSeparator: '__',
      elementOrModifier: modifierIndex >= 0 ? elementAndModifier.slice(0, modifierIndex) : elementAndModifier,
      modifier: modifierIndex >= 0 ? elementAndModifier.slice(modifierIndex + 2) : '',
    };
  }
  const modifierIndex = sanitized.indexOf('--');
  if (modifierIndex > 0) {
    return {
      block: sanitized.slice(0, modifierIndex),
      elementSeparator: '--',
      elementOrModifier: sanitized.slice(modifierIndex + 2),
      modifier: '',
    };
  }
  const semanticBlock = inferPixflowStageBSemanticHyphenClassBlock(sanitized, knownClassNames);
  if (semanticBlock && semanticBlock !== sanitized) {
    return {
      block: semanticBlock,
      elementSeparator: '-',
      elementOrModifier: sanitized.slice(semanticBlock.length + 1),
      modifier: '',
    };
  }
  return {
    block: sanitized,
    elementSeparator: '',
    elementOrModifier: '',
    modifier: '',
  };
}

function inferPixflowStageBSemanticHyphenClassBlock(sanitizedClassName, knownClassNames = null) {
  const source = firstString(sanitizedClassName);
  if (!source.includes('-')) {
    return source;
  }
  const known = knownClassNames instanceof Set ? knownClassNames : new Set();
  const parts = source.split('-').filter(Boolean);
  for (let length = parts.length - 1; length >= 1; length -= 1) {
    const candidate = parts.slice(0, length).join('-');
    if (candidate && candidate !== source && known.has(candidate)) {
      return candidate;
    }
  }
  return source;
}

function prefixPixflowStageBSourceBemTreeClassName(sourceClassName, sourcePrefix, parsedBem = null) {
  const source = buildPixflowStageBSourceClassName(sourceClassName);
  const prefix = sanitizePixflowStageBClassPublicName(sourcePrefix, 'pfx');
  if (source.startsWith(`${prefix}-`)) {
    return source;
  }
  const bem = parsedBem || parsePixflowStageBSourceBemClassName(source);
  const prefixedBlock = `${prefix}-${bem.block}`;
  if (!bem.elementSeparator) {
    return prefixedBlock;
  }
  const modifier = bem.modifier ? `--${bem.modifier}` : '';
  return `${prefixedBlock}${bem.elementSeparator}${bem.elementOrModifier}${modifier}`;
}

function buildPixflowStageBSourceBemClassName(sourceClassName, options = {}) {
  const sourcePrefix = sanitizePixflowStageBClassPublicName(options.sourcePrefix, 'pf-handoff');
  return prefixPixflowStageBSourceBemTreeClassName(sourceClassName, sourcePrefix);
}

function sanitizePixflowStageBClassPublicName(value, fallback = 'pf-stage-b-class') {
  const input = firstString(value, fallback)
    .replace(/[^a-z0-9_-]+/gi, '-')
    .replace(/-{3,}/g, '--')
    .replace(/_{3,}/g, '__')
    .replace(/^-+|-+$/g, '');
  return input || fallback;
}

function isPixflowStageBCompatibleExistingGlobalClass(existingClass, settings) {
  if (!existingClass) {
    return false;
  }
  if (existingClass.settingsEmpty) {
    return true;
  }
  return firstString(existingClass.settingsHash) === hashPixflowStageBClassSettings(settings);
}

function hashPixflowStageBClassSettings(settings) {
  return createHash('md5').update(stablePixflowStageBJsonStringify(objectValue(settings))).digest('hex');
}

function stablePixflowStageBJsonStringify(value) {
  if (Array.isArray(value)) {
    return `[${value.map((item) => stablePixflowStageBJsonStringify(item)).join(',')}]`;
  }
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stablePixflowStageBJsonStringify(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

function buildPixflowStageBClassDecision(details = {}) {
  const settings = objectValue(details.settings);
  const decision = {
    kind: firstString(details.kind, 'class'),
    key: firstString(details.key, details.sourceName, details.requestedName),
    sourceName: firstString(details.sourceName),
    originalSourceClass: firstString(details.originalSourceClass),
    requestedName: firstString(details.requestedName),
    finalName: firstString(details.finalName),
    id: firstString(details.id),
    status: firstString(details.status, 'created'),
    reason: firstString(details.reason, 'available'),
    settingsHash: hashPixflowStageBClassSettings(settings),
  };
  if (details.existingClass) {
    decision.existingClass = {
      id: firstString(details.existingClass.id),
      name: firstString(details.existingClass.name),
      settingsEmpty: details.existingClass.settingsEmpty === true,
      settingsHash: firstString(details.existingClass.settingsHash),
    };
  }
  return decision;
}

function isPixflowStageBPageWrapper(node) {
  return node?.type === 'element'
    && node.tag === 'div'
    && pixflowStageBHtmlClassList(node).includes('page')
    && !pixflowStageBAttr(node, 'data-od-id');
}

function findFirstPixflowHtmlElement(node, predicate) {
  if (!node) return null;
  if (node.type === 'element' && predicate(node)) {
    return node;
  }
  for (const child of node.children || []) {
    const found = findFirstPixflowHtmlElement(child, predicate);
    if (found) return found;
  }
  return null;
}

function flattenPixflowHtmlElements(node, result = []) {
  if (!node) return result;
  if (node.type === 'element') {
    result.push(node);
  }
  for (const child of node.children || []) {
    flattenPixflowHtmlElements(child, result);
  }
  return result;
}

function selectPixflowStageBExactPlannedTemplateNode(elements, sectionPlan, selectedOdId) {
  const selectedSection = objectValue(sectionPlan);
  const selected = elements.find((node) => (
    selectedOdId
    && (
      pixflowStageBAttr(node, 'data-od-id') === selectedOdId
      || pixflowStageBAttr(node, 'data-pf-source-id') === selectedOdId
      || pixflowStageBAttr(node, 'id') === selectedOdId
    )
  ));
  if (selected) return selected;

  const selectedSourceTag = firstString(selectedSection.sourceTag, selectedSection.tag).toLowerCase();
  const selectedClassNames = arrayValue(selectedSection.classList)
    .map((value) => firstString(value))
    .filter(Boolean);
  if (!selectedSourceTag || selectedClassNames.length === 0) return null;
  return elements.find((node) => (
    firstString(node?.tag).toLowerCase() === selectedSourceTag
    && selectedClassNames.every((className) => pixflowStageBHtmlClassList(node).includes(className))
  )) || null;
}

function selectPixflowStageBHeaderTemplateBoundary(selected) {
  if (!selected) return null;
  for (let ancestor = selected.parent; ancestor; ancestor = ancestor.parent) {
    const tag = firstString(ancestor?.tag).toLowerCase();
    if (tag === 'body' || tag === 'html') break;
    const identity = [
      tag,
      pixflowStageBAttr(ancestor, 'id'),
      pixflowStageBAttr(ancestor, 'role'),
      ...pixflowStageBHtmlClassList(ancestor),
    ].join(' ').toLowerCase();
    if (
      tag === 'header'
      || /(?:^|[\s_-])(?:nav|navigation)(?:[\s_-])(?:component|container|shell|wrapper|wrap)(?:$|[\s_-])/.test(identity)
      || /(?:^|[\s_-])(?:site|global|main)(?:[\s_-])(?:header|nav|navigation)(?:$|[\s_-])/.test(identity)
    ) {
      return ancestor;
    }
  }
  return selected;
}

function selectPixflowStageBHeaderNodes(documentRoot, plan) {
  if (objectValue(plan?.headerPlan).detected !== true) {
    return { templateNodes: [], pageSkipNodes: [] };
  }
  const elements = flattenPixflowHtmlElements(documentRoot);
  const selectedOdId = firstString(plan?.headerPlan?.selectedSectionOdId);
  const exactSelected = selectPixflowStageBExactPlannedTemplateNode(
    elements,
    plan?.headerPlan?.selectedSection,
    selectedOdId,
  );
  const selected = (exactSelected && selectPixflowStageBHeaderTemplateBoundary(exactSelected))
    // Pixflow-owned: section maps may use synthetic ids such as "header-1"
    // when the accepted HTML has no data-od-id. Prefer the planned top-level
    // section before falling back to nested nav nodes, otherwise the page keeps
    // the outer header while the template only receives the inner nav.
    || selectPixflowStageBPlannedBodyRootNode(documentRoot, plan?.headerPlan?.selectedSection)
    || elements.find((node) => node.tag === 'header')
    || elements.find((node) => node.tag === 'nav');
  if (!selected) {
    return { templateNodes: [], pageSkipNodes: [] };
  }
  const extras = [];
  const previous = findPreviousPixflowElementSibling(selected);
  if (previous && isPixflowStageBHeaderAuxiliaryNode(previous)) {
    extras.push(previous);
  }
  return {
    templateNodes: [...extras, selected],
    pageSkipNodes: [...extras, selected],
  };
}

function selectPixflowStageBFooterNodes(documentRoot, plan) {
  if (objectValue(plan?.footerPlan).detected !== true) {
    return { templateNodes: [], pageSkipNodes: [] };
  }
  const elements = flattenPixflowHtmlElements(documentRoot);
  const selectedOdId = firstString(plan?.footerPlan?.selectedSectionOdId);
  const selected = selectPixflowStageBExactPlannedTemplateNode(
    elements,
    plan?.footerPlan?.selectedSection,
    selectedOdId,
  )
    // Pixflow-owned: mirror header selection for generated footers that only
    // have synthetic section-map ids, keeping footer content out of page JSON.
    || selectPixflowStageBPlannedBodyRootNode(documentRoot, plan?.footerPlan?.selectedSection)
    || elements.find((node) => node.tag === 'footer');
  if (!selected) {
    return { templateNodes: [], pageSkipNodes: [] };
  }
  return {
    templateNodes: [selected],
    pageSkipNodes: [selected],
  };
}

function selectPixflowStageBPlannedBodyRootNode(documentRoot, sectionPlan) {
  const plan = objectValue(sectionPlan);
  if (Object.keys(plan).length === 0) {
    return null;
  }
  const body = findFirstPixflowHtmlElement(documentRoot, (node) => node.tag === 'body') || documentRoot;
  const roots = getPixflowStageBBodyRootNodes(body).filter((node) => node?.type === 'element');
  const sourceTag = firstString(plan.sourceTag, plan.tag).toLowerCase();
  const index = Number(plan.index);
  if (Number.isFinite(index) && index > 0) {
    const byIndex = roots[index - 1];
    if (byIndex && (!sourceTag || firstString(byIndex.tag).toLowerCase() === sourceTag)) {
      return byIndex;
    }
  }
  const htmlId = firstString(plan.htmlId, plan.id);
  if (htmlId) {
    const byId = roots.find((node) => pixflowStageBAttr(node, 'id') === htmlId);
    if (byId) {
      return byId;
    }
  }
  const classNames = arrayValue(plan.classList).map((value) => firstString(value)).filter(Boolean);
  if (sourceTag && classNames.length > 0) {
    return roots.find((node) => (
      firstString(node.tag).toLowerCase() === sourceTag
      && classNames.every((className) => pixflowStageBHtmlClassList(node).includes(className))
    )) || null;
  }
  return sourceTag ? roots.find((node) => firstString(node.tag).toLowerCase() === sourceTag) || null : null;
}

function findPreviousPixflowElementSibling(node) {
  const siblings = node?.parent?.children || [];
  const index = siblings.indexOf(node);
  for (let cursor = index - 1; cursor >= 0; cursor -= 1) {
    const sibling = siblings[cursor];
    if (sibling?.type === 'text' && !normalizeWhitespace(sibling.text)) {
      continue;
    }
    return sibling?.type === 'element' ? sibling : null;
  }
  return null;
}

function isPixflowStageBHeaderAuxiliaryNode(node) {
  const haystack = [
    node?.tag,
    pixflowStageBAttr(node, 'data-od-id'),
    pixflowStageBAttr(node, 'id'),
    ...pixflowStageBHtmlClassList(node),
  ].join(' ').toLowerCase();
  return /\b(topbar|announcement|preheader|utility-bar|header-bar)\b/.test(haystack);
}

function pixflowStageBAttr(node, name) {
  return firstString(node?.attrs?.[String(name || '').toLowerCase()]);
}

function hasPixflowStageBAttr(node, name) {
  const wanted = String(name || '').toLowerCase();
  return arrayValue(node?.attrList).some((attribute) => firstString(attribute?.name).toLowerCase() === wanted);
}

function pixflowStageBHtmlClassList(node) {
  return classListFromAttr(pixflowStageBAttr(node, 'class'));
}

function pixflowStageBNodeText(node) {
  if (!node) return '';
  if (node.type === 'text') return node.text || '';
  if (node.tag === 'script' || node.tag === 'style') return '';
  return (node.children || []).map((child) => pixflowStageBNodeText(child)).join(' ');
}

function pixflowStageBNodeVisibleText(node) {
  if (!node) return '';
  if (node.type === 'text') return node.text || '';
  const tag = firstString(node?.tag).toLowerCase();
  if (tag === 'script' || tag === 'style' || tag === 'svg') return '';
  const classText = pixflowStageBHtmlClassList(node).join(' ').toLowerCase();
  const inlineStyle = firstString(pixflowStageBAttr(node, 'style')).toLowerCase();
  if (
    hasPixflowStageBAttr(node, 'hidden')
    || firstString(pixflowStageBAttr(node, 'aria-hidden')).toLowerCase() === 'true'
    || /(?:^|\s)(?:sr-only|screen-reader-text|screen-reader-only|visually-hidden)(?:\s|$)/.test(classText)
    || /(?:display\s*:\s*none|visibility\s*:\s*hidden)/.test(inlineStyle)
  ) {
    return '';
  }
  return (node.children || []).map((child) => pixflowStageBNodeVisibleText(child)).join(' ');
}

function pixflowStageBNodeInnerHtml(node) {
  const root = findPixflowStageBDocumentRoot(node);
  if (!root?.rawHtml || typeof node?.contentStart !== 'number' || typeof node?.contentEnd !== 'number') {
    return pixflowStageBNodeText(node);
  }
  return root.rawHtml.slice(node.contentStart, node.contentEnd);
}

function findPixflowStageBDocumentRoot(node) {
  let cursor = node;
  while (cursor?.parent) {
    cursor = cursor.parent;
  }
  return cursor;
}

function hasPixflowStageBElementChildren(node) {
  return (node?.children || []).some((child) => child.type === 'element');
}

function isPixflowStageBInlineTextParentNode(node) {
  const tag = firstString(node?.tag).toLowerCase();
  if (tag === 'p' && pixflowStageBNodeHasDescendantInteractiveContent(node)) {
    return true;
  }
  if (['a', 'span', 'small', 'b', 'strong', 'em', 'i', 'u', 'code'].includes(tag)) {
    return true;
  }
  return firstString(node?.customTag).toLowerCase() === 'span';
}

function isPixflowStageBInlineProseChildNode(node) {
  const parent = node?.parent;
  return firstString(parent?.tag).toLowerCase() === 'p'
    && pixflowStageBNodeHasDescendantInteractiveContent(parent);
}

function isPixflowStageBSkipNavigationNode(node) {
  const tag = firstString(node?.tag).toLowerCase();
  if (tag !== 'a') {
    return false;
  }
  const href = pixflowStageBAttr(node, 'href').trim().toLowerCase();
  const text = normalizeWhitespace(pixflowStageBNodeText(node)).toLowerCase();
  const classText = pixflowStageBHtmlClassList(node).join(' ').toLowerCase();
  return (
    href.startsWith('#')
    && /skip/.test(`${text} ${classText}`)
    && /(?:content|main|navigation|nav)/.test(`${text} ${href} ${classText}`)
  );
}

function isPixflowStageBInlineTextOnlyAnchorNode(node) {
  if (firstString(node?.tag).toLowerCase() !== 'a') {
    return false;
  }
  const allowed = new Set(['br', 'span', 'small', 'b', 'strong', 'em', 'i', 'u', 'code']);
  const elements = flattenPixflowHtmlElements(node).filter((item) => item !== node);
  if (elements.length === 0) {
    return true;
  }
  return elements.every((item) => {
    if (!allowed.has(firstString(item.tag).toLowerCase())) {
      return false;
    }
    if (firstString(item.tag).toLowerCase() === 'br') {
      return true;
    }
    return pixflowStageBHtmlClassList(item).length === 0
      && !pixflowStageBAttr(item, 'id')
      && !pixflowStageBAttr(item, 'data-od-id');
  });
}

function isPixflowStageBCollapsibleInlineTextNode(node) {
  const tag = firstString(node?.tag).toLowerCase();
  if (!['span', 'small'].includes(tag) || !hasPixflowStageBElementChildren(node)) {
    return false;
  }
  const allowed = new Set(['b', 'strong', 'em', 'i', 'u', 'code', 'small', 'span']);
  const elements = flattenPixflowHtmlElements(node).filter((item) => item !== node);
  if (elements.length === 0) {
    return false;
  }
  return elements.every((item) => {
    if (!allowed.has(firstString(item.tag).toLowerCase())) {
      return false;
    }
    return pixflowStageBHtmlClassList(item).length === 0
      && !pixflowStageBAttr(item, 'id')
      && !pixflowStageBAttr(item, 'data-od-id');
  });
}

function isPixflowStageBEmptyDecorativeInlineNode(node) {
  if (node?.tag !== 'span' || hasPixflowStageBElementChildren(node)) {
    return false;
  }
  if (normalizeWhitespace(pixflowStageBNodeText(node))) {
    return false;
  }
  // An empty inline has no textual editing surface. Bricks text-basic renders
  // authoring placeholder copy for it in the canvas, while a structural `div`
  // with `tag: span` preserves the authored DOM and descendant CSS exactly.
  return true;
}

function isPixflowStageBEmptyRuntimeImageNode(node) {
  if (firstString(node?.tag).toLowerCase() !== 'img') {
    return false;
  }
  const src = firstString(
    pixflowStageBAttr(node, 'src'),
    pixflowStageBAttr(node, 'data-img'),
    pixflowStageBAttr(node, 'data-src'),
    pixflowStageBAttr(node, 'srcset'),
  );
  if (src) {
    return false;
  }
  const haystack = [
    pixflowStageBAttr(node, 'id'),
    pixflowStageBHtmlClassList(node).join(' '),
    pixflowStageBAttr(node?.parent, 'id'),
    pixflowStageBHtmlClassList(node?.parent).join(' '),
  ].join(' ').toLowerCase();
  return /\b(?:lightbox|modal|preview|runtime|placeholder)\b/.test(haystack);
}

function isPixflowStageBIncidentalNonVisualNode(node) {
  const tag = firstString(node?.tag).toLowerCase();
  if (tag === 'next-route-announcer' || firstString(pixflowStageBAttr(node, 'id')) === '__next-route-announcer__') {
    return true;
  }
  if (tag !== 'iframe') {
    return false;
  }
  const width = Number.parseFloat(firstString(pixflowStageBAttr(node, 'width')));
  const height = Number.parseFloat(firstString(pixflowStageBAttr(node, 'height')));
  const style = firstString(pixflowStageBAttr(node, 'style')).toLowerCase();
  return hasPixflowStageBAttr(node, 'hidden')
    || firstString(pixflowStageBAttr(node, 'aria-hidden')).toLowerCase() === 'true'
    || (Number.isFinite(width) && Number.isFinite(height) && width <= 1 && height <= 1)
    || /(?:display\s*:\s*none|visibility\s*:\s*hidden|opacity\s*:\s*0|clip\s*:|position\s*:\s*absolute[^;]*\bleft\s*:\s*-?\d{3,}px)/i.test(style);
}

function isPixflowStageBArtworkSvgNode(node) {
  if (firstString(node?.tag).toLowerCase() !== 'svg') {
    return false;
  }
  const haystack = [
    pixflowStageBAttr(node, 'id'),
    pixflowStageBHtmlClassList(node).join(' '),
    pixflowStageBAttr(node?.parent, 'id'),
    pixflowStageBHtmlClassList(node?.parent).join(' '),
  ].join(' ').toLowerCase();
  const explicitRole = firstString(pixflowStageBAttr(node, 'data-pixflow-svg-role')).toLowerCase();
  if (explicitRole === 'artwork') {
    return true;
  }
  if (explicitRole === 'icon') {
    return false;
  }
  if (/(?:^|[^a-z0-9])(?:brand|logo|logotype|wordmark|chart|graph|sparkline|timeline|waveform|metric|visualization|dataviz|screen)(?:$|[^a-z0-9])/.test(haystack)) {
    return true;
  }
  const graphicNodes = flattenPixflowHtmlElements(node);
  const graphicNodeCount = graphicNodes
    .filter((item) => ['path', 'polyline', 'polygon', 'line', 'rect', 'circle', 'ellipse'].includes(firstString(item?.tag).toLowerCase()))
    .length;
  const hasArtworkPrimitive = graphicNodes.some((item) => (
    ['defs', 'text', 'image', 'lineargradient', 'radialgradient', 'pattern', 'mask', 'clippath', 'filter']
      .includes(firstString(item?.tag).toLowerCase())
  ));
  const viewBox = firstString(pixflowStageBAttr(node, 'viewbox')).trim().split(/[\s,]+/).map(Number);
  const compactViewBox = viewBox.length === 4
    && viewBox.every(Number.isFinite)
    && Math.abs(viewBox[2]) <= 64
    && Math.abs(viewBox[3]) <= 64;
  const iconContext = /\b(?:icon|button|link|service|feature|benefit|check|arrow|badge|marker)\b/.test(haystack);
  if (!hasArtworkPrimitive && graphicNodeCount > 0 && graphicNodeCount <= 10 && (compactViewBox || iconContext)) {
    return false;
  }
  // Pixflow-owned: complex or explicitly marked SVGs are distinct artwork and
  // remain in Bricks' native SVG element. Compact icon-like SVGs take the
  // Pixflow icon-set path so the payload never carries raw SVG icon markup.
  return graphicNodeCount > 0;
}

function pixflowStageBNodeOuterHtml(node) {
  const inner = pixflowStageBNodeInnerHtml(node);
  const tag = firstString(node?.tag).toLowerCase();
  if (!tag || !firstString(node?.openTag)) {
    return inner;
  }
  return `${node.openTag}${inner}</${tag}>`;
}

function sanitizePixflowStageBInlineSvgMarkup(value) {
  return String(value || '')
    .replace(/<script\b[\s\S]*?<\/script>/gi, '')
    .replace(/<style\b[\s\S]*?<\/style>/gi, '')
    .replace(/<foreignObject\b[\s\S]*?<\/foreignObject>/gi, '')
    .replace(/\son[a-z]+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, '')
    .replace(/\s(?:href|xlink:href)\s*=\s*(["'])\s*javascript:[\s\S]*?\1/gi, '');
}

function sanitizePixflowStageBInlineHtml(value) {
  const withoutUnsafe = String(value || '')
    .replace(/<script\b[\s\S]*?<\/script>/gi, '')
    .replace(/<style\b[\s\S]*?<\/style>/gi, '')
    .replace(/<svg\b[\s\S]*?<\/svg>/gi, '')
    .replace(/\son[a-z]+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, '');
  // Whitespace can itself be authored inline content. Animation-heavy source
  // documents commonly render word and space tokens as sibling spans, and
  // collapsing markup here turns a deliberate space-only span into an empty
  // element. Browsers already apply HTML whitespace collapsing when rendering,
  // so preserve the source's internal text and trim only the outer boundary.
  return withoutUnsafe.trim();
}

function isPixflowStageBCtaNode(node) {
  const classText = pixflowStageBHtmlClassList(node).join(' ').toLowerCase();
  return /\b(btn|button|cta|action)\b/.test(classText)
    || pixflowStageBAttr(node, 'role').toLowerCase() === 'button';
}

function sanitizePixflowStageBPreformattedInlineHtml(value) {
  return String(value || '')
    .replace(/<script\b[\s\S]*?<\/script>/gi, '')
    .replace(/<style\b[\s\S]*?<\/style>/gi, '')
    .replace(/<svg\b[\s\S]*?<\/svg>/gi, '')
    .replace(/\son[a-z]+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, '');
}

function pixflowStageBSourceButtonOwnsVisualStyle(node, context = {}) {
  const paintProperties = new Set([
    'background',
    'background-color',
    'color',
    'border',
    'border-color',
    'border-width',
    'border-style',
    'border-radius',
    'box-shadow',
  ]);
  const sources = [
    parseStageBCssDeclarations(firstString(pixflowStageBAttr(node, 'style'))),
    ...pixflowStageBHtmlClassList(node).map((className) => (
      objectValue(context?.classInfo?.declarationsByClass?.get?.(className))
    )),
  ];
  return sources.some((declarations) => Object.keys(objectValue(declarations))
    .some((property) => paintProperties.has(String(property || '').toLowerCase())));
}

function applyPixflowStageBNativeButtonSettings(settings, node, options = {}) {
  // Pixflow-owned: Bricks handoff keeps source classes for fidelity, but routine
  // button variants and sizes must use native Bricks controls first so Theme
  // Styles can own editable defaults.
  const styleKey = firstString(options.styleKey, 'style');
  const sizeKey = firstString(options.sizeKey, 'size');
  const tag = firstString(node?.tag).toLowerCase();
  const classText = pixflowStageBHtmlClassList(node).join(' ').toLowerCase();
  const text = normalizeWhitespace(pixflowStageBNodeText(node)).toLowerCase();
  const haystack = `${classText} ${text}`;
  const sourceOwnsVisualStyle = pixflowStageBSourceButtonOwnsVisualStyle(node, options.context);

  if (!firstString(settings[styleKey]) && !sourceOwnsVisualStyle) {
    if (/\b(?:secondary|alt|outline|ghost)\b/.test(haystack)) {
      settings[styleKey] = 'dark';
    } else if (/\b(?:light)\b/.test(haystack)) {
      settings[styleKey] = 'light';
    } else if (/\b(?:dark)\b/.test(haystack)) {
      settings[styleKey] = 'dark';
    } else if (/\b(?:muted)\b/.test(haystack)) {
      settings[styleKey] = 'muted';
    } else if (/\b(?:info)\b/.test(haystack)) {
      settings[styleKey] = 'info';
    } else if (/\b(?:success)\b/.test(haystack)) {
      settings[styleKey] = 'success';
    } else if (/\b(?:warning|warn)\b/.test(haystack)) {
      settings[styleKey] = 'warning';
    } else if (/\b(?:danger|error|destructive)\b/.test(haystack)) {
      settings[styleKey] = 'danger';
    } else if (/\b(?:btn|button|cta|action|primary|main|find|book|ticket|subscribe|open|start|contact)\b/.test(haystack)) {
      settings[styleKey] = 'primary';
    } else if (tag === 'button') {
      settings[styleKey] = 'secondary';
    }
  }

  if (!firstString(settings[sizeKey]) && !hasPixflowStageBSourceButtonSizing(node, options.context)) {
    if (/\b(?:xs|tiny|compact|small|sm)\b/.test(haystack)) {
      settings[sizeKey] = 'sm';
    } else if (/\b(?:xl|extra[-_ ]?large|hero)\b/.test(haystack)) {
      settings[sizeKey] = 'xl';
    } else if (/\b(?:lg|large|prominent)\b/.test(haystack)) {
      settings[sizeKey] = 'lg';
    } else if (firstString(settings[styleKey]) || tag === 'button') {
      settings[sizeKey] = 'md';
    }
  }
}

function buildPixflowStageBActionIconSetting(node) {
  const iconId = inferPixflowStageBIconId(node);
  const sourceIconNode = flattenPixflowHtmlElements(node)
    .find((item) => item !== node && firstString(item?.tag).toLowerCase() === 'svg');
  return buildPixflowStageBIconControlSetting({
    iconId,
    setId: 'tabler-outline',
    node: sourceIconNode || node,
  });
}

function buildPixflowStageBIconControlSetting({ iconId, setId = 'tabler-outline', node = null, context = {} } = {}) {
  const size = resolvePixflowStageBIconControlDimensions(node, context);
  return {
    library: 'pixflowSvg',
    icon: buildStageBIconPlaceholder(setId, iconId),
    width: size.width,
    height: size.height,
  };
}

function resolvePixflowStageBIconControlDimensions(node, context = {}) {
  const widthCandidates = [];
  const heightCandidates = [];
  const pushWidth = (value) => {
    const normalized = normalizePixflowStageBIconSizeValue(value);
    if (normalized) widthCandidates.push(normalized);
  };
  const pushHeight = (value) => {
    const normalized = normalizePixflowStageBIconSizeValue(value);
    if (normalized) heightCandidates.push(normalized);
  };

  if (node && node.type === 'element') {
    const attributes = objectValue(Object.keys(objectValue(node.attrs)).length > 0 ? node.attrs : node.attributes);
    const inlineDeclarations = parseStageBCssDeclarations(firstString(attributes.style));
    pushWidth(inlineDeclarations.width);
    pushHeight(inlineDeclarations.height);

    // SVG width/height attributes are presentation hints with lower cascade
    // priority than authored CSS. Utility/source classes such as w-4/h-4 must
    // therefore determine the Bricks native icon control before falling back
    // to the SVG's common intrinsic 24x24 attributes. Otherwise Bricks emits
    // a winning element-id rule at 24px and defeats the preserved source CSS.
    for (const className of pixflowStageBHtmlClassList(node)) {
      const declarations = objectValue(context?.classInfo?.declarationsByClass?.get(className));
      pushWidth(declarations.width);
      pushHeight(declarations.height);
    }

    pushWidth(attributes.width);
    pushHeight(attributes.height);

    const viewBox = firstString(attributes.viewbox, attributes.viewBox)
      .trim()
      .split(/[\s,]+/)
      .map((part) => Number(part));
    if (viewBox.length === 4 && viewBox.every(Number.isFinite) && viewBox[2] > 0 && viewBox[3] > 0) {
      const explicitWidth = firstString(...widthCandidates);
      const explicitHeight = firstString(...heightCandidates);
      const numericWidth = Number.parseFloat(explicitWidth);
      const numericHeight = Number.parseFloat(explicitHeight);
      if (explicitWidth && !explicitHeight && Number.isFinite(numericWidth)) {
        pushHeight(String((numericWidth * viewBox[3]) / viewBox[2]));
      } else if (explicitHeight && !explicitWidth && Number.isFinite(numericHeight)) {
        pushWidth(String((numericHeight * viewBox[2]) / viewBox[3]));
      }
    }
  }

  const width = firstString(...widthCandidates);
  const height = firstString(...heightCandidates);
  const fallback = firstString(width, height, '24');

  return {
    width: firstString(width, fallback),
    height: firstString(height, fallback),
  };
}

function normalizePixflowStageBIconSizeValue(value) {
  const raw = firstString(value).trim();
  if (!raw) return '';
  if (/^var\(/i.test(raw)) return raw;
  const match = raw.match(/^(\d+(?:\.\d+)?)(px|rem|em)?$/i);
  if (!match) return '';
  const numeric = Number(match[1]);
  if (!Number.isFinite(numeric) || numeric <= 0) return '';
  const normalized = String(numeric).replace(/\.0+$/, '');
  const unit = firstString(match[2]).toLowerCase();
  if (unit === 'rem' || unit === 'em') {
    return `${normalized}${unit}`;
  }
  return normalized;
}

function shouldPixflowStageBButtonUseActionIcon(node) {
  // Pixflow-owned: deterministic baseline conversion must preserve source
  // visual parity. Do not add decorative action icons to plain controls such
  // as filter buttons unless the source already carried an icon/arrow signal.
  // Authored arrow/download glyphs are already retained in the native button
  // text. Adding a second Bricks icon duplicates the affordance and changes
  // the control's intrinsic size, so reserve the icon control for non-textual
  // icon sources such as SVG or font-icon elements.
  const nodeText = normalizeWhitespace(pixflowStageBNodeText(node));
  if (/[→↗➜➔⟶⤓←↑↓]/u.test(nodeText)) {
    return false;
  }
  const classText = pixflowStageBHtmlClassList(node).join(' ').toLowerCase();
  const text = pixflowStageBNodeInnerHtml(node);
  if (/\b(?:icon|has-icon|with-icon|arrow|external)\b/.test(classText)) {
    return true;
  }
  if (/[→↗➜➔⟶]/.test(text)) {
    return true;
  }
  return arrayValue(node?.children).some((child) => {
    const tag = firstString(child?.tag).toLowerCase();
    return ['svg', 'use', 'i'].includes(tag)
      || pixflowStageBHtmlClassList(child).some((name) => /\b(?:icon|arrow)\b/i.test(name));
  });
}

function inferPixflowStageBIconId(node) {
  const text = normalizeWhitespace(pixflowStageBNodeText(node)).toLowerCase();
  const href = pixflowStageBAttr(node, 'href').toLowerCase();
  const classNames = pixflowStageBHtmlClassList(node);
  // Source icon libraries encode the intended glyph directly on the icon.
  // Preserve that exact identity before inspecting nearby copy: ancestor text
  // such as a "20+" statistic must not turn a lucide-arrow-right into plus.
  const exactLucideClass = classNames.find((className) => (
    /^lucide-[a-z0-9-]+$/i.test(className)
    && className.toLowerCase() !== 'lucide'
  ));
  if (exactLucideClass) {
    return mapPixflowStageBSourceIconIdToTabler(
      normalizeStageBIconId(exactLucideClass.replace(/^lucide-/i, '')),
    );
  }
  const classText = classNames.join(' ').toLowerCase();
  const ownHaystack = `${text} ${href} ${classText}`.toLowerCase();
  const ancestors = [];
  let ancestor = node?.parent;
  for (let depth = 0; ancestor && depth < 3; depth += 1, ancestor = ancestor.parent) {
    ancestors.push(
      pixflowStageBAttr(ancestor, 'id'),
      pixflowStageBHtmlClassList(ancestor).join(' '),
      normalizeWhitespace(pixflowStageBNodeText(ancestor)),
    );
  }
  const haystack = `${ownHaystack} ${ancestors.join(' ')}`.toLowerCase();
  if (/\b(?:local seo|seo|search visibility|map|location|near me)\b/.test(haystack)) return 'map-pin';
  if (/\b(?:web design|website|browser|layout|interface|screen)\b/.test(haystack)) return 'browser';
  if (/\b(?:content writing|copywriting|content|document|article|service page copy)\b/.test(haystack)) return 'file-text';
  if (/download|release/.test(text)) return 'download';
  if (/github|repository/.test(haystack)) return 'brand-github';
  if (/download|release/.test(haystack)) return 'download';
  // Do not let a page-level search control in an ancestor (for example a
  // header wrapping a Careers CTA) turn an unrelated button into a search
  // icon. Search is meaningful only when it is present on the control itself.
  if (/search/.test(ownHaystack)) return 'search';
  if (/mail|email|subscribe/.test(haystack)) return 'mail';
  if (/play|video/.test(haystack)) return 'player-play';
  if (/plus|\+/.test(haystack)) return 'plus';
  if (/heart|like/.test(haystack)) return 'heart';
  if (/external|open|start|study|try|book|contact|arrow|method/.test(haystack)) return 'arrow-up-right';
  return 'arrow-up-right';
}

function mapPixflowStageBSourceIconIdToTabler(iconId) {
  const normalized = normalizeStageBIconId(iconId);
  const aliases = {
    // Lucide and Tabler share most semantic names, but these authored Lucide
    // identities use different installable names in Pixflow's Tabler catalog.
    'flask-conical': 'flask-2',
    linkedin: 'brand-linkedin',
  };
  return aliases[normalized] || normalized;
}

function isPixflowStageBSimpleClassSelector(selector, className) {
  const pattern = pixflowStageBSimpleClassSelectorPattern(className);
  return splitPixflowCssSelectorList(selector).some((part) => {
    const trimmed = part.trim();
    // Pixflow-owned: exact `.class` and tag-qualified `section.class` selectors
    // represent the same visible baseline and should become Bricks global class
    // settings. Attribute, chained-class, descendant, and state selectors are
    // conditional source rules and must remain scoped CSS so they do not
    // overwrite the baseline, for example `.card[hidden]` or `.card.featured`.
    return pattern.test(trimmed);
  });
}

function matchPixflowStageBSimpleDescendantClassSelector(selector) {
  const normalized = normalizeWhitespace(firstString(selector)).trim();
  if (!normalized || /[:[\]#*+~>,]/.test(normalized)) {
    return null;
  }
  const match = normalized.match(/^\.([A-Za-z0-9_-]+)\s+\.([A-Za-z0-9_-]+)$/);
  if (!match) {
    return null;
  }
  return {
    ancestorClass: match[1],
    descendantClass: match[2],
  };
}

function buildPixflowStageBDescendantClassStyleMap(rules, cssVariables = new Map(), fontOptions = {}) {
  const byKey = new Map();
  for (const rule of arrayValue(rules)) {
    if (rule?.hasPseudoElement || rule?.hasPseudoState) continue;
    for (const selector of splitPixflowCssSelectorList(rule?.selector || '')) {
      const match = matchPixflowStageBSimpleDescendantClassSelector(selector);
      if (!match) continue;
      const settings = removeUndefinedObjectValues(mapPixflowCssDeclarationsToBricksSettings(
        objectValue(rule.declarations),
        { cssVariables, ...fontOptions },
      ));
      if (Object.keys(settings).length === 0) continue;
      const key = buildPixflowStageBDescendantClassStyleKey(match.ancestorClass, match.descendantClass);
      const current = byKey.get(key) || {
        ancestorClass: match.ancestorClass,
        descendantClass: match.descendantClass,
        settings: {},
      };
      mergePixflowStageBSettings(current.settings, settings);
      byKey.set(key, current);
    }
  }
  return byKey;
}

function isPixflowStageBFullyMappableDescendantClassRule(rule, cssVariables = new Map()) {
  const selectors = splitPixflowCssSelectorList(rule?.selector || '');
  if (selectors.length === 0 || !selectors.every((selector) => matchPixflowStageBSimpleDescendantClassSelector(selector))) {
    return false;
  }
  const declarations = objectValue(rule?.declarations);
  if (Object.keys(declarations).length === 0) return false;
  const mapped = mapPixflowCssDeclarationsToBricksSettings(declarations, { deriveResponsive: false, cssVariables });
  return Object.keys(mapped).length > 0
    && Object.entries(declarations).every(([property, value]) => Object.keys(
      mapPixflowCssDeclarationsToBricksSettings({ [property]: value }, { deriveResponsive: false, cssVariables }),
    ).length > 0);
}

function buildPixflowStageBDescendantClassStyleKey(ancestorClass, descendantClass) {
  return `${firstString(ancestorClass)}|${firstString(descendantClass)}`;
}

function pixflowStageBSimpleClassSelectorPattern(className, suffix = '') {
  const escapedClassName = escapeRegExp(encodePixflowCssIdentifier(className));
  return new RegExp(`^(?:[a-z][a-z0-9-]*\\s*)?\\.${escapedClassName}${suffix}$`, 'i');
}

function buildPixflowStageBClassStateSettings(rule, className, cssVariables = new Map()) {
  const states = pixflowStageBSimpleClassStatesForSelector(rule?.selector, className);
  if (states.length === 0) {
    return {};
  }
  const mapped = mapPixflowCssDeclarationsToBricksSettings(rule?.declarations, {
    deriveResponsive: false,
    cssVariables,
  });
  const picked = pickPixflowStageBStateDeclarations(mapped);
  if (Object.keys(picked).length === 0) {
    return {};
  }
  const settings = {};
  for (const state of states) {
    for (const [key, value] of Object.entries(picked)) {
      settings[`${key}:${state}`] = value;
    }
  }
  return settings;
}

function pixflowStageBSimpleClassStatesForSelector(selector, className) {
  const states = [];
  const pattern = pixflowStageBSimpleClassSelectorPattern(className, ':(hover|focus|focus-visible|focus-within|active|visited|disabled|checked)');
  for (const part of splitPixflowCssSelectorList(selector)) {
    const match = firstString(part).trim().match(pattern);
    if (match) {
      states.push(match[1].toLowerCase());
    }
  }
  return uniqueStrings(states);
}

function pickPixflowStageBStateDeclarations(settings) {
  // Bricks state suffixes apply to the same exposed style controls as the base
  // setting. Restrict only the selector shape, not the native control family.
  return pickPixflowStageBResponsiveDeclarations(settings);
}

function matchPixflowStageBSimpleStructuralClassSelector(selector) {
  const adjacentMatch = firstString(selector).trim().match(/^\.([A-Za-z0-9_-]+)\s*\+\s*\.([A-Za-z0-9_-]+)$/i);
  if (adjacentMatch) {
    return {
      previousClass: adjacentMatch[1],
      sourceClass: adjacentMatch[2],
      structuralPseudo: `after-${adjacentMatch[1]}`,
    };
  }
  const indexedMatch = firstString(selector).trim().match(/^\.([A-Za-z0-9_-]+):nth-(child|of-type)\(\s*(\d+)\s*\)$/i);
  if (indexedMatch) {
    return {
      sourceClass: indexedMatch[1],
      structuralPseudo: `nth-${indexedMatch[2].toLowerCase()}-${indexedMatch[3]}`,
    };
  }
  const match = firstString(selector).trim().match(/^\.([A-Za-z0-9_-]+):(first-child|last-child|first-of-type|last-of-type)$/i);
  return match ? { sourceClass: match[1], structuralPseudo: match[2].toLowerCase() } : null;
}

function buildPixflowStageBStructuralClassStyleMap(rules, cssVariables = new Map()) {
  const byKey = new Map();
  for (const rule of arrayValue(rules)) {
    for (const selector of splitPixflowCssSelectorList(rule?.selector || '')) {
      const match = matchPixflowStageBSimpleStructuralClassSelector(selector);
      if (!match) continue;
      const settings = removeUndefinedObjectValues(mapPixflowCssDeclarationsToBricksSettings(
        objectValue(rule.declarations),
        { deriveResponsive: false, cssVariables },
      ));
      if (Object.keys(settings).length === 0) continue;
      const key = `${match.sourceClass}|${match.structuralPseudo}`;
      const current = byKey.get(key) || { ...match, settings: {} };
      mergePixflowStageBSettings(current.settings, settings);
      byKey.set(key, current);
    }
  }
  return byKey;
}

function isPixflowStageBFullyMappableStructuralClassRule(rule, cssVariables = new Map()) {
  const selectors = splitPixflowCssSelectorList(rule?.selector || '');
  if (selectors.length === 0 || selectors.some((selector) => !matchPixflowStageBSimpleStructuralClassSelector(selector))) {
    return false;
  }
  const declarations = objectValue(rule?.declarations);
  return Object.keys(declarations).length > 0
    && Object.entries(declarations).every(([property, value]) => Object.keys(
      mapPixflowCssDeclarationsToBricksSettings({ [property]: value }, { deriveResponsive: false, cssVariables }),
    ).length > 0);
}

function isPixflowStageBFullyMappableMixedSimpleStructuralClassRule(rule, cssVariables = new Map()) {
  const selectors = splitPixflowCssSelectorList(rule?.selector || '');
  if (selectors.length < 2) return false;
  let hasSimple = false;
  let hasStructural = false;
  for (const selector of selectors) {
    if (matchPixflowStageBSimpleStructuralClassSelector(selector)) {
      hasStructural = true;
      continue;
    }
    const isSimple = arrayValue(rule?.classNames).some((className) => (
      pixflowStageBSimpleClassSelectorPattern(className).test(firstString(selector).trim())
    ));
    if (!isSimple) return false;
    hasSimple = true;
  }
  if (!hasSimple || !hasStructural) return false;
  const declarations = objectValue(rule?.declarations);
  return Object.keys(declarations).length > 0
    && Object.entries(declarations).every(([property, value]) => Object.keys(
      mapPixflowCssDeclarationsToBricksSettings({ [property]: value }, { deriveResponsive: false, cssVariables }),
    ).length > 0);
}

function isPixflowStageBSimpleIdSelector(selector, idName) {
  return splitPixflowCssSelectorList(selector).some((part) => {
    const trimmed = part.trim();
    // Pixflow-owned: mirror class handling so `#id[state]` or `#id .child`
    // cannot collapse conditional source CSS into the base Bricks id helper.
    return trimmed === `#${idName}`;
  });
}

function buildPixflowStageBDescendantElementStyleMap(rules, cssVariables = new Map(), fontOptions = {}) {
  const byKey = new Map();
  for (const rule of Array.isArray(rules) ? rules : []) {
    if (rule?.hasPseudoElement) {
      continue;
    }
    const declarations = objectValue(rule?.declarations);
    if (Object.keys(declarations).length === 0) {
      continue;
    }
    for (const selector of splitPixflowCssSelectorList(rule.selector || '')) {
      const match = matchPixflowStageBSimpleDescendantElementSelector(selector);
      if (!match) {
        continue;
      }
      const descendantDeclarations = filterPixflowStageBDescendantElementDeclarations(match.tag, declarations);
      applyPixflowStageBDescendantInheritedFontFamily(match.tag, descendantDeclarations, fontOptions);
      if (Object.keys(descendantDeclarations).length === 0) {
        continue;
      }
      const mapped = mapPixflowCssDeclarationsToBricksSettings(descendantDeclarations, { cssVariables, ...fontOptions });
      const settings = removeUndefinedObjectValues(match.state
        ? Object.fromEntries(Object.entries(pickPixflowStageBStateDeclarations(mapped))
          .map(([key, value]) => [`${key}:${match.state}`, value]))
        : mapped);
      if (Object.keys(objectValue(settings)).length === 0) {
        continue;
      }
      const key = buildPixflowStageBDescendantElementStyleKey(
        match.ancestorClass,
        match.tag,
        match.structuralPseudo,
        match.excludedClass,
        match.state,
        match.requiredAncestorClass,
      );
      const current = byKey.get(key) || {
        requiredAncestorClass: match.requiredAncestorClass,
        interactionAncestorClass: match.interactionAncestorClass,
        ancestorClass: match.ancestorClass,
        tag: match.tag,
        structuralPseudo: match.structuralPseudo,
        excludedClass: match.excludedClass,
        state: match.state,
        settings: {},
      };
      mergePixflowStageBSettings(current.settings, settings);
      byKey.set(key, current);
    }
  }
  return byKey;
}

function applyPixflowStageBDescendantInheritedFontFamily(tag, declarations, options = {}) {
  const normalizedTag = firstString(tag).toLowerCase();
  if (!/^h[1-6]$/.test(normalizedTag) || firstString(declarations?.['font-family'])) {
    return;
  }
  const tagDeclarationsByTag = options?.tagDeclarationsByTag instanceof Map ? options.tagDeclarationsByTag : new Map();
  if (firstString(objectValue(tagDeclarationsByTag.get(normalizedTag))['font-family'])) {
    return;
  }
  const inheritedFamily = firstString(objectValue(options?.inheritedTextDeclarations)['font-family']);
  if (inheritedFamily) {
    declarations['font-family'] = inheritedFamily;
  }
}

function filterPixflowStageBDescendantElementDeclarations(tag, declarations) {
  // Pixflow-owned: simple descendant selectors like ".card b" are source text
  // styling, not new Bricks layout classes. Keep full style lifting for media,
  // links, and buttons, but inline text descendants only get inherited text
  // declarations unless the source explicitly turns the inline element into a
  // visual box. In that case the descendant is materialized as a real Bricks
  // element, so dropping its padding/border/background destroys both wrapping
  // and responsive geometry (for example customer-logo chips).
  const normalizedTag = firstString(tag).toLowerCase();
  if (/^(?:span|small|strong|b|em|label)$/.test(normalizedTag)) {
    const hasExplicitBoxStyling = Object.keys(objectValue(declarations)).some((property) => [
      'background',
      'background-color',
      'background-image',
      'border',
      'border-top',
      'border-right',
      'border-bottom',
      'border-left',
      'border-width',
      'border-style',
      'border-color',
      'border-radius',
      'box-shadow',
      'height',
      'min-height',
      'max-height',
      'padding',
      'padding-block',
      'padding-inline',
      'padding-top',
      'padding-right',
      'padding-bottom',
      'padding-left',
    ].includes(String(property || '').toLowerCase()));
    if (hasExplicitBoxStyling) {
      return objectValue(declarations);
    }
    const picked = pickPixflowStageBInheritedTextDeclarations(declarations);
    for (const [property, value] of Object.entries(objectValue(declarations))) {
      const key = String(property || '').toLowerCase();
      if ([
        'display',
        'flex',
        'flex-grow',
        'flex-shrink',
        'flex-basis',
        'align-self',
        'order',
        'width',
        'min-width',
        'max-width',
      ].includes(key) && value) {
        picked[property] = value;
      }
    }
    return picked;
  }
  if (/^(?:h[1-6]|p|blockquote)$/.test(normalizedTag)) {
    const picked = {
      ...pickPixflowStageBInheritedTextDeclarations(declarations),
    };
    for (const [property, value] of Object.entries(objectValue(declarations))) {
      const key = String(property || '').toLowerCase();
      if ([
        'display',
        'flex',
        'flex-grow',
        'flex-shrink',
        'flex-basis',
        'align-self',
        'align-items',
        'justify-content',
        'gap',
        'row-gap',
        'column-gap',
        'order',
        'padding',
        'padding-block',
        'padding-inline',
        'padding-top',
        'padding-right',
        'padding-bottom',
        'padding-left',
        'border',
        'border-top',
        'border-right',
        'border-bottom',
        'border-left',
        'border-width',
        'border-style',
        'border-color',
        'border-radius',
        'margin',
        'margin-block',
        'margin-inline',
        'margin-top',
        'margin-right',
        'margin-bottom',
        'margin-left',
        'width',
        'min-width',
        'max-width',
      ].includes(key) && value) {
        picked[property] = value;
      }
    }
    return picked;
  }
  return objectValue(declarations);
}

function matchPixflowStageBSimpleDescendantElementSelector(selector) {
  const normalized = normalizeWhitespace(firstString(selector))
    .replace(/\s*>\s*/g, ' > ')
    .trim();
  if (!normalized || /[[\]#*+~]/.test(normalized)) {
    return null;
  }
  const nestedClassMatch = normalized.match(
    /^\.([A-Za-z0-9_-]+)\s+\.([A-Za-z0-9_-]+)\s+(?:>\s+)?([a-z][a-z0-9-]*)(.*)$/i,
  );
  if (nestedClassMatch && isPixflowStageBDescendantElementStyleTag(nestedClassMatch[3])) {
    const suffixMatch = firstString(nestedClassMatch[4]).match(
      /^(?::(first-child|last-child))?(?::not\(\.([A-Za-z0-9_-]+)\))?(?::(hover|focus|focus-visible|focus-within|active|visited|disabled|checked))?$/i,
    );
    if (suffixMatch) {
      return {
        requiredAncestorClass: nestedClassMatch[1],
        ancestorClass: nestedClassMatch[2],
        tag: nestedClassMatch[3].toLowerCase(),
        structuralPseudo: firstString(suffixMatch[1]).toLowerCase(),
        excludedClass: firstString(suffixMatch[2]),
        state: firstString(suffixMatch[3]).toLowerCase(),
      };
    }
  }
  // Common card interactions put the state on a containing card while the
  // native property belongs to a nested media element, for example
  // `.card:hover .card__media img`. Bricks has no parent-state selector field,
  // but its native element state is the closest editable representation and
  // is visually equivalent while the pointer is over that media. Materialize
  // the declaration on the nested element instead of duplicating it as custom
  // CSS on every class named by the selector.
  const parentStateMatch = normalized.match(
    /^\.([A-Za-z0-9_-]+):(hover|focus|focus-visible|focus-within|active)\s+\.([A-Za-z0-9_-]+)\s+(?:>\s+)?([a-z][a-z0-9-]*)$/i,
  );
  if (parentStateMatch && isPixflowStageBDescendantElementStyleTag(parentStateMatch[4])) {
    return {
      ancestorClass: parentStateMatch[3],
      interactionAncestorClass: parentStateMatch[1],
      tag: parentStateMatch[4].toLowerCase(),
      structuralPseudo: '',
      excludedClass: '',
      state: parentStateMatch[2].toLowerCase(),
    };
  }
  const match = normalized.match(/^\.([A-Za-z0-9_-]+)\s+(?:>\s+)?([a-z][a-z0-9-]*)(.*)$/i);
  if (!match) {
    return null;
  }
  const tag = match[2].toLowerCase();
  if (!isPixflowStageBDescendantElementStyleTag(tag)) {
    return null;
  }
  const suffix = firstString(match[3]);
  const suffixMatch = suffix.match(/^(?::(first-child|last-child))?(?::not\(\.([A-Za-z0-9_-]+)\))?(?::(hover|focus|focus-visible|focus-within|active|visited|disabled|checked))?$/i);
  if (!suffixMatch) return null;
  return {
    ancestorClass: match[1],
    tag,
    structuralPseudo: firstString(suffixMatch[1]).toLowerCase(),
    excludedClass: firstString(suffixMatch[2]),
    state: firstString(suffixMatch[3]).toLowerCase(),
  };
}

function isPixflowStageBSimpleDescendantElementSelectorForClass(selector, className) {
  return splitPixflowCssSelectorList(selector).some((part) => {
    const match = matchPixflowStageBSimpleDescendantElementSelector(part);
    return match?.ancestorClass === className;
  });
}

function isPixflowStageBDescendantElementStyleTag(tag) {
  return /^(?:div|h[1-6]|p|blockquote|label|span|small|strong|b|em|a|button|input|select|textarea|img|video|svg|figure|figcaption|li|ul|ol)$/.test(firstString(tag).toLowerCase());
}

function buildPixflowStageBDescendantElementStyleKey(ancestorClass, tag, structuralPseudo = '', excludedClass = '', state = '', requiredAncestorClass = '') {
  const pseudo = firstString(structuralPseudo).toLowerCase();
  const excluded = firstString(excludedClass);
  const stateName = firstString(state).toLowerCase();
  const relation = [firstString(requiredAncestorClass), firstString(ancestorClass)].filter(Boolean).join('>>');
  return `${relation}|${firstString(tag).toLowerCase()}${pseudo ? `:${pseudo}` : ''}${excluded ? `:not(.${excluded})` : ''}${stateName ? `:${stateName}` : ''}`;
}

function resolvePixflowStageBDescendantElementClassIds(node, classInfo = {}) {
  const tag = firstString(node?.tag).toLowerCase();
  if (!tag || !classInfo?.descendantElementClassIdByKey || typeof classInfo.descendantElementClassIdByKey.get !== 'function') {
    return [];
  }
  const classIds = [];
  const ownClassNames = pixflowStageBHtmlClassList(node);
  const ancestorClassNames = new Set(getPixflowStageBAncestorClassNames(node));
  const elementSiblings = arrayValue(node?.parent?.children).filter((child) => child?.type === 'element');
  const structuralPseudos = [
    '',
    ...(elementSiblings[0] === node ? ['first-child'] : []),
    ...(elementSiblings[elementSiblings.length - 1] === node ? ['last-child'] : []),
  ];
  for (const rule of arrayValue(classInfo.descendantElementClassRules)) {
    if (firstString(rule?.tag).toLowerCase() !== tag) continue;
    if (!ancestorClassNames.has(firstString(rule?.ancestorClass))) continue;
    if (firstString(rule?.requiredAncestorClass) && !ancestorClassNames.has(firstString(rule.requiredAncestorClass))) continue;
    if (firstString(rule?.interactionAncestorClass) && !ancestorClassNames.has(firstString(rule.interactionAncestorClass))) continue;
    if (firstString(rule?.excludedClass) && ownClassNames.includes(firstString(rule.excludedClass))) continue;
    if (firstString(rule?.structuralPseudo) && !structuralPseudos.includes(firstString(rule.structuralPseudo))) continue;
    if (firstString(rule?.id)) classIds.push(firstString(rule.id));
  }
  for (const ancestorClass of ancestorClassNames) {
    for (const structuralPseudo of structuralPseudos) {
      const id = classInfo.descendantElementClassIdByKey.get(
        buildPixflowStageBDescendantElementStyleKey(ancestorClass, tag, structuralPseudo),
      );
      if (id) classIds.push(id);
    }
  }
  return uniqueStrings(classIds);
}

function getPixflowStageBAncestorClassNames(node) {
  const names = [];
  let cursor = node?.parent;
  while (cursor) {
    if (cursor.type === 'element') {
      names.push(...pixflowStageBHtmlClassList(cursor));
    }
    cursor = cursor.parent;
  }
  return uniqueStrings(names);
}

function convertPixflowStageBCssRuleToRoot(rule, className, cssVariables = new Map(), options = {}) {
  const selector = firstString(rule?.selector);
  let declarations = omitStageBStylesheetCustomPropertyDeclarations(rule?.declarations);
  if (!selector || Object.keys(declarations).length === 0) return '';
  if (/:root\b|^\s*(?:html|body)\b/i.test(selector)) return '';
  if (/@import\b|@font-face\b|fonts\.googleapis\.com|fonts\.gstatic\.com/i.test(selector)) return '';
  if (isPixflowStageBSimpleClassSelector(selector, className) && options.preserveNativeDeclarations !== true) {
    declarations = filterPixflowStageBUnsupportedCssDeclarations(declarations, cssVariables);
    if (Object.keys(declarations).length === 0) return '';
  }
  if (pixflowStageBSimpleClassStatesForSelector(selector, className).length > 0) {
    declarations = filterPixflowStageBUnsupportedStateCssDeclarations(declarations, cssVariables);
    if (Object.keys(declarations).length === 0) return '';
  }
  if (isPixflowStageBSimpleDescendantElementSelectorForClass(selector, className)) {
    declarations = filterPixflowStageBUnsupportedCssDeclarations(declarations, cssVariables);
    if (Object.keys(declarations).length === 0) return '';
  }
  if (options.preserveNativeDeclarations === true) {
    // Bricks emits native class controls as `.class.brxe-*`, which is more
    // specific than the source utility selector. A min-width fallback must
    // beat those generated base controls or the exact source media rule never
    // becomes observable. Scope plus `!important` keeps that precedence local
    // to this class and media condition.
    if (/^(?:inline-)?flex$/i.test(firstString(declarations.display)) && !firstString(declarations['flex-direction'])) {
      // A Bricks block carries `flex-direction: column` even while hidden.
      // Source `display:flex` activates the CSS initial row direction, so make
      // that observable default explicit when a min-width utility reveals it.
      declarations['flex-direction'] = 'row';
    }
    declarations = Object.fromEntries(Object.entries(declarations).map(([property, value]) => [
      property,
      /\s!important\s*$/i.test(firstString(value)) ? value : `${value} !important`,
    ]));
  }
  const selectors = splitPixflowCssSelectorList(selector)
    .filter((part) => extractPixflowCssClassNames(part).includes(className))
    .map((part) => replacePixflowCssClassSelector(part, className, '%root%').trim())
    .filter(Boolean);
  if (selectors.length === 0) return '';
  const body = serializePixflowCssDeclarations(declarations, { cssVariables });
  if (!body) return '';
  return `${selectors.join(', ')} { ${body} }`;
}

function applyPixflowStageBSingleAxisGapCompatibility(settings, declarations, responsiveRules, cssVariables = new Map()) {
  const customRules = [];
  const applyFallback = (sourceDeclarations, keySuffix = '', mediaCondition = '') => {
    const source = objectValue(sourceDeclarations);
    if (firstString(source.gap)) return;
    const columnGap = firstString(source['column-gap']);
    const rowGap = firstString(source['row-gap']);
    const property = columnGap && !rowGap
      ? 'column-gap'
      : (rowGap && !columnGap ? 'row-gap' : '');
    if (!property) return;

    const settingKey = `${property === 'column-gap' ? '_columnGap' : '_rowGap'}${keySuffix}`;
    delete settings[settingKey];
    const body = serializePixflowCssDeclarations({ [property]: firstString(source[property]) }, { cssVariables });
    if (!body) return;
    const rootRule = `%root% { ${body} }`;
    customRules.push(mediaCondition ? `@media ${mediaCondition} { ${rootRule} }` : rootRule);
  };

  // Bricks 2.4 requires both native gap axes before it emits either one for a
  // global class. Do not invent the missing axis: separate gap-x/gap-y utility
  // classes must remain composable regardless of Bricks' stylesheet order.
  // Keep the authored axis at the same class owner through narrowly scoped CSS.
  applyFallback(declarations);
  for (const rule of arrayValue(responsiveRules)) {
    for (const suffix of arrayValue(rule?.suffixes)) {
      applyFallback(rule?.declarations, `:${suffix}`, firstString(rule?.condition));
    }
  }
  return [...new Set(customRules)];
}

function applyPixflowStageBDefaultSourceDisplay(settings, className, declarations, usageItem) {
  const safeSettings = objectValue(settings);
  const safeDeclarations = objectValue(declarations);
  if (firstString(safeSettings._display, safeDeclarations.display) !== '') {
    return;
  }

  const normalizedClassName = String(className || '').toLowerCase();
  const observedNames = new Set();
  for (const item of arrayValue(usageItem?.elements)) {
    observedNames.add(String(item?.tag || item?.name || '').toLowerCase());
  }

  // Pixflow-owned: Bricks `container` elements default to flex, while common
  // source `.container`/`.wrap` divs are block flow unless the CSS says
  // otherwise. Preserve that source default so sibling sections do not shrink
  // into accidental flex rows during handoff.
  if (
    /^(?:container|wrap|wrapper|inner|content|shell)$/.test(normalizedClassName)
    || /\b(?:container|wrap|wrapper|inner|content|shell)\b/.test(normalizedClassName)
    || observedNames.has('container')
  ) {
    safeSettings._display = 'block';
  }
}

function applyPixflowStageBMaxWidthBlockFill(settings, declarations, usageItem) {
  const safeSettings = objectValue(settings);
  const safeDeclarations = objectValue(declarations);
  if (!firstString(safeDeclarations['max-width']) || firstString(safeDeclarations.width, safeSettings._width)) return;
  if (['inline-flex', 'inline-grid', 'inline-block'].includes(firstString(safeDeclarations.display, safeSettings._display).toLowerCase())) return;
  const blockTags = new Set(['address', 'article', 'aside', 'div', 'footer', 'form', 'header', 'main', 'nav', 'section']);
  const usedAsBlock = arrayValue(usageItem?.elements).some((item) => (
    blockTags.has(firstString(item?.tag, item?.name).toLowerCase())
  ));
  if (usedAsBlock) safeSettings._width = '100%';
}

function applyPixflowStageBUtilityDisplayDefaults(settings) {
  const safeSettings = objectValue(settings);
  const display = firstString(safeSettings._display).toLowerCase();
  const hasFlexControl = ['_direction', '_flexDirection', '_flexWrap'].some((key) => Boolean(safeSettings[key]) && firstString(safeSettings[key]) !== '');
  const hasGridControl = [
    '_gridTemplateColumns',
    '_gridTemplateRows',
    '_justifyItemsGrid',
    '_alignItemsGrid',
    '_justifyContentGrid',
    '_alignContentGrid',
  ].some((key) => Boolean(safeSettings[key]) && firstString(safeSettings[key]) !== '');
  // Utility classes are frequently authored as a composable set (`grid
  // grid-rows-1`, `flex items-center`). Bricks validates each global class in
  // isolation, so give control-only utilities an explicit layout owner while
  // leaving an existing native display choice authoritative.
  if (hasGridControl && !['grid', 'inline-grid'].includes(display)) {
    safeSettings._display = 'grid';
  } else if (hasFlexControl && !['flex', 'inline-flex'].includes(display)) {
    safeSettings._display = 'flex';
  }
  // Alignment utilities are layout-polymorphic in authored CSS: the same
  // `.items-center` class works on flex and grid containers. Bricks separates
  // those controls and its grid class emits an `align-items: initial` reset,
  // so retain both controls without making the utility itself a grid owner.
  if (!display && safeSettings._alignItems && !safeSettings._alignItemsGrid) {
    safeSettings._alignItemsGrid = safeSettings._alignItems;
  }
  if (!display && safeSettings._justifyContent && !safeSettings._justifyContentGrid) {
    safeSettings._justifyContentGrid = safeSettings._justifyContent;
  }
}

function applyPixflowStageBPolymorphicAlignmentFallback(settings) {
  const safeSettings = objectValue(settings);
  if (firstString(safeSettings._display)) return;
  const declarations = [];
  if (firstString(safeSettings._alignItems)) {
    declarations.push(`align-items: ${safeSettings._alignItems} !important`);
  }
  if (firstString(safeSettings._justifyContent)) {
    declarations.push(`justify-content: ${safeSettings._justifyContent} !important`);
  }
  if (declarations.length === 0) return;
  const fallback = `%root% { ${declarations.join('; ')}; }`;
  if (!firstString(safeSettings._cssCustom).includes(fallback)) {
    safeSettings._cssCustom = [firstString(safeSettings._cssCustom), fallback].filter(Boolean).join('\n');
  }
}

function isPixflowStageBUtilityAggregationClassName(name) {
  const normalized = firstString(name).toLowerCase();
  if (!normalized) return false;
  if (isPixflowStageBUtilityLikeClassName(normalized)) return true;
  // Sanitised arbitrary/negative utility variants can be grouped under a
  // stable public class (for example `negative-top` or `flex-2`) while the
  // custom CSS still targets the escaped utility selectors. Those classes
  // are intentional aggregation buckets, not unscoped component CSS.
  if (/^negative-(?:inset|top|right|bottom|left|mx|my|ms|me|mt|mr|mb|ml|translate|rotate|skew|space|scroll|text|leading|tracking|order|z|flex|grid|gap|p|m)(?:-|$)/.test(normalized)) {
    return true;
  }
  if (/^flex-\d+$/.test(normalized)) return true;
  if (/^(?:inset-y|list|space-y|space-x)$/.test(normalized)) return true;
  return /^(?:inset(?:-[xse])?|top|right|bottom|left|z|mx|my|ms|me|mt|mr|mb|ml|aspect|size|h|max-h|min-h|w|max-w|min-w|basis|origin|translate(?:-[a-z0-9]+)?|scale|transform(?:-[a-z0-9]+)?|animate|scroll-mt|auto-cols|grid-cols|grid-rows|gap(?:-[xy])?|rounded(?:-[0-9]+)?|border(?:-[0-9]+)?|p(?:[xylr])?|indent|text|leading|opacity)$/.test(normalized);
}

function convertPixflowStageBIdCssRuleToRoot(rule, idName, cssVariables = new Map()) {
  const selector = firstString(rule?.selector);
  let declarations = omitStageBStylesheetCustomPropertyDeclarations(rule?.declarations);
  if (!selector || Object.keys(declarations).length === 0) return '';
  if (/:root\b|^\s*(?:html|body)\b/i.test(selector)) return '';
  if (/@import\b|@font-face\b|fonts\.googleapis\.com|fonts\.gstatic\.com/i.test(selector)) return '';
  if (isPixflowStageBSimpleIdSelector(selector, idName)) {
    declarations = filterPixflowStageBUnsupportedCssDeclarations(declarations, cssVariables);
    if (Object.keys(declarations).length === 0) return '';
  }
  const selectors = splitPixflowCssSelectorList(selector)
    .filter((part) => part.includes(`#${idName}`))
    .map((part) => part.replace(new RegExp(`#${escapeRegExp(idName)}\\b`, 'g'), '%root%').trim())
    .filter(Boolean);
  if (selectors.length === 0) return '';
  const body = serializePixflowCssDeclarations(declarations, { cssVariables });
  if (!body) return '';
  return `${selectors.join(', ')} { ${body} }`;
}

function filterPixflowStageBUnsupportedCssDeclarations(declarations, cssVariables = new Map()) {
  const result = {};
  for (const [property, value] of Object.entries(omitStageBStylesheetCustomPropertyDeclarations(declarations))) {
    if (!isPixflowStageBMappableCssDeclaration(property, value, cssVariables)) {
      result[property] = value;
    }
  }
  return result;
}

function filterPixflowStageBUnsupportedStateCssDeclarations(declarations, cssVariables = new Map()) {
  const stylesheetDeclarations = omitStageBStylesheetCustomPropertyDeclarations(declarations);
  const mapped = mapPixflowCssDeclarationsToBricksSettings(stylesheetDeclarations, {
    deriveResponsive: false,
    cssVariables,
  });
  const mappedStateKeys = new Set(Object.keys(pickPixflowStageBStateDeclarations(mapped)));
  if (mappedStateKeys.size === 0) {
    return stylesheetDeclarations;
  }
  const result = {};
  for (const [property, value] of Object.entries(stylesheetDeclarations)) {
    const declarationSettings = mapPixflowCssDeclarationsToBricksSettings({ [property]: value }, {
      deriveResponsive: false,
      cssVariables,
    });
    const declarationMapsToState = Object.keys(pickPixflowStageBStateDeclarations(declarationSettings)).length > 0;
    if (!declarationMapsToState) {
      result[property] = value;
    }
  }
  return result;
}

function isPixflowStageBMappableCssDeclaration(property, value, cssVariables = new Map()) {
  const key = String(property || '').toLowerCase();
  if (!value) return true;
  // Bricks native controls do not encode CSS cascade priority. Treat an
  // authored !important winner as a scoped fallback even when its underlying
  // property has a native control; otherwise a later ordinary rule can be
  // lifted into the class and silently reverse the source cascade.
  if (/\s!important\s*$/i.test(String(value))) return false;
  if (key.startsWith('--')) return false;
  const resolvedValue = resolvePixflowStageBCssVariableExpression(value, cssVariables);
  if ([
    'display',
    'flex-direction',
    'flex-wrap',
    'flex-grow',
    'flex-shrink',
    'flex-basis',
    'align-self',
    'order',
    'justify-self',
    'align-items',
    'justify-content',
    'justify-items',
    'align-content',
    'place-items',
    'place-content',
    'gap',
    'column-gap',
    'row-gap',
    'grid-template-columns',
    'grid-template-rows',
    'width',
    'height',
    'min-width',
    'max-width',
    'min-height',
    'max-height',
    'aspect-ratio',
    'object-fit',
    'object-position',
    'overflow',
    'overflow-x',
    'overflow-y',
    'visibility',
    'opacity',
    'cursor',
    'isolation',
    'mix-blend-mode',
    'pointer-events',
    'perspective',
    'perspective-origin',
    'scroll-snap-type',
    'scroll-snap-align',
    'scroll-snap-stop',
    'scroll-margin',
    'position',
    'inset',
    'top',
    'right',
    'bottom',
    'left',
    'z-index',
    'transition',
    'transform-origin',
    'padding',
    'padding-block',
    'padding-inline',
    'padding-top',
    'padding-right',
    'padding-bottom',
    'padding-left',
    'margin',
    'margin-block',
    'margin-inline',
    'margin-top',
    'margin-right',
    'margin-bottom',
    'margin-left',
    'color',
    'font-family',
    'font-size',
    'font-weight',
    'font-style',
    'font-variation-settings',
    'line-height',
    'letter-spacing',
    'white-space',
    'text-wrap',
    'text-align',
    'text-transform',
    'text-decoration',
    'border-radius',
    'border-top-left-radius',
    'border-top-right-radius',
    'border-bottom-right-radius',
    'border-bottom-left-radius',
    'border',
    'border-top',
    'border-right',
    'border-bottom',
    'border-left',
    'border-width',
    'border-style',
    'border-color',
    'border-top-width',
    'border-right-width',
    'border-bottom-width',
    'border-left-width',
  ].includes(key)) {
    return true;
  }
  if (key === 'flex') {
    return Boolean(parsePixflowStageBFlexShorthand(resolvedValue));
  }
  if (key === 'transform') {
    return Boolean(parsePixflowStageBTransform(resolvedValue));
  }
  if (key === 'translate') {
    return Boolean(parsePixflowStageBIndividualTranslate(resolvedValue));
  }
  if (key === 'filter') {
    return Boolean(parsePixflowStageBCssFilters(resolvedValue));
  }
  if (key === 'text-shadow') {
    return Boolean(parsePixflowStageBShadow(resolvedValue));
  }
  if (key === 'box-shadow') {
    return Boolean(parsePixflowStageBShadow(resolvedValue, { allowInset: true, allowSpread: true }));
  }
  if (key === 'font') {
    return Object.keys(parsePixflowStageBFontShorthand(resolvedValue)).length > 0;
  }
  if (key === 'background' && (isPixflowCssColorValue(resolvedValue) || parsePixflowStageBNativeGradientBackground(resolvedValue) || parsePixflowStageBBackgroundImage(resolvedValue))) {
    return true;
  }
  if (key === 'background-color' && isPixflowCssColorValue(resolvedValue)) {
    return true;
  }
  if (key === 'background-image') {
    return Boolean(parsePixflowStageBBackgroundImage(resolvedValue));
  }
  if (key === 'background-position') return Boolean(parsePixflowStageBBackgroundPosition(resolvedValue));
  if (key === 'background-size') return Boolean(parsePixflowStageBBackgroundSize(resolvedValue));
  if (['background-repeat', 'background-attachment', 'background-blend-mode'].includes(key)) return isPixflowStageBSingleBackgroundLayerValue(resolvedValue);
  return false;
}

function splitPixflowCssSelectorList(selector) {
  const result = [];
  let depth = 0;
  let current = '';
  for (const char of String(selector || '')) {
    if (char === '(' || char === '[') depth += 1;
    if (char === ')' || char === ']') depth = Math.max(0, depth - 1);
    if (char === ',' && depth === 0) {
      if (current.trim()) result.push(current.trim());
      current = '';
      continue;
    }
    current += char;
  }
  if (current.trim()) result.push(current.trim());
  return result;
}

function serializePixflowCssDeclarations(declarations, options = {}) {
  const cssVariables = options.cssVariables || new Map();
  return Object.entries(objectValue(declarations))
    .filter(([key, value]) => key && value)
    .map(([key, value]) => `${key}: ${normalizePixflowStageBCustomCssDeclarationValue(key, value, { ...options, cssVariables })};`)
    .join(' ');
}

function applyPixflowStageBInheritedControlTypography(settings, className, usageItem, options = {}) {
  // Pixflow-owned: Bricks button variants carry their own font metrics, while
  // standalone Stage A anchors inherit body typography. Put those inherited
  // metrics on source-authored control classes so the accepted header and CTA
  // geometry survives conversion without changing class-owned declarations.
  const sourceClassName = firstString(className);
  if (!/\b(?:btn|button|cta|action)\b/i.test(sourceClassName.replace(/[_-]+/g, ' '))) return;
  // BEM modifiers/elements are attached after their base class in Bricks.
  // Copying inherited metrics onto `.button--primary` or `.header__cta`
  // therefore overwrites the base button's explicit font-size/line-height.
  // Every text control already receives stage-a-body-type, so this bridge is
  // only needed on a base control class.
  if (/(?:__|--)/.test(sourceClassName)) return;
  const tags = arrayValue(usageItem?.tags).map((tag) => firstString(tag).toLowerCase());
  if (!tags.some((tag) => tag === 'a' || tag === 'button')) return;
  const inherited = mapPixflowCssDeclarationsToBricksSettings(
    pickPixflowStageBInheritedTextDeclarations(options.inheritedTextDeclarations),
    { cssVariables: options.cssVariables, ...objectValue(options.fontOptions) },
  )._typography;
  if (!inherited || Object.keys(objectValue(inherited)).length === 0) return;
  settings._typography = { ...objectValue(inherited), ...objectValue(settings._typography) };
}

function resolvePixflowStageBDescendantClassIds(node, classInfo = {}) {
  if (!classInfo?.descendantClassIdByKey || typeof classInfo.descendantClassIdByKey.get !== 'function') {
    return [];
  }
  const ownClassNames = pixflowStageBHtmlClassList(node);
  if (ownClassNames.length === 0) {
    return [];
  }
  const classIds = [];
  for (const ancestorClass of getPixflowStageBAncestorClassNames(node)) {
    for (const descendantClass of ownClassNames) {
      const id = classInfo.descendantClassIdByKey.get(
        buildPixflowStageBDescendantClassStyleKey(ancestorClass, descendantClass),
      );
      if (id) classIds.push(id);
    }
  }
  return uniqueStrings(classIds);
}

function resolvePixflowStageBStructuralClassIds(node, classInfo = {}) {
  const ownClassNames = new Set(pixflowStageBHtmlClassList(node));
  if (ownClassNames.size === 0) return [];
  const elementSiblings = arrayValue(node?.parent?.children).filter((child) => child?.type === 'element');
  const sameTypeSiblings = elementSiblings.filter((child) => firstString(child?.tag).toLowerCase() === firstString(node?.tag).toLowerCase());
  const structuralPseudos = new Set([
    ...(elementSiblings[0] === node ? ['first-child'] : []),
    ...(elementSiblings[elementSiblings.length - 1] === node ? ['last-child'] : []),
    ...(sameTypeSiblings[0] === node ? ['first-of-type'] : []),
    ...(sameTypeSiblings[sameTypeSiblings.length - 1] === node ? ['last-of-type'] : []),
    ...(elementSiblings.includes(node) ? [`nth-child-${elementSiblings.indexOf(node) + 1}`] : []),
    ...(sameTypeSiblings.includes(node) ? [`nth-of-type-${sameTypeSiblings.indexOf(node) + 1}`] : []),
  ]);
  const nodeIndex = elementSiblings.indexOf(node);
  const previousSibling = nodeIndex > 0 ? elementSiblings[nodeIndex - 1] : null;
  const previousClassNames = new Set(pixflowStageBHtmlClassList(previousSibling));
  return uniqueStrings(arrayValue(classInfo.structuralClassRules)
    .filter((rule) => ownClassNames.has(firstString(rule?.sourceClass))
      && (firstString(rule?.previousClass)
        ? previousClassNames.has(firstString(rule.previousClass))
        : structuralPseudos.has(firstString(rule?.structuralPseudo))))
    .map((rule) => firstString(rule?.id))
    .filter(Boolean));
}

function isPixflowStageBFullyMappableDescendantElementRule(rule, cssVariables = new Map()) {
  const selectors = splitPixflowCssSelectorList(rule?.selector || '');
  const matches = selectors.map((selector) => matchPixflowStageBSimpleDescendantElementSelector(selector));
  if (matches.length === 0 || matches.some((match) => !match)) return false;
  const declarations = objectValue(rule?.declarations);
  if (Object.keys(declarations).length === 0) return false;
  return matches.every((match) => {
    const filtered = filterPixflowStageBDescendantElementDeclarations(match.tag, declarations);
    const mapped = mapPixflowCssDeclarationsToBricksSettings(filtered, { deriveResponsive: false, cssVariables });
    return Object.keys(mapped).length > 0
      && Object.entries(filtered).every(([property, value]) => Object.keys(
        mapPixflowCssDeclarationsToBricksSettings({ [property]: value }, { deriveResponsive: false, cssVariables }),
      ).length > 0);
  });
}

function isPixflowStageBFullyMappableMixedSimpleDescendantElementRule(rule, cssVariables = new Map()) {
  const selectors = splitPixflowCssSelectorList(rule?.selector || '');
  if (selectors.length < 2) return false;
  const declarations = objectValue(rule?.declarations);
  if (Object.keys(declarations).length === 0) return false;
  let hasSimple = false;
  let hasDescendant = false;
  for (const selector of selectors) {
    const descendant = matchPixflowStageBSimpleDescendantElementSelector(selector);
    if (descendant) {
      hasDescendant = true;
      const filtered = filterPixflowStageBDescendantElementDeclarations(descendant.tag, declarations);
      if (Object.keys(filtered).length === 0 || !Object.entries(filtered).every(([property, value]) => Object.keys(
        mapPixflowCssDeclarationsToBricksSettings({ [property]: value }, { deriveResponsive: false, cssVariables }),
      ).length > 0)) {
        return false;
      }
      continue;
    }
    const isSimple = arrayValue(rule?.classNames).some((className) => (
      pixflowStageBSimpleClassSelectorPattern(className).test(firstString(selector).trim())
    ));
    if (!isSimple) return false;
    hasSimple = true;
    if (!Object.entries(declarations).every(([property, value]) => Object.keys(
      mapPixflowCssDeclarationsToBricksSettings({ [property]: value }, { deriveResponsive: false, cssVariables }),
    ).length > 0)) {
      return false;
    }
  }
  return hasSimple && hasDescendant;
}

function normalizePixflowStageBCustomCssDeclarationValue(property, value, options = {}) {
  const key = String(property || '').toLowerCase();
  const cssVariables = options.cssVariables || new Map();
  if (key === 'font-family') {
    const fontFamily = resolvePixflowStageBFontFamilyTypography(value, {
      cssVariables,
      availableFontFamilies: options.availableFontFamilies,
    })['font-family'] || '';
    if (fontFamily) {
      return /[\s,]/.test(fontFamily) ? `"${fontFamily.replace(/"/g, '\\"')}"` : fontFamily;
    }
  }
  return value;
}

function parsePixflowCssBoxValue(value) {
  const parts = splitPixflowCssValueList(value);
  const top = parts[0] || '0';
  const right = parts[1] || top;
  const bottom = parts[2] || top;
  const left = parts[3] || right;
  return { top, right, bottom, left };
}

function parsePixflowCssLogicalBlockValue(value) {
  const parts = splitPixflowCssValueList(value);
  return {
    top: parts[0] || '0',
    bottom: parts[1] || parts[0] || '0',
  };
}

function parsePixflowCssLogicalInlineValue(value) {
  const parts = splitPixflowCssValueList(value);
  return {
    right: parts[1] || parts[0] || '0',
    left: parts[0] || '0',
  };
}

function parsePixflowCssPlacePairValue(value) {
  const parts = splitPixflowCssValueList(value).filter((part) => !/^normal$/i.test(part));
  const align = parts[0] || 'center';
  return {
    align,
    justify: parts[1] || align,
  };
}

function parsePixflowCssBorderRadiusValue(value) {
  const box = parsePixflowCssBoxValue(value);
  return {
    top: box.top,
    right: box.right,
    bottom: box.bottom,
    left: box.left,
  };
}

function pixflowCssBorderCornerToBricksRadiusSide(property) {
  const key = String(property || '').toLowerCase();
  if (key.includes('top-left')) return 'top';
  if (key.includes('top-right')) return 'right';
  if (key.includes('bottom-right')) return 'bottom';
  if (key.includes('bottom-left')) return 'left';
  return 'top';
}

function buildPixflowCssBorderSideBox(value) {
  const normalized = normalizePixflowCssBorderWidthValue(value);
  return {
    top: normalized,
    right: normalized,
    bottom: normalized,
    left: normalized,
  };
}

function normalizePixflowCssBorderWidthValue(value) {
  const source = firstString(value).trim();
  const pxMatch = source.match(/^(-?(?:\d+|\d*\.\d+))px$/i);
  if (pxMatch) {
    return pxMatch[1];
  }
  return source;
}

function splitPixflowCssValueList(value) {
  const parts = [];
  let depth = 0;
  let current = '';
  for (const char of String(value || '').trim()) {
    if (char === '(') depth += 1;
    if (char === ')') depth = Math.max(0, depth - 1);
    if (/\s/.test(char) && depth === 0) {
      if (current.trim()) parts.push(current.trim());
      current = '';
      continue;
    }
    current += char;
  }
  if (current.trim()) parts.push(current.trim());
  return parts;
}

function parsePixflowCssBorderValue(value) {
  const parts = splitPixflowCssValueList(value);
  if (parts.length === 1 && /^(?:0(?:\.0+)?(?:[a-z%]+)?|none)$/i.test(parts[0])) {
    return { width: buildPixflowCssBorderSideBox('0'), style: 'none' };
  }
  const styleIndex = parts.findIndex((part) => /^(?:none|solid|dashed|dotted|double)$/i.test(part));
  if (styleIndex < 0) {
    return {};
  }
  const width = parts.slice(0, styleIndex).join(' ') || '1px';
  const style = parts[styleIndex];
  const color = parts.slice(styleIndex + 1).join(' ');
  const border = { width: buildPixflowCssBorderSideBox(width), style };
  if (color) {
    border.color = { raw: color };
  }
  return border;
}

function parsePixflowCssBorderSideValue(value, side) {
  const sideName = firstString(side).toLowerCase();
  if (/^0(?:[a-z%]+)?$/i.test(firstString(value)) && ['top', 'right', 'bottom', 'left'].includes(sideName)) {
    return { width: { [sideName]: '0' } };
  }
  const parsed = parsePixflowCssBorderValue(value);
  if (Object.keys(parsed).length === 0) {
    return {};
  }
  if (!['top', 'right', 'bottom', 'left'].includes(sideName)) {
    return parsed;
  }
  const width = objectValue(parsed.width);
  const sideWidth = firstString(width[sideName], width.top, width.right, width.bottom, width.left);
  const border = {
    ...parsed,
    width: sideWidth ? { [sideName]: sideWidth } : width,
  };
  return border;
}

function isPixflowCssColorValue(value) {
  const source = String(value || '').trim();
  if (!source) return false;
  return source === 'transparent'
    || source === 'currentColor'
    || (
      /^[A-Za-z][A-Za-z0-9-]*$/.test(source)
      && !/^(?:none|auto|inherit|initial|unset|revert|revert-layer)$/i.test(source)
    )
    || /^var\(\s*--[A-Za-z0-9_-]+(?:\s*,[\s\S]+)?\)$/i.test(source)
    || /^#(?:[0-9a-f]{3}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(source)
    || /^(?:rgb|rgba|hsl|hsla|oklch|oklab|color-mix)\(/i.test(source);
}

function mergePixflowBricksSettings(...settingsList) {
  const result = {};
  for (const settings of settingsList) {
    mergePixflowBricksSettingsInto(result, settings);
  }
  return result;
}

function mergePixflowBricksSettingsInto(target, source) {
  for (const [key, value] of Object.entries(objectValue(source))) {
    if (value === undefined || value === null || value === '') continue;
    if (
      value
      && typeof value === 'object'
      && !Array.isArray(value)
      && target[key]
      && typeof target[key] === 'object'
      && !Array.isArray(target[key])
      && !['link', 'image', 'icon'].includes(key)
    ) {
      target[key] = mergePixflowBricksSettings(target[key], value);
    } else {
      target[key] = value;
    }
  }
  return target;
}

function removeUndefinedObjectValues(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return value;
  }
  const result = {};
  for (const [key, child] of Object.entries(value)) {
    if (child === undefined || child === null || child === '') {
      continue;
    }
    if (Array.isArray(child)) {
      result[key] = child.map((item) => removeUndefinedObjectValues(item));
    } else if (child && typeof child === 'object') {
      result[key] = removeUndefinedObjectValues(child);
    } else {
      result[key] = child;
    }
  }
  return result;
}

function extractPixflowStageBTokenReferences(value) {
  return uniqueStrings([...String(value || '').matchAll(/var\(\s*(--[A-Za-z0-9_-]+)/g)].map((match) => match[1])).slice(0, 120);
}

function extractPixflowStageBRawColorFallbacks(cssText) {
  const raw = uniqueStrings([...String(cssText || '').matchAll(/#(?:[0-9a-f]{3}|[0-9a-f]{6}|[0-9a-f]{8})\b/gi)].map((match) => match[0].toLowerCase()));
  return raw.slice(0, 40);
}

function stripPixflowStageBAtRuleBlocks(cssText, atRuleName) {
  const source = String(cssText || '');
  const name = firstString(atRuleName).replace(/^@/, '');
  if (!name) return source;
  let result = '';
  let cursor = 0;
  const pattern = new RegExp(`@${escapeRegExp(name)}\\b`, 'gi');
  let match;
  while ((match = pattern.exec(source)) !== null) {
    result += source.slice(cursor, match.index);
    const openIndex = source.indexOf('{', pattern.lastIndex);
    if (openIndex < 0) {
      cursor = pattern.lastIndex;
      continue;
    }
    const closeIndex = findPixflowCssBlockClose(source, openIndex);
    cursor = closeIndex > openIndex ? closeIndex + 1 : openIndex + 1;
    pattern.lastIndex = cursor;
  }
  result += source.slice(cursor);
  return result;
}

function extractPixflowStageBKeyframes(cssText, name) {
  const source = String(cssText || '');
  const keyframeName = firstString(name);
  const pattern = new RegExp(`@keyframes\\s+${escapeRegExp(keyframeName)}\\s*\\{`, 'i');
  const match = source.match(pattern);
  if (!match || typeof match.index !== 'number') return '';
  const openIndex = source.indexOf('{', match.index);
  const closeIndex = findPixflowCssBlockClose(source, openIndex);
  if (openIndex < 0 || closeIndex <= openIndex) return '';
  return source.slice(match.index, closeIndex + 1).trim();
}

function extractPixflowStageBKeyframeBlocks(cssText) {
  const source = String(cssText || '');
  const rootRemPx = inferStageBRootRemPxFromCss(source);
  const blocks = [];
  const seen = new Set();
  const pattern = /@(?:-[a-z]+-)?keyframes\s+[A-Za-z0-9_-]+\s*\{/gi;
  let match;
  while ((match = pattern.exec(source)) !== null) {
    const openIndex = source.indexOf('{', match.index);
    const closeIndex = findPixflowCssBlockClose(source, openIndex);
    if (openIndex < 0 || closeIndex <= openIndex) {
      pattern.lastIndex = match.index + 1;
      continue;
    }
    const block = normalizeStageBRemValue(source.slice(match.index, closeIndex + 1).trim(), rootRemPx);
    const key = block.replace(/\s+/g, ' ');
    if (block && !seen.has(key)) {
      blocks.push(block);
      seen.add(key);
    }
    pattern.lastIndex = closeIndex + 1;
  }
  return blocks.join('\n');
}

function findPixflowCssBlockClose(source, openIndex) {
  let depth = 0;
  for (let index = openIndex; index < source.length; index += 1) {
    const char = source[index];
    if (char === '{') depth += 1;
    if (char === '}') {
      depth -= 1;
      if (depth === 0) return index;
    }
  }
  return -1;
}

function buildPixflowStageBRevealCss(cssText) {
  if (!/\[data-reveal\]/i.test(String(cssText || ''))) {
    return '';
  }
  return [
    '%root% [data-reveal] { opacity: 0; translate: 0 28px; transition: opacity 720ms cubic-bezier(0.22, 1, 0.36, 1) var(--reveal-delay, 0ms), translate 720ms cubic-bezier(0.22, 1, 0.36, 1) var(--reveal-delay, 0ms), scale 720ms cubic-bezier(0.22, 1, 0.36, 1) var(--reveal-delay, 0ms); will-change: opacity, translate, scale; }',
    '%root% [data-reveal="left"] { translate: -32px 0; }',
    '%root% [data-reveal="right"] { translate: 32px 0; }',
    '%root% [data-reveal="scale"] { translate: 0 0; scale: 0.97; }',
    '%root% [data-reveal][data-revealed="true"] { opacity: 1; translate: 0 0; scale: 1; }',
    '@media (prefers-reduced-motion: reduce) { %root% [data-reveal] { opacity: 1 !important; translate: 0 0 !important; scale: 1 !important; transition: none !important; } }',
  ].join('\n');
}

function renderPixflowStageBHtmlBaselineReport(plan, baseline, globalClasses, content) {
  const layoutSummary = summarizePixflowStageBBaselineLayoutSignal({
    globalClasses,
    content,
    headerContent: baseline.headerContent,
    footerContent: baseline.footerContent,
  });
  const lines = [];
  lines.push('# Stage B Baseline Conversion Report');
  lines.push('');
  lines.push('Mode: Pixflow-owned clean-room HTML-to-Bricks baseline. Bricks source code was not copied; the converter targets the copied-elements JSON contract and Pixflow Stage B QA rules.');
  lines.push('');
  lines.push('## Summary');
  lines.push('');
  lines.push(`- Source title: ${safe(plan.source?.title)}`);
  lines.push(`- Page elements: ${content.length}`);
  lines.push(`- Header elements: ${Number(baseline.headerContent?.length || 0)}`);
  lines.push(`- Footer elements: ${Number(baseline.footerContent?.length || 0)}`);
  lines.push(`- Global classes: ${globalClasses.length}`);
  lines.push(`- CSS rules observed: ${Number(baseline.summary?.cssRuleCount || 0)}`);
  lines.push(`- Source tokens referenced: ${baseline.tokensUsed.join(', ') || '-'}`);
  lines.push(`- Baseline layout signal: ${layoutSummary.score}% (${layoutSummary.summary})`);
  lines.push(`- Source structure nodes: ${Number(baseline.structureReport?.sourceNodeCount || 0)}`);
  lines.push(`- Source-node coverage: ${(Number(baseline.structureReport?.sourceCoverageRatio || 0) * 100).toFixed(2)}%`);
  lines.push(`- Source-projected elements: ${Number(baseline.structureReport?.sourceProjectedElementCount || 0)}`);
  lines.push(`- Documented synthetic elements: ${Number(baseline.structureReport?.syntheticElementCount || 0)}`);
  lines.push(`- Native-editable / exact-fallback elements: ${Number(baseline.structureReport?.nativeEditableElementCount || 0)} / ${Number(baseline.structureReport?.exactFallbackElementCount || 0)}`);
  lines.push(`- Native style declarations: ${Number(baseline.styleOwnershipReport?.nativeControlDeclarationCount || 0)}`);
  lines.push(`- Scoped/page CSS fallback declarations: ${Number(baseline.styleOwnershipReport?.fallbackDeclarationCount || 0)}`);
  lines.push(`- Scoped/page CSS bytes: ${Number(baseline.styleOwnershipReport?.scopedCustomCssBytes || 0)} / ${Number(baseline.styleOwnershipReport?.pageCssBytes || 0)}`);
  lines.push(`- Unresolved/silently lost declarations: ${Number(baseline.styleOwnershipReport?.unresolvedDeclarationCount || 0)} / ${Number(baseline.styleOwnershipReport?.silentLossCount || 0)}`);
  lines.push(`- Retained/pruned global classes: ${Number(baseline.classLifecycleReport?.retainedClassCount || 0)} / ${Number(baseline.classLifecycleReport?.prunedClassCount || 0)}`);
  lines.push(`- Direct/dependency-only global classes: ${Number(baseline.classLifecycleReport?.directlyReferencedClassCount || 0)} / ${Number(baseline.classLifecycleReport?.dependencyOnlyClassCount || 0)}`);
  lines.push(`- Orphan/unexplained-unused global classes: ${Number(baseline.classLifecycleReport?.orphanReferenceCount || 0)} / ${Number(baseline.classLifecycleReport?.unexplainedUnusedClassCount || 0)}`);
  lines.push(`- Resolved/unresolved source tokens: ${Number(baseline.tokenGraphReport?.resolvedTokenCount || 0)} / ${Number(baseline.tokenGraphReport?.unresolvedTokenCount || 0)}`);
  lines.push(`- Undefined emitted variables: ${Number(baseline.tokenGraphReport?.undefinedOutputReferenceCount || 0)}`);
  lines.push(`- Framework exact reuse/rejected colours: ${Number(baseline.tokenGraphReport?.framework?.exactReuseCount || 0)} / ${Number(baseline.tokenGraphReport?.framework?.rejectedColourCount || 0)}`);
  lines.push(`- Added editable variables/palette colours: ${arrayValue(baseline.tokenGraphReport?.mutationIntent?.resourceAdditions?.variables).length} / ${arrayValue(baseline.tokenGraphReport?.mutationIntent?.resourceAdditions?.paletteColors).length}`);
  lines.push('');
  lines.push('## Conversion Policy');
  lines.push('');
  lines.push('- Stage A DOM hierarchy is used as the first-pass structure instead of a model-authored blank Bricks payload.');
  lines.push('- Source classes are preserved as Bricks global classes and applied to elements by class id.');
  lines.push('- Simple source CSS declarations are projected onto Bricks settings for layout, type, spacing, colors, radius, borders, media sizing, and flex/grid controls.');
  lines.push('- Selector details, pseudo states, and unsupported effects remain scoped in global-class `_cssCustom` with `%root%` selectors. Routine layout, spacing, typography, background, border, radius, media, and object-fit declarations are represented as Bricks settings instead of duplicated in `_cssCustom`.');
  lines.push('- Visible pseudo-element marks such as label rules, timeline lines, and small dividers should be rebuilt as editable Bricks child elements when practical; do not use `%root%::before`/`%root%::after` for token buckets or page-wide overlays.');
  lines.push('- CTA anchors with source button classes become Bricks `button` elements, with Pixflow Tabler SVG placeholders replacing inline arrow SVGs.');
  lines.push('- Stage A `data-*`, `aria-*`, `role`, `title`, and `tabindex` attributes are represented with Bricks `_attributes`.');
  lines.push('- Stage A JavaScript is carried in Bricks page settings (`customScriptsBodyFooter`) as a complete script block; Bricks `code` elements are not used for Stage B JavaScript.');
  lines.push('- Font imports are intentionally not emitted; `stage-b-font-system.json` remains the installer contract.');
  lines.push('');
  lines.push('## Baseline Layout Signal');
  lines.push('');
  lines.push(`- Global classes with grid display: ${layoutSummary.globalClassGridCount}`);
  lines.push(`- Global classes with flex display: ${layoutSummary.globalClassFlexCount}`);
  lines.push(`- Global classes with positioned layout: ${layoutSummary.globalClassPositionCount}`);
  lines.push(`- Global classes with explicit sizing/aspect controls: ${layoutSummary.globalClassSizingCount}`);
  lines.push(`- Responsive Bricks setting count: ${layoutSummary.responsiveSettingCount}`);
  lines.push(`- Elements with direct inline-derived style settings: ${layoutSummary.elementDirectStyleCount}`);
  lines.push(`- Elements with positioned direct settings: ${layoutSummary.elementPositionCount}`);
  lines.push('');
  return `${lines.join('\n')}\n`;
}

function summarizePixflowStageBBaselineLayoutSignal({ globalClasses, content, headerContent, footerContent }) {
  const classes = arrayValue(globalClasses);
  const elements = [
    ...arrayValue(content),
    ...arrayValue(headerContent),
    ...arrayValue(footerContent),
  ];
  const globalClassGridCount = classes.filter((item) => firstString(item?.settings?._display).toLowerCase().includes('grid')).length;
  const globalClassFlexCount = classes.filter((item) => firstString(item?.settings?._display).toLowerCase().includes('flex')).length;
  const globalClassPositionCount = classes.filter((item) => firstString(item?.settings?._position)).length;
  const globalClassSizingCount = classes.filter((item) => {
    const settings = objectValue(item?.settings);
    return ['_width', '_height', '_widthMin', '_widthMax', '_heightMin', '_heightMax', '_aspectRatio'].some((key) => firstString(settings[key]));
  }).length;
  const responsiveSettingCount = classes.reduce((count, item) => (
    count + Object.keys(objectValue(item?.settings)).filter((key) => key.includes(':')).length
  ), 0);
  const elementDirectStyleCount = elements.filter((item) => collectStageBElementDirectStyleKeys(objectValue(item?.settings)).length > 0).length;
  const elementPositionCount = elements.filter((item) => firstString(item?.settings?._position)).length;
  const signalCount = globalClassGridCount
    + globalClassFlexCount
    + globalClassPositionCount
    + globalClassSizingCount
    + Math.min(20, responsiveSettingCount)
    + elementDirectStyleCount
    + elementPositionCount;
  const elementCount = Math.max(1, elements.length);
  // Pixflow-owned: this is not a visual parity grade. It is a quick baseline
  // health signal showing whether source layout data survived before the model
  // cleanup pass starts.
  const score = Math.max(0, Math.min(100, Math.round((signalCount / Math.max(12, elementCount * 0.18)) * 100)));
  const summary = [
    `${globalClassGridCount} grid classes`,
    `${globalClassFlexCount} flex classes`,
    `${globalClassPositionCount + elementPositionCount} positioned sources`,
    `${responsiveSettingCount} responsive settings`,
  ].join(', ');
  return {
    score,
    summary,
    globalClassGridCount,
    globalClassFlexCount,
    globalClassPositionCount,
    globalClassSizingCount,
    responsiveSettingCount,
    elementDirectStyleCount,
    elementPositionCount,
  };
}

function normalizeFlags(flags) {
  const aliases = {
    c: 'config',
    h: 'help',
    'site-url': 'siteUrl',
    'rest-namespace': 'restNamespace',
    'prompt-file': 'promptFile',
    'metadata-file': 'metadataFile',
    'source-id': 'sourceId',
    'run-id': 'runId',
    'handoff-file': 'handoffFile',
    'stage-a-workspace': 'stageAWorkspace',
    'workspace-dir': 'workspaceDir',
    'out-dir': 'outDir',
    'project-id': 'projectId',
    'result-file': 'resultFile',
    'qa-file': 'qaFile',
    'conversion-report-file': 'conversionReportFile',
    'page-title': 'pageTitle',
    'target-post-id': 'targetPostId',
    'replace-existing': 'replaceExisting',
    'post-status': 'postStatus',
    'include-header': 'includeHeader',
    'header-scope': 'headerScope',
    'header-title': 'headerTitle',
    'header-template-title': 'headerTemplateTitle',
    'include-footer': 'includeFooter',
    'footer-scope': 'footerScope',
    'footer-title': 'footerTitle',
    'footer-template-title': 'footerTemplateTitle',
    'route-id': 'routeId',
    'route-label': 'routeLabel',
    'framework-route': 'frameworkRoute',
    'style-mode': 'styleMode',
    'bridge-status-file': 'bridgeStatusFile',
    'style-status-file': 'styleStatusFile',
    'theme-style-state-file': 'themeStyleStateFile',
    'route-contract-file': 'routeContractFile',
    'theme-style-contract-file': 'themeStyleContractFile',
    'theme-style-health-file': 'themeStyleHealthFile',
    'create-theme-style-baseline': 'createThemeStyleBaseline',
    'theme-style-scope': 'themeStyleScope',
    'skip-status-preflight': 'skipStatusPreflight',
    'wp-cookie': 'wpCookie',
    'wp-cookies': 'wpCookie',
    'runner-command': 'runnerCommand',
    'library-page': 'libraryPage',
    'repair-attempts': 'repairAttempts',
    'stage-b-min-score': 'stageBMinScore',
    'stage-b-allow-p1': 'stageBAllowP1',
    'allow-stage-b-p1': 'stageBAllowP1',
    'allow-low-stage-b-qa': 'allowLowStageBQa',
    'skip-stage-b-qa-gate': 'allowLowStageBQa',
    'daemon-url': 'daemonUrl',
    'data-dir': 'dataDir',
    'no-open': 'noOpen',
    'no-browser': 'noBrowser',
  };
  const normalized = {};
  for (const [key, value] of Object.entries(flags)) {
    normalized[aliases[key] || key] = value;
  }
  return normalized;
}

async function buildImportArtifactPayload(flags) {
  const htmlPath = firstString(flags.html, flags.file, flags.artifact);
  if (!htmlPath) {
    throw new CliError('Missing required --html <path> for import-artifact.');
  }

  const htmlFile = path.resolve(process.cwd(), htmlPath);
  const html = await readTextFile(htmlPath, 'HTML artifact');
  const prompt = flags.promptFile
    ? await readTextFile(flags.promptFile, 'prompt file')
    : firstString(flags.prompt);
  const metadata = await readMetadata(flags);
  const handoff = await readImportHandoff(flags, htmlPath, metadata);
  const libraryArtifacts = await readLibraryImportArtifacts(htmlFile);
  const stageAArtifacts = await readStageAImportArtifacts(htmlFile);

  const fidelity = firstString(flags.fidelity, metadata.fidelity, 'high_fidelity');
  const sourceId = firstString(flags.sourceId, metadata.sourceId, metadata.source_id, path.basename(path.dirname(path.resolve(htmlPath))) || 'pixflow-cli-stage-a');
  const requestPayload = buildStageAImportRequestPayload({
    prompt,
    fidelity,
    sourceId,
    metadata,
    handoff,
  });

  return {
    artifact: {
      html,
      sourceId,
    },
    metadata: {
      ...metadata,
      sourceId,
      importedFrom: path.resolve(htmlPath),
    },
    request_payload: requestPayload,
    library_page_plan: libraryArtifacts.libraryPagePlan,
    section_flow_critique: libraryArtifacts.sectionFlowCritique,
    composition_dna: stageAArtifacts.compositionDna,
    stage_a_self_critique: stageAArtifacts.selfCritique,
    library_self_critique: stageAArtifacts.selfCritique,
    prompt,
    fidelity,
    sourceId,
  };
}

async function readLibraryImportArtifacts(htmlFile) {
  const workspaceCandidates = inferStageAWorkspaceCandidates(htmlFile);
  const libraryPagePlan = await readFirstOptionalJsonCandidate(workspaceCandidates, 'library-page-plan.json');
  const sectionFlowCritique = await readFirstOptionalTextCandidate(workspaceCandidates, 'section-flow-critique.md');

  return {
    libraryPagePlan,
    sectionFlowCritique,
  };
}

async function readStageAImportArtifacts(htmlFile) {
  const workspaceCandidates = inferStageAWorkspaceCandidates(htmlFile);
  const compositionDna = await readFirstOptionalTextCandidate(workspaceCandidates, 'composition-dna.md');
  const selfCritique =
    await readFirstOptionalTextCandidate(workspaceCandidates, 'library-self-critique.md')
    || await readFirstOptionalTextCandidate(workspaceCandidates, 'stage-a-self-critique.md');

  return {
    compositionDna,
    selfCritique,
  };
}

function inferStageAWorkspaceCandidates(htmlFile) {
  const htmlDir = path.dirname(htmlFile);
  const workspaceDir = path.dirname(htmlDir);
  return uniqueStrings([
    workspaceDir,
    htmlDir,
  ]).filter(Boolean);
}

async function readFirstOptionalJsonCandidate(candidateDirs, fileName) {
  for (const candidateDir of candidateDirs) {
    const artifact = await readOptionalJson(path.join(candidateDir, fileName));
    if (artifact && typeof artifact === 'object' && Object.keys(artifact).length > 0) {
      return artifact;
    }
  }

  return {};
}

async function readFirstOptionalTextCandidate(candidateDirs, fileName) {
  for (const candidateDir of candidateDirs) {
    const artifact = await readOptionalText(path.join(candidateDir, fileName));
    if (artifact.trim() !== '') {
      return artifact;
    }
  }

  return '';
}

async function readImportHandoff(flags, htmlPath, metadata) {
  const explicitPath = firstString(flags.handoff, flags.handoffFile);
  if (explicitPath) {
    return await readOptionalJson(explicitPath);
  }

  const candidates = [];
  if (flags.metadataFile) {
    candidates.push(path.join(path.dirname(path.resolve(process.cwd(), flags.metadataFile)), 'handoff.json'));
  }
  candidates.push(path.join(path.dirname(path.resolve(process.cwd(), htmlPath)), '..', 'handoff.json'));
  candidates.push(path.join(path.dirname(path.resolve(process.cwd(), htmlPath)), 'handoff.json'));

  for (const candidate of candidates) {
    const handoff = await readOptionalJson(candidate);
    if (Object.keys(handoff).length > 0) {
      return handoff;
    }
  }

  return isPlainObject(metadata.handoff) ? metadata.handoff : {};
}

function buildStageAImportRequestPayload({ prompt, fidelity, sourceId, metadata, handoff }) {
  const selectedPrototype = firstPlainObject(
    metadata.selectedPrototype,
    metadata.selected_prototype,
    handoff?.selectedPrototype,
    handoff?.selected_prototype
  );
  const selectedTemplate = firstPlainObject(
    metadata.selectedTemplate,
    metadata.selected_template,
    handoff?.selectedTemplate,
    handoff?.selected_template
  );
  const selectedPixflowDesignSystem = firstPlainObject(
    metadata.selectedPixflowDesignSystem,
    metadata.selected_pixflow_design_system,
    metadata.pixflowDesignSystem,
    metadata.pixflow_design_system,
    handoff?.pixflowDesignSystem,
    handoff?.pixflow_design_system,
    handoff?.selectedPixflowDesignSystem,
    handoff?.selected_pixflow_design_system
  );
  const workflow = firstPlainObject(metadata.workflow, handoff?.workflow);
  const target = firstPlainObject(metadata.target, handoff?.target);
  const sitemapContext = firstPlainObject(
    metadata.sitemapContext,
    metadata.sitemap_context,
    stageASitemapContextFromHandoff(handoff)
  );
  const pageIntentContract = firstPlainObject(
    metadata.pageIntentContract,
    metadata.page_intent_contract,
    stageAPageIntentContractFromHandoff(handoff)
  );
  const prototypeId = normalizeKey(firstString(
    selectedPrototype?.id,
    selectedPrototype?.slug,
    selectedPrototype?.key,
    sourceId
  ));
  const pluginId = normalizeKey(firstString(
    selectedPrototype?.pluginId,
    selectedPrototype?.plugin_id,
    selectedPrototype?.source,
    selectedPrototype?.id,
    sourceId
  ));
  const templateId = normalizeKey(firstString(
    selectedTemplate?.id,
    selectedTemplate?.slug,
    selectedTemplate?.key,
    prototypeId
  ));
  const systemId = normalizeKey(firstString(
    selectedPixflowDesignSystem?.key,
    selectedPixflowDesignSystem?.id,
    selectedPixflowDesignSystem?.slug,
    selectedPixflowDesignSystem?.name,
    handoff?.pixflowDesignSystemId,
    metadata.pixflowDesignSystemId
  ));
  const pageTitle = firstString(
    target?.pageTitle,
    target?.title,
    metadata.title,
    selectedPrototype?.title,
    selectedPrototype?.name,
    sourceId
  );
  const payload = {
    prompt,
    current_page_title: pageTitle,
    page_title: pageTitle,
    fidelity,
    prototype_fidelity: fidelity,
    direct_stage_a_artifact_first: true,
    directStageAArtifactFirst: true,
    direct_pixflow_design_mode: true,
    directPixflowDesignMode: true,
    direct_cli_bridge_import: true,
    directCliBridgeImport: true,
    direct_generation_stage: DEFAULT_STAGE,
    directGenerationStage: DEFAULT_STAGE,
    bricks_excluded: true,
    bricksExcluded: true,
  };

  if (Object.keys(selectedPrototype).length > 0) {
    payload.selectedPrototype = selectedPrototype;
    payload.selected_prototype = selectedPrototype;
    payload.direct_pixflow_design_example = selectedPrototype;
    payload.directPixflowDesignExample = selectedPrototype;
  }
  if (Object.keys(selectedTemplate).length > 0) {
    payload.selectedTemplate = selectedTemplate;
    payload.selected_template = selectedTemplate;
  }
  if (Object.keys(selectedPixflowDesignSystem).length > 0) {
    payload.selectedPixflowDesignSystem = selectedPixflowDesignSystem;
    payload.selected_pixflow_design_system = selectedPixflowDesignSystem;
  }
  if (Object.keys(workflow).length > 0) {
    payload.workflow = workflow;
  }
  if (Object.keys(target).length > 0) {
    payload.target = target;
  }
  if (Object.keys(sitemapContext).length > 0) {
    payload.direct_sitemap_context = sitemapContext;
    payload.directSitemapContext = sitemapContext;
  }
  if (Object.keys(pageIntentContract).length > 0) {
    payload.direct_page_intent_contract = pageIntentContract;
    payload.directPageIntentContract = pageIntentContract;
    if (firstString(workflow.generationPipeline, metadata.generationPipeline, handoff?.generationPipeline) !== 'pixflow_library_page') {
      payload.direct_page_only_generation = true;
      payload.directPageOnlyGeneration = true;
      payload.stage_b_header = { includeHeader: false, source: 'page_only_sitemap' };
      payload.stageBHeader = { includeHeader: false, source: 'page_only_sitemap' };
      payload.stage_b_footer = { includeFooter: false, source: 'page_only_sitemap' };
      payload.stageBFooter = { includeFooter: false, source: 'page_only_sitemap' };
    }
  }
  if (pluginId) {
    payload.direct_pixflow_design_plugin_id = pluginId;
    payload.directPixflowDesignPluginId = pluginId;
  }
  if (prototypeId) {
    payload.direct_pixflow_design_skill = prototypeId;
    payload.pixflow_design_skill = prototypeId;
  }
  if (templateId) {
    payload.direct_pixflow_design_template = templateId;
    payload.pixflow_design_template = templateId;
  }
  if (systemId) {
    payload.direct_pixflow_design_system = systemId;
    payload.pixflow_design_system = systemId;
    payload.pixflowDesignSystemId = systemId;
  }

  return payload;
}

async function buildStageBImportPayload(flags) {
  const runId = firstString(flags.runId, flags.run, flags.run_id);
  if (!runId) {
    throw new CliError('Missing required --run-id <id> for Stage B import.');
  }

  const resultPath = resolveStageBResultPath(flags);
  const result = await readJsonFile(resultPath, 'Stage B Bricks result');
  const workspaceDir = path.dirname(path.resolve(process.cwd(), resultPath));
  const colorSystem = await readStageBColorSystem(flags, workspaceDir);
  const contracts = await readStageBContracts(flags, workspaceDir);
  const resultWithColorSystem = attachStageBContractsToResult(
    attachStageBColorSystemToResult(result, colorSystem),
    contracts
  );
  const metadataFile = firstString(flags.metadataFile, path.join(workspaceDir, 'metadata.json'));
  const metadata = await readOptionalJson(metadataFile);
  const qaFile = firstString(flags.qaFile, path.join(workspaceDir, 'stage-b-qa.json'));
  const qa = await readOptionalJson(qaFile);
  assertStageBRemoteQaReady(qa, qaFile, flags, 'Stage B import');
  const conversionReportFile = firstString(flags.conversionReportFile, path.join(workspaceDir, 'conversion-report.md'));
  const conversionReport = await readOptionalText(conversionReportFile);
  const title = firstString(flags.title, flags.pageTitle, metadata.title, result.page_title, result.pageTitle, metadata.sourceId, metadata.source_id);
  const titledResult = applyStageBPayloadTitle(resultWithColorSystem, title);
  const sourceId = firstString(flags.sourceId, flags.source_id, metadata.sourceId, metadata.source_id, result.source_id, result.sourceId, path.basename(workspaceDir));
  const headerOptions = buildStageBHeaderPayloadOptions(flags);
  const footerOptions = buildStageBFooterPayloadOptions(flags);
  const binaryAssets = await collectStageBPayloadBinaryAssets(workspaceDir, titledResult);

  const payload = {
    runId,
    result: titledResult,
    colorSystem,
    routeContract: contracts.routeContract,
    themeStyleContract: contracts.themeStyleContract,
    themeStyleHealth: contracts.themeStyleHealth,
    metadata: {
      ...metadata,
      sourceId,
      importedFrom: path.resolve(resultPath),
    },
    qa,
    conversionReport,
    title,
    pageTitle: title,
    page_title: title,
    sourceId,
  };
  if (binaryAssets.length > 0) {
    payload.workspace = { binary_assets: binaryAssets };
    payload.binary_assets = binaryAssets;
  }
  if (Object.keys(headerOptions).length > 0) {
    payload.stageBHeader = headerOptions;
  }
  if (Object.keys(footerOptions).length > 0) {
    payload.stageBFooter = footerOptions;
  }
  return payload;
}

async function buildStageBInsertPayload(flags) {
  const payload = {
    runId: firstString(flags.runId, flags.run, flags.run_id),
  };
  if (!payload.runId) {
    throw new CliError('Missing required --run-id <id> for Stage B insert.');
  }

  const resultPath = firstString(flags.resultFile, flags.result, flags.bricksResult, flags.file);
  if (resultPath) {
    const workspaceDir = path.dirname(path.resolve(process.cwd(), resultPath));
    const result = await readJsonFile(resultPath, 'Stage B Bricks result');
    const colorSystem = await readStageBColorSystem(flags, workspaceDir);
    const contracts = await readStageBContracts(flags, workspaceDir);
    const title = firstString(flags.title, flags.pageTitle);
    payload.result = applyStageBPayloadTitle(
      attachStageBContractsToResult(attachStageBColorSystemToResult(result, colorSystem), contracts),
      title
    );
    const binaryAssets = await collectStageBPayloadBinaryAssets(workspaceDir, payload.result);
    if (binaryAssets.length > 0) {
      payload.workspace = { binary_assets: binaryAssets };
      payload.binary_assets = binaryAssets;
    }
    payload.colorSystem = colorSystem;
    payload.routeContract = contracts.routeContract;
    payload.themeStyleContract = contracts.themeStyleContract;
    payload.themeStyleHealth = contracts.themeStyleHealth;
    const metadata = await readOptionalJson(firstString(flags.metadataFile, path.join(workspaceDir, 'metadata.json')));
    if (Object.keys(metadata).length > 0) {
      payload.metadata = metadata;
    }
    const qa = await readOptionalJson(firstString(flags.qaFile, path.join(workspaceDir, 'stage-b-qa.json')));
    assertStageBRemoteQaReady(qa, firstString(flags.qaFile, path.join(workspaceDir, 'stage-b-qa.json')), flags, 'Stage B insert');
    if (Object.keys(qa).length > 0) {
      payload.qa = qa;
    }
    const report = await readOptionalText(firstString(flags.conversionReportFile, path.join(workspaceDir, 'conversion-report.md')));
    if (report) {
      payload.conversionReport = report;
    }
  }

  const title = firstString(flags.title, flags.pageTitle);
  if (title) {
    payload.title = title;
    payload.pageTitle = title;
    payload.page_title = title;
    payload.postTitle = title;
  }
  const targetPostId = firstString(flags.targetPostId, flags.postId, flags.post_id);
  if (targetPostId) {
    payload.targetPostId = targetPostId;
  }
  const projectId = firstString(flags.projectId, flags.project_id);
  if (projectId) {
    payload.projectId = projectId;
  }
  const replaceExisting = firstString(flags.replaceExisting);
  if (replaceExisting) {
    payload.replaceExisting = replaceExisting;
  }
  const postStatus = firstString(flags.postStatus);
  if (postStatus) {
    payload.postStatus = postStatus;
  }
  const headerOptions = buildStageBHeaderPayloadOptions(flags);
  if (Object.keys(headerOptions).length > 0) {
    payload.stageBHeader = headerOptions;
  }
  const footerOptions = buildStageBFooterPayloadOptions(flags);
  if (Object.keys(footerOptions).length > 0) {
    payload.stageBFooter = footerOptions;
  }

  return payload;
}

function buildStageBWpInitialInsertPayload(payload) {
  const result = objectValue(payload?.result);
  if (Object.keys(result).length === 0) {
    throw new CliError('Stage B WP-first insert requires --result-file so the Bricks handoff result can be sent to WordPress.');
  }

  const targetPostId = firstString(payload.targetPostId, payload.postId, payload.post_id);
  const title = firstString(payload.title, payload.pageTitle, payload.postTitle);
  const replaceExisting = firstString(payload.replaceExisting);
  const metadata = objectValue(payload.metadata);
  const runId = firstString(payload.runId, metadata.runId, metadata.sourceId, payload.projectId);
  const qa = objectValue(payload.qa);
  const files = { 'bricks-result.json': result };
  if (Object.keys(qa).length > 0) files['bricks-handoff-qa.json'] = qa;
  if (firstString(payload.conversionReport)) files['conversion-report.md'] = firstString(payload.conversionReport);

  return {
    ...(targetPostId ? { postId: targetPostId } : {}),
    ...(title ? { pageTitle: title } : {}),
    bricksHandoffResult: result,
    handoffQa: qa,
    sourceFile: objectValue(metadata.sourceFile) || { path: 'drafts/index.html', label: 'Stage A HTML' },
    handoffArtifacts: {
      handoffId: firstString(runId, `stage-b-${Date.now()}`),
      files,
    },
    replaceExisting: replaceExisting ? replaceExisting !== 'false' : true,
    frameworkContext: arrayValue(payload.frameworkContext),
  };
}

function applyStageBPayloadTitle(result, title) {
  const normalizedTitle = firstString(title);
  if (!normalizedTitle || !isPlainObject(result)) {
    return result;
  }

  return {
    ...result,
    page_title: normalizedTitle,
    pageTitle: normalizedTitle,
  };
}

function buildStageBHeaderPayloadOptions(flags) {
  const options = {};
  if (Object.prototype.hasOwnProperty.call(flags, 'includeHeader')) {
    options.includeHeader = flags.includeHeader;
  }
  const scope = firstString(flags.headerScope);
  if (scope) {
    options.scope = scope;
  }
  const title = firstString(flags.headerTemplateTitle, flags.headerTitle);
  if (title) {
    options.templateTitle = title;
  }
  return options;
}

function buildStageBFooterPayloadOptions(flags) {
  const options = {};
  if (Object.prototype.hasOwnProperty.call(flags, 'includeFooter')) {
    options.includeFooter = flags.includeFooter;
  }
  const scope = firstString(flags.footerScope);
  if (scope) {
    options.scope = scope;
  }
  const title = firstString(flags.footerTemplateTitle, flags.footerTitle);
  if (title) {
    options.templateTitle = title;
  }
  return options;
}

async function collectStageBPayloadBinaryAssets(workspaceDir, result) {
  const refs = collectStageBLocalBinaryAssetRefs(result);
  const assets = [];
  const seenDestinations = new Set();
  for (const ref of refs) {
    const destination = stageBServerAssetDestination(ref);
    if (!destination || seenDestinations.has(destination)) {
      continue;
    }
    const sourcePath = await resolveStageBWorkspaceAssetPath(workspaceDir, ref, destination);
    if (!sourcePath) {
      continue;
    }
    const buffer = await fs.readFile(sourcePath);
    if (buffer.length <= 0 || buffer.length > 25 * 1024 * 1024) {
      continue;
    }
    seenDestinations.add(destination);
    assets.push({
      workspaceFile: destination,
      workspace_file: destination,
      contentBase64: buffer.toString('base64'),
      mimeType: mimeTypeForStageBAssetPath(destination),
      size: buffer.length,
    });
  }
  return assets;
}

function collectStageBLocalBinaryAssetRefs(value, refs = new Set()) {
  if (Array.isArray(value)) {
    for (const item of value) {
      collectStageBLocalBinaryAssetRefs(item, refs);
    }
    return [...refs];
  }
  if (isPlainObject(value)) {
    for (const item of Object.values(value)) {
      collectStageBLocalBinaryAssetRefs(item, refs);
    }
    return [...refs];
  }
  if (typeof value !== 'string') {
    return [...refs];
  }
  const ref = normalizeStageBLocalAssetRef(value);
  if (ref) {
    refs.add(ref);
  }
  return [...refs];
}

function normalizeStageBLocalAssetRef(value) {
  let ref = String(value || '').trim().replace(/\\/g, '/');
  if (!ref || /^(?:https?:\/\/|data:|blob:|\/|[a-z]:\/)/i.test(ref)) {
    return '';
  }
  ref = ref.replace(/^\.\/+/, '').replace(/\/+/g, '/');
  if (!/\.(?:png|jpe?g|webp|avif|gif|svg)$/i.test(ref)) {
    return '';
  }
  if (
    ref.startsWith('assets/')
    || ref.startsWith('drafts/assets/')
    || ref.startsWith('stage-a/drafts/assets/')
    || ref.startsWith('stage-a/assets/')
  ) {
    return ref;
  }
  return '';
}

function stageBServerAssetDestination(ref) {
  if (ref.startsWith('drafts/assets/')) {
    return ref;
  }
  if (ref.startsWith('assets/')) {
    return `drafts/${ref}`;
  }
  if (ref.startsWith('stage-a/drafts/assets/')) {
    return ref.slice('stage-a/'.length);
  }
  if (ref.startsWith('stage-a/assets/')) {
    return `drafts/assets/${ref.slice('stage-a/assets/'.length)}`;
  }
  return '';
}

async function resolveStageBWorkspaceAssetPath(workspaceDir, ref, destination) {
  const candidates = [
    path.join(workspaceDir, ref),
    path.join(workspaceDir, destination),
  ];
  if (destination.startsWith('drafts/assets/')) {
    const assetName = destination.slice('drafts/assets/'.length);
    candidates.push(path.join(workspaceDir, 'assets', assetName));
    candidates.push(path.join(workspaceDir, 'stage-a', 'drafts', 'assets', assetName));
  }
  for (const candidate of candidates) {
    try {
      const stat = await fs.stat(candidate);
      if (stat.isFile()) {
        return candidate;
      }
    } catch {
      // Keep trying candidates.
    }
  }
  return '';
}

function mimeTypeForStageBAssetPath(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  if (ext === '.jpg' || ext === '.jpeg') return 'image/jpeg';
  if (ext === '.webp') return 'image/webp';
  if (ext === '.avif') return 'image/avif';
  if (ext === '.gif') return 'image/gif';
  if (ext === '.svg') return 'image/svg+xml';
  return 'image/png';
}

async function readStageBColorSystem(flags, workspaceDir) {
  const colorSystemFile = firstString(
    flags.colorSystemFile,
    flags.colorSystem,
    flags.color_system,
    path.join(workspaceDir, 'stage-b-color-system.json')
  );
  if (!colorSystemFile) {
    return {};
  }
  return await readOptionalJson(colorSystemFile);
}

async function readStageBContracts(flags, workspaceDir) {
  const routeContractFile = firstString(
    flags.routeContractFile,
    flags.routeContract,
    path.join(workspaceDir, 'stage-b-route-contract.json')
  );
  const themeStyleContractFile = firstString(
    flags.themeStyleContractFile,
    flags.themeStyleContract,
    path.join(workspaceDir, 'stage-b-theme-style-contract.json')
  );
  const themeStyleHealthFile = firstString(
    flags.themeStyleHealthFile,
    flags.themeStyleHealth,
    path.join(workspaceDir, 'stage-b-theme-style-health.json')
  );
  return {
    routeContract: await readOptionalJson(routeContractFile),
    themeStyleContract: await readOptionalJson(themeStyleContractFile),
    themeStyleHealth: await readOptionalJson(themeStyleHealthFile),
  };
}

function attachStageBColorSystemToResult(result, colorSystem) {
  if (!colorSystem || Object.keys(colorSystem).length === 0) {
    return result;
  }
  return {
    ...result,
    stage_b_color_system: colorSystem,
    color_system: result.color_system || colorSystem,
  };
}

function attachStageBContractsToResult(result, contracts) {
  const routeContract = objectValue(contracts?.routeContract);
  const themeStyleContract = objectValue(contracts?.themeStyleContract);
  const themeStyleHealth = objectValue(contracts?.themeStyleHealth);
  const next = { ...result };
  if (Object.keys(routeContract).length > 0 && !next.stage_b_route_contract) {
    next.stage_b_route_contract = routeContract;
  }
  if (Object.keys(themeStyleContract).length > 0 && !next.stage_b_theme_style_contract) {
    next.stage_b_theme_style_contract = themeStyleContract;
  }
  if (Object.keys(themeStyleHealth).length > 0 && !next.stage_b_theme_style_health) {
    next.stage_b_theme_style_health = themeStyleHealth;
  }
  return next;
}

function resolveStageBResultPath(flags) {
  const explicit = firstString(flags.resultFile, flags.result, flags.bricksResult, flags.file);
  if (explicit) {
    return explicit;
  }

  const workspaceDir = firstString(flags.workspace, flags.workspaceDir, flags.cwd, '.');
  return path.join(workspaceDir, 'bricks-result.json');
}

async function readTextFile(filePath, label) {
  const absolutePath = path.resolve(process.cwd(), filePath);
  try {
    return await fs.readFile(absolutePath, 'utf8');
  } catch (error) {
    throw new CliError(`Could not read ${label}: ${absolutePath}`);
  }
}

async function readMetadata(flags) {
  if (flags.metadataFile) {
    const raw = stripBom(await readTextFile(flags.metadataFile, 'metadata file'));
    try {
      return JSON.parse(raw);
    } catch (error) {
      throw new CliError(`Metadata file is not valid JSON: ${path.resolve(process.cwd(), flags.metadataFile)}`);
    }
  }

  if (typeof flags.metadata === 'string' && flags.metadata.trim() !== '') {
    try {
      return JSON.parse(flags.metadata);
    } catch (error) {
      throw new CliError('--metadata must be a JSON object string.');
    }
  }

  return {};
}

async function prepareStageAWorkspace(flags) {
  const handoffPath = firstString(flags.handoff, flags.handoffFile, flags.file);
  if (!handoffPath) {
    throw new CliError('Missing required --handoff <path> for prepare-stage-a.');
  }

  const handoff = await readJsonFile(handoffPath, 'Stage A handoff');
  const sourceId = inferStageASourceId(handoff, flags);
  const workspaceRoot = path.resolve(
    process.cwd(),
    firstString(flags.workspace, flags.workspaceDir, flags.outDir, './pixflow-stage-a-runs')
  );
  const workspaceDir = path.join(workspaceRoot, sourceId);
  await ensureStageAWorkspace(workspaceDir, Boolean(flags.force));

  const prompt = inferStageAPrompt(handoff);
  const userPrompt = firstString(handoff?.prompt?.userPrompt, prompt);
  const fidelity = firstString(
    flags.fidelity,
    handoff?.workflow?.fidelity,
    handoff?.workflow?.prototypeFidelity,
    handoff?.context?.prototype_fidelity,
    'high_fidelity'
  );
  const title = inferStageATitle(handoff, sourceId);
  const requiredModelReads = [];
  const sitemapContext = stageASitemapContextFromHandoff(handoff);
  const pageIntentContract = stageAPageIntentContractFromHandoff(handoff);
  const sitemapIntent = firstPlainObject(pageIntentContract, sitemapContext);
  if (Boolean(flags.libraryPage === true || flags.libraryPage === 'true') || firstString(sitemapIntent.generationMode) === 'pixflow_library') {
    throw new CliError('Stage A runner received a Pixflow Library handoff. Use run-library-page so Library planning stays isolated from Stage A.');
  }
  const odRunRequest = firstPlainObject(handoff?.odRunRequest, handoff?.od_run_request);
  const odStageASubmit = firstPlainObject(handoff?.odStageASubmit, handoff?.od_stage_a_submit);
  const recipeAction = stageARecipeActionFromHandoff(handoff);
  const odRunShape = stageAOdRunShapeFromHandoff(handoff);
  const controlDir = path.join(workspaceRoot, '.pixflow-bridge', sourceId);
  await fs.mkdir(controlDir, { recursive: true });
  const metadata = {
    sourceId,
    title,
    fidelity,
    stage: DEFAULT_STAGE,
    generationPipeline: 'pixflow_generation_stage_a',
    libraryPageActive: false,
    executionMode: 'local_cli',
    handoffType: firstString(handoff?.type, 'pixflow_design_cli_stage_a_handoff'),
    handoffVersion: handoff?.version || 1,
    generatedAt: new Date().toISOString(),
    workspaceDir,
    promptText: prompt,
    userPromptText: userPrompt,
    target: handoff?.target || {},
    selectedPrototype: handoff?.selectedPrototype || null,
    selectedTemplate: handoff?.selectedTemplate || null,
    selectedPixflowDesignSystem: handoff?.pixflowDesignSystem || null,
    requiredModelReads,
    sitemapContextActive: Object.keys(sitemapIntent).length > 0,
    sitemapContext,
    pageIntentContract,
    sitemapGenerationMode: firstString(sitemapIntent.generationMode),
    sitemapPageType: firstString(sitemapIntent.pageType),
    sitemapPageTitle: firstString(sitemapIntent.pageTitle),
    odRunRequestActive: Boolean(odRunRequest && Object.keys(odRunRequest).length > 0),
    recipeAction,
    odRunShape,
    ...(odRunRequest && Object.keys(odRunRequest).length > 0 ? { odRunRequest } : {}),
    ...(odStageASubmit && Object.keys(odStageASubmit).length > 0 ? { odStageASubmit } : {}),
  };

  const files = {
    runnerPrompt: path.join(controlDir, 'codex-stage-a-prompt.txt'),
    metadata: path.join(controlDir, 'metadata.json'),
    artifact: path.join(workspaceDir, 'index.html'),
  };

  await Promise.all([
    writeTextFile(files.runnerPrompt, renderStageARunnerPrompt(metadata)),
    writeTextFile(files.metadata, `${JSON.stringify(metadata, null, 2)}\n`),
  ]);
  const preflightMaterialization = await materializeWorkspacePreflight(handoff, workspaceDir);
  const materializedRequiredReads = Array.isArray(preflightMaterialization.requiredModelReads)
    ? preflightMaterialization.requiredModelReads
    : [];
  if (!sameStringList(materializedRequiredReads, metadata.requiredModelReads)) {
    metadata.requiredModelReads = materializedRequiredReads;
    await Promise.all([
      writeTextFile(files.runnerPrompt, renderStageARunnerPrompt(metadata)),
      writeTextFile(files.metadata, `${JSON.stringify(metadata, null, 2)}\n`),
    ]);
  }

  const importCommand = [
    'node',
    'tools/pixflow-design-cli/pixflow-design-cli.mjs',
    'import-artifact',
    '--config',
    './pixflow-design-cli.config.json',
    '--html',
    quoteForShell(files.artifact),
    '--prompt',
    quoteForShell(prompt),
    '--metadata-file',
    quoteForShell(files.metadata),
  ].join(' ');
  const suggestedRunCommand = [
    'Get-Content',
    '-Raw',
    quoteForShell(files.runnerPrompt),
    '|',
    'codex',
    'exec',
    '--json',
    '--skip-git-repo-check',
    '--sandbox',
    'danger-full-access',
    '-c',
    quoteForShell('default_permissions=":workspace"'),
    '-C',
    quoteForShell(workspaceDir),
  ].join(' ');

  const result = {
    status: 'prepared',
    workspaceDir,
    sourceId,
    title,
    generationPipeline: metadata.generationPipeline,
    libraryPageActive: false,
    promptFile: null,
    prompt,
    instructionsFile: null,
    runnerPromptFile: files.runnerPrompt,
    metadataFile: files.metadata,
    artifactFile: files.artifact,
    workspacePreflight: preflightMaterialization,
    suggestedRunCommand,
    importCommand,
  };

  return result;
}

function parsePixflowCssInsetValue(value) {
  const box = parsePixflowCssBoxValue(value);
  return {
    _top: box.top,
    _right: box.right,
    _bottom: box.bottom,
    _left: box.left,
  };
}

async function materializeWorkspacePreflight(handoff, workspaceDir, options = {}) {
  const workspace = workspacePreflightFromHandoff(handoff);
  const result = {
    active: false,
    fileCount: 0,
    binaryAssetCount: 0,
    writtenFiles: [],
    writtenBinaryAssets: [],
    skippedBinaryAssets: [],
    requiredModelReads: [],
  };

  if (!workspace) {
    return result;
  }

  normalizeStageAWorkspacePreflightForRunShape(workspace, stageAOdRunShapeFromHandoff(handoff));

  result.active = true;
  const manifest = objectValue(workspace.manifest);
  const sourceContract = objectValue(workspace.source_contract || workspace.sourceContract);
  const diagnostics = objectValue(workspace.diagnostics);
  result.requiredModelReads = requiredModelReadsFromSourceContract(sourceContract);

  const files = objectValue(workspace.files);
  for (const [relativePath, contents] of Object.entries(files)) {
    const safeRelativePath = normalizeWorkspaceRelativePath(relativePath);
    if (!safeRelativePath || typeof contents !== 'string') {
      continue;
    }
    await writeTextFile(path.join(workspaceDir, safeRelativePath), contents.endsWith('\n') ? contents : `${contents}\n`);
    result.writtenFiles.push(safeRelativePath);
  }

  const binaryAssets = Array.isArray(workspace.binary_assets)
    ? workspace.binary_assets
    : Array.isArray(workspace.binaryAssets)
      ? workspace.binaryAssets
      : [];
  for (const asset of binaryAssets) {
    const written = await materializeWorkspaceBinaryAsset(asset, workspaceDir);
    if (written.ok) {
      result.writtenBinaryAssets.push(written.path);
    } else if (written.path || written.reason) {
      result.skippedBinaryAssets.push(written);
    }
  }

  result.fileCount = result.writtenFiles.length;
  result.binaryAssetCount = result.writtenBinaryAssets.length;
  return result;
}

function normalizeStageAWorkspacePreflightForRunShape(workspace, runShape) {
  if (!isPlainObject(workspace)) {
    return;
  }

  const files = objectValue(workspace.files);
  const filteredFiles = {};
  for (const [relativePath, contents] of Object.entries(files)) {
    const safeRelativePath = normalizeWorkspaceRelativePath(relativePath);
    if (!safeRelativePath || typeof contents !== 'string') {
      continue;
    }
    if (stageAWorkspacePathAllowedForRunShape(safeRelativePath, runShape)) {
      filteredFiles[safeRelativePath] = contents;
    }
  }

  const filteredPaths = Object.keys(filteredFiles);
  workspace.files = filteredFiles;

  const requiredPaths = runShape === 'replicate_content'
    ? filteredPaths.filter((filePath) => /^\.od-skills\/[^/]+\/example\.html$/i.test(filePath))
    : filteredPaths;

  const sourceContract = objectValue(workspace.source_contract || workspace.sourceContract);
  if (Object.keys(sourceContract).length > 0) {
    sourceContract.required_model_reads = requiredPaths;
    sourceContract.requiredModelReads = requiredPaths;
    sourceContract.authoritative_files = requiredPaths;
    sourceContract.authoritativeFiles = requiredPaths;
    sourceContract.read_tracking = {
      ...objectValue(sourceContract.read_tracking),
      required_model_reads: requiredPaths,
    };
    sourceContract.stage_a_resource_boundary = {
      ...objectValue(sourceContract.stage_a_resource_boundary),
      authoritative_files: requiredPaths,
    };
  }

  const manifest = objectValue(workspace.manifest);
  if (Array.isArray(manifest.files)) {
    manifest.files = manifest.files.filter((file) => {
      const filePath = normalizeWorkspaceRelativePath(firstString(file?.name, file?.path));
      return filteredPaths.includes(filePath);
    });
  }

  const diagnostics = objectValue(workspace.diagnostics);
  if (Object.keys(diagnostics).length > 0) {
    diagnostics.authoritative_files = requiredPaths;
    diagnostics.required_model_reads = requiredPaths;
  }
}

function stageAWorkspacePathAllowedForRunShape(filePath, runShape) {
  if (runShape === 'replicate_content') {
    return /^\.od-skills\/[^/]+\/example\.html$/i.test(filePath);
  }
  if (runShape === 'use_plugin') {
    return /^\.od-(?:skills|plugins)\//i.test(filePath);
  }
  if (runShape === 'prompt_only_with_files') {
    return filePath === 'attachment-references.json'
      || filePath.startsWith('attachments/')
      || filePath.startsWith('tool-artifacts/');
  }
  if (runShape === 'prompt_only') {
    return false;
  }
  return false;
}

