function readLibraryReference(fileName) {
  const safeFileName = firstString(fileName).replace(/[^a-z0-9_.-]/gi, '');
  if (!safeFileName) {
    throw new CliError('Missing Pixflow Library reference file name.');
  }
  const skillRoot = pluginOwnedConverterSkillRoot('bricks-web-prototype');
  const referencePath = path.join(skillRoot, 'references', 'library', safeFileName);
  try {
    return `${readFileSync(referencePath, 'utf8').trim()}\n`;
  } catch (error) {
    throw new CliError(`Missing Pixflow Library reference ${safeFileName}: ${error.message}`);
  }
}

function parseJsonText(value) {
  if (typeof value !== 'string' || value.trim() === '') {
    return {};
  }
  try {
    return JSON.parse(value);
  } catch {
    return {};
  }
}

function workspacePreflightFromHandoff(handoff) {
  for (const key of ['workspacePreflight', 'workspace_preflight', 'workspace']) {
    const candidate = handoff?.[key];
    if (candidate && typeof candidate === 'object' && !Array.isArray(candidate)) {
      return candidate;
    }
  }
  return null;
}

async function materializeWorkspaceBinaryAsset(asset, workspaceDir) {
  if (!asset || typeof asset !== 'object' || Array.isArray(asset)) {
    return { ok: false, path: '', reason: 'invalid_asset' };
  }

  const relativePath = normalizeWorkspaceRelativePath(
    firstString(asset.workspaceFile, asset.workspace_file, asset.modelPath, asset.model_path, asset.path)
  );
  if (!relativePath) {
    return { ok: false, path: '', reason: 'missing_workspace_file' };
  }

  const targetPath = path.join(workspaceDir, relativePath);
  const base64 = firstString(asset.contentBase64, asset.content_base64, asset.base64);
  if (base64) {
    await fs.mkdir(path.dirname(targetPath), { recursive: true });
    await fs.writeFile(targetPath, Buffer.from(base64, 'base64'));
    return { ok: true, path: relativePath };
  }

  const downloadUrl = firstString(asset.downloadUrl, asset.download_url, asset.url);
  if (downloadUrl) {
    try {
      const response = await fetch(downloadUrl);
      if (!response.ok) {
        return { ok: false, path: relativePath, reason: `download_http_${response.status}` };
      }
      const bytes = Buffer.from(await response.arrayBuffer());
      await fs.mkdir(path.dirname(targetPath), { recursive: true });
      await fs.writeFile(targetPath, bytes);
      return { ok: true, path: relativePath };
    } catch (error) {
      return { ok: false, path: relativePath, reason: `download_failed:${error?.message || 'unknown'}` };
    }
  }

  const sourcePath = firstString(asset.sourcePath, asset.source_path);
  if (sourcePath) {
    try {
      await fs.mkdir(path.dirname(targetPath), { recursive: true });
      await fs.copyFile(sourcePath, targetPath);
      return { ok: true, path: relativePath };
    } catch (error) {
      return { ok: false, path: relativePath, reason: `copy_failed:${error?.message || 'unknown'}` };
    }
  }

  return { ok: false, path: relativePath, reason: 'no_asset_transport' };
}

async function writeJsonFile(filePath, value) {
  await writeTextFile(filePath, `${JSON.stringify(value || {}, null, 2)}\n`);
}

function extractQuestionFormBlock(text) {
  const source = firstString(text);
  if (!source) return null;
  const openRe = /<(question-form|ask-question)\b[^>]*>/i;
  const match = openRe.exec(source);
  if (!match) return null;
  const tagName = firstString(match[1], 'question-form').toLowerCase();
  const closeTag = `</${tagName}>`;
  const openStart = match.index;
  const openEnd = openStart + match[0].length;
  const lower = source.toLowerCase();
  const closeIndex = lower.indexOf(closeTag, openEnd);
  if (closeIndex === -1) return null;
  return source.slice(openStart, closeIndex + closeTag.length);
}

function promptAlreadyHasFormAnswers(text) {
  return /\[form answers\s*[-\u2014]/i.test(firstString(text))
    || /Submitted discovery form answers:/i.test(firstString(text))
    || /Discovery answers:/i.test(firstString(text));
}

function stageAShouldStartWithDiscovery(metadata) {
  if (metadata?.libraryPageActive === true) {
    return false;
  }
  const promptText = [
    firstString(metadata?.promptText),
    firstString(metadata?.userPromptText),
    firstString(metadata?.odRunRequest?.message),
    firstString(metadata?.odRunRequest?.currentPrompt),
  ].join('\n');
  if (promptAlreadyHasFormAnswers(promptText)) {
    return false;
  }
  return true;
}

function pluginOwnedConverterSkillRoot(packName) {
  const authorityRoot = firstString(process.env.PIXFLOW_BRICKS_SKILL_PACK_ROOT);
  if (!authorityRoot) {
    throw new CliError('Missing plugin-owned Pixflow Bricks converter skill pack. Reconnect the Bridge and retry.');
  }
  const root = path.resolve(authorityRoot, packName);
  const authorityBoundary = `${path.resolve(authorityRoot)}${path.sep}`;
  if (!root.startsWith(authorityBoundary) || !existsSync(path.join(root, 'SKILL.md'))) {
    throw new CliError(`Invalid plugin-owned Pixflow Bricks converter skill pack: ${packName}.`);
  }
  return root;
}

async function extractStageADiscoveryQuestionForm(prepared, eventsFile) {
  const promptText = firstString(prepared.prompt);
  if (promptAlreadyHasFormAnswers(promptText)) {
    return null;
  }
  const eventText = await readOptionalText(eventsFile);
  const block = extractQuestionFormBlock(eventText);
  if (!block) {
    return null;
  }
  return {
    raw: block,
    source: eventsFile || '',
  };
}

async function runStageAWorkspace(flags) {
  const prepared = await prepareStageAWorkspace(flags);
  const runnerInvocation = buildStageARunnerInvocation(prepared, flags);
  runnerInvocation.jsonOutput = Boolean(flags.json);
  const result = {
    ...prepared,
    status: 'running',
    runnerCommand: runnerInvocation.display,
    runner: runnerInvocation.kind,
    runnerExitCode: null,
    runnerEventsFile: runnerInvocation.eventsFile || null,
    runnerStderrFile: runnerInvocation.stderrFile || null,
    runnerEventSummary: null,
    imported: null,
  };

  const runnerResult = await runStageAInvocation(runnerInvocation, prepared.workspaceDir);
  result.runnerExitCode = runnerResult.code;
  result.runnerEventSummary = runnerResult.eventSummary;
  const discoveryQuestionForm = await extractStageADiscoveryQuestionForm(
    prepared,
    runnerResult.eventsFile
  );
  if (discoveryQuestionForm && !prepared.libraryPageActive) {
    result.status = 'discovery_questions';
    result.discoveryQuestionFormDetected = true;
    result.discoveryQuestionForm = discoveryQuestionForm;
    result.message = 'Pixflow Design discovery questions are ready.';
    return result;
  }
  await assertFileExists(prepared.artifactFile, 'Stage A artifact');
  result.status = 'artifact_ready';

  if (flags.import === true || flags.import === 'true') {
    const config = await loadConfig(flags);
    const client = createPixflowClient(config);
    let payload = await buildImportArtifactPayload({
      ...flags,
      html: prepared.artifactFile,
      prompt: prepared.prompt,
      metadataFile: prepared.metadataFile,
    });
    result.imported = await client.post('/cli-bridge/stage-a/import-artifact', payload);
    result.status = 'imported';
  }

  return result;
}

async function runLibraryPageWorkspace(flags) {
  const prepared = await prepareLibraryPageWorkspace(flags);
  const runnerInvocation = buildLibraryPageRunnerInvocation(prepared, flags);
  runnerInvocation.jsonOutput = Boolean(flags.json);
  const result = {
    ...prepared,
    status: 'running',
    runnerCommand: runnerInvocation.display,
    runner: runnerInvocation.kind,
    runnerExitCode: null,
    runnerEventsFile: runnerInvocation.eventsFile || null,
    runnerStderrFile: runnerInvocation.stderrFile || null,
    runnerEventSummary: null,
    repairAttempts: [],
    stageAQa: null,
    stageAToolTraceFile: null,
    imported: null,
    libraryPagePlan: null,
  };

  const runnerResult = await runStageAInvocation(runnerInvocation, prepared.workspaceDir);
  result.runnerExitCode = runnerResult.code;
  result.runnerEventSummary = runnerResult.eventSummary;
  const eventFiles = [runnerResult.eventsFile].filter(Boolean);
  const combinedEventsFile = await combineStageAEventLogs(prepared.workspaceDir, eventFiles);
  const activeRunnerResult = {
    ...runnerResult,
    eventsFile: combinedEventsFile || runnerResult.eventsFile,
    eventSummary: runnerResult.eventSummary,
  };
  result.libraryPagePlan = await assertLibraryPagePlanExists(prepared.workspaceDir);
  await writeLibraryPageCompatibilityArtifact(prepared);
  result.stageAToolTraceFile = await writeStageAToolTrace(prepared.workspaceDir, activeRunnerResult, null, {
    fileName: 'library-tool-trace.md',
    title: '# Pixflow Library Tool Trace',
  });
  result.status = 'library_plan_ready';

  if (flags.import === true || flags.import === 'true') {
    const config = await loadConfig(flags);
    const client = createPixflowClient(config);
    const payload = await buildImportArtifactPayload({
      ...flags,
      html: prepared.artifactFile,
      prompt: prepared.prompt,
      metadataFile: prepared.metadataFile,
    });
    result.imported = await client.post('/cli-bridge/stage-a/import-artifact', payload);
    result.status = 'imported';
  }

  return result;
}

async function runLibraryTask(flags) {
  const task = firstString(flags.task, flags.type, 'template-adaptation');
  if (task !== 'template-adaptation') {
    throw new CliError(`Unsupported Pixflow Library task "${task}".`);
  }

  const payloadPath = firstString(flags.payload, flags.payloadFile, flags.payload_file, 'library-task-payload.json');
  const payload = await readJsonFile(payloadPath, 'Pixflow Library task payload');
  const request = objectValue(payload.request || payload.payload || payload);
  if (!Array.isArray(request.payload)) {
    throw new CliError('Pixflow Library template adaptation requires a payload array.');
  }

  const workspaceDir = path.resolve(firstString(flags.workspace, flags.workspaceDir, process.cwd()));
  await fs.mkdir(workspaceDir, { recursive: true });
  const startedAt = Date.now();
  const fields = extractLibraryTaskTextFields(request.payload).slice(0, 80);
  const prompt = buildLibraryTemplateAdaptationPrompt(request, fields);
  const promptFile = path.join(workspaceDir, 'library-task-prompt.md');
  await fs.writeFile(promptFile, prompt, 'utf8');

  const runnerId = normalizeBridgeRunnerId(firstString(flags.runner, flags.agent, flags.provider, 'codex'));
  const invocation = await buildLibraryTaskInvocation(runnerId, workspaceDir, promptFile, flags);
  const run = await runLocalInvocationCapture(invocation, workspaceDir, 'Pixflow Library task');
  const structured = extractLibraryTaskJson(run.stdoutText);
  const filledFields = normalizeLibraryTaskFilledFields(structured.filled_fields || structured.filledFields || [], fields);
  const adaptedPayload = applyLibraryTaskFilledFields(request.payload, filledFields);
  const result = buildLibraryTemplateAdaptationResult(request, adaptedPayload, fields, filledFields, {
    runnerId,
    durationMs: Date.now() - startedAt,
    stdoutBytes: run.stdoutText.length,
    stderrBytes: run.stderrText.length,
    model: firstString(flags.model),
  });

  const resultPath = path.join(workspaceDir, 'library-task-result.json');
  await fs.writeFile(resultPath, JSON.stringify(result, null, 2), 'utf8');

  return {
    status: 'ok',
    command: 'library-task',
    task,
    resultPath,
    result,
    filledFieldCount: filledFields.length,
    run: {
      runnerId,
      durationMs: Date.now() - startedAt,
    },
  };
}

async function assertLibraryPagePlanExists(workspaceDir) {
  const planFile = path.join(workspaceDir, 'library-page-plan.json');
  const plan = await readOptionalJson(planFile);
  if (!plan || typeof plan !== 'object' || Object.keys(plan).length === 0) {
    throw new CliError('Pixflow Library run did not create library-page-plan.json.');
  }

  const sections = Array.isArray(plan.sections) ? plan.sections : [];
  if (sections.length === 0) {
    throw new CliError('Pixflow Library run created library-page-plan.json without any sections.');
  }

  return plan;
}

async function writeLibraryPageCompatibilityArtifact(prepared) {
  const plan = await readOptionalJson(path.join(prepared.workspaceDir, 'library-page-plan.json'));
  const page = objectValue(plan.page);
  const title = safe(firstString(page.title, prepared.title, 'Pixflow Library page'));
  const sectionCount = Array.isArray(plan.sections) ? plan.sections.length : 0;
  const html = [
    '<!doctype html>',
    '<html lang="en">',
    '<head>',
    '  <meta charset="utf-8">',
    '  <meta name="viewport" content="width=device-width, initial-scale=1">',
    `  <title>${title}</title>`,
    '  <style>body{margin:0;font-family:system-ui,sans-serif;background:#fafafa;color:#111}main{padding:32px;max-width:760px;margin:0 auto}</style>',
    '</head>',
    '<body>',
    `  <main data-od-id="pixflow-library-plan" data-library-section-count="${sectionCount}">`,
    `    <h1>${title}</h1>`,
    '    <p>This compatibility artifact points WordPress at library-page-plan.json. The live page is assembled from Pixflow Library JSON templates.</p>',
    '  </main>',
    '</body>',
    '</html>',
    '',
  ].join('\n');
  await writeTextFile(prepared.artifactFile, html);
}

