function buildStageBRunnerInvocation(prepared, flags, overrides = {}) {
  const maxRuntimeMs = parsePositiveIntegerFlag(
    firstString(flags.stageBRunnerTimeoutMs, flags.stage_b_runner_timeout_ms, flags.runnerTimeoutMs, flags.runner_timeout_ms),
    DEFAULT_STAGE_B_RUNNER_TIMEOUT_MS
  );
  const customCommand = firstString(flags.runnerCommand);
  if (customCommand) {
    const command = customCommand
      .replace(/\{workspace\}/g, prepared.workspaceDir)
      .replace(/\{prompt\}/g, prepared.runnerPromptFile)
      .replace(/\{artifact\}/g, prepared.resultFile)
      .replace(/\{result\}/g, prepared.resultFile);
    return {
      kind: 'custom_shell',
      display: command,
      command,
      shell: true,
      stdin: null,
      eventsFile: overrides.eventsFile || path.join(prepared.workspaceDir, 'stage-b-runner-events.log'),
      stderrFile: overrides.stderrFile || path.join(prepared.workspaceDir, 'stage-b-runner-stderr.log'),
      // Pixflow-owned: Codex can finish writing the Bricks handoff artifacts
      // and then linger during MCP/plugin shutdown. The handoff should not
      // leave the browser waiting forever once the expected result exists.
      completionFile: prepared.resultFile,
      completionRequiredFiles: [path.join(prepared.workspaceDir, 'handoff-critique.md')],
      completionQuietMs: 12_000,
      maxRuntimeMs,
    };
  }

  return buildBridgeStageRunnerInvocation('stage-b', prepared, flags, { ...overrides, maxRuntimeMs });
}

async function runStageBInvocation(invocation, cwd) {
  return runLocalInvocation(invocation, cwd, 'Stage B');
}

