function quickTextEditModelLedSession(request) {
  const runContext = objectValue(request?.runContext || request?.run_context);
  return firstString(request?.mode).toLowerCase() === 'design'
    && (
      runContext.authorizedMutationSession === true
      || runContext.sessionAuthorized === true
      || request?.modelLed === true
      || request?.model_led === true
      || firstString(request?.sessionType, request?.session_type).toLowerCase() === 'bricks_agent_model_edit'
    );
}

function quickTextEditHasBoundedConditionIntent(request, modelResult = null) {
  if (firstString(request?.mode).toLowerCase() !== 'design') return false;
  const inventory = buildBricksAgentMutationInventory(request);
  if (!inventory.optionTargets.some((target) => target.fieldKey === '_conditions')) return false;
  const resolvedFact = objectValue(request?.resolvedWorkingMemoryFact || request?.resolved_working_memory_fact);
  if (firstString(resolvedFact.kind) === 'visibility_condition') return true;
  const action = firstString(modelResult?.action).toLowerCase().replace(/[\s-]+/g, '_');
  return ['condition', 'condition_patch', 'compound', 'compound_patch', 'compound_mutation', 'multi_action'].includes(action);
}

export function buildBridgeCodexRunnerArgsForTest({
  workspaceDir = process.cwd(),
  model = 'default',
  reasoning = 'default',
  fastMode = false,
} = {}) {
  return buildBridgeStageRunnerSpec(
    'codex',
    { workspaceDir },
    { model, reasoning, fastMode },
  ).args;
}
function quickTextEditHasBoundedQueryLoopIntent(request, modelResult = null) {
  if (firstString(request?.mode).toLowerCase() !== 'design') return false;
  const inventory = buildBricksAgentMutationInventory(request);
  const queryTargets = inventory.optionTargets.filter((target) => (
    target.targetKind === 'query_loop' && ['hasLoop', 'query'].includes(target.fieldKey)
  ));
  if (!queryTargets.some((target) => queryTargets.some((candidate) => (
    candidate.elementId === target.elementId && candidate.fieldKey !== target.fieldKey
  )))) return false;
  const resolvedFact = objectValue(request?.resolvedWorkingMemoryFact || request?.resolved_working_memory_fact);
  if (firstString(resolvedFact.kind) === 'query_loop') return true;
  const action = firstString(modelResult?.action).toLowerCase().replace(/[\s-]+/g, '_');
  return ['query_loop', 'query_loop_update', 'compound', 'compound_patch', 'compound_mutation', 'multi_action'].includes(action);
}
function quickTextEditPendingDynamicDataConversation(request) {
  const fact = objectValue(request?.resolvedWorkingMemoryFact || request?.resolved_working_memory_fact);
  return firstString(fact.kind) === 'dynamic_data_binding' ? JSON.stringify(fact) : '';
}
function quickTextEditHasBoundedDynamicDataIntent(request) {
  if (firstString(request?.mode).toLowerCase() !== 'design') return false;
  const inventory = buildBricksAgentMutationInventory(request);
  if (!inventory.allTargets.some((target) => ['text', 'link', 'media'].includes(target.targetKind))) return false;
  const fact = objectValue(request?.resolvedWorkingMemoryFact || request?.resolved_working_memory_fact);
  if (firstString(fact.kind) === 'dynamic_data_binding') return true;
  return false;
}
export function quickTextEditHasBoundedDynamicDataMutationIntent(request, modelResult) {
  return quickTextEditHasBoundedDynamicDataIntent(request)
    || firstString(modelResult?.action).toLowerCase() === 'dynamic_data';
}
function buildApprovedConversationDynamicDataFallback(request) {
  const fact = objectValue(request?.resolvedWorkingMemoryFact || request?.resolved_working_memory_fact);
  const authority = objectValue(request?.workingMemoryAuthority || request?.working_memory_authority);
  const target = objectValue(fact.target);
  const intent = objectValue(fact.intent);
  if (firstString(fact.kind) !== 'dynamic_data_binding' || firstString(intent.kind) !== 'dynamic_data_binding') return null;
  if (!firstString(fact.id) || firstString(authority.factId, authority.fact_id) !== firstString(fact.id)) return null;
  const elementId = firstString(target.elementId, target.element_id);
  const fieldKey = firstString(target.fieldKey, target.field_key);
  const expression = firstString(intent.expression);
  if (!elementId || !fieldKey || !/^\{[^{}]+\}$/.test(expression)) return null;
  return buildStructuredDynamicDataPatchModelResult({
    action: 'dynamic_data',
    targetId: elementId,
    fieldKey,
    expression,
    answer: `I bound ${elementId} ${fieldKey} to ${expression}.`,
    mutationTitle: 'Bind native Dynamic Data',
    changeSummary: `Set ${elementId} ${fieldKey} to ${expression}.`,
    confidence: 'high',
    reason: 'The v2 working-memory authority resolves one exact compatible Dynamic Data fact.',
  }, request);
}
function collectDynamicDataRepairTags(request) {
  const tags = [];
  const seen = new Set();
  const visit = (value, depth = 0) => {
    if (depth > 9 || value === null || value === undefined || tags.length >= 80) return;
    if (Array.isArray(value)) {
      value.slice(0, 500).forEach((item) => visit(item, depth + 1));
      return;
    }
    if (typeof value !== 'object') return;
    const tag = firstString(value.tag, value.name);
    if (/^\{[^{}]+\}$/.test(tag) && value.runtimeAvailable !== false && !seen.has(tag)) {
      seen.add(tag);
      tags.push({
        tag,
        provider: firstString(value.provider),
        returns: firstString(value.returns, value.returnType, value.return_type),
        placements: arrayValue(value.placements).slice(0, 8),
        contexts: arrayValue(value.contexts).slice(0, 8),
      });
    }
    Object.values(value).slice(0, 500).forEach((item) => visit(item, depth + 1));
  };
  visit(request?.mcpRuntimeContext || request?.mcp_runtime_context || request?.runtimeKnowledge);
  return tags;
}

